--------------------------------------------------------
--  DDL for Procedure CHECK_SIGN_TRANSACTION_COMPLETE
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."CHECK_SIGN_TRANSACTION_COMPLETE" (
    P_TRANSACTION_CODE IN VARCHAR2,
    P_RESULT OUT VARCHAR2
)
IS
    v_total_docs NUMBER;
    v_signed_docs NUMBER;
BEGIN
    -- ??m t?ng s? DOC_ID c?n TPB ký
    SELECT COUNT(*) INTO v_total_docs
    FROM SIGN_ATTACHMENT
    WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
      AND DOC_TYPE = 'NO_SIGN'
      AND REQUIRE_TPB_SIGN = 1;

    -- ??m s? DOC_ID ?ã TPB ký thành công
    SELECT COUNT(*) INTO v_signed_docs
    FROM SIGN_ATTACHMENT
    WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
      AND DOC_TYPE = 'TPB_SIGNED'
      AND REQUIRE_TPB_SIGN = 1
      AND STATUS = 'SIGNED';

    -- Ki?m tra t?t c? ?ã ký ch?a
    IF v_total_docs > 0 AND v_total_docs = v_signed_docs THEN
        -- C?p nh?t tr?ng thái giao d?ch
        UPDATE SIGN_TRANSACTION
        SET STATUS = 'COMPLETE'
        WHERE TRANSACTION_CODE = P_TRANSACTION_CODE;

        -- Ghi l?ch s? ký s?
        INSERT INTO SIGN_HISTORY (TRANSACTION_CODE, ACTION, FRE_STATUS, STATUS)
        VALUES (P_TRANSACTION_CODE, 'TPB_SIGN', 'TPB_SIGN_REPRESENT', 'TPB_SIGN');

        COMMIT;
        P_RESULT := 'SUCCESS';
    ELSE
        P_RESULT := 'INCOMPLETE';
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        P_RESULT := 'ERROR: ' || SQLERRM;
END CHECK_SIGN_TRANSACTION_COMPLETE;

/
--------------------------------------------------------
--  DDL for Procedure SP_BPM_SYNC_SNAPSHOT_DEPENDENCY
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_BPM_SYNC_SNAPSHOT_DEPENDENCY" (
    p_json_object IN CLOB
) AS 
    json_obj JSON_OBJECT_T;
    p_env_name VARCHAR2(20) DEFAULT NULL;
    p_project_id VARCHAR2(50) DEFAULT NULL;
    p_jsonData JSON_ARRAY_T DEFAULT NULL;
    v_object JSON_OBJECT_T;
    v_element JSON_ELEMENT_T;
    v_size PLS_INTEGER;     
    v_project_name VARCHAR2(200) DEFAULT '';
    v_short_name VARCHAR2(50) DEFAULT '';
    v_is_toolkit VARCHAR2(20) DEFAULT '';
    v_snapshot_id VARCHAR2(50) DEFAULT '';
    v_snapshot_name VARCHAR2(200) DEFAULT '';
    v_snapshot_deps CLOB;

BEGIN
    json_obj := JSON_OBJECT_T.parse(p_json_object);
    p_project_id := json_obj.get_String('projectId');
    p_env_name := json_obj.get_String('env');
    p_jsonData := json_obj.get_Array('jsonData');

    DELETE FROM BPM_SNAPSHOT_DEPENDENCY WHERE PROJECT_ID = p_project_id;
    v_size := p_jsonData.get_size;
    IF (v_size > 0) THEN
        FOR i IN 0.. v_size -1 LOOP
            v_element := p_jsonData.get(i);
            IF (v_element IS NOT NULL) THEN
                v_object := TREAT (v_element AS JSON_OBJECT_T);
                v_project_name:= v_object.get_String('projectName');
                v_short_name:= v_object.get_String('shortName');
                v_is_toolkit:= v_object.get_String('isToolkit');
                v_snapshot_id:= v_object.get_String('snapshotId');
                v_snapshot_name:= v_object.get_String('snapshotName');
                v_snapshot_deps:= TO_CLOB(v_object.get_String('snapshotDeps'));

                INSERT INTO BPM_SNAPSHOT_DEPENDENCY (
                    ENV_NAME,
                    PROJECT_ID,
                    PROJECT_NAME,
                    SHORT_NAME,
                    IS_TOOLKIT,
                    SNAPSHOT_ID,
                    SNAPSHOT_NAME,
                    SNAPSHOT_DEPS                        
                ) VALUES (
                    p_env_name, 
                    p_project_id,
                    v_project_name,
                    v_short_name,
                    v_is_toolkit,
                    v_snapshot_id,
                    v_snapshot_name,
                    v_snapshot_deps
                );
            END IF;                                           
        END LOOP;
    END IF;
    Commit;

END SP_BPM_SYNC_SNAPSHOT_DEPENDENCY;

/
--------------------------------------------------------
--  DDL for Procedure SP_DASH_CN_LIST_COMPLETE
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_DASH_CN_LIST_COMPLETE" (
    P_BRANCH IN VARCHAR2,
    P_USER IN VARCHAR2,
    P_ROLE IN VARCHAR2,
    OUT_DATA OUT SYS_REFCURSOR
) AS
BEGIN
    OPEN OUT_DATA FOR
        WITH BRANCHLIST AS (
            SELECT TRIM(REGEXP_SUBSTR(P_BRANCH, '[^,]+', 1, LEVEL)) AS BRANCH_CODE
            FROM dual
            CONNECT BY LEVEL <= REGEXP_COUNT(P_BRANCH, ',') + 1
        )
        SELECT
            GT.ID id,
            GT.STATUS status,                                           -- Tr?ng thái
            GS.NAME statusName,                                         -- Tr?ng thái hi?n th?
            '<a>' || GT.GNTD_CODE || '</a>' AS gntdCode,                -- Mã gi?i ngân tín d?ng
            GT.BRANCH_CODE branchCode,                                  -- Mã ?VKD - Mã chi nhánh
            GT.BRANCH_NAME branchName,                                  -- Tên ?VKD - Tên chi nhánh
            GT.TRANSACTION_FLOW transactionFlow,                        -- Phân lu?ng phê duy?t
            GCC.NAME transactionFlowName,                               -- Phân lu?ng phê duy?t hi?n th?
            GT.CUSTOMER_CODE customerCode,                              -- Mã Khách Hàng
            GT.CUSTOMER_NAME customerName,                              -- Tên Khách Hàng
            GT.CUSTOMER_CODE || '<br/>' || GT.CUSTOMER_NAME customerDisplay,
            GT.TRANSACTION_TYPE1 transactionType1,
            GTT.NAME transactionType1Name,                              -- Lo?i GD C?p 1
            GT.TRANSACTION_TYPE2 transactionType2,                      -- Lo?i GD C?p 2
            GT.TRANSACTION_TYPE3 transactionType3,                      -- Lo?i GD C?p 3
            GT.PDTD_CODE pdtdCode,                                      -- Mã PDTD (LOS, BPM, ECM)
            LOWER(GT.APPROVER_SUGGEST) approverSuggest,                        -- User PD ???c ?? xu?t
            LOWER(GT.PROCESSING_USER) processingUser,                          -- User x? lý
            GT.PROCESS_GROUP processGroup,                              -- Nhóm x? lý t?p trung
            LOWER(GT.PROCESSING_OWNER) processingOwner,                        -- User ?? xu?t
            CASE 
                WHEN GT.PROCESSING_DATE IS NOT NULL 
                THEN TO_CHAR(GT.PROCESSING_DATE, 'DD/MM/YYYY') || '<br>' || TO_CHAR(GT.PROCESSING_DATE, 'HH24:MI')
                ELSE ''
            END AS processingDate,                                      -- Ngày t?i tr?ng thái ch? x? lý
            LOWER(GT.APPROVAL_BY) approvalBy,                                  -- Ng??i phê duy?t
            GT.APPROVAL_DATE approvalDate                               -- Th?i gian phê duy?t
        FROM
            GNCN_TRANSACTION GT
            LEFT JOIN GNCN_STATUS GS 
                ON GT.STATUS = GS.CODE
            LEFT JOIN GNCN_CONFIG_COMMONS GCC 
                ON GT.TRANSACTION_FLOW = GCC.CODE 
                AND GCC.SCOPE = 'TRAN_FLOW'
            LEFT JOIN GNCN_TRANSACTION_TYPE GTT 
                ON GT.TRANSACTION_TYPE1 = GTT.CODE 
                AND GTT.USE_STATUS = 1 
                AND GTT.level_type = 1
        WHERE
            (
                EXISTS (SELECT 1 FROM BRANCHLIST b WHERE b.BRANCH_CODE = 'ALL_BRANCH')
                OR GT.BRANCH_CODE IN (SELECT b.BRANCH_CODE FROM BRANCHLIST b)
            )
            AND TRUNC(GT.APPROVAL_DATE) = TRUNC(SYSDATE)
            AND GT.STATUS = 'GNCN_HOAN_THANH'
            AND (LOWER(GT.APPROVAL_BY) = P_USER OR LOWER(GT.PROCESSING_OWNER) = P_USER);
END SP_DASH_CN_LIST_COMPLETE;

/
--------------------------------------------------------
--  DDL for Procedure SP_DASH_CN_LIST_MISSING
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_DASH_CN_LIST_MISSING" (
    P_BRANCH IN VARCHAR2,
    P_USER IN VARCHAR2,
    P_ROLE IN VARCHAR2,
    OUT_DATA OUT SYS_REFCURSOR
) AS 
BEGIN
    OPEN OUT_DATA FOR
        WITH BRANCHLIST AS (
            SELECT TRIM(REGEXP_SUBSTR(P_BRANCH, '[^,]+', 1, LEVEL)) AS BRANCH_CODE
            FROM dual
            CONNECT BY LEVEL <= REGEXP_COUNT(P_BRANCH, ',') + 1
        )
        /* ??n h?n T */
        SELECT
            d.ID id,
            GCD.STATUS status,                                          -- Tr?ng thái
            GS.NAME statusName,                                         -- Tr?ng thái hi?n th?
            '<a>' || GCD.GNTD_CODE || '</a>' AS gntdCode,               -- Mã gi?i ngân tín d?ng
            GCD.BRANCH_CODE branchCode,                                 -- Mã ?VKD - Mã chi nhánh
            GCD.BRANCH_NAME branchName,                                 -- Tên ?VKD - Tên chi nhánh
            GCD.TRANSACTION_FLOW transactionFlow,                       -- Phân lu?ng phê duy?t
            GCC.NAME transactionFlowName,                               -- Phân lu?ng phê duy?t hi?n th?
            GCD.CUSTOMER_CODE customerCode,                             -- Mã Khách Hàng
            GCD.CUSTOMER_NAME customerName,                             -- Tên Khách Hàng
            GCD.CUSTOMER_CODE || '<br/>' || GCD.CUSTOMER_NAME customerDisplay,
            GCD.TRANSACTION_TYPE1 transactionType1,
            GTT.NAME transactionType1Name,                               -- Lo?i GD C?p 3
            GCD.PDTD_CODE pdtdCode,                                     -- User PD ???c ?? xu?t
            LOWER(GCD.PROCESSING_USERNAME) processingUser,                     -- User x? lý
            LOWER(GT.APPROVER_SUGGEST) approverSuggest,
            CASE 
                WHEN GCD.APPROVAL_DATE IS NOT NULL THEN 
                    TO_CHAR(GCD.APPROVAL_DATE, 'DD/MM/YYYY') || '<br>' || TO_CHAR(GCD.APPROVAL_DATE, 'HH24:MI')
                ELSE ''
            END AS processingDate,                                      -- Ngày t?i tr?ng thái ch? x? lý
            LOWER(GCD.APPROVAL_BY) approvalBy,                                 -- Ng??i phê duy?t
            GCD.APPROVAL_DATE approvalDate,                              -- Th?i gian phê duy?t
            d.DEADLINE expiryDate
        FROM
            GNCN_CA_DISBURSEMENT_DOCUMENTS d
            INNER JOIN GNCN_CA_DISBURSEMENT GCD ON GCD.GNTD_CODE = d.GNTD_CODE

            LEFT JOIN GNCN_STATUS GS ON GCD.STATUS = GS.CODE
            LEFT JOIN GNCN_CONFIG_COMMONS GCC 
                ON GCD.TRANSACTION_FLOW = GCC.CODE 
                AND GCC.SCOPE = 'TRAN_FLOW'
            LEFT JOIN GNCN_TRANSACTION_TYPE GTT
                ON GCD.TRANSACTION_TYPE1 = GTT.CODE 
                AND GTT.USE_STATUS = 1 
                AND GTT.level_type = 1
            LEFT JOIN GNCN_TRANSACTION GT ON d.GNTD_CODE = GT.GNTD_CODE
        WHERE
--            GCD.BRANCH_CODE = P_BRANCH
            (EXISTS (SELECT 1 FROM BRANCHLIST b WHERE b.BRANCH_CODE = 'ALL_BRANCH')
             OR GCD.BRANCH_CODE IN (SELECT b.BRANCH_CODE FROM BRANCHLIST b))
            AND d.STATUS <> 'HSSGN_HOAN_THANH'
            AND d.STATUS <> 'HSSGN_HUY_DK_BO_SUNG'
            AND TRUNC(d.DEADLINE) = TRUNC(SYSDATE)
            AND (
                ---------------------------------------------------------------------
                -- 1. CV HTTD DVKD
                ---------------------------------------------------------------------
                (
                    INSTR(P_ROLE, 'GNCN_CV_HTTD_DVKD') > 0
                    AND d.STATUS = 'HSSGN_CHO_BO_SUNG'
                    AND LOWER(d.CREATED_BY) = P_USER
                )
                OR
                ---------------------------------------------------------------------
                -- 2. QL HTTD DVKD
                ---------------------------------------------------------------------
                (
                    INSTR(P_ROLE, 'GNCN_QL_HTTD_DVKD') > 0
                    AND (
                        (d.STATUS = 'HSSGN_CHO_BO_SUNG' AND LOWER(d.CREATED_BY) = P_USER)
                        OR (d.STATUS = 'HSSGN_CHO_PHE_DUYET' AND LOWER(d.assignee_user_by) = P_USER)
                    )
                )
                OR
                ---------------------------------------------------------------------
                -- 3. CV HTTD HO ho?c QL HTTD HO
                ---------------------------------------------------------------------
                (
                    (INSTR(P_ROLE, 'GNCN_CV_HTTD_HO') > 0 OR INSTR(P_ROLE, 'GNCN_QL_HTTD_HO') > 0)
                    AND d.STATUS = 'HSSGN_CHO_PHE_DUYET'
                    AND LOWER(d.assignee_user_by) = P_USER
                )
            )

            /* S?p ??n h?n (T+3) */
           UNION ALL 
        SELECT
            d.ID id,
            GCD.STATUS status,                                          -- Tr?ng thái
            GS.NAME statusName,                                         -- Tr?ng thái hi?n th?
            '<a>' || GCD.GNTD_CODE || '</a>' AS gntdCode,               -- Mã gi?i ngân tín d?ng
            GCD.BRANCH_CODE branchCode,                                 -- Mã ?VKD - Mã chi nhánh
            GCD.BRANCH_NAME branchName,                                 -- Tên ?VKD - Tên chi nhánh
            GCD.TRANSACTION_FLOW transactionFlow,                       -- Phân lu?ng phê duy?t
            GCC.NAME transactionFlowName,                               -- Phân lu?ng phê duy?t hi?n th?
            GCD.CUSTOMER_CODE customerCode,                             -- Mã Khách Hàng
            GCD.CUSTOMER_NAME customerName,                             -- Tên Khách Hàng
            GCD.CUSTOMER_CODE || '<br/>' || GCD.CUSTOMER_NAME customerDisplay,
            GCD.TRANSACTION_TYPE1 transactionType1,
            GT.NAME transactionType1Name,                               -- Lo?i GD C?p 3
            GCD.PDTD_CODE pdtdCode,                                     -- User PD ???c ?? xu?t
            LOWER(GCD.PROCESSING_USERNAME) processingUser,                     -- User x? lý
            LOWER(GT.APPROVER_SUGGEST) approverSuggest,
            CASE 
                WHEN GCD.APPROVAL_DATE IS NOT NULL THEN 
                    TO_CHAR(GCD.APPROVAL_DATE, 'DD/MM/YYYY') || '<br>' || TO_CHAR(GCD.APPROVAL_DATE, 'HH24:MI')
                ELSE ''
            END AS processingDate,                                      -- Ngày t?i tr?ng thái ch? x? lý
            LOWER(GCD.APPROVAL_BY) approvalBy,                                 -- Ng??i phê duy?t
            GCD.APPROVAL_DATE approvalDate,                              -- Th?i gian phê duy?t
            d.DEADLINE expiryDate
        FROM
            GNCN_CA_DISBURSEMENT_DOCUMENTS d
            INNER JOIN GNCN_CA_DISBURSEMENT GCD ON GCD.GNTD_CODE = d.GNTD_CODE

            LEFT JOIN GNCN_STATUS GS ON GCD.STATUS = GS.CODE
            LEFT JOIN GNCN_CONFIG_COMMONS GCC 
                ON GCD.TRANSACTION_FLOW = GCC.CODE 
                AND GCC.SCOPE = 'TRAN_FLOW'
            LEFT JOIN GNCN_TRANSACTION_TYPE GT 
                ON GCD.TRANSACTION_TYPE1 = GT.CODE 
                AND GT.USE_STATUS = 1 
                AND GT.level_type = 1
            LEFT JOIN GNCN_TRANSACTION GT ON d.GNTD_CODE = GT.GNTD_CODE
        WHERE
--            GCD.BRANCH_CODE = P_BRANCH
            (EXISTS (SELECT 1 FROM BRANCHLIST b WHERE b.BRANCH_CODE = 'ALL_BRANCH')
             OR GCD.BRANCH_CODE IN (SELECT b.BRANCH_CODE FROM BRANCHLIST b))
            AND d.STATUS <> 'HSSGN_HOAN_THANH'
            AND d.STATUS <> 'HSSGN_HUY_DK_BO_SUNG'
            AND TRUNC(d.DEADLINE) BETWEEN TRUNC(SYSDATE) + 1 AND TRUNC(SYSDATE) + 4
            AND (
                ---------------------------------------------------------------------
                -- 1. CV HTTD DVKD
                ---------------------------------------------------------------------
                (
                    INSTR(P_ROLE, 'GNCN_CV_HTTD_DVKD') > 0
                    AND d.STATUS = 'HSSGN_CHO_BO_SUNG'
                    AND LOWER(d.CREATED_BY) = P_USER
                )
                OR
                ---------------------------------------------------------------------
                -- 2. QL HTTD DVKD
                ---------------------------------------------------------------------
                (
                    INSTR(P_ROLE, 'GNCN_QL_HTTD_DVKD') > 0
                    AND (
                        (d.STATUS = 'HSSGN_CHO_BO_SUNG' AND LOWER(d.CREATED_BY) = P_USER)
                        OR (d.STATUS = 'HSSGN_CHO_PHE_DUYET' AND LOWER(d.assignee_user_by) = P_USER)
                    )
                )
                OR
                ---------------------------------------------------------------------
                -- 3. CV HTTD HO ho?c QL HTTD HO
                ---------------------------------------------------------------------
                (
                    (INSTR(P_ROLE, 'GNCN_CV_HTTD_HO') > 0 OR INSTR(P_ROLE, 'GNCN_QL_HTTD_HO') > 0)
                    AND d.STATUS = 'HSSGN_CHO_PHE_DUYET'
                    AND LOWER(d.assignee_user_by) = P_USER
                )
            )
             /* Quá h?n > T */
           UNION ALL 
        SELECT
            d.ID id,
            GCD.STATUS status,                                          -- Tr?ng thái
            GS.NAME statusName,                                         -- Tr?ng thái hi?n th?
            '<a>' || GCD.GNTD_CODE || '</a>' AS gntdCode,               -- Mã gi?i ngân tín d?ng
            GCD.BRANCH_CODE branchCode,                                 -- Mã ?VKD - Mã chi nhánh
            GCD.BRANCH_NAME branchName,                                 -- Tên ?VKD - Tên chi nhánh
            GCD.TRANSACTION_FLOW transactionFlow,                       -- Phân lu?ng phê duy?t
            GCC.NAME transactionFlowName,                               -- Phân lu?ng phê duy?t hi?n th?
            GCD.CUSTOMER_CODE customerCode,                             -- Mã Khách Hàng
            GCD.CUSTOMER_NAME customerName,                             -- Tên Khách Hàng
            GCD.CUSTOMER_CODE || '<br/>' || GCD.CUSTOMER_NAME customerDisplay,
            GCD.TRANSACTION_TYPE1 transactionType1,
            GT.NAME transactionType1Name,                               -- Lo?i GD C?p 3
            GCD.PDTD_CODE pdtdCode,                                     -- User PD ???c ?? xu?t
            LOWER(GCD.PROCESSING_USERNAME) processingUser,                     -- User x? lý
            LOWER(GT.APPROVER_SUGGEST) approverSuggest,
            CASE 
                WHEN GCD.APPROVAL_DATE IS NOT NULL THEN 
                    TO_CHAR(GCD.APPROVAL_DATE, 'DD/MM/YYYY') || '<br>' || TO_CHAR(GCD.APPROVAL_DATE, 'HH24:MI')
                ELSE ''
            END AS processingDate,                                      -- Ngày t?i tr?ng thái ch? x? lý
            LOWER(GCD.APPROVAL_BY) approvalBy,                                 -- Ng??i phê duy?t
            GCD.APPROVAL_DATE approvalDate,                              -- Th?i gian phê duy?t
            d.DEADLINE expiryDate
        FROM
            GNCN_CA_DISBURSEMENT_DOCUMENTS d
            INNER JOIN GNCN_CA_DISBURSEMENT GCD ON GCD.GNTD_CODE = d.GNTD_CODE

            LEFT JOIN GNCN_STATUS GS ON GCD.STATUS = GS.CODE
            LEFT JOIN GNCN_CONFIG_COMMONS GCC 
                ON GCD.TRANSACTION_FLOW = GCC.CODE 
                AND GCC.SCOPE = 'TRAN_FLOW'
            LEFT JOIN GNCN_TRANSACTION_TYPE GT 
                ON GCD.TRANSACTION_TYPE1 = GT.CODE 
                AND GT.USE_STATUS = 1 
                AND GT.level_type = 1
            LEFT JOIN GNCN_TRANSACTION GT ON d.GNTD_CODE = GT.GNTD_CODE
        WHERE
--            GCD.BRANCH_CODE = P_BRANCH
            (EXISTS (SELECT 1 FROM BRANCHLIST b WHERE b.BRANCH_CODE = 'ALL_BRANCH')
             OR GCD.BRANCH_CODE IN (SELECT b.BRANCH_CODE FROM BRANCHLIST b))
            AND d.STATUS <> 'HSSGN_HOAN_THANH'
            AND d.STATUS <> 'HSSGN_HUY_DK_BO_SUNG'
            AND TRUNC(d.DEADLINE) < TRUNC(SYSDATE)
            AND (
                ---------------------------------------------------------------------
                -- 1. CV HTTD DVKD
                ---------------------------------------------------------------------
                (
                    INSTR(P_ROLE, 'GNCN_CV_HTTD_DVKD') > 0
                    AND d.STATUS = 'HSSGN_CHO_BO_SUNG'
                    AND LOWER(d.CREATED_BY) = P_USER
                )
                OR
                ---------------------------------------------------------------------
                -- 2. QL HTTD DVKD
                ---------------------------------------------------------------------
                (
                    INSTR(P_ROLE, 'GNCN_QL_HTTD_DVKD') > 0
                    AND (
                        (d.STATUS = 'HSSGN_CHO_BO_SUNG' AND LOWER(d.CREATED_BY) = P_USER)
                        OR (d.STATUS = 'HSSGN_CHO_PHE_DUYET' AND LOWER(d.assignee_user_by) = P_USER)
                    )
                )
                OR
                ---------------------------------------------------------------------
                -- 3. CV HTTD HO ho?c QL HTTD HO
                ---------------------------------------------------------------------
                (
                    (INSTR(P_ROLE, 'GNCN_CV_HTTD_HO') > 0 OR INSTR(P_ROLE, 'GNCN_QL_HTTD_HO') > 0)
                    AND d.STATUS = 'HSSGN_CHO_PHE_DUYET'
                    AND LOWER(d.assignee_user_by) = P_USER
                )
            );
END SP_DASH_CN_LIST_MISSING;

/
--------------------------------------------------------
--  DDL for Procedure SP_DASH_CN_LIST_PENDING
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_DASH_CN_LIST_PENDING" (
    P_BRANCH IN VARCHAR2,
    P_USER IN VARCHAR2,
    P_ROLE IN VARCHAR2,
    OUT_DATA OUT SYS_REFCURSOR
) AS BEGIN OPEN OUT_DATA FOR
WITH BRANCHLIST AS (
        SELECT TRIM(REGEXP_SUBSTR(P_BRANCH, '[^,]+', 1, LEVEL)) AS BRANCH_CODE
        FROM dual
        CONNECT BY LEVEL <= REGEXP_COUNT(P_BRANCH, ',') + 1
    )
SELECT
    GT.ID id,
    GT.STATUS status,
    -- Tr?ng thái
    GS.NAME statusName,
    -- Tr?ng thái hi?n th?
    '<a>' || GT.GNTD_CODE || '</a>' AS gntdCode,
--    GT.GNTD_CODE AS gntdCode,
    -- Mã gi?i ngân tín d?ng
    GT.BRANCH_CODE branchCode,
    -- Mã ?VKD - Mã chi nhánh
    GT.BRANCH_NAME branchName,
    -- Tên ?VKD - Tên chi nhánh
    GT.TRANSACTION_FLOW transactionFlow,
    -- Phân lu?ng phê duy?t
    GCC.NAME transactionFlowName,
    -- Phân lu?ng phê duy?t hi?n th?
    GT.CUSTOMER_CODE customerCode,
    -- Mã Khách Hàng
    GT.CUSTOMER_NAME customerName,
    -- Tên Khách Hàng
    GT.CUSTOMER_CODE || '<br/>' || GT.CUSTOMER_NAME customerDisplay,
    GT.TRANSACTION_TYPE1 transactionType1,
    GTT.NAME transactionType1Name,
    -- Lo?i GD C?p 1
    GT.TRANSACTION_TYPE2 transactionType2,
    -- Lo?i GD C?p 2
    GT.TRANSACTION_TYPE3 transactionType3,
    -- Lo?i GD C?p 3
    GT.PDTD_CODE pdtdCode,
    -- Mã PDTD (LOS, BPM, ECM)
    LOWER(GT.APPROVER_SUGGEST) approverSuggest,
    -- User PD ???c ?? xu?t
    LOWER(GT.PROCESSING_USER) processingUser,
    -- User x? lý
    GT.PROCESS_GROUP processGroup,
    -- Nhóm x? lý t?p trung
    LOWER(GT.PROCESSING_OWNER) processingOwner,
    -- User ?? xu?t
    CASE
        WHEN GT.PROCESSING_DATE IS NOT NULL THEN TO_CHAR(GT.PROCESSING_DATE, 'DD/MM/YYYY') || '<br>' || TO_CHAR(GT.PROCESSING_DATE, 'HH24:MI')
        ELSE ''
    END AS processingDate,
    -- L?u ngày t?i tr?ng thái ch? x? lý
    LOWER(GT.APPROVAL_BY) approvalBy,
    -- Ng??i phê duy?t
    GT.APPROVAL_DATE approvalDate,
    -- Th?i gian phê duy?t
    GT.YELLOW_FLAG_DATE yellowFlagDate,
    GT.RED_FLAG_DATE redFlagDate
FROM
    GNCN_TRANSACTION GT
    LEFT JOIN GNCN_STATUS GS ON GT.STATUS = GS.CODE
    LEFT JOIN GNCN_CONFIG_COMMONS GCC ON GT.TRANSACTION_FLOW = GCC.CODE
    AND GCC.SCOPE = 'TRAN_FLOW'
    LEFT JOIN GNCN_TRANSACTION_TYPE GTT ON GT.TRANSACTION_TYPE1 = GTT.CODE
    AND GTT.USE_STATUS = 1
    AND GTT.level_type = 1
WHERE
    ( P_BRANCH = 'ALL_BRANCH' OR EXISTS (SELECT 1 FROM BRANCHLIST B WHERE B.BRANCH_CODE = GT.BRANCH_CODE))
    AND (TRUNC(GT.PROCESSING_DATE) >= TRUNC(SYSDATE) - 7 or GT.PROCESSING_DATE IS NULL)
--    AND (TRUNC(GT.PROCESSING_DATE) = TRUNC(SYSDATE) or GT.PROCESSING_DATE IS NULL)
    AND GT.STATUS NOT IN ('GNCN_HOAN_THANH', 'GNCN_HUY')
    AND (
        -------------------------------------------------
        -- 1. Các Role Nhân viên (CV HTTD)
        -------------------------------------------------
        (
            (
                INSTR(P_ROLE, 'GNCN_CV_HTTD_DVKD') > 0
                OR INSTR(P_ROLE, 'GNCN_CV_HTTD_HO') > 0
            )
            AND (GT.STATUS IN ('GNCN_KHOI_TAO', 'GNCN_CHO_BO_SUNG', 'GNCN_LOI_HACH_TOAN_HAN_MUC', 'GNCN_LOI_HACH_TOAN_KHOAN_VAY') AND LOWER(GT.CREATED_BY) = P_USER)
        )
        OR -------------------------------------------------
        -- 2. Các Role Qu?n lý (QL HTTD)
        -------------------------------------------------
        (
            (
                INSTR(P_ROLE, 'GNCN_QL_HTTD_DVKD') > 0
                OR INSTR(P_ROLE, 'GNCN_QL_HTTD_HO') > 0
            )
            AND GT.STATUS IN ('GNCN_CHO_XU_LY', 'GNCN_LOI_CHUYEN_TIEN', 'GNCN_HOAN_TAT_KHOAN_VAY')
            AND ( (GT.USER_LOCKED IS NOT NULL AND LOWER(GT.USER_LOCKED) = P_USER) or (GT.USER_LOCKED IS NULL AND GT.APPROVER_SUGGEST IS NOT NULL AND LOWER(GT.APPROVER_SUGGEST) = P_USER) )
        )
    );

END SP_DASH_CN_LIST_PENDING;

/
--------------------------------------------------------
--  DDL for Procedure SP_DASH_CN_LIST_TRACKING
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_DASH_CN_LIST_TRACKING" (
    P_BRANCH   IN  VARCHAR2,
    P_USER     IN  VARCHAR2,
    P_ROLE     IN  VARCHAR2,
    OUT_DATA   OUT SYS_REFCURSOR
) AS
BEGIN
    
    OPEN OUT_DATA FOR
    WITH BRANCHLIST AS (
        SELECT TRIM(REGEXP_SUBSTR(P_BRANCH, '[^,]+', 1, LEVEL)) AS BRANCH_CODE
        FROM dual
        CONNECT BY LEVEL <= REGEXP_COUNT(P_BRANCH, ',') + 1
    )
        SELECT
            GT.ID                                AS id,
            GT.STATUS                            AS status,              -- Tr?ng thái
            GS.NAME                              AS statusName,          -- Tr?ng thái hi?n th?
            '<a>' || GT.GNTD_CODE || '</a>'      AS gntdCode,            -- Mã gi?i ngân tín d?ng
            GT.BRANCH_CODE                       AS branchCode,          -- Mã ?VKD - Mã chi nhánh
            GT.BRANCH_NAME                       AS branchName,          -- Tên ?VKD - Tên chi nhánh
            GT.TRANSACTION_FLOW                  AS transactionFlow,     -- Phân lu?ng phê duy?t
            GCC.NAME                             AS transactionFlowName, -- Phân lu?ng phê duy?t hi?n th?
            GT.CUSTOMER_CODE                     AS customerCode,        -- Mã Khách Hàng
            GT.CUSTOMER_NAME                     AS customerName,        -- Tên Khách Hàng
            GT.CUSTOMER_CODE || '<br/>' || GT.CUSTOMER_NAME AS customerDisplay,
            GT.TRANSACTION_TYPE1                 AS transactionType1,
            GTT.NAME                             AS transactionType1Name,-- Lo?i GD C?p 1
            GT.TRANSACTION_TYPE2                 AS transactionType2,    -- Lo?i GD C?p 2
            GT.TRANSACTION_TYPE3                 AS transactionType3,    -- Lo?i GD C?p 3
            GT.PDTD_CODE                         AS pdtdCode,            -- Mã PDTD (LOS, BPM, ECM)
            LOWER(GT.APPROVER_SUGGEST)           AS approverSuggest,     -- User PD ???c ?? xu?t
            LOWER(GT.PROCESSING_USER)            AS processingUser,      -- User x? lý
            GT.PROCESS_GROUP                     AS processGroup,        -- Nhóm x? lý t?p trung
            LOWER(GT.PROCESSING_OWNER)           AS processingOwner,     -- User phân công
            CASE 
                WHEN GT.PROCESSING_DATE IS NOT NULL THEN
                    TO_CHAR(GT.PROCESSING_DATE, 'DD/MM/YYYY') || '<br>' || 
                    TO_CHAR(GT.PROCESSING_DATE, 'HH24:MI')
                ELSE ''
            END                                  AS processingDate,      -- Ngày t?i tr?ng thái ch? x? lý
            LOWER(GT.APPROVAL_BY)                AS approvalBy,          -- Ng??i phê duy?t
            GT.APPROVAL_DATE                     AS approvalDate,        -- Th?i gian phê duy?t
            GT.YELLOW_FLAG_DATE                  AS yellowFlagDate,
            GT.RED_FLAG_DATE                     AS redFlagDate
        FROM
            GNCN_TRANSACTION GT
            LEFT JOIN GNCN_STATUS GS 
                ON GT.STATUS = GS.CODE
            LEFT JOIN GNCN_CONFIG_COMMONS GCC 
                ON GT.TRANSACTION_FLOW = GCC.CODE 
               AND GCC.SCOPE = 'TRAN_FLOW'
            LEFT JOIN GNCN_TRANSACTION_TYPE GTT 
                ON GT.TRANSACTION_TYPE1 = GTT.CODE  
               AND GTT.level_type = 1 
               AND GTT.USE_STATUS = 1
        WHERE
            (   P_BRANCH = 'ALL_BRANCH'
                OR EXISTS (SELECT 1 FROM BRANCHLIST B WHERE B.BRANCH_CODE = GT.BRANCH_CODE)
            )
            AND GT.STATUS NOT IN ('GNCN_HOAN_THANH', 'GNCN_HUY')
            --            AND GT.PROCESSING_DATE >= TRUNC(SYSDATE) - 7
            AND ( INSTR(LOWER(GT.VIEWER), P_USER) > 0 AND TRUNC( (SELECT MAX(GTH.CREATED_DATE) FROM GNCN_TRANSACTION_HISTORY GTH WHERE GTH.GNTD_CODE = GT.GNTD_CODE AND LOWER(GTH.CREATED_BY) = P_USER) ) >= TRUNC(SYSDATE) - 7 )
            AND GT.GNTD_CODE NOT IN (
                SELECT GNTD_CODE
                FROM GNCN_TRANSACTION
                WHERE 
--                BRANCH_CODE = P_BRANCH
                (   P_BRANCH = 'ALL_BRANCH'
                    OR EXISTS (SELECT 1 FROM BRANCHLIST B WHERE B.BRANCH_CODE = GT.BRANCH_CODE)
                )
                  AND STATUS NOT IN ('GNCN_HOAN_THANH', 'GNCN_HUY')
                  AND (
                        -------------------------------------------------
                        -- 1. Role Nhân viên (CV HTTD)
                        -------------------------------------------------
                        (
                            (
                                INSTR(P_ROLE, 'GNCN_CV_HTTD_DVKD') > 0
                                OR INSTR(P_ROLE, 'GNCN_CV_HTTD_HO') > 0
                            )
                            AND STATUS IN (
                                'GNCN_KHOI_TAO',
                                'GNCN_CHO_BO_SUNG',
                                'GNCN_LOI_HACH_TOAN_HAN_MUC',
                                'GNCN_LOI_HACH_TOAN_KHOAN_VAY'
                            )
                            AND LOWER(CREATED_BY) = P_USER
                        )
                        OR
                        -------------------------------------------------
                        -- 2. Role Qu?n lý (QL HTTD)
                        -------------------------------------------------
                        (
                            (
                                INSTR(P_ROLE, 'GNCN_QL_HTTD_DVKD') > 0
                                OR INSTR(P_ROLE, 'GNCN_QL_HTTD_HO') > 0
                            )
                            AND STATUS IN (
                                'GNCN_CHO_XU_LY',
                                'GNCN_LOI_CHUYEN_TIEN',
                                'GNCN_HOAN_TAT_KHOAN_VAY'
                            )
                            AND (
                                (USER_LOCKED IS NOT NULL AND LOWER(USER_LOCKED) = P_USER)
                                OR 
                                (USER_LOCKED IS NULL AND APPROVER_SUGGEST IS NOT NULL AND LOWER(APPROVER_SUGGEST) = P_USER)
                            )
                        )
                    )
            );
END SP_DASH_CN_LIST_TRACKING;

/
--------------------------------------------------------
--  DDL for Procedure SP_DASH_GR_LIST_DHT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_DASH_GR_LIST_DHT" (
    P_USERLIST    IN VARCHAR2,
    P_BRANCH      IN VARCHAR2,
    P_POSITION_OP IN VARCHAR2,
    OUT_DATA      OUT SYS_REFCURSOR
) AS 
BEGIN
    OPEN OUT_DATA FOR
        WITH USERLIST AS (
            SELECT TRIM(REGEXP_SUBSTR(P_USERLIST, '[^,]+', 1, LEVEL)) AS USERNAME
            FROM dual
            CONNECT BY LEVEL <= REGEXP_COUNT(P_USERLIST, ',') + 1
        ),
        BRANCHLIST AS (
            SELECT TRIM(REGEXP_SUBSTR(P_BRANCH, '[^,]+', 1, LEVEL)) AS BRANCH_CODE
            FROM dual
            CONNECT BY LEVEL <= REGEXP_COUNT(P_BRANCH, ',') + 1
        )
        SELECT
            GT.ID id,
            GT.STATUS status,
            GS.NAME statusName,
            '<a>' || GT.GNTD_CODE || '</a>' AS gntdCode,
            GT.BRANCH_CODE branchCode,
            GT.BRANCH_NAME branchName,
            GT.TRANSACTION_FLOW transactionFlow,
            GCC.NAME transactionFlowName,
            GT.CUSTOMER_CODE customerCode,
            GT.CUSTOMER_NAME customerName,
            GT.CUSTOMER_CODE || '<br/>' || GT.CUSTOMER_NAME customerDisplay,
            GT.TRANSACTION_TYPE1 transactionType1,
            GTT.NAME transactionType1Name,
            GT.TRANSACTION_TYPE2 transactionType2,
            GT.TRANSACTION_TYPE3 transactionType3,
            GT.PDTD_CODE pdtdCode,
            LOWER(GT.APPROVER_SUGGEST) approverSuggest,
            LOWER(GT.PROCESSING_USER) processingUser,
            GT.PROCESS_GROUP processGroup,
            LOWER(GT.PROCESSING_OWNER) processingOwer,
            CASE 
                WHEN GT.PROCESSING_DATE IS NOT NULL 
                THEN TO_CHAR(GT.PROCESSING_DATE, 'DD/MM/YYYY') || '<br>' || TO_CHAR(GT.PROCESSING_DATE, 'HH24:MI')
                ELSE ''
            END AS processingDate, -- L?u ngày t?i tr?ng thái ch? x? lý
            LOWER(GT.APPROVAL_BY) approvalBy,
            GT.APPROVAL_DATE approvalDate,
            GT.YELLOW_FLAG_DATE yellowFlagDate,
            GT.RED_FLAG_DATE redFlagDate,
            'RB.CA' departmentProcess
        FROM
            GNCN_TRANSACTION GT
            LEFT JOIN GNCN_STATUS GS 
                ON GT.STATUS = GS.CODE
            LEFT JOIN GNCN_CONFIG_COMMONS GCC 
                ON GT.TRANSACTION_FLOW = GCC.CODE 
                AND GCC.SCOPE = 'TRAN_FLOW'
            LEFT JOIN GNCN_TRANSACTION_TYPE GTT 
                ON GT.TRANSACTION_TYPE1 = GTT.CODE 
                AND GTT.USE_STATUS = 1 
                AND GTT.level_type = 1
        WHERE
            GT.APPROVAL_DATE >= TRUNC(SYSDATE) AND GT.APPROVAL_DATE < TRUNC(SYSDATE) + 1 AND
             (
                EXISTS (SELECT 1 FROM BRANCHLIST b WHERE b.BRANCH_CODE = 'ALL_BRANCH')
                OR GT.BRANCH_CODE IN (SELECT b.BRANCH_CODE FROM BRANCHLIST b)
            )
            AND (
                (P_POSITION_OP IS NOT NULL 
                 AND GT.APPROVAL_BY IS NOT NULL 
                 AND LOWER(GT.APPROVAL_BY) IN (SELECT USERNAME FROM USERLIST)
                )
                OR 
                (P_POSITION_OP IS NULL 
                 AND (
                        (GT.PROCESSING_OWNER IS NOT NULL AND LOWER(GT.PROCESSING_OWNER) IN (SELECT USERNAME FROM USERLIST)) 
                        OR (GT.APPROVAL_BY IS NOT NULL AND LOWER(GT.APPROVAL_BY) IN (SELECT USERNAME FROM USERLIST))
                    )
                )
            )
            AND GT.TRANSACTION_TYPE1 IN ('Giaingankhoanvay','Giainganthauchi','Khoitaohanmuc','NhapvaduyetFCC','Khac')
            AND GT.STATUS = 'GNCN_HOAN_THANH';
END SP_DASH_GR_LIST_DHT;

