    OUT_DATA   OUT SYS_REFCURSOR
) AS 
BEGIN
    OPEN OUT_DATA FOR
        WITH USERLIST AS (
            SELECT TRIM(REGEXP_SUBSTR(P_USERLIST, '[^,]+', 1, LEVEL)) AS USERNAME
            FROM dual
            CONNECT BY LEVEL <= REGEXP_COUNT(P_USERLIST, ',') + 1
        ),
        BRANCHLIST AS (
            SELECT TRIM(REGEXP_SUBSTR(P_BRANCH, '[^,]+', 1, LEVEL)) AS BRANCH_CODE
            FROM dual
            CONNECT BY LEVEL <= REGEXP_COUNT(P_BRANCH, ',') + 1
        )
        SELECT
            GT.ID id,
            GT.STATUS status,                                           -- Tr?ng thái
            GS.NAME statusName,                                         -- Tr?ng thái hi?n th?
            '<a>' || GT.GNTD_CODE || '</a>' AS gntdCode,                -- Mã gi?i ngân tín d?ng
            GT.BRANCH_CODE branchCode,                                  -- Mã ?VKD - Mã chi nhánh
            GT.BRANCH_NAME branchName,                                  -- Tên ?VKD - Tên chi nhánh
            GT.TRANSACTION_FLOW transactionFlow,                        -- Phân lu?ng phê duy?t
            GCC.NAME transactionFlowName,                               -- Phân lu?ng phê duy?t hi?n th?
            GT.CUSTOMER_CODE customerCode,                              -- Mã Khách Hàng
            GT.CUSTOMER_NAME customerName,                              -- Tên Khách Hàng
            GT.CUSTOMER_CODE || '<br/>' || GT.CUSTOMER_NAME customerDisplay,
            GT.TRANSACTION_TYPE1 transactionType1,
            GTT.NAME transactionType1Name,                              -- Lo?i GD C?p 1
            GT.TRANSACTION_TYPE2 transactionType2,                      -- Lo?i GD C?p 2
            GT.TRANSACTION_TYPE3 transactionType3,                      -- Lo?i GD C?p 3
            GT.PDTD_CODE pdtdCode,                                      -- Mã PDTD (LOS, BPM, ECM)
            LOWER(GT.APPROVER_SUGGEST) approverSuggest,                 -- User PD ???c ?? xu?t
            CASE 
                WHEN GT.USER_LOCKED IS NOT NULL THEN LOWER(GT.USER_LOCKED)
                WHEN GT.APPROVAL_BY IS NOT NULL THEN LOWER(GT.APPROVAL_BY)
                WHEN GT.APPROVER_SUGGEST IS NOT NULL THEN LOWER(GT.APPROVER_SUGGEST)
                ELSE ''
            END AS processingUser, 

            GT.PROCESS_GROUP processGroup,                              -- Nhóm x? lý t?p trung
            GT.PROCESSING_OWNER processingOwer,                         -- User ?? xu?t
            CASE 
                WHEN GT.PROCESSING_DATE IS NOT NULL 
                THEN TO_CHAR(GT.PROCESSING_DATE, 'DD/MM/YYYY') || '<br>' || TO_CHAR(GT.PROCESSING_DATE, 'HH24:MI')
                ELSE ''
            END AS processingDate,                                      -- Ngày t?i tr?ng thái ch? x? lý
            GT.APPROVAL_BY approvalBy,                                  -- Ng??i phê duy?t
            GT.APPROVAL_DATE approvalDate,                              -- Th?i gian phê duy?t
            GT.YELLOW_FLAG_DATE yellowFlagDate,
            GT.RED_FLAG_DATE redFlagDate,
            'RB.CA' departmentProcess
        FROM
            GNCN_TRANSACTION GT
            LEFT JOIN GNCN_STATUS GS 
                ON GT.STATUS = GS.CODE
            LEFT JOIN GNCN_CONFIG_COMMONS GCC 
                ON GT.TRANSACTION_FLOW = GCC.CODE 
                AND GCC.SCOPE = 'TRAN_FLOW'
            LEFT JOIN GNCN_TRANSACTION_TYPE GTT 
                ON GT.TRANSACTION_TYPE1 = GTT.CODE 
                AND GTT.USE_STATUS = 1 
                AND GTT.level_type = 1
        WHERE
            GT.MODIFIED_DATE >= TRUNC(SYSDATE) AND GT.MODIFIED_DATE < TRUNC(SYSDATE) + 1
            AND ( EXISTS (SELECT 1 FROM BRANCHLIST b WHERE b.BRANCH_CODE = 'ALL_BRANCH')
                OR GT.BRANCH_CODE IN (SELECT b.BRANCH_CODE FROM BRANCHLIST b) )
            AND GT.TRANSACTION_TYPE1 IN ('Giaingankhoanvay','Giainganthauchi','Khoitaohanmuc','NhapvaduyetFCC','Khac')
            AND ( GT.STATUS IN ( 'GNCN_KHOI_TAO', 'GNCN_CHO_XU_LY', 'GNCN_CHO_BO_SUNG', 'GNCN_LOI_HACH_TOAN_HAN_MUC', 'GNCN_LOI_HACH_TOAN_KHOAN_VAY',
                    'GNCN_LOI_CHUYEN_TIEN', 'GNCN_HOAN_TAT_KHOAN_VAY', 'GNCN_LOI_HACH_TOAN_THAU_CHI'))
             AND (
                 CASE
                    WHEN GT.USER_LOCKED IS NOT NULL THEN LOWER(GT.USER_LOCKED)
                    WHEN GT.APPROVAL_BY IS NOT NULL THEN LOWER(GT.APPROVAL_BY)
                    WHEN GT.APPROVER_SUGGEST IS NOT NULL THEN LOWER(GT.APPROVER_SUGGEST)
                    ELSE NULL
                 END
             ) IN (SELECT USERNAME FROM USERLIST);
            END SP_DASH_GR_LIST_DXL;

/
--------------------------------------------------------
--  DDL for Procedure SP_DASH_GR_LIST_PHNL
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_DASH_GR_LIST_PHNL" (
    P_USERLIST IN VARCHAR2,
    P_BRANCH   IN VARCHAR2,
    OUT_DATA   OUT SYS_REFCURSOR
) AS 
BEGIN
    OPEN OUT_DATA FOR
        WITH USERLIST AS (
            SELECT TRIM(REGEXP_SUBSTR(P_USERLIST, '[^,]+', 1, LEVEL)) AS USERNAME
            FROM dual
            CONNECT BY LEVEL <= REGEXP_COUNT(P_USERLIST, ',') + 1
        ),
        BRANCHLIST AS (
            SELECT TRIM(REGEXP_SUBSTR(P_BRANCH, '[^,]+', 1, LEVEL)) AS BRANCH_CODE
            FROM dual
            CONNECT BY LEVEL <= REGEXP_COUNT(P_BRANCH, ',') + 1
        )
        SELECT
            GT.ID id,
            GT.STATUS status,                                           -- Tr?ng thái
            GS.NAME statusName,                                         -- Tr?ng thái hi?n th?
            '<a>' || GT.GNTD_CODE || '</a>' AS gntdCode,                -- Mã gi?i ngân tín d?ng
            GT.BRANCH_CODE branchCode,                                  -- Mã ?VKD - Mã chi nhánh
            GT.BRANCH_NAME branchName,                                  -- Tên ?VKD - Tên chi nhánh
            GT.TRANSACTION_FLOW transactionFlow,                        -- Phân lu?ng phê duy?t
            GCC.NAME transactionFlowName,                               -- Phân lu?ng phê duy?t hi?n th?
            GT.CUSTOMER_CODE customerCode,                              -- Mã Khách Hàng
            GT.CUSTOMER_NAME customerName,                              -- Tên Khách Hàng
            GT.CUSTOMER_CODE || '<br/>' || GT.CUSTOMER_NAME customerDisplay,
            GT.TRANSACTION_TYPE1 transactionType1,
            GTT.NAME transactionType1Name,                              -- Lo?i GD C?p 1
            GT.TRANSACTION_TYPE2 transactionType2,                      -- Lo?i GD C?p 2
            GT.TRANSACTION_TYPE3 transactionType3,                      -- Lo?i GD C?p 3
            GT.PDTD_CODE pdtdCode,                                      -- Mã PDTD (LOS, BPM, ECM)
            LOWER(GT.APPROVER_SUGGEST) approverSuggest,                 -- User PD ???c ?? xu?t
            LOWER(GT.PROCESSING_USER) processingUser,                   -- User x? lý
            GT.PROCESS_GROUP processGroup,                              -- Nhóm x? lý t?p trung
            GT.PROCESSING_OWNER processingOwer,                         -- User ?? xu?t
            gt.PROCESSING_USER createdBy,-- CREATED_BY ??i sang PROCESSING_USER ?? k c?n s?a code bpm
            CASE 
                WHEN GT.PROCESSING_DATE IS NOT NULL 
                THEN TO_CHAR(GT.PROCESSING_DATE, 'DD/MM/YYYY') || '<br>' || TO_CHAR(GT.PROCESSING_DATE, 'HH24:MI')
                ELSE ''
            END AS processingDate,                                      -- L?u ngày t?i tr?ng thái ch? x? lý
            GT.APPROVAL_BY approvalBy,                                  -- Ng??i phê duy?t
            GT.APPROVAL_DATE approvalDate,                              -- Th?i gian phê duy?t
            GT.YELLOW_FLAG_DATE yellowFlagDate,
            GT.RED_FLAG_DATE redFlagDate,
            'RB.CA' departmentProcess
        FROM
            GNCN_TRANSACTION GT
            INNER JOIN (
                SELECT GNTD_CODE
                FROM GNCN_TRANSACTION_HISTORY
                WHERE STATUS = 'GNCN_CHO_BO_SUNG'
                GROUP BY GNTD_CODE
                HAVING COUNT(*) > 2
            ) GTH
                ON GT.GNTD_CODE = GTH.GNTD_CODE
            LEFT JOIN GNCN_STATUS GS 
                ON GT.STATUS = GS.CODE
            LEFT JOIN GNCN_CONFIG_COMMONS GCC 
                ON GT.TRANSACTION_FLOW = GCC.CODE 
                AND GCC.SCOPE = 'TRAN_FLOW'
            LEFT JOIN GNCN_TRANSACTION_TYPE GTT 
                ON GT.TRANSACTION_TYPE1 = GTT.CODE 
                AND GTT.USE_STATUS = 1 
                AND GTT.level_type = 1
        WHERE
            GT.CREATED_BY IS NOT NULL
            AND (
                EXISTS (SELECT 1 FROM BRANCHLIST b WHERE b.BRANCH_CODE = 'ALL_BRANCH')
                OR GT.BRANCH_CODE IN (SELECT b.BRANCH_CODE FROM BRANCHLIST b)
            )
            AND LOWER(GT.CREATED_BY) IN (SELECT USERNAME FROM USERLIST)
            AND GT.TRANSACTION_TYPE1 IN ('Giaingankhoanvay','Giainganthauchi','Khoitaohanmuc','NhapvaduyetFCC','Khac')
            AND GT.STATUS IN ('GNCN_CHO_BO_SUNG');
END SP_DASH_GR_LIST_PHNL;

