    P_DOC_ID IN VARCHAR2
) AS
    sql_Temp VARCHAR2(2000) DEFAULT '';
    tempId NUMBER;
    currentDate DATE := SYSDATE;
BEGIN
    tempId := -1;
    sql_Temp := 'SELECT COUNT(*) FROM GNCN_TRANSACTION_ATTACHMENT WHERE DOC_ID=:id';
    EXECUTE IMMEDIATE  sql_Temp INTO tempId USING P_DOC_ID;
    IF(P_DOC_ID IS NOT NULL AND tempId > 0) THEN
        DELETE FROM GNCN_TRANSACTION_ATTACHMENT WHERE DOC_ID = P_DOC_ID;
    END IF;
END SP_DELETE_GNCN_TRANSACTION_ATTACHMENT_BY_DOCUMENT_ID;

