/
--------------------------------------------------------
--  DDL for Procedure SP_ECM_CA_DISBURSEMENT_DOCUMENTS_SYNC
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_ECM_CA_DISBURSEMENT_DOCUMENTS_SYNC" (
    p_maGNTD        IN VARCHAR2, -- GNTD_CODE
    p_maPDTD        IN VARCHAR2, -- PDTD_CODE
    p_maDVKD        IN VARCHAR2, -- branch_code
    p_tenDVKD       IN VARCHAR2, -- branch_name
    p_cifKH         IN VARCHAR2,
    p_tenKH         IN VARCHAR2,
    p_userDXGN IN VARCHAR2,
    p_userDuyetGNTD IN VARCHAR2,
    p_tenChungTu IN VARCHAR2 default '',
    p_phanLoaiCT IN VARCHAR2,
    p_ngayHoanThien IN VARCHAR2,
    p_tanSuat IN VARCHAR2,
    p_donViTanSuat IN VARCHAR2
) AS
    trangThaiHS       VARCHAR2(255) := 'CHUA_BO_SUNG';
    gnStatus          VARCHAR2(50)  := 'GNCN_HOAN_THANH';
    docCategory       NUMBER;
    docCode           VARCHAR2(500);
    deadlineTimestamp timestamp     := to_timestamp(p_ngayHoanThien, 'DD/MM/YYYY');
    tempTotalRows     NUMBER;
    tempSql           VARCHAR2(2000) DEFAULT '';
    donViTanSuat      VARCHAR2(50);
    tempCaId          NUMBER;
BEGIN
    --SET CÁC GIÁ TR? M?C ??NH, CH?NH S?A DATA ECM THEO CHU?N C?A BPM
    -- set mã ch?ng t? docCode;
    docCode := VN_TO_CAMELCASE(p_tenChungTu);
    -- ??n v? t?n su?t NA (N/A) -> giá tr? r?ng c?a ECM. Sang BPM thì set là null
    IF p_donViTanSuat = 'NA' THEN
        donViTanSuat := null;
    END IF;
    -- lo?i ch?ng t?
    docCategory :=
            CASE
                WHEN (p_phanLoaiCT = 'S?n ph?m tín d?ng')
                    THEN 1
                WHEN (p_phanLoaiCT = 'Phê duy?t tín d?ng/ quy ??nh ki?m tra sau vay')
                    THEN 2
                WHEN (p_phanLoaiCT = 'Phê duy?t ngo?i l? c?a c?p phê duy?t GNTD')
                    THEN 3
                ELSE 0
                END;
    -- END --

    -- B??C 2: L?U CÁC THÔNG TIN C?N THI?T C?A TRANSACTIONS
    -- ??m s? l??ng TRANSACTIONS xem có trùng không
    tempTotalRows := -1;
    tempSql := 'SELECT COUNT(*) FROM GNCN_CA_DISBURSEMENT WHERE PDTD_CODE=:v1 AND GNTD_CODE =:v2';
    EXECUTE IMMEDIATE tempSql INTO tempTotalRows USING p_maPDTD, p_maGNTD;
    DBMS_OUTPUT.PUT_LINE('totalRows: ' || tempTotalRows);
    IF (tempTotalRows < 1) then
        INSERT INTO GNCN_CA_DISBURSEMENT(GNTD_CODE, PDTD_CODE, BRANCH_CODE, CUSTOMER_CODE, CUSTOMER_NAME,
                                         PROCESSING_USERNAME, APPROVAL_BY, STATUS, BRANCH_NAME)
        VALUES (p_maGNTD, p_maPDTD, p_maDVKD, p_cifKH, p_tenKH, p_userDXGN, p_userDuyetGNTD, gnStatus, p_tenDVKD)
        RETURNING ID into tempCaId;
    ELSE
        tempSql := 'SELECT ID FROM GNCN_CA_DISBURSEMENT WHERE PDTD_CODE=:v1 AND GNTD_CODE =:v2 and ROWNUM = 1';
        EXECUTE IMMEDIATE tempSql INTO tempCaId USING p_maPDTD, p_maGNTD;
    END IF;

    -- B??C 3: L?U THÔNG TIN CH?NG T?

    -- ??m s? l??ng ch?ng t? theo tên và code xem có trùng không
    tempTotalRows := -1;
    tempSql :=
            'SELECT COUNT(*) FROM GNCN_CA_DISBURSEMENT_DOCUMENTS ' ||
            'WHERE PDTD_CODE=:v1 AND GNTD_CODE =:v2 AND DOC_NAME = :v3 AND DOC_CODE = :v4';
    EXECUTE IMMEDIATE tempSql INTO tempTotalRows USING p_maPDTD, p_maGNTD, p_tenChungTu, docCode;

    -- n?u không t?n t?i ch?ng t? trong db thì thêm m?i, còn t?n t?i r?i thì thôi
    IF (tempTotalRows < 1) THEN
        INSERT INTO GNCN_CA_DISBURSEMENT_DOCUMENTS (COMPLETED_AFTER_DISBURSEMENT_ID,
                                                    GNTD_CODE,
                                                    PDTD_CODE,
                                                    DOC_CODE,
                                                    DOC_NAME,
                                                    DOC_CATEGORY,
                                                    DEADLINE,
                                                    FREQUENCY,
                                                    FREQUENCY_UNIT,
                                                    STATUS)
        VALUES (tempCaId,
                p_maGNTD,
                p_maPDTD,
                docCode,
                p_tenChungTu,
                docCategory,
                deadlineTimestamp,
                p_tanSuat,
                p_donViTanSuat,
                trangThaiHS);
    END IF;
END
SP_ECM_CA_DISBURSEMENT_DOCUMENTS_SYNC;

/
--------------------------------------------------------
--  DDL for Procedure SP_ECM_CREDIT_APPROVAL_INFO_SYNC
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_ECM_CREDIT_APPROVAL_INFO_SYNC" (
    p_pdtdCode IN VARCHAR2,
    p_ngayPheDuyet IN VARCHAR2 DEFAULT '',
    p_maDVKD IN VARCHAR2,
    p_tenDVKD IN VARCHAR2,
    p_cvkh IN VARCHAR2,
    p_truongNhom IN VARCHAR2,
    p_loaiTs IN VARCHAR2,
    p_maLoaiHinhCapTinDung IN VARCHAR2,
    p_tenLoaiHinhCapTinDung IN VARCHAR2,
    p_maSpVay IN VARCHAR2,
    p_tenSpVay IN VARCHAR2,
    p_idKh IN VARCHAR2,
    p_cif IN VARCHAR2 DEFAULT '',
    p_loaiKh IN VARCHAR2,
    p_tenKh IN VARCHAR2,
    p_soGiayTo IN VARCHAR2,
    p_ngayCap IN VARCHAR2 DEFAULT '',
    p_noiCap IN VARCHAR2,
    p_diaChi IN VARCHAR2,
    p_loaiGiayTo IN VARCHAR2
) AS
    bpmMaLoaiGiayTo    VARCHAR2(100);
    bpmMaSpVay         VARCHAR2(100);
    bpmTenSpVay        VARCHAR2(100);
    tempReturningCusId NUMBER;
    tempNumOfRows      NUMBER;
    tempSql            VARCHAR(2000);
BEGIN
    -- B??C 1: SET l?i các giá tr? theo chu?n trên BPM
    -- 1.1 key c?a lo?i gi?y t?(các lo?i cùng lo?i gi?y t? v?i bpm thì gi? nguyên, lo?i m?i thì l?y theo key c?a ECM):
    -- CMT_NHAN_DAN			    nationalIDold
    -- HO_CHIEU				    passport
    -- CAN_CUOC_CONG_DAN		nationalID
    -- CHUNG_MINH_QUAN_DOI		nationalIDArmy
    -- CHUNG_MINH_CONG_AN		nationalIDPolice
    -- các mã gi?y t? còn l?i l?y theo ECM. C? th?:
    -- THI_THUC				    THI_THUC
    -- CHUNG_NHAN_TAM_TRU		CHUNG_NHAN_TAM_TRU
    -- THE_TAM_TRU				THE_TAM_TRU
    -- THE_THUONG_TRU			THE_THUONG_TRU
    -- CHUNG_MINH_SI_QUAN		CHUNG_MINH_SI_QUAN
    -- DANG_KI_KINH_DOANH		DANG_KI_KINH_DOANH
    -- GIAY_CHUNG_NHAN_DAU_TU	GIAY_CHUNG_NHAN_DAU_TU
    -- QUYET_DINH_THANH_LAP	    QUYET_DINH_THANH_LAP
    -- MA_SO_THUE				MA_SO_THUE
    CASE p_loaiGiayTo
        WHEN 'CMT_NHAN_DAN' THEN bpmMaLoaiGiayTo := 'nationalIDold';
        WHEN 'HO_CHIEU' THEN bpmMaLoaiGiayTo := 'passport';
        WHEN 'CAN_CUOC_CONG_DAN' THEN bpmMaLoaiGiayTo := 'nationalID';
        WHEN 'CHUNG_MINH_QUAN_DOI' THEN bpmMaLoaiGiayTo := 'nationalIDArmy';
        WHEN 'CHUNG_MINH_CONG_AN' THEN bpmMaLoaiGiayTo := 'nationalIDPolice';
        else bpmMaLoaiGiayTo := p_loaiGiayTo;
        END CASE;
    DBMS_OUTPUT.PUT_LINE('loai giay to: ' || bpmMaLoaiGiayTo);
    -- 1.2 set mã và lo?i sp vay:
--     sanphammuaoto               --> 1103: Loan Granting (Autoloan)
--     sanphammuanhadat, sanphammuanhaduan --> 1104: Loan Granting (Mortgage)
--     sanphamtinchap                   --> 1105: Loan Granting (Consumer Loan)
    CASE p_maSpVay
        WHEN 'sanphammuaoto' THEN bpmMaSpVay := 1103;
                                  bpmTenSpVay := 'Loan Granting (Autoloan)';
        WHEN 'sanphammuanhadat' THEN bpmMaSpVay := 1104;
                                     bpmTenSpVay := 'Loan Granting (Mortgage)';
        WHEN 'sanphammuanhaduan' THEN bpmMaSpVay := 1104;
                                      bpmTenSpVay := 'Loan Granting (Mortgage)';
        WHEN 'sanphamtinchap' THEN bpmMaSpVay := 1105;
                                   bpmTenSpVay := 'Loan Granting (Consumer Loan)';
        ELSE bpmMaSpVay := 'other';
             bpmTenSpVay := 'Other';
        END CASE;
    DBMS_OUTPUT.PUT_LINE('ma + loai sp: ' || bpmMaSpVay || bpmTenSpVay);

    tempSql := 'select count(*)
                from GNCN_CREDIT_CUSTOMER_SYNC cus
                         left join GNCN_CREDIT_CUSTOMER_DOC_SYNC docs
                                   on cus.ID = docs.CUS_ID
                where (((cus.CIF IS NOT NULL or cus.CIF <> '''') AND cus.CIF = :cif) or (docs.DOC_ID = :docId))';
    EXECUTE IMMEDIATE tempSql INTO tempNumOfRows USING p_cif, p_soGiayTo;

    -- B??C 2: L?U THÔNG TIN KHÁCH HÀNG
    -- n?u không t?n t?i customer thì insert, t?n t?i r?i thì l?y ID ?? l?u vô b?ng ph? map v?i TTPD.
    IF (tempNumOfRows < 1) THEN
        INSERT INTO GNCN_CREDIT_CUSTOMER_SYNC(CIF, NAME, PERMANENT_ADDRESS, CUS_TYPE)
        VALUES (p_cif, p_tenKh, p_diaChi, p_loaiKh)
        returning ID INTO tempReturningCusId;

        -- l?u khách hàng xong thì l?u gi?y t? ?i kèm
        INSERT INTO KHCN_MASTERDATA.GNCN_CREDIT_CUSTOMER_DOC_SYNC (CUS_ID, SYS_NAME, DOC_ID, ISSUE_DATE, ISSUED_BY, IS_MAIN_DOC)
        VALUES (tempReturningCusId, bpmMaLoaiGiayTo, p_soGiayTo, TO_DATE(p_ngayCap, 'YYYY-MM-DD'), p_noiCap, 1);
    ELSE -- tr??ng h?p customer ?ã t?n t?i
        tempSql := 'select cus.ID
                    from GNCN_CREDIT_CUSTOMER_SYNC cus
                             left join GNCN_CREDIT_CUSTOMER_DOC_SYNC docs
                                       on cus.ID = docs.CUS_ID
                    where (((cus.CIF IS NOT NULL or cus.CIF <> '''') AND cus.CIF = :cif) or (docs.DOC_ID = :docId))
                      and ROWNUM = 1';
        EXECUTE IMMEDIATE tempSql INTO tempReturningCusId USING p_cif, p_soGiayTo;
    END IF;

    -- intersection data: thông tin PDTD x Khách Hàng
    INSERT INTO GNCN_CREDIT_APPROVAL_REF_CUSTOMER_SYNC(CUS_ID, PDTD_CODE)
    VALUES (tempReturningCusId, p_pdtdCode);

    -- B??C 4:  L?U TTPD, TÀI S?N
    INSERT INTO GNCN_CREDIT_APPROVAL_INFO_SYNC(SOURCE_SYNC, PDTD_CODE, APPROVAL_DATE, BRANCH_CODE,
                                               CHUYEN_VIEN_KHACH_HANG,
                                               TRUONG_NHOM, PRODUCT_CODE, PRODUCT_NAME, LOAN_METHOD)
    VALUES ('ECM', p_pdtdCode, to_timestamp(p_ngayPheDuyet, 'YYYY-MM-DD HH24:MI:SS.FF3'), p_maDVKD, p_cvkh, p_truongNhom,
            bpmMaSpVay, bpmTenSpVay, p_tenLoaiHinhCapTinDung);
    -- l?u assets
    INSERT INTO GNCN_CREDIT_APPROVAL_ASSET_SYNC(PDTD_CODE, ASSET_FROM_LOAN_CAPITAL)
    VALUES (p_pdtdCode, p_loaiTs);
END
SP_ECM_CREDIT_APPROVAL_INFO_SYNC;

/
--------------------------------------------------------
--  DDL for Procedure SP_EKYC_INSERT_DATA
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_EKYC_INSERT_DATA" (
    P_BODY_JSON   IN CLOB,
    P_FILES_JSON  IN CLOB,
    P_STATUS      OUT VARCHAR2,
    P_MESSAGE     OUT VARCHAR2
)
AS
    -- =======================
    -- BODY VARIABLES
    -- =======================
    V_TRANS_ID           VARCHAR2(50);
    V_BRANCH             VARCHAR2(50);
    V_REF_NUM            VARCHAR2(50);
    V_USER_ID            VARCHAR2(50);
    V_REQUEST_DATE       DATE;
    V_ID_CARD            VARCHAR2(50);
    V_CARD_TYPE          VARCHAR2(50);
    V_CIF                VARCHAR2(50);
    V_FULL_NAME          VARCHAR2(255);
    V_BIRTHDAY           DATE;
    V_PERMANENT_ADDRESS  VARCHAR2(2000);
    V_CURRENT_ADDRESS    VARCHAR2(2000);
    V_GENDER             VARCHAR2(20);
    V_CUSTOMER_PHOTO     VARCHAR2(500);
    V_JSON_DATA          CLOB;
    C_DATE_FORMAT CONSTANT VARCHAR2(20) := 'YYYY-MM-DD';

    -- =======================
    -- FILE COLLECTION
    -- =======================
    TYPE T_FILE IS RECORD (
        filename VARCHAR2(255),
        ecmId    VARCHAR2(255)
    );

    TYPE T_FILE_TAB IS TABLE OF T_FILE INDEX BY PLS_INTEGER;
    V_FILES T_FILE_TAB;

BEGIN
    -- =======================
    -- PARSE BODY (1 l?n)
    -- =======================

    SELECT JSON_VALUE(P_BODY_JSON, '$.jsonData')
    INTO V_JSON_DATA
    FROM dual;

    SELECT 
        jt.transId,
        jt.branch,
        jt.refNum,
        jt.userId,
        CASE 
          WHEN jt.requestDate IS NOT NULL 
          THEN TO_DATE(jt.requestDate, C_DATE_FORMAT)
        END,
        jt.idCard,
        jt.cardType,
        jt.cif,
        jt.fullName,
        CASE 
          WHEN jt.birthday IS NOT NULL 
          THEN TO_DATE(jt.birthday, C_DATE_FORMAT)
        END,
        jt.permanentAddress,
        jt.currentAddress,
        jt.gender,
        jt.customerPhoto
    INTO
        V_TRANS_ID,
        V_BRANCH,
        V_REF_NUM,
        V_USER_ID,
        V_REQUEST_DATE,
        V_ID_CARD,
        V_CARD_TYPE,
        V_CIF,
        V_FULL_NAME,
        V_BIRTHDAY,
        V_PERMANENT_ADDRESS,
        V_CURRENT_ADDRESS,
        V_GENDER,
        V_CUSTOMER_PHOTO
    FROM JSON_TABLE(P_BODY_JSON, '$'
        COLUMNS (
            transId            VARCHAR2(50)  PATH '$.transId',
            branch             VARCHAR2(50)  PATH '$.branch',
            refNum             VARCHAR2(50)  PATH '$.refNum',
            userId             VARCHAR2(50)  PATH '$.userId',
            requestDate        VARCHAR2(20)  PATH '$.requestDate',
            idCard             VARCHAR2(50)  PATH '$.idCard',
            cardType           VARCHAR2(50)  PATH '$.cardType',
            cif                VARCHAR2(50)  PATH '$.cif',
            fullName           VARCHAR2(255) PATH '$.fullName',
            birthday           VARCHAR2(20)  PATH '$.birthday',
            permanentAddress   VARCHAR2(2000) PATH '$.permanentAddress',
            currentAddress     VARCHAR2(2000) PATH '$.currentAddress',
            gender             VARCHAR2(20)  PATH '$.gender',
            customerPhoto      VARCHAR2(500) PATH '$.customerPhoto'
        )
    ) jt;

    -- =======================
    -- BULK LOAD FILES
    -- =======================
    SELECT filename, ecmId
    BULK COLLECT INTO V_FILES
    FROM JSON_TABLE(
        P_FILES_JSON,
        '$[*]'
        COLUMNS (
            filename VARCHAR2(255) PATH '$.filename',
            ecmId    VARCHAR2(255) PATH '$.ecmId'
        )
    )
    WHERE ecmId IS NOT NULL; -- filter luôn t?i DB

    -- =======================
    -- BULK INSERT (FAST)
    -- =======================
    FORALL i IN INDICES OF V_FILES
        INSERT INTO TBL_EKYC_INFO (
            TRANS_ID,
            BRANCH,
            REF_NUM,
            USER_ID,
            REQUEST_DATE,
            ID_CARD,
            CARD_TYPE,
            CIF,
            FULL_NAME,
            BIRTHDAY,
            PERMANENT_ADDRESS,
            CURRENT_ADDRESS,
            GENDER,
            CUSTOMER_PHOTO,
            JSON_DATA,
            FILE_NAME,
            ECM_ID
        )
        VALUES (
            V_TRANS_ID,
            V_BRANCH,
            V_REF_NUM,
            V_USER_ID,
            V_REQUEST_DATE,
            V_ID_CARD,
            V_CARD_TYPE,
            V_CIF,
            V_FULL_NAME,
            V_BIRTHDAY,
            V_PERMANENT_ADDRESS,
            V_CURRENT_ADDRESS,
            V_GENDER,
            V_CUSTOMER_PHOTO,
            V_JSON_DATA,
            V_FILES(i).filename,
            V_FILES(i).ecmId
        );

    -- =======================
    -- RESULT
    -- =======================
    P_STATUS := '200';
    P_MESSAGE := 'SUCCESS - INSERTED: ' || V_FILES.COUNT;

-- =======================
-- ERROR HANDLING
-- =======================
EXCEPTION
    WHEN OTHERS THEN
        P_STATUS := '999';
        P_MESSAGE := SQLERRM;
END;

/
--------------------------------------------------------
--  DDL for Procedure SP_EKYC_SEARCH_AUDIT_LOG
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_EKYC_SEARCH_AUDIT_LOG" (
  P_DATA IN VARCHAR,
  P_PAGING_CURSOR OUT SYS_REFCURSOR
) AS 
  json_obj             JSON_OBJECT_T;
  V_TRANS_ID           VARCHAR2(50);
  V_SEARCH             VARCHAR2(2000);
  P_FROM_DATE          VARCHAR2(50);
  P_TO_DATE            VARCHAR2(50);
  C_FORMAT_DATE  CONSTANT VARCHAR2(10) := 'DD/MM/YYYY';
  V_FROM_DATE          VARCHAR2(50);
  V_TO_DATE            VARCHAR2(50);
  V_FUNC               VARCHAR2(2000);
  V_RESCODE            VARCHAR2(2000);
BEGIN 
  json_obj := JSON_OBJECT_T.parse(P_DATA);
  V_TRANS_ID := json_obj.get_String('transId');
  V_SEARCH := json_obj.get_String('search');
  P_FROM_DATE := json_obj.get_String('fromDate');
  P_TO_DATE := json_obj.get_String('toDate');

  IF P_FROM_DATE IS NOT NULL THEN 
    V_FROM_DATE := TO_DATE(P_FROM_DATE, C_FORMAT_DATE);
  END IF;

  IF P_TO_DATE IS NOT NULL THEN 
    V_TO_DATE := TO_DATE(P_TO_DATE, C_FORMAT_DATE) + 1;
  END IF;

  IF V_SEARCH IS NOT NULL THEN 
    V_FUNC := LOWER(V_SEARCH);
    V_RESCODE := UPPER(V_SEARCH);
  END IF;

  OPEN P_PAGING_CURSOR FOR
    SELECT
      TRANS_ID AS transId,
      FUNC_CODE AS funcCode,
      RES_STATUS AS httpStatus,
      RES_CODE,
      RES_MSG,
      -- REQ_TIME,
      NVL(
        TO_CHAR(
            DATE '1970-01-01' + (REQ_TIME / 1000 / 86400) + (7/24),
            'DD/MM/YYYY HH24:MI:SS'
        ),
        ''
      ) AS REQ_TIME,
      NVL(
        TO_CHAR(
            DATE '1970-01-01' + (RES_TIME / 1000 / 86400) + (7/24),
            'DD/MM/YYYY HH24:MI:SS'
        ),
        ''
      ) AS RES_TIME,
      DURATION,
      JSON_DATA,
      TO_CHAR(CREATED_DATE, 'DD/MM/YYYY HH24:MI:SS') AS CREATED_AT
    FROM 
      TBL_EKYC_TRACKING
    WHERE 
      1 = 1
      AND (
        V_TRANS_ID IS NULL OR TRANS_ID = V_TRANS_ID
      )
      AND (
        V_SEARCH IS NULL
        OR TRANS_ID = P_DATA
        OR INSTR(FUNC_CODE, V_FUNC) > 0
        OR INSTR(RES_CODE, V_RESCODE) > 0
        OR INSTR(RES_MSG, V_SEARCH) > 0
      )
      AND (V_FROM_DATE IS NULL OR CREATED_DATE >= V_FROM_DATE)
      AND (V_TO_DATE IS NULL OR CREATED_DATE < V_TO_DATE)
    ORDER BY
      CREATED_DATE DESC FETCH FIRST 20000 ROWS ONLY;

END SP_EKYC_SEARCH_AUDIT_LOG;

/
--------------------------------------------------------
--  DDL for Procedure SP_EKYC_SEARCH_DATA_INFO
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_EKYC_SEARCH_DATA_INFO" (
  P_DATA IN VARCHAR,
  P_PAGING_CURSOR OUT SYS_REFCURSOR
) AS 
  json_obj             JSON_OBJECT_T;
  V_TRANS_ID           VARCHAR2(50);
  V_BRANCH             VARCHAR2(50);
  V_USER_ID            VARCHAR2(50);
  V_ID_CARD            VARCHAR2(50);
  V_CUS_NAME           VARCHAR2(50);
  P_FROM_DATE          VARCHAR2(50);
  P_TO_DATE            VARCHAR2(50);
  C_FORMAT_DATE  CONSTANT VARCHAR2(10) := 'DD/MM/YYYY';
  V_FROM_DATE          VARCHAR2(50);
  V_TO_DATE            VARCHAR2(50);
BEGIN 
  json_obj := JSON_OBJECT_T.parse(P_DATA);
  V_TRANS_ID := json_obj.get_String('transId');
  V_BRANCH := json_obj.get_String('branch');
  V_USER_ID := json_obj.get_String('userId');
  V_ID_CARD := json_obj.get_String('idCard');
  V_CUS_NAME := json_obj.get_String('cusName');
  P_FROM_DATE := json_obj.get_String('fromDate');
  P_TO_DATE := json_obj.get_String('toDate');

  IF P_FROM_DATE IS NOT NULL THEN 
    V_FROM_DATE := TO_DATE(P_FROM_DATE, C_FORMAT_DATE);
  END IF;

  IF P_TO_DATE IS NOT NULL THEN 
    V_TO_DATE := TO_DATE(P_TO_DATE, C_FORMAT_DATE) + 1;
  END IF;

  IF V_CUS_NAME IS NOT NULL THEN V_CUS_NAME := UPPER(V_CUS_NAME); END IF;
  IF V_USER_ID IS NOT NULL THEN V_USER_ID := UPPER(V_USER_ID); END IF;
  
  OPEN P_PAGING_CURSOR FOR
    SELECT
      TRANS_ID,
      BRANCH,
      USER_ID,
      TO_CHAR(REQUEST_DATE, 'DD/MM/YYYY') AS REQUEST_DATE,
      CIF,
      ID_CARD,
      CARD_TYPE,
      FULL_NAME,
      TO_CHAR(BIRTHDAY, 'DD/MM/YYYY') AS BIRTHDAY,
      CURRENT_ADDRESS AS ADDRESS,
      REF_NUM,
      ECM_ID,
      FILE_NAME,
      CUSTOMER_PHOTO,
      JSON_DATA,
      TO_CHAR(CREATED_DATE, 'DD/MM/YYYY HH24:MI:SS') AS CREATED_AT
    FROM 
      TBL_EKYC_INFO
    WHERE 
      1 = 1
      -- AND (
      --   P_DATA IS NULL
      --   OR TRANS_ID = P_DATA
      --   OR ID_CARD = P_DATA
      --   OR BRANCH = P_DATA
      --   OR INSTR(ID_CARD, UPPER(P_DATA)) > 0
      -- )
      AND (
        V_TRANS_ID IS NULL OR TRANS_ID = V_TRANS_ID
      )
      AND (
        V_BRANCH IS NULL OR INSTR(',' || V_BRANCH || ',', ',' || BRANCH || ',') > 0
      )
      AND (
        V_ID_CARD IS NULL OR ID_CARD = V_ID_CARD
      )
      AND (
        V_USER_ID IS NULL OR INSTR(UPPER(USER_ID), V_USER_ID) > 0
      )
      AND (
        V_CUS_NAME IS NULL OR INSTR(UPPER(FULL_NAME), V_CUS_NAME) > 0
      )
      AND (V_FROM_DATE IS NULL OR REQUEST_DATE >= V_FROM_DATE)
      AND (V_TO_DATE IS NULL OR REQUEST_DATE < V_TO_DATE)
    ORDER BY
      CREATED_DATE DESC;

END SP_EKYC_SEARCH_DATA_INFO;

/
--------------------------------------------------------
--  DDL for Procedure SP_ETL_DATA_REPORT_LOAN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_ETL_DATA_REPORT_LOAN" (
  P_DATE VARCHAR2,
  P_COUNT OUT INTEGER
) AS BEGIN
  -- Xóa d? li?u ??ng b? c? theo ngày phê duy?t
  DELETE FROM ETL_LOAN_TRANSACTION_REPORT WHERE TO_CHAR(APPROVAL_DATE, 'YYYY-MM-DD') = P_DATE;

  -- Insert d? li?u ??ng b? m?i theo ngày phê duy?t
  INSERT INTO ETL_LOAN_TRANSACTION_REPORT (
    GNTD_CODE,
    STATUS,
    BRANCH_CODE,
    BRANCH_NAME,
    PDTD_CODE,
    LIMIT_CODE,
    CUS_ID_CARD,
    CUSTOMER_CODE,
    CUSTOMER_NAME,
    PRODUCT_CODE,
    PRODUCT_NAME,
    APPROVAL_BY,
    APPROVAL_DATE,
    ISSUED_DATE,
    ISSUED_BY,
    TRANSACTION_TYPE1,
    TRANSACTION_TYPE2,
    TRANSACTION_TYPE3,
    MODIFIED_DATE,
    CREATED_DATE,
    TOTAL_AMOUNT,
    CURRENCY,
    DEADLINE,
    DURATION_UNIT,
    DURATION_DISPLAY,
    FCC_REF_NUM,
    REASON,
    FROM_DATE,
    TO_DATE,
    RATE_CODE,
    MARGIN_RATE,
    EARLY_REPAYMENT_FEE,
    TRANSACTION_TYPE1_NAME,
    STATUS_NAME
  ) WITH data_summary AS (
    SELECT
      GNTD_CODE,
      TOTAL_AMOUNT,
      CURRENCY,
      DEADLINE,
      DURATION_UNIT,
      DEADLINE_DISPLAY AS DURATION_DISPLAY,
      FCC_REF_NUM,
      REASON,
      FROM_DATE,
      TO_DATE,
      CASE
        WHEN LOAN_DATA IS NOT NULL THEN JSON_VALUE(LOAN_DATA, '$.listInterestRates[0].rateCode')
        WHEN OVERDRAFT_DATA IS NOT NULL THEN JSON_VALUE(OVERDRAFT_DATA, '$.rateCode')
      END AS RATE_CODE,
      CASE
        WHEN LOAN_DATA IS NOT NULL THEN TO_NUMBER(
          JSON_VALUE(
            LOAN_DATA,
            '$.listInterestRates[0].interestRateMargin'
          )
        )
        WHEN OVERDRAFT_DATA IS NOT NULL THEN TO_NUMBER(JSON_VALUE(OVERDRAFT_DATA, '$.rate'))
      END AS MARGIN_RATE,
      CASE
        WHEN LOAN_DATA IS NOT NULL THEN TO_NUMBER(
          JSON_VALUE(LOAN_DATA, '$.listInterestRates[0].fee')
        )
        ELSE 0
      END AS EARLY_REPAYMENT_FEE
    FROM
      GNCN_TRANSACTION_PURPOSE
    WHERE
      FCC_REF_NUM IS NOT NULL
  )
  SELECT
    t.GNTD_CODE,
    t.STATUS,
    t.BRANCH_CODE,
    t.BRANCH_NAME,
    t.PDTD_CODE,
    t.LIMIT_CODE,
    t.ID_CARD AS CUS_ID_CARD,
    t.CUSTOMER_CODE,
    t.CUSTOMER_NAME,
    t.PRODUCT_CODE,
    t.PRODUCT_NAME,
    t.APPROVAL_BY,
    t.APPROVAL_DATE,
    t.APPROVAL_SUBMIT_TIME AS ISSUED_DATE,
    t.PROCESSING_OWNER AS ISSUED_BY,
    t.TRANSACTION_TYPE1,
    t.TRANSACTION_TYPE2,
    t.TRANSACTION_TYPE3,
    t.MODIFIED_DATE,
    t.CREATED_DATE,
    ds.TOTAL_AMOUNT,
    ds.CURRENCY,
    ds.DEADLINE,
    ds.DURATION_UNIT,
    ds.DURATION_DISPLAY,
    ds.FCC_REF_NUM,
    ds.REASON,
    ds.FROM_DATE,
    ds.TO_DATE,
    ds.RATE_CODE,
    ds.MARGIN_RATE,
    ds.EARLY_REPAYMENT_FEE,
    tt1.NAME AS TRANSACTION_TYPE1_NAME,
    s.NAME AS STATUS_NAME
  FROM
    GNCN_TRANSACTION t
    INNER JOIN data_summary ds ON ds.GNTD_CODE = t.GNTD_CODE
    LEFT JOIN GNCN_TRANSACTION_TYPE tt1 ON tt1.CODE = t.TRANSACTION_TYPE1
    AND tt1.USE_STATUS = 1
    AND tt1.LEVEL_TYPE = 1
    LEFT JOIN GNCN_STATUS s ON t.STATUS = s.CODE
  WHERE
    t.TRANSACTION_TYPE1 IN ('Giaingankhoanvay', 'Giainganthauchi')
    AND APPROVAL_DATE IS NOT NULL
    AND TO_CHAR(APPROVAL_DATE, 'YYYY-MM-DD') = P_DATE;

  COMMIT;

  -- Return s? l??ng b?n ghi ??ng b? theo ngày
  SELECT COUNT (*) INTO P_COUNT FROM ETL_LOAN_TRANSACTION_REPORT WHERE TO_CHAR(APPROVAL_DATE, 'YYYY-MM-DD') = P_DATE;

END SP_ETL_DATA_REPORT_LOAN;

