/
--------------------------------------------------------
--  DDL for Procedure SP_GEN_GNTD_CODE
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GEN_GNTD_CODE" (
  P_BRANCH_CODE IN VARCHAR2,
  P_GNTD_CODE OUT VARCHAR2
) AS 
  V_COUNT NUMBER;
  V_NUM NUMBER;
  V_NUM_STR VARCHAR (10);
  V_CODE VARCHAR(20);
  V_DATE VARCHAR(100);

BEGIN -- Khóa b?ng GNCN_CREATE_TRANSACTION_LOG v?i ch? ?? EXCLUSIVE
  LOCK TABLE GNCN_CREATE_TRANSACTION_LOG IN EXCLUSIVE MODE;

  P_GNTD_CODE := CONCAT('GNCN', P_BRANCH_CODE);

  SELECT to_char(SYSDATE, 'yyMMdd') INTO V_DATE FROM dual;

  SELECT
    COUNT(*) INTO V_COUNT
  FROM
    GNCN_CREATE_TRANSACTION_LOG
  WHERE
    to_char(CREATED_DATE, 'dd/MM/yyyy') = to_char(SYSDATE, 'dd/MM/yyyy')
    and BRANCH_CODE = P_BRANCH_CODE;

  V_COUNT := V_COUNT + 1;
  V_NUM := 3 - LENGTH(V_COUNT);

  IF V_NUM > 0 THEN
    SELECT rpad('0', V_NUM, '0') INTO V_NUM_STR FROM dual;
    SELECT to_char(SYSDATE, 'YYMMDD') || V_NUM_STR || V_COUNT INTO V_CODE FROM  dual;
  ELSE 
    SELECT to_char(SYSDATE, 'YYMMDD') || V_COUNT INTO V_CODE FROM dual;
  END IF;

  P_GNTD_CODE := CONCAT(P_GNTD_CODE, V_CODE);

  INSERT INTO
    GNCN_CREATE_TRANSACTION_LOG(GNTD_CODE, BRANCH_CODE, CREATED_BY, CREATED_DATE)
  VALUES
    (P_GNTD_CODE, P_BRANCH_CODE, 'SYSTEM', SYSDATE);

  COMMIT;

  EXCEPTION
  WHEN OTHERS THEN -- N?u có l?i, th?c hi?n Rollback và m? khóa b?ng
  ROLLBACK;
  RAISE;

END SP_GEN_GNTD_CODE;

/
--------------------------------------------------------
--  DDL for Procedure SP_GEN_PDTD_CODE
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GEN_PDTD_CODE" 
(
  P_BRANCH_CODE IN VARCHAR2,  
  P_CREATED_BY IN VARCHAR2,  
  P_PDTD_CODE OUT VARCHAR2
) AS 
BEGIN
    DECLARE
    p_count NUMBER(38, 0);
    p_date  VARCHAR2(100);
    BEGIN
        SELECT
            to_char(sysdate, 'yyMMdd')
        INTO p_date
        FROM
            dual;

        P_PDTD_CODE := CONCAT(CONCAT('PD', P_BRANCH_CODE), p_date);
        SELECT
            COUNT(*)
        INTO p_count
        FROM
            GNCN_CREATE_APPROVAL_LOG
        WHERE
            to_char(CREATED_DATE, 'dd/MM/yyyy') = to_char(sysdate, 'dd/MM/yyyy') and BRANCH_CODE = P_BRANCH_CODE;

        p_count := p_count + 1;
        IF ( p_count < 10 ) THEN
            P_PDTD_CODE := concat(concat(P_PDTD_CODE, '000'), p_count);
        ELSIF ( p_count < 100 ) THEN
            P_PDTD_CODE := concat(concat(P_PDTD_CODE, '00'), to_char(p_count));
        ELSIF ( p_count < 1000 ) THEN
            P_PDTD_CODE := concat(concat(P_PDTD_CODE, '0'), to_char(p_count));
        ELSE
            P_PDTD_CODE := concat(P_PDTD_CODE, to_char(p_count));
        END IF;

        INSERT INTO GNCN_CREATE_APPROVAL_LOG(PDTD_CODE, BRANCH_CODE, CREATED_BY, CREATED_DATE, IS_APPROVAL) 
        VALUES(P_PDTD_CODE, P_BRANCH_CODE, P_CREATED_BY, SYSDATE, 0);
    END;

END SP_GEN_PDTD_CODE;

/
--------------------------------------------------------
--  DDL for Procedure SP_GEN_TRANSACTION_CODE
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GEN_TRANSACTION_CODE" (
  P_BRANCH_CODE IN VARCHAR2,
  P_TYPE IN VARCHAR2,
  O_TRANSACTION_CODE OUT VARCHAR2
) AS
  V_DATE VARCHAR(20);
  V_COUNT NUMBER DEFAULT 0;
  V_MAX_CHAR NUMBER DEFAULT 5;
  V_NUM NUMBER;
  V_NUM_STR VARCHAR (10);
  V_CODE VARCHAR(20);
BEGIN
  LOCK TABLE LOG_CREATE_TRANSACTION_CODE IN EXCLUSIVE MODE;

  SELECT to_char(SYSDATE, 'yyMMdd') INTO V_DATE FROM dual;

  SELECT
    MAX(SORT_NUM) INTO V_COUNT
  FROM
    LOG_CREATE_TRANSACTION_CODE
  WHERE
    TO_CHAR(CREATED_AT, 'dd/MM/yyyy') = TO_CHAR(SYSDATE, 'dd/MM/yyyy')
    AND CATEGORY = P_TYPE
    AND BRANCH_CODE = P_BRANCH_CODE;

  IF (V_COUNT IS NULL) THEN V_COUNT := 0; END IF;
  IF (P_TYPE = 'GNCN') THEN V_MAX_CHAR := 3; END IF;
  V_COUNT := V_COUNT + 1;
  V_NUM := V_MAX_CHAR - LENGTH(V_COUNT);

  IF V_NUM > 0 THEN
    SELECT rpad('0', V_NUM, '0') INTO V_NUM_STR FROM dual;
    SELECT TO_CHAR(SYSDATE, 'YYMMDD') || V_NUM_STR || V_COUNT INTO V_CODE FROM dual;
  ELSE 
    SELECT TO_CHAR(SYSDATE, 'YYMMDD') || V_COUNT INTO V_CODE FROM dual;
  END IF;

  O_TRANSACTION_CODE := P_TYPE || P_BRANCH_CODE || V_CODE;

  INSERT INTO
    LOG_CREATE_TRANSACTION_CODE(TRANSACTION_CODE, BRANCH_CODE, CATEGORY, SORT_NUM)
  VALUES
    (O_TRANSACTION_CODE, P_BRANCH_CODE, P_TYPE, V_COUNT);

  COMMIT;

  EXCEPTION
  WHEN OTHERS THEN -- N?u có l?i, th?c hi?n Rollback và m? khóa b?ng
  ROLLBACK;
  RAISE;

END SP_GEN_TRANSACTION_CODE;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_CMP_TRANSACTION_INFO
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_CMP_TRANSACTION_INFO" (
    P_CUSTOMER_CODE       IN  VARCHAR2,
    P_PAGING_CURSOR       OUT PAGINGPACKAGE.PAGING_CURSOR
) AS
    v_count  NUMBER;
BEGIN
    SELECT COUNT(CUSTOMER_CODE) INTO v_count 
    FROM GNCN_CMP_TRANSACTION
    WHERE CUSTOMER_CODE = P_CUSTOMER_CODE;
    IF v_count > 0 THEN
        UPDATE GNCN_CMP_TRANSACTION
           SET HANDLE_STATUS = 'DANG_XU_LY'
        WHERE CUSTOMER_CODE = P_CUSTOMER_CODE
           AND (HANDLE_STATUS IS NULL OR HANDLE_STATUS <> 'DANG_XU_LY');

        IF SQL%ROWCOUNT = 0 THEN
            OPEN P_PAGING_CURSOR FOR
            SELECT DISBURSEMENT_CODE as disbursementCode, EXTERNAL_CODE as externalCode, 
            TRANSACTION_CODE as transactionCode, RESPONSE_STATUS as responseStatus,
            CUSTOMER_CODE as customerCode, 'DANG_XU_LY' as handleStatus, 
            CMP_JSON_DATA as cmpJsonData, MODIFIED_DATE as updatedDate
            FROM GNCN_CMP_TRANSACTION WHERE CUSTOMER_CODE = P_CUSTOMER_CODE;
        ELSE 
            COMMIT;
            OPEN P_PAGING_CURSOR FOR
            SELECT DISBURSEMENT_CODE as disbursementCode, EXTERNAL_CODE as externalCode, 
            TRANSACTION_CODE as transactionCode, RESPONSE_STATUS as responseStatus,
            CUSTOMER_CODE as customerCode, '' as handleStatus,
            CMP_JSON_DATA as cmpJsonData, MODIFIED_DATE as updatedDate
            FROM GNCN_CMP_TRANSACTION WHERE CUSTOMER_CODE = P_CUSTOMER_CODE;
        END IF;
    ELSE 
        INSERT INTO GNCN_CMP_TRANSACTION(CUSTOMER_CODE, HANDLE_STATUS, CREATED_DATE)
        VALUES (P_CUSTOMER_CODE, 'DANG_XU_LY', SYSDATE);
        COMMIT;
        OPEN P_PAGING_CURSOR FOR
        SELECT P_CUSTOMER_CODE as customerCode, '' as handleStatus, null as updatedDate FROM DUAL;
    END IF;
--EXCEPTION
--    WHEN OTHERS THEN
--        P_MESS_CODE := '1';
--        ROLLBACK;
END SP_GET_CMP_TRANSACTION_INFO;

