--  DDL for Procedure SP_GET_EMAIL_TEMPLATE
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_EMAIL_TEMPLATE" 
(    
    P_CODE IN VARCHAR2,   --
    P_PAGING_CURSOR         OUT PAGINGPACKAGE.PAGING_CURSOR
)

AS 
BEGIN 
    OPEN P_PAGING_CURSOR FOR 
		SELECT 
            ET.CODE ET_CODE, --
            ET.NAME ET_NAME, --
            ET.SUBJECT ET_SUBJECT, --
            ET.BODY ET_BODY, --
