/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GNCN_APPROVAL_SYNC_PAGING
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_GNCN_APPROVAL_SYNC_PAGING" (
  P_CODE            IN    VARCHAR2,               --MÃ PDTD
  P_SOURCE_SYNC     IN    VARCHAR2,               --NGU?N PDTD
  P_BRANCH_CODE     IN    VARCHAR2,               --MÃ DVKD
  P_CIF             IN    VARCHAR2,               --CIF
  P_ID_CARD         IN    VARCHAR2,               --CCCD
  P_CUSTOMER_NAME   IN    VARCHAR2,               --TÊN KH
  P_PRODUCT_NAME    IN    VARCHAR2,               --SP
  P_FROM_DATE       IN    VARCHAR2,               --T? NGÀY
  P_TO_DATE         IN    VARCHAR2,               --??N NGÀY
  P_PAGE_NUM        IN    NUMBER DEFAULT 1,       -- CURRENT PAGE 
  P_PAGE_SIZES      IN    NUMBER DEFAULT 200,     -- NUMBER OF RECORDS PER PAGE     
  P_TOTAL_ROWS      OUT   NUMBER,                 -- TOTAL RECORDS 
  P_TOTAL_PAGE      OUT   NUMBER,                 -- TOTAL PAGES 
  P_PAGING_CURSOR   OUT   PAGINGPACKAGE.PAGING_CURSOR
) AS 
BEGIN OPEN P_PAGING_CURSOR FOR WITH CREDIT_APPROVAL AS (
                                      SELECT
                                        CAI.CREATED_DATE,
                                        CAI.APPROVAL_LEVEL,
                                        CAI.APPROVAL_DATE,
                                        CAI.CURRENCY,
                                        CAI.LOAN_AMOUNT,
                                        CAI.LOAN_TERM,
                                        CAI.BANK_PRODUCT_NAME,
                                        CAI.PRODUCT_NAME,
                                        CAI.PRODUCT_CODE,
                                        CAI.PDTD_CODE,
                                        CAI.SOURCE_SYNC,
                                        CAI.BRANCH_CODE,
                                        CARC.CUS_ID
                                      FROM
                                        GNCN_CREDIT_APPROVAL_INFO_SYNC           CAI,
                                        GNCN_CREDIT_APPROVAL_REF_CUSTOMER_SYNC   CARC
                                      WHERE
                                        CAI.PDTD_CODE = CARC.PDTD_CODE
                                        AND CARC.RELATIONSHIP IS NULL
                                    )
                                    SELECT
                                      CA.PDTD_CODE          AC_PDTD_CODE,             --mã PDTD
                                      CA.SOURCE_SYNC        AC_SOURCE_SYNC,           --mã ngu?n PDTD
                                      CA.BRANCH_CODE        AC_BRANCH_CODE,           --mã ?VKD
                                      CC.CIF                AC_CUSTOMER_CODE,                   --CIF, mã kh
                                      CCD.DOC_ID            AC_ID_CARD,               --CCCD
                                      CC.NAME               AC_CUSTOMER_NAME,                  --TÊN KHÁCH HÀNG
                                      CA.PRODUCT_CODE       AC_PRODUCT_CODE,         --MA SAN PHAM
                                      CA.PRODUCT_NAME       AC_PRODUCT_NAME,         --TÊN S?N PH?M
                                      CA.BANK_PRODUCT_NAME,
                                      CA.LOAN_AMOUNT        AC_MONEY_NUM,          --S? TI?N
                                      CA.LOAN_TERM          AC_LOAN_TERM,           -- TH?I H?N VAY
                                      CA.CURRENCY           AC_MONEY_CATEGORY,             --LO?I TI?N
                                      CA.APPROVAL_DATE      AC_APPROVE_DATE_DATE,        --NGÀY PHÊ DUY?T TIMESTAP
--                                      (
--                                        SELECT
--                                          (
--                                            SELECT
--                                              TO_CHAR(AC2.APPROVAL_DATE, 'dd/MM/yyyy')
--                                            FROM
--                                              GNCN_CREDIT_APPROVAL_INFO_SYNC AC2
--                                            WHERE
--                                              ( P_FROM_DATE IS NULL
--                                                OR AC2.APPROVAL_DATE >= TO_DATE(P_FROM_DATE, 'dd/mm/yy') )
--                                              AND ( P_TO_DATE IS NULL
--                                                    OR AC2.APPROVAL_DATE <= TO_DATE(P_TO_DATE, 'dd/mm/yy') + 1 )
--                                              AND ROWNUM = 1
--                                              AND AC2.PDTD_CODE = PDTD_CODE
--                                          )
--                                        FROM
--                                          GNCN_CREDIT_APPROVAL_INFO_SYNC
--                                        WHERE
--                                          ROWNUM = 1
--                                      ) AC_APPROVE_DATE,        --13.TH?I GIAN PHÊ DUY?T
                                      TO_CHAR(CA.APPROVAL_DATE, 'dd/MM/yyyy') AC_APPROVE_DATE, --13.TH?I GIAN PHÊ DUY?T
                                      CA.APPROVAL_LEVEL AC_APPROVE_LEVEL,        --C?P PHÊ DUY?T
                                      CC.CUS_TYPE AC_CUSTOMER_CATEGORY,          --Lo?i KH
                                      CA.CREATED_DATE AC_CREATED_DATE
                                    FROM
                                      CREDIT_APPROVAL                 CA,
                                      GNCN_CREDIT_CUSTOMER_SYNC       CC,
                                      GNCN_CREDIT_CUSTOMER_DOC_SYNC   CCD
                                    WHERE
                                      CA.CUS_ID = CC.ID     
                                      AND CC.ID = CCD.CUS_ID
                                      AND CCD.IS_MAIN_DOC = 1
                                      AND (P_CODE IS NULL OR P_CODE = '' OR CA.PDTD_CODE LIKE '%'||P_CODE||'%')     --MÃ PHÊ DUY?T TÍN D?NG
                                      AND (P_SOURCE_SYNC IS NULL OR P_SOURCE_SYNC = '' OR CA.SOURCE_SYNC LIKE '%'||P_SOURCE_SYNC||'%')    --NG?N PHÊ DUY?T
--                                AND (P_BRANCH_CODE IS NULL OR P_BRANCH_CODE = '' OR AC1.BRANCH_CODE LIKE '%'||P_BRANCH_CODE||'%')
                                      AND (P_BRANCH_CODE = '' OR P_BRANCH_CODE IS NULL OR LOWER(CA.BRANCH_CODE) IN (        
                                      SELECT regexp_substr(LOWER(P_BRANCH_CODE),'[^,]+', 1, LEVEL) FROM dual
                                        CONNECT BY regexp_substr(LOWER(P_BRANCH_CODE), '[^,]+', 1, LEVEL) IS NOT NULL))       --?VKD
                                      AND (P_CIF IS NULL OR P_CIF = '' OR CC.CIF LIKE '%'||P_CIF||'%')        --CIF
                                      AND (P_ID_CARD IS NULL OR P_ID_CARD = '' OR CCD.DOC_ID LIKE '%'||P_ID_CARD||'%')    --CCCD
                                      AND (P_CUSTOMER_NAME IS NULL OR P_CUSTOMER_NAME = '' OR CC.NAME LIKE '%'||P_CUSTOMER_NAME||'%')   --TÊN KH
--                                AND (P_PRODUCT_NAME IS NULL OR P_PRODUCT_NAME = '' OR AC1.PRODUCT_NAME LIKE '%'||P_PRODUCT_NAME||'%')
                                      AND (P_PRODUCT_NAME = '' OR P_PRODUCT_NAME IS NULL OR LOWER(CA.PRODUCT_NAME) IN (
                                        SELECT regexp_substr(LOWER(P_PRODUCT_NAME),'[^,]+', 1, LEVEL) FROM dual
                                        CONNECT BY regexp_substr(LOWER(P_PRODUCT_NAME), '[^,]+', 1, LEVEL) IS NOT NULL))    --TÊN SP
                                      AND (P_FROM_DATE IS NULL OR P_FROM_DATE = '' OR TO_DATE(P_FROM_DATE, 'dd/mm/yy') <= CA.APPROVAL_DATE)    --T? NGÀY
                                      AND (P_TO_DATE IS NULL OR P_TO_DATE = '' OR (TO_DATE(P_TO_DATE, 'dd/mm/yy')+1) >= CA.APPROVAL_DATE);     --??N NGÀY
    P_TOTAL_PAGE:=1;
    P_TOTAL_ROWS :=4;
END SP_GET_GNCN_APPROVAL_SYNC_PAGING;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GNCN_APPROVED_COMPETENT_PAGING
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_GNCN_APPROVED_COMPETENT_PAGING" 
(
    P_ID IN NUMBER,   --
    P_TRANS_LEVEL_CODE_1 IN VARCHAR2,   --Mã giao d?ch c?p 1
    P_TRANS_LEVEL_CODE_2 IN VARCHAR2,   --Mã giao d?ch c?p 2
    P_TRANS_LEVEL_CODE_3 IN VARCHAR2,   --Mã giao d?ch c?p 3
    P_APPROVE_LEVEL IN VARCHAR2,   --C?p phê duy?t
    P_MONEY_FROM IN NUMBER,   --S? ti?n th?c hi?n phân quy?n gi?i ngân t?
    P_MONEY_TO IN NUMBER,   --S? ti?n th?c hi?n phân quy?n gi?i ngân ??n
    P_PRIORITY IN NUMBER,   --Th? t? ?u tiên
      
    P_PAGE_NUM              IN NUMBER   DEFAULT 1,      -- CURRENT PAGE 
    P_PAGE_SIZES            IN NUMBER   DEFAULT 200,     -- NUMBER OF RECORDS PER PAGE     
    P_TOTAL_ROWS            OUT NUMBER, -- TOTAL RECORDS 
    P_TOTAL_PAGE            OUT NUMBER, -- TOTAL PAGES 
    P_PAGING_CURSOR         OUT PAGINGPACKAGE.PAGING_CURSOR
)

AS 
BEGIN 
    OPEN P_PAGING_CURSOR FOR 
		SELECT 
            MC.ID MC_ID, --Id
            MC.TRANS_LEVEL_CODE_1 MC_TRANS_LEVEL_CODE_1, --TransLevelCode1
            (SELECT NAME FROM GNCN_TRANSACTION_TYPE TT WHERE TT.LEVEL_TYPE =1 AND TT.CODE = MC.TRANS_LEVEL_CODE_1 AND ROWNUM =1) MC_TRANS_LEVEL_CODE_1_NAME,
            MC.TRANS_LEVEL_CODE_2 MC_TRANS_LEVEL_CODE_2, --TransLevelCode2
            (SELECT NAME FROM GNCN_TRANSACTION_TYPE TT WHERE TT.LEVEL_TYPE =2 AND TT.CODE = MC.TRANS_LEVEL_CODE_2 AND ROWNUM =1) MC_TRANS_LEVEL_CODE_2_NAME,
            MC.TRANS_LEVEL_CODE_3 MC_TRANS_LEVEL_CODE_3, --TransLevelCode3
            (SELECT NAME FROM GNCN_TRANSACTION_TYPE TT WHERE TT.LEVEL_TYPE =3 AND TT.CODE = MC.TRANS_LEVEL_CODE_3 AND ROWNUM =1) MC_TRANS_LEVEL_CODE_3_NAME,
            MC.APPROVE_LEVEL MC_APPROVE_LEVEL,
            (SELECT NAME FROM GNCN_POSITION_CONFIG PC WHERE MC.APPROVE_LEVEL = PC.CODE AND ROWNUM = 1) MC_APPROVE_COMPETENT_NAME,
            MC.MONEY_FROM MC_MONEY_FROM,
            MC.MONEY_TO MC_MONEY_TO,
            MC.PRIORITY MC_PRIORITY, --TH? T? ?U TIÊN
            MC.CREATED_BY MC_CREATED_BY, --CreatedBy
            MC.CREATED_DATE MC_CREATED_DATE, --CreatedDate
            MC.MODIFIED_BY MC_MODIFIED_BY, --ModifiedBy
            MC.MODIFIED_DATE MC_MODIFIED_DATE, --ModifiedDate
            MC.DESCRIPTION MC_DESCRIPTION --Description

        FROM GNCN_ROLE_APPROVE_CONFIG MC
        WHERE
            MC.ID IN 
            (
                SELECT b.ID FROM
                    (
                        SELECT rownum STT, a.*
                        FROM
                        (
                            SELECT MC1.ID
                            FROM GNCN_ROLE_APPROVE_CONFIG MC1
                            WHERE             
                                (P_ID IS NULL OR P_ID < 1 OR MC1.ID = P_ID)
                                AND (USE_STATUS = 1)
                                AND (P_TRANS_LEVEL_CODE_1 IS NULL OR P_TRANS_LEVEL_CODE_1 = '' OR MC1.TRANS_LEVEL_CODE_1 LIKE P_TRANS_LEVEL_CODE_1)
                                AND (P_TRANS_LEVEL_CODE_2 IS NULL OR P_TRANS_LEVEL_CODE_2 = '' OR MC1.TRANS_LEVEL_CODE_2 LIKE P_TRANS_LEVEL_CODE_2)
                                AND (P_TRANS_LEVEL_CODE_3 IS NULL OR P_TRANS_LEVEL_CODE_3 = '' OR MC1.TRANS_LEVEL_CODE_3 LIKE P_TRANS_LEVEL_CODE_3)
                                AND (P_APPROVE_LEVEL IS NULL OR P_APPROVE_LEVEL = '' OR MC1.APPROVE_LEVEL LIKE P_APPROVE_LEVEL)
--                                AND (P_INIT_LIMIT_REQUEST IS NULL OR P_INIT_LIMIT_REQUEST < 0 OR MC1.INIT_LIMIT_REQUEST = P_INIT_LIMIT_REQUEST)
                                AND (P_MONEY_FROM IS NULL OR P_MONEY_FROM < 1 OR MC1.MONEY_FROM = P_MONEY_FROM)
                                AND (P_MONEY_TO IS NULL OR P_MONEY_TO < 1 OR MC1.MONEY_TO = P_MONEY_TO)
                                AND (P_PRIORITY IS NULL OR P_PRIORITY <1 OR MC1.PRIORITY LIKE P_PRIORITY)

                            ORDER BY COALESCE(MC1.MODIFIED_DATE, MC1.CREATED_DATE) DESC
                    ) a
                    WHERE rownum < ((P_PAGE_NUM * P_PAGE_SIZES) + 1 )
                ) b
                WHERE STT >= (((P_PAGE_NUM-1) * P_PAGE_SIZES) + 1)
            )
        ORDER BY COALESCE(MC.MODIFIED_DATE, MC.CREATED_DATE);

     SELECT COUNT(*) INTO P_TOTAL_ROWS 
        FROM GNCN_ROLE_APPROVE_CONFIG MC1
        WHERE             
            (P_ID IS NULL OR P_ID < 1 OR MC1.ID = P_ID)
            AND (USE_STATUS = 1)
                                AND (P_TRANS_LEVEL_CODE_1 IS NULL OR P_TRANS_LEVEL_CODE_1 = '' OR MC1.TRANS_LEVEL_CODE_1 LIKE P_TRANS_LEVEL_CODE_1)
                                AND (P_TRANS_LEVEL_CODE_2 IS NULL OR P_TRANS_LEVEL_CODE_2 = '' OR MC1.TRANS_LEVEL_CODE_2 LIKE P_TRANS_LEVEL_CODE_2)
                                AND (P_TRANS_LEVEL_CODE_3 IS NULL OR P_TRANS_LEVEL_CODE_3 = '' OR MC1.TRANS_LEVEL_CODE_3 LIKE P_TRANS_LEVEL_CODE_3)
                                AND (P_APPROVE_LEVEL IS NULL OR P_APPROVE_LEVEL = '' OR MC1.APPROVE_LEVEL LIKE P_APPROVE_LEVEL)
--                                AND (P_INIT_LIMIT_REQUEST IS NULL OR P_INIT_LIMIT_REQUEST < 0 OR MC1.INIT_LIMIT_REQUEST = P_INIT_LIMIT_REQUEST)
                                AND (P_MONEY_FROM IS NULL OR P_MONEY_FROM < 1 OR MC1.MONEY_FROM = P_MONEY_FROM)
                                AND (P_MONEY_TO IS NULL OR P_MONEY_TO < 1 OR MC1.MONEY_TO = P_MONEY_TO)
                                AND (P_PRIORITY IS NULL OR P_PRIORITY <1 OR MC1.PRIORITY LIKE P_PRIORITY);

     --CALCULATE TOTAL PAGE 
     IF MOD(P_TOTAL_ROWS,P_PAGE_SIZES)=0 THEN 
        P_TOTAL_PAGE := ROUND(P_TOTAL_ROWS/P_PAGE_SIZES); 
     ELSE 
        P_TOTAL_PAGE := ROUND(P_TOTAL_ROWS/P_PAGE_SIZES + 1); 
     END IF;
END SP_GET_GNCN_APPROVED_COMPETENT_PAGING;

/
