  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_GNCN_CA_DISBURSEMENT_ATTACHMENT_BY_GNTDCODE" (
     P_GNTD_CODE            VARCHAR,
