/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GNCN_CA_DISBURSEMENT_DOCUMENTS_DETAIL
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_GNCN_CA_DISBURSEMENT_DOCUMENTS_DETAIL" 
(
    P_ID     IN NUMBER,   --Mã h? s? gi?i ngân
    
    P_PAGE_NUM              IN NUMBER   DEFAULT 1,      -- CURRENT PAGE 
    P_PAGE_SIZES            IN NUMBER   DEFAULT 200,     -- NUMBER OF RECORDS PER PAGE     
    P_TOTAL_ROWS            OUT NUMBER, -- TOTAL RECORDS 
    P_TOTAL_PAGE            OUT NUMBER, -- TOTAL PAGES 
    P_PAGING_CURSOR         OUT PAGINGPACKAGE.PAGING_CURSOR
) AS 
BEGIN
  OPEN P_PAGING_CURSOR FOR 
		SELECT
            GCD.ID GCD_ID, --3.2.14	UC01.17 Hoàn thi?n h? s? sau gi?i ngân – Thêm/Ch?nh s?a h? s? c?n hoàn thi?n sau gi?i ngân
            GCD.TASK_ID GCD_TASK_ID, --Mã Task trên BPM
            GCD.INSTANCE_ID GCD_INSTANCE_ID, --Mã Instance ID
            --Tr?ng thái gi?i ngân (Ch? ??ng b? giao d?ch sau khi chuy?n tr?ng thái: GN_HOAN_THANH)
            --Khi ??ng b? ??i tr?ng thái thành: GNCN_KHOI_TAO
            GCD.STATUS GCD_STATUS, 
            GCD.GNTD_CODE GCD_GNTD_CODE, --Mã gi?i ngân tín d?ng
            GCD.PDTD_CODE GCD_PDTD_CODE, --Mã phê duy?t tín d?ng
            GCD.BRANCH_CODE GCD_BRANCH_CODE, --Mã ?VKD - Mã chi nhánh
            GCD.BRANCH_NAME GCD_BRANCH_NAME, --Tên ?VKD - Tên chi nhánh
            GCD.TRANSACTION_CODE GCD_TRANSACTION_CODE, --Lo?i giao d?ch gi?i ngân (Liên k?t ??n b?ng Mapping_Config
            --Lo?i h? s?, g?m:
            -- HO_SO_PHAP_LY
            -- HO_SO_CAP_TIN_DUNG
            -- HO_SO_TAI_CHINH
            -- HO_SO_TAI_SAN
            -- HO_SO_GIAI_NGAN
            -- HO_SO_HACH_TOAN
            GCD.DOCUMENT_TYPE GCD_DOCUMENT_TYPE, 
            GCD.APPROVAL_BY GCD_APPROVAL_BY, --
            GCD.APPROVAL_DATE GCD_APPROVAL_DATE, --
            --Lu?ng Giao d?ch Gi?i ngân
            --G? ?VKD
            --VH ?VKD
            --T?p Trung
            GCD.TRANSACTION_FLOW GCD_TRANSACTION_FLOW, 
            GCD.TRANSACTION_TYPE1 GCD_TRANSACTION_TYPE1, --
            GCD.TRANSACTION_TYPE2 GCD_TRANSACTION_TYPE2, --
            GCD.TRANSACTION_TYPE3 GCD_TRANSACTION_TYPE3, --
            GCD.CUSTOMER_CODE GCD_CUSTOMER_CODE, --Mã khách hàng
            GCD.CUSTOMER_NAME GCD_CUSTOMER_NAME, --Tên khách hàng
            GCD.CREDIT_USER GCD_CREDIT_USER,
            GCD.ID_CARD GCD_ID_CARD,
            GCD.DOCUMENT_SRC GCD_DOCUMENT_SRC,
            GCD.PROCESSING_USERNAME GCD_PROCESSING_USERNAME,
            gcdd.pdtd_code GCDD_PDTD_CODE,

            GCDD.ID GCDD_ID, --UC 09.01 Kh?i t?o hoàn thi?n h? s? sau gi?i ngân
            GCDD.GNTD_CODE GCDD_GNTD_CODE, --Code giao d?ch Gi?i ngân
            GCDD.COMPLETED_AFTER_DISBURSEMENT_ID GCDD_COMPLETED_AFTER_DISBURSEMENT_ID, --UC 16.12 C?u hình H? s? c?n hoàn thi?n sau GN
            GCDD.DOC_CODE GCDD_DOC_CODE, --Mã Ch?ng t?
            GCDD.DOC_NAME GCDD_DOC_NAME, --Tên ch?ng t?
            --Tr?ng thái hoàn thi?n h? s?
            --M?c ??nh: CHUA_HOAN_THANH
            --(Tr?ng thái: CHUA_HOAN_THANH, DANG_THUC_HIEN, HOAN_THANH)
            GCDD.STATUS GCDD_STATUS,
            -- Phân lo?i ch?ng t?
            -- + 1. Quy ??nh s?n ph?m
            -- + 2. Phê duy?t c?a c?p PDTD
            -- + 3. Phê duy?t c?a c?p phê duy?t GNTD
            GCDD.DOC_CATEGORY GCDD_DOC_CATEGORY, 
            -- Th?i gian c?n hoàn thi?n ch?ng t? l?n ??u
            -- + Ch?ng t? ???c c?u hình: set giá tr? = "Th?i gian c?n b? sung ch?ng t? + Today". ??nh d?ng dd/mm/yyyy
            -- + Ch?ng t? thêm m?i/ch?nh s?a: Hi?n th? các n?
            GCDD.DEADLINE GCDD_DEADLINE,
            GCDD.FREQUENCY GCDD_FREQUENCY, --T?n su?t ??ng b? t? b?ng c?u hình
            GCDD.FREQUENCY_UNIT GCDD_FREQUENCY_UNIT, --??n v? t?n su?t (Ngày, tu?n, tháng...). ??ng b? t? b?ng c?u hình
            GCDD.FREQUENCY_DISPLAYTEXT GCDD_FREQUENCY_DISPLAYTEXT, --T?n su?t (1 Tháng/l?n)
            GCDD.DESCRIPTION GCDD_DESCRIPTION, --Ý ki?n
            GCDD.CREATED_BY GCDD_CREATED_BY, --
            GCDD.CREATED_DATE GCDD_CREATED_DATE, --
            GCDD.MODIFIED_BY GCDD_MODIFIED_BY, --
            GCDD.MODIFIED_DATE GCDD_MODIFIED_DATE,
            GCDD.STATUS_DOC GCDD_STATUS_DOC,
            GCDD.GROUP_DOC_CODE GCDD_GROUP_DOC_CODE,
            GCDD.GROUP_DOC_NAME GCDD_GROUP_DOC_CATEGORY,
            GCDD.GROUP_DOC_NAME GCDD_GROUP_DOC_NAME,
            GCDD.DEADLINE_EXT  GCDD_DEADLINE_EXT,
            gcdd.ecm_folder GCDD_ECM_FOLDER,
            GCDD.USER_IDEA GCDD_USER_IDEA,
            GCDD.APPROVAL_IDEA GCDD_APPROVAL_IDEA,
            GCDD.APPROVAL_BY   GCDD_APPROVAL_BY,
            GCDD.ECM_FOLDER GCDD_ECM_FOLDER,
            GCDD.STATUS_APPROVAL GCDD_STATUS_APPROVAL,
            GCDA.ID GCDA_ID, --UC 09.01 Kh?i t?o hoàn thi?n h? s? sau gi?i ngân
            GCDA.DISBURSEMENT_DOC_ID GCDA_DISBURSEMENT_DOC_ID, --
            GCDA.GNTD_CODE GCDA_GNTD_CODE, --
            GCDA.ECM_FILE_ID GCDA_ECM_FILE_ID, --
            GCDA.ECM_FOLDER_PATH GCDA_ECM_FOLDER_PATH, --
            GCDA.FILE_NAME GCDA_FILE_NAME, --
            GCDA.FILE_TYPE GCDA_FILE_TYPE, --
            GCDA.FILE_SIZE GCDA_FILE_SIZE, --
            GCDA.DESCRIPTION GCDA_DESCRIPTION, --
            GCDA.CREATED_BY GCDA_CREATED_BY, --
            GCDA.CREATED_DATE GCDA_CREATED_DATE,
            GCDD.ASSIGNEE_USER_BY  GCDD_ASSIGNEE_USER_BY,
            GCDD.ASSIGNEE_DATE  GCDD_ASSIGNEE_DATE,
            GCDD.APPROVAL_BY  GCDD_APPROVAL_BY,
            GCDD.APPROVAL_DATE  GCDD_APPROVAL_DATE,
            GCDD.APPROVAL_SUBMIT_BY  GCDD_APPROVAL_SUBMIT_BY,
            GCDD.APPROVAL_SUBMIT_DATE  GCDD_APPROVAL_SUBMIT_DATE

        FROM GNCN_CA_DISBURSEMENT_DOCUMENTS  GCDD
        LEFT JOIN GNCN_CA_DISBURSEMENT GCD ON gcd.gntd_code = gcdd.gntd_code
        LEFT JOIN GNCN_CA_DISBURSEMENT_ATTACHMENT GCDA ON GCDD.ID = GCDA.DISBURSEMENT_DOC_ID
        WHERE
            GCDD.ID IN 
            (
                SELECT b.ID FROM
                    (
                        SELECT rownum STT, a.*
                        FROM
                        (
                            SELECT GCDD1.ID
                            FROM GNCN_CA_DISBURSEMENT_DOCUMENTS GCDD1
                            WHERE             
                                (P_ID IS NULL OR P_ID < 1 OR GCDD1.ID = P_ID)
                            ORDER BY COALESCE(GCDD1.MODIFIED_DATE, GCDD1.CREATED_DATE) DESC
                        ) a
                        WHERE rownum < ((P_PAGE_NUM * P_PAGE_SIZES) + 1 )
                    ) b
                WHERE STT >= (((P_PAGE_NUM-1) * P_PAGE_SIZES) + 1)
            )
        ORDER BY COALESCE(GCDD.MODIFIED_DATE, GCDD.CREATED_DATE);

     SELECT COUNT(*) INTO P_TOTAL_ROWS
        FROM GNCN_CA_DISBURSEMENT_DOCUMENTS GCDD1
        WHERE             
            (P_ID IS NULL OR P_ID < 1 OR GCDD1.ID = P_ID);

     --CALCULATE TOTAL PAGE 
     IF MOD(P_TOTAL_ROWS, P_PAGE_SIZES) = 0 THEN 
        P_TOTAL_PAGE := ROUND(P_TOTAL_ROWS/P_PAGE_SIZES); 
     ELSE 
        P_TOTAL_PAGE := ROUND(P_TOTAL_ROWS/P_PAGE_SIZES + 1); 
     END IF;
END SP_GET_GNCN_CA_DISBURSEMENT_DOCUMENTS_DETAIL;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GNCN_CA_DISBURSEMENT_DOCUMENTS_PAGING
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_GNCN_CA_DISBURSEMENT_DOCUMENTS_PAGING" 
(
    p_json_object IN CLOB,
    OUT_DATA OUT SYS_REFCURSOR,
    PAGINATION_INFO OUT SYS_REFCURSOR
) AS 
    json_obj                    JSON_OBJECT_T;
    P_GNTD_CODE                 VARCHAR2(50);   --Code giao d?ch Gi?i ngân
    P_BRANCHS                   VARCHAR2(500);   --Mã Ch?ng t?
    P_CUSTOMER                  VARCHAR(50);
    P_FROM_DATE                 DATE;
    P_TO_DATE                   DATE;
    P_STATES                    VARCHAR(50);
    P_STATUS_DOC                VARCHAR(150);
    P_DOC_NAME                  VARCHAR2(50);   --Tên ch?ng t?
    P_RESULT_APPROVE            VARCHAR2(100);
    P_USER_XU_LY                VARCHAR(50);
    P_CVKH                      VARCHAR(50);
    P_PROCESSING_USER_NAME      VARCHAR(50);
    P_APPROVAL_BY               VARCHAR(50);
    P_STATUS_QUEUE              VARCHAR2(100);
    P_LOGIN_USER                VARCHAR(50);
BEGIN
    IF (p_json_object IS NOT NULL) THEN
        json_obj := JSON_OBJECT_T.parse(p_json_object);
        P_GNTD_CODE := json_obj.get_String('gntdCode');
        P_BRANCHS := json_obj.get_String('branchs');
        P_CUSTOMER := json_obj.get_String('customer');
        P_FROM_DATE := json_obj.get_Date('fromDate');
        P_TO_DATE := json_obj.get_Date('toDate');
        P_RESULT_APPROVE:= json_obj.get_String('resultApprove');
        P_STATUS_QUEUE:= json_obj.get_String('statusQueue'); 
        P_STATES := json_obj.get_String('states');
        P_STATUS_DOC := json_obj.get_String('statusDoc');
        P_DOC_NAME := json_obj.get_String('docName');
        P_USER_XU_LY := json_obj.get_String('userXuLy');
        P_CVKH:= json_obj.get_String('cvkh');
        P_PROCESSING_USER_NAME:= json_obj.get_String('processingUsername');
        P_APPROVAL_BY:= json_obj.get_String('approvalBy');
        P_LOGIN_USER:= json_obj.get_String('userLogin');
    END IF;

  OPEN OUT_DATA FOR 
		SELECT
            GCD.ID                      GCD_ID,
            GCD.TASK_ID                 GCD_TASK_ID,
            GCD.STATUS                  GCD_STATUS, 
            GCD.GNTD_CODE               GCD_GNTD_CODE,
            GCD.PDTD_CODE               GCD_PDTD_CODE,
            GCD.BRANCH_CODE             GCD_BRANCH_CODE,
            GCD.BRANCH_NAME             GCD_BRANCH_NAME,
            GCD.TRANSACTION_CODE        GCD_TRANSACTION_CODE,
            GCD.DOCUMENT_TYPE           GCD_DOCUMENT_TYPE, 
            GCD.APPROVAL_BY             GCD_APPROVAL_BY, --
            GCD.APPROVAL_DATE           GCD_APPROVAL_DATE,
            GCD.TRANSACTION_FLOW        GCD_TRANSACTION_FLOW, 
            GCD.TRANSACTION_TYPE1       GCD_TRANSACTION_TYPE1,
            GCD.TRANSACTION_TYPE2       GCD_TRANSACTION_TYPE2,
            GCD.TRANSACTION_TYPE3       GCD_TRANSACTION_TYPE3,
            GCD.CUSTOMER_CODE           GCD_CUSTOMER_CODE,
            GCD.CUSTOMER_NAME           GCD_CUSTOMER_NAME,
            GCD.CREDIT_USER             GCD_CREDIT_USER,
            GCD.PROCESSING_USERNAME     GCD_PROCESSING_USERNAME,
            GCD.CREATED_BY              GCD_CREATED_BY,
            GCD.DOCUMENT_SRC            GCD_DOCUMENT_SRC,

            GCDD.ID                     GCDD_ID,
            GCDD.GNTD_CODE              GCDD_GNTD_CODE,
            GCDD.COMPLETED_AFTER_DISBURSEMENT_ID GCDD_COMPLETED_AFTER_DISBURSEMENT_ID,
            GCDD.DOC_CODE               GCDD_DOC_CODE,
            GCDD.DOC_NAME               GCDD_DOC_NAME,
            GCDD.group_doc_name         GCDD_GROUP_DOC_NAME,
            GCDD.STATUS                 GCDD_STATUS,
            GCDD.DOC_CATEGORY           GCDD_DOC_CATEGORY,
            GCDD.DEADLINE               GCDD_DEADLINE,
            GCDD.FREQUENCY              GCDD_FREQUENCY,
            GCDD.FREQUENCY_UNIT         GCDD_FREQUENCY_UNIT,
            GCDD.FREQUENCY_DISPLAYTEXT  GCDD_FREQUENCY_DISPLAYTEXT,
            GCDD.DESCRIPTION            GCDD_DESCRIPTION,
            GCDD.GROUP_DOC_CODE         GCDD_GROUP_DOC_CODE,
            GCDD.GROUP_DOC_NAME         GCDD_GROUP_DOC_CATEGORY,
            GCDD.GROUP_DOC_NAME         GCDD_GROUP_DOC_NAME,
            GCDD.CREATED_BY             GCDD_CREATED_BY,
            GCDD.CREATED_DATE           GCDD_CREATED_DATE,
            GCDD.MODIFIED_BY            GCDD_MODIFIED_BY,
            GCDD.MODIFIED_DATE          GCDD_MODIFIED_DATE,
            gcdd.status_verify          GCDD_STATUS_VERIFY,
            GCDD.STATUS_DOC             GCDD_STATUS_DOC,
            GCDD.PRE_STATUS_DOC         GCDD_PRE_STATUS_DOC,
            GCDD.group_doc_name         GCDD_GROUP_DOC_NAME,
            GCDD.status_approval        GCDD_STATUS_APPROVAL,
            GCDD.DEADLINE_EXT           GCDD_DEADLINE_EXT,
            GCDD.ASSIGNEE_ROLE_BY       GCDD_ASSIGNEE_ROLE_BY,
            GCDD.ASSIGNEE_USER_BY       GCDD_ASSIGNEE_USER_BY,
            GCDD.ASSIGNEE_DATE          GCDD_ASSIGNEE_DATE,
            GCDD.ecm_folder             GCDD_ECM_FOLDER,
            GCDD.APPROVAL_BY            GCDD_APPROVAL_BY,
            GCDD.APPROVAL_DATE          GCDD_APPROVAL_DATE,
            GCDD.APPROVAL_SUBMIT_BY     GCDD_APPROVAL_SUBMIT_BY,
            GCDD.APPROVAL_SUBMIT_DATE   GCDD_APPROVAL_SUBMIT_DATE,
            CASE
                WHEN (TRUNC(gcdd.deadline) IS NOT NULL) AND (TRUNC(gcdd.deadline) < TRUNC(SYSDATE))THEN 1
                WHEN (TRUNC(gcdd.deadline) IS NOT NULL) AND (TRUNC(gcdd.deadline) = TRUNC(SYSDATE))THEN 2
                ELSE 3
            END GCDD_ORDER_DEADLINE
        FROM GNCN_CA_DISBURSEMENT_DOCUMENTS  GCDD
        LEFT JOIN GNCN_CA_DISBURSEMENT GCD ON gcd.gntd_code = gcdd.gntd_code
        WHERE             
                GCD.STATUS IN ('GNCN_HOAN_THANH','GNCN_LOI_HACH_TOAN_HAN_MUC', 'GNCN_LOI_HACH_TOAN_KHOAN_VAY', 'GNCN_LOI_HACH_TOAN_THAU_CHI', 'GNCN_LOI_CHUYEN_TIEN', 'GNCN_HOAN_TAT_KHOAN_VAY')
                AND (P_GNTD_CODE IS NULL OR LOWER(GCDD.GNTD_CODE) LIKE '%' || LOWER(P_GNTD_CODE) || '%')
                AND (P_DOC_NAME IS NULL OR LOWER(GCDD.DOC_NAME) like '%' || LOWER(P_DOC_NAME) || '%')
                AND (P_RESULT_APPROVE IS NULL OR  GCDD.STATUS_APPROVAL like P_RESULT_APPROVE)
                AND (P_STATUS_QUEUE IS NULL OR P_STATUS_QUEUE = '' OR GCDD.STATUS = P_STATUS_QUEUE)
                AND (P_USER_XU_LY IS NULL OR P_USER_XU_LY = '' OR LOWER(gcdd.assignee_user_by) like  '%' || LOWER(P_USER_XU_LY)  || '%' )
                AND (P_PROCESSING_USER_NAME IS NULL OR P_PROCESSING_USER_NAME = '' OR  LOWER(GCD.processing_username) like '%' || LOWER(P_PROCESSING_USER_NAME) || '%')
                AND (P_APPROVAL_BY IS NULL OR P_APPROVAL_BY = '' OR LOWER(GCD.approval_by) LIKE '%' || LOWER(P_APPROVAL_BY) || '%')
                AND (P_STATUS_DOC IS NULL OR P_STATUS_DOC = '' OR INSTR(',' || P_STATUS_DOC || ',', ',' || GCDD.STATUS_DOC || ',') > 0)
                AND (P_BRANCHS IS NULL OR P_BRANCHS = '' OR INSTR(',' || P_BRANCHS || ',', ',' || GCD.BRANCH_CODE || ',') > 0)
                AND (P_FROM_DATE IS NULL OR TRUNC(GCDD.deadline) >= TRUNC(P_FROM_DATE))
                AND (P_TO_DATE IS NULL OR TRUNC(GCDD.deadline) <= TRUNC(P_TO_DATE))
                AND (P_CUSTOMER IS NULL OR P_CUSTOMER = '' or (LOWER(GCD.customer_name) like '%' || LOWER(P_CUSTOMER)  || '%') or (GCD.customer_code like '%' || P_CUSTOMER || '%'))
                AND (P_CVKH is null or P_CVKH = '' or LOWER(GCD.credit_user) like  '%' || LOWER(P_CVKH) || '%')
                AND (
                    P_STATES IS NULL OR P_STATES = ''
                    OR (
                        GCDD.status_doc = 'GIA_HAN_BO_SUNG'
                        AND GCDD.STATUS_APPROVAL = 'DONG Y'
                        AND TRUNC(GCDD.deadline_ext) IS NOT NULL
                        AND (
                            (INSTR(P_STATES, '1') > 0 AND TRUNC(GCDD.deadline_ext) = TRUNC(SYSDATE))
                            OR (INSTR(P_STATES, '2') > 0 AND TRUNC(GCDD.deadline_ext) > TRUNC(SYSDATE))
                            OR (INSTR(P_STATES, '3') > 0 AND TRUNC(GCDD.deadline_ext) < TRUNC(SYSDATE))
                        )
                    )
                    OR (
                        (GCDD.status_doc <> 'GIA_HAN_BO_SUNG' OR GCDD.STATUS_APPROVAL <> 'DONG Y')
                        AND TRUNC(GCDD.deadline) IS NOT NULL
                        AND (
                            (INSTR(P_STATES, '1') > 0 AND TRUNC(GCDD.deadline) = TRUNC(SYSDATE))
                            OR (INSTR(P_STATES, '2') > 0 AND TRUNC(GCDD.deadline) > TRUNC(SYSDATE))
                            OR (INSTR(P_STATES, '3') > 0 AND TRUNC(GCDD.deadline) < TRUNC(SYSDATE))
                        )
                    )
                )
        ORDER BY
            -- ?u tiên 1: Các h? s? c?a User khác trong cùng chi nhánh thì hi?n th? xu?ng sau (s?p x?p User X? Lý)
            CASE 
                --WHEN (LOWER(COALESCE(gcdd.modified_by, gcdd.created_by)) = LOWER(P_LOGIN_USER)) THEN 1
                WHEN (LOWER(GCDD.ASSIGNEE_USER_BY) = LOWER(P_LOGIN_USER)) THEN 1
                ELSE 2
            END  ASC,
            -- ?u tiên 2: Hi?n th? h? s? theo Tình tr?ng h? s?: (Quá h?n -> ??n h?n -> S?p ??n h?n) - s?p x?p Tr?ng thái
            GCDD_ORDER_DEADLINE ASC,
            -- ?u tiên hi?n th? h? s? theo Ngày ??n h?n là ngày c? nh?t lên tr??c - s?p x?p ngày
            --TRUNC(COALESCE(TRUNC(gcdd.deadline_ext), TRUNC(gcdd.deadline))) DESC,
            TRUNC(gcdd.deadline) ASC,
            -- ?u tiên hi?n th? h? s? c?a cùng 1 Mã GN lên tr??c g?n nhau (Mã GN)
            gcdd.gntd_code ASC;

END SP_GET_GNCN_CA_DISBURSEMENT_DOCUMENTS_PAGING;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GNCN_CA_DISBURSEMENT_SYNC
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_GNCN_CA_DISBURSEMENT_SYNC" 
(
    P_GNTD_CODE IN VARCHAR2,	
    P_PDTD_CODE IN VARCHAR2,	
    P_BRANCH_CODE IN VARCHAR2,	
    P_TRANSACTION_TYPE1 IN VARCHAR2,
    P_TRANSACTION_TYPE2 IN VARCHAR2,
    P_TRANSACTION_TYPE3 IN VARCHAR2,
    P_CUSTOMER_CODE IN VARCHAR2,	
    P_CUSTOMER_NAME IN VARCHAR2,	
    P_CREDIT_USER IN VARCHAR2,	
    P_PROCESSING_USERNAME IN VARCHAR2,	
    P_APPROVAL_BY IN VARCHAR2,	
    P_DOC_NAME IN VARCHAR2,	
    P_DOC_CATEGORY IN NUMBER,	
    P_DOCUMENT_TYPE IN VARCHAR2,	
    P_STATUS IN VARCHAR2,	
    P_DEADLINE IN VARCHAR2,	
    P_FREQUENCY_UNIT IN VARCHAR2,
    P_FREQUENCY IN NUMBER,	
    P_TRANSACTION_FLOW IN VARCHAR2,	
    P_STATUS_DOC IN VARCHAR2,	
    P_DEADLINE_EXT IN VARCHAR2,	
    P_USER_IDEA IN VARCHAR2,	
    P_ECM_FILE_ID IN VARCHAR2,	
    P_STATUS_APPROVAL IN VARCHAR2,	
    P_APPROVAL_IDEA IN VARCHAR2
)
AS
BEGIN
    DELETE GNCN_CA_DISBURSEMENT WHERE UPPER(GNTD_CODE) = UPPER(P_GNTD_CODE) AND UPPER(PDTD_CODE) = UPPER(P_PDTD_CODE);
    COMMIT;
    INSERT INTO GNCN_CA_DISBURSEMENT
    ( 
        STATUS, -- 
        GNTD_CODE, -- 
        PDTD_CODE, -- 
        BRANCH_CODE, --
        TRANSACTION_TYPE1,
        TRANSACTION_TYPE2,
        TRANSACTION_TYPE3, 
        BRANCH_NAME,
        DOCUMENT_TYPE, -- 
        APPROVAL_BY, -- 
        TRANSACTION_FLOW, -- 
        CUSTOMER_CODE, -- 
        CUSTOMER_NAME, -- 
        CREDIT_USER, -- 
        PROCESSING_USERNAME, -- 
        DOCUMENT_SRC
    ) 
    VALUES 
    ( 
        'GNCN_HOAN_THANH', -- 
        UPPER(P_GNTD_CODE), -- 
        UPPER(P_PDTD_CODE), -- 
        P_BRANCH_CODE, -- 
        P_TRANSACTION_TYPE1,
        P_TRANSACTION_TYPE2,
        P_TRANSACTION_TYPE3,
        (SELECT BRANCHNAME FROM BRANCH WHERE ROWNUM=1 AND UPPER(BRANCHCODE) LIKE UPPER(P_BRANCH_CODE)),
        P_DOCUMENT_TYPE, -- 
        P_APPROVAL_BY, -- 
        P_TRANSACTION_FLOW, -- 
        P_CUSTOMER_CODE, -- 
        P_CUSTOMER_NAME, -- 
        P_CREDIT_USER, -- 
        P_PROCESSING_USERNAME, -- 
        'ECM'
    );

    INSERT INTO GNCN_CA_DISBURSEMENT_DOCUMENTS
    (
        GNTD_CODE, --  
        PDTD_CODE, --  
        DOC_NAME, --
        DOC_CODE,
        STATUS, -- 
        STATUS_APPROVAL,
        DOC_CATEGORY, --  
        DEADLINE, --  
        FREQUENCY_UNIT, 
        FREQUENCY, --  
        STATUS_DOC, --  
        DEADLINE_EXT, --  
        USER_IDEA, --  
        APPROVAL_IDEA, 
        GROUP_DOC_CODE,
        GROUP_DOC_NAME,        
        APPROVAL_BY,
        CREATED_BY,
        CREATED_DATE
    ) 
    VALUES 
    ( 
        UPPER(P_GNTD_CODE), -- 
        UPPER(P_PDTD_CODE), -- 
        P_DOC_NAME, -- 
        --SET CÁC GIÁ TR? M?C ??NH, CH?NH S?A DATA ECM THEO CHU?N C?A BPM
        -- set mã ch?ng t? docCode;
        VN_TO_CAMELCASE(P_DOC_NAME),
        P_STATUS, -- 
        CASE (P_STATUS)
            WHEN 'HSSGN_CHO_PHE_DUYET' THEN 'Ch? phê duy?t'
            ELSE null
        END,
        

        P_DOC_CATEGORY, -- 
        TO_DATE(P_DEADLINE,'yyyy-MM-dd'), --  -- 
        P_FREQUENCY_UNIT, 
        P_FREQUENCY,
        P_STATUS_DOC, -- 
        TO_DATE(P_DEADLINE_EXT,'yyyy-MM-dd'), -- 
        P_USER_IDEA, -- 
        P_APPROVAL_IDEA, 
        P_DOCUMENT_TYPE,        
        CASE (P_DOCUMENT_TYPE)
            WHEN 'HO_SO_GIAI_NGAN_TIN_DUNG' THEN 'H? S? GI?I NGÂN TÍN D?NG'
            WHEN 'HO_SO_CAP_TIN_DUNG' THEN 'H? S? C?P TÍN D?NG'
            WHEN 'HO_SO_PHAP_LY' THEN 'H? S? PHÁP LÝ'
            WHEN 'HO_SO_TAI_CHINH' THEN 'H? S? TÀI CHÍNH'
            WHEN 'HO_SO_TAI_SAN' THEN 'H? S? TS?B'
            WHEN 'HO_SO_HACH_TOAN' THEN 'H? S? H?CH TOÁN'
            ELSE 'NULL TYPE: ' || P_DOCUMENT_TYPE
        END,
        P_APPROVAL_BY,
        'bawadmin',
        SYSDATE
    );
    COMMIT;
END SP_GET_GNCN_CA_DISBURSEMENT_SYNC;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GNCN_CREDIT_APPROVAL_INFO_SYNC
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_GNCN_CREDIT_APPROVAL_INFO_SYNC" (
    P_PDTD_CODE in VARCHAR2, P_PAGING_CURSOR OUT PAGINGPACKAGE.PAGING_CURSOR)
as
BEGIN
    OPEN P_PAGING_CURSOR FOR
        select GCAIS.PDTD_CODE,
               GCAIS.SOURCE_SYNC,
               GCAIS.BRANCH_CODE,
               GCAIS.PRODUCT_CODE,
               GCAIS.PRODUCT_NAME,
               GCAIS.BANK_PRODUCT_NAME,
               GCAIS.SUB_PRODUCT_NAME,
               GCAIS.LOAN_PURPOSE,
               GCAIS.LOAN_PURPOSE_DETAIL,
               GCAIS.VEHICLE_CLASS,
               GCAIS.VEHICLE_CONDITION,
               GCAIS.MANUFACTURE_YEAR,
               GCAIS.WITHDRAWAL_TERM,
               GCAIS.LOAN_PRODUCT_ATTACH,
               GCAIS.LOAN_PRODUCT_ATTACH_DESC,
               GCAIS.LOAN_AMOUNT,
               GCAIS.LOAN_PERCENTAGE,
               GCAIS.LOAN_METHOD,
               GCAIS.AMOUNT_NEEDED,
               GCAIS.AMOUNT_OWNED,
               GCAIS.LOAN_TERM,
               GCAIS.GRACE_PERIOD,
               GCAIS.COMMISSION_FEE,
               GCAIS.PRINCIPAL_REPAYMENT_METHOD,
               GCAIS.INTEREST_REPAYMENT_METHOD,
               GCAIS.PAYMENT_DATE,
               GCAIS.CURRENCY,
               GCAIS.LOAN_INTEREST_RATE,
--               GCAIS.APPROVAL_LEVEL,
                gcais.truong_nhom as APPROVAL_LEVEL, --linhnt92 update 11/02/2025
               GCAIS.APPROVAL_DATE,
               GCAIS.APPROVAL_RESULT,
               GCAIS.APPROVAL_COMMENTS,
               GCAIS.FINANC_INFO_COMMENTS,
               GCAIS.LOAN_TYPE_TEXT,
               GCAIS.CREATED_DATE,
               GCAIS.MODIFIED_DATE,
               GCAIS.FINANC_INFO,
               GCAIS.LOAN_FLOW,
               GCAIS.TRUONG_NHOM,
               GCAIS.CHUYEN_VIEN_KHACH_HANG,


               -- thông tin tài s?n
               GCAAS.id     as ASSET_ID,
               GCAAS.REAL_ESTATE,
               GCAAS.ASSET_FROM_LOAN_CAPITAL,
               GCAAS.ASSET_TYPE,
               GCAAS.COL_BRAND,
               GCAAS.COL_REGISTRATION_NUMBERCAR,
               GCAAS.COL_VEHICLE_NUMBERPLATE,
               GCAAS.COL_VEHICLE_COLOR,
               GCAAS.COL_CHASSIS_NO,
               GCAAS.COL_ENGINE_NUMBER,
               GCAAS.COL_LAND_NO,
               GCAAS.COL_MAP_NO,
               GCAAS.COL_DOCUMENTS_PROVING_USAGE_RIGHT,
               GCAAS.COL_DOCUMENTS_PROVING_OWNERSHIP_RIGHT,
               GCAAS.COL_SAVING_BOOK,
               GCAAS.COL_SAVING_BOOK_DETAIL,

               -- incomeS -- thông tin thu nh?p
               GCAIS2.ID       INCOME_ID,
               GCAIS2.INCOME_TYPE,
               GCAIS2.INCOME_TYPE_BRIEF,
               GCAIS2.INCOME_TYPE_OTHER,
               GCAIS2.INCOME_AMOUNT,

               -- EXPENSES -- chi phí
               GCAES.ID        EXPENSE_ID,
               GCAES.EXPENSE_TYPE,
               GCAES.EXPENSE_VALUE,

               -- customer info
               GCCS.ID      AS CUS_ID,
               GCCS.CIF,
               GCCS.NAME,
               GCCS.CUS_TYPE,
               GCCS.DATE_OF_BIRTH,
               GCCS.LIVING_ADDRESS,
               GCCS.PERMANENT_ADDRESS,
               GCCS.ORIGINAL_HOMETOWN,
               RELATIONSHIP,


               -- thông tin gi?y t? tùy thân
               GCCDS.ID     AS DOCUMENT_ID,
               GCCDS.CUS_ID as CUS_ID_OF_DOC,
               GCCDS.SYS_NAME,
               GCCDS.DOC_ID, -- SO GIAY TO
               GCCDS.ISSUE_DATE,
               GCCDS.ISSUED_BY,
               GCCDS.IS_MAIN_DOC


        from GNCN_CREDIT_APPROVAL_INFO_SYNC GCAIS
                 left join GNCN_CREDIT_APPROVAL_ASSET_SYNC GCAAS
                           on GCAIS.PDTD_CODE = GCAAS.PDTD_CODE
                 left join KHCN_MASTERDATA.GNCN_CREDIT_APPROVAL_INCOME_SYNC GCAIS2
                           on GCAIS.PDTD_CODE = GCAIS2.PDTD_CODE
                 left join KHCN_MASTERDATA.GNCN_CREDIT_APPROVAL_EXPENSE_SYNC GCAES
                           on GCAIS.PDTD_CODE = GCAES.PDTD_CODE
                 left join GNCN_CREDIT_APPROVAL_REF_CUSTOMER_SYNC GCARCS
                           on GCAIS.PDTD_CODE = GCARCS.PDTD_CODE
                 left join GNCN_CREDIT_CUSTOMER_SYNC GCCS on GCARCS.CUS_ID = GCCS.ID
                 left join GNCN_CREDIT_CUSTOMER_DOC_SYNC GCCDS on GCCS.ID = GCCDS.CUS_ID
        where GCAIS.PDTD_CODE = P_PDTD_CODE
        ORDER BY RELATIONSHIP NULLS FIRST, GCCDS.IS_MAIN_DOC DESC; --linhnt92 edit 9/12/2024

END SP_GET_GNCN_CREDIT_APPROVAL_INFO_SYNC;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GNCN_CREDIT_APPROVAL_INFO_SYNC_PAGING
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_GNCN_CREDIT_APPROVAL_INFO_SYNC_PAGING" (
  P_CODE            IN    VARCHAR2,               --MÃ PDTD
  P_SOURCE_SYNC     IN    VARCHAR2,               --NGU?N PDTD
  P_BRANCH_CODE     IN    VARCHAR2,               --MÃ DVKD
  P_CIF             IN    VARCHAR2,               --CIF
  P_ID_CARD         IN    VARCHAR2,               --CCCD
  P_CUSTOMER_NAME   IN    VARCHAR2,               --TÊN KH
  P_PRODUCT_NAME    IN    VARCHAR2,               --SP
  P_FROM_DATE       IN    VARCHAR2,               --T? NGÀY
  P_TO_DATE         IN    VARCHAR2,               --??N NGÀY
  P_PAGE_NUM        IN    NUMBER DEFAULT 1,       -- CURRENT PAGE 
  P_PAGE_SIZES      IN    NUMBER DEFAULT 200,     -- NUMBER OF RECORDS PER PAGE     
  P_TOTAL_ROWS      OUT   NUMBER,                 -- TOTAL RECORDS 
  P_TOTAL_PAGE      OUT   NUMBER,                 -- TOTAL PAGES 
  P_PAGING_CURSOR   OUT   PAGINGPACKAGE.PAGING_CURSOR
) AS 
BEGIN OPEN P_PAGING_CURSOR FOR WITH CREDIT_APPROVAL AS (
                                      SELECT
                                        CAI.CREATED_DATE,
                                        CAI.APPROVAL_LEVEL,
                                        CAI.APPROVAL_DATE,
                                        CAI.CURRENCY,
                                        CAI.LOAN_AMOUNT,
                                        CAI.LOAN_TERM,
                                        CAI.LOAN_METHOD,
                                        CAI.BANK_PRODUCT_NAME,
                                        CAI.PRODUCT_NAME,
                                        CAI.PRODUCT_CODE,
                                        CAI.PDTD_CODE,
                                        CAI.SOURCE_SYNC,
                                        CAI.BRANCH_CODE,
                                        (SELECT  BRANCHNAME FROM BRANCH 
                                        WHERE STATUS='A' AND BRANCHCODE = CAI.BRANCH_CODE fetch first 1 row only) AS BRANCH_NAME,
                                        CARC.CUS_ID
                                      FROM
                                        GNCN_CREDIT_APPROVAL_INFO_SYNC           CAI,
                                        GNCN_CREDIT_APPROVAL_REF_CUSTOMER_SYNC   CARC
                                      WHERE
                                        CAI.PDTD_CODE = CARC.PDTD_CODE
                                        AND CARC.RELATIONSHIP IS NULL
                                    )
                                    SELECT
                                      CA.PDTD_CODE          AC_PDTD_CODE,             --mã PDTD
                                      CA.SOURCE_SYNC        AC_SOURCE_SYNC,           --mã ngu?n PDTD
                                      CA.BRANCH_CODE        AC_BRANCH_CODE,           --mã ?VKD
                                      CA.BRANCH_NAME        AC_BRANCH_NAME,           --tên ?VKD
                                      CC.CIF                AC_CUSTOMER_CODE,                   --CIF, mã kh
                                      CCD.DOC_ID            AC_ID_CARD,               --CCCD
                                      CC.NAME               AC_CUSTOMER_NAME,                  --TÊN KHÁCH HÀNG
                                      CA.PRODUCT_CODE       AC_PRODUCT_CODE,         --MA SAN PHAM
                                      CA.PRODUCT_NAME       AC_PRODUCT_NAME,         --TÊN S?N PH?M
                                      CA.BANK_PRODUCT_NAME,
                                      CA.LOAN_AMOUNT        AC_MONEY_NUM,          --S? TI?N
                                      CA.LOAN_TERM          AC_LOAN_TERM,           -- TH?I H?N VAY
                                      CA.LOAN_METHOD        AC_LOAN_METHOD,
                                      CA.CURRENCY           AC_MONEY_CATEGORY,             --LO?I TI?N
                                      CA.APPROVAL_DATE      AC_APPROVE_DATE_DATE,        --NGÀY PHÊ DUY?T TIMESTAP
--                                      (
--                                        SELECT
--                                          (
--                                            SELECT
--                                              TO_CHAR(AC2.APPROVAL_DATE, 'dd/MM/yyyy')
--                                            FROM
--                                              GNCN_CREDIT_APPROVAL_INFO_SYNC AC2
--                                            WHERE
--                                              ( P_FROM_DATE IS NULL
--                                                OR AC2.APPROVAL_DATE >= TO_DATE(P_FROM_DATE, 'dd/mm/yy') )
--                                              AND ( P_TO_DATE IS NULL
--                                                    OR AC2.APPROVAL_DATE <= TO_DATE(P_TO_DATE, 'dd/mm/yy') + 1 )
--                                              AND ROWNUM = 1
--                                              AND AC2.PDTD_CODE = PDTD_CODE
--                                          )
--                                        FROM
--                                          GNCN_CREDIT_APPROVAL_INFO_SYNC
--                                        WHERE
--                                          ROWNUM = 1
--                                      ) AC_APPROVE_DATE,        --13.TH?I GIAN PHÊ DUY?T
                                      TO_CHAR(CA.APPROVAL_DATE, 'dd/MM/yyyy') AC_APPROVE_DATE, --13.TH?I GIAN PHÊ DUY?T
--                                      CA.APPROVAL_LEVEL AC_APPROVE_LEVEL,        --C?P PHÊ DUY?T
                                      CASE
                                        WHEN UPPER(CA.APPROVAL_LEVEL) = UPPER('Make Decision (in Application screen)') THEN 'CGPD duy?t'
                                        WHEN UPPER(CA.APPROVAL_LEVEL) = UPPER('Make Decision (in Task list screen)') THEN 'G? ?VKD duy?t'
                                        WHEN UPPER(CA.APPROVAL_LEVEL) = UPPER('Make Decision by branch Manager') THEN 'G? ?VKD duy?t'
                                        WHEN UPPER(CA.APPROVAL_LEVEL) = UPPER('Make Decision by Approver') THEN 'CGPD ra quy?t ??nh'
                                        WHEN UPPER(CA.APPROVAL_LEVEL) = UPPER('Meeting Minutes Control') THEN 'Phê duy?t BBH h?p'
                                        ELSE ''
                                      END AC_APPROVE_LEVEL,        --C?P PHÊ DUY?T
                                      CC.CUS_TYPE AC_CUSTOMER_CATEGORY,          --Lo?i KH
                                      CA.CREATED_DATE AC_CREATED_DATE
                                    FROM
                                      CREDIT_APPROVAL                 CA,
                                      GNCN_CREDIT_CUSTOMER_SYNC       CC,
                                      GNCN_CREDIT_CUSTOMER_DOC_SYNC   CCD
                                    WHERE
                                      CA.CUS_ID = CC.ID     
                                      AND CC.ID = CCD.CUS_ID
                                      AND CCD.IS_MAIN_DOC = 1
                                      AND (P_CODE IS NULL OR P_CODE = '' OR CA.PDTD_CODE = P_CODE)     --MÃ PHÊ DUY?T TÍN D?NG
                                      AND (P_SOURCE_SYNC IS NULL OR P_SOURCE_SYNC = '' OR CA.SOURCE_SYNC LIKE '%'||P_SOURCE_SYNC||'%')    --NG?N PHÊ DUY?T
--                                AND (P_BRANCH_CODE IS NULL OR P_BRANCH_CODE = '' OR AC1.BRANCH_CODE LIKE '%'||P_BRANCH_CODE||'%')
                                      AND (P_BRANCH_CODE = '' OR P_BRANCH_CODE IS NULL OR LOWER(CA.BRANCH_CODE) IN (        
                                      SELECT regexp_substr(LOWER(P_BRANCH_CODE),'[^,]+', 1, LEVEL) FROM dual
                                        CONNECT BY regexp_substr(LOWER(P_BRANCH_CODE), '[^,]+', 1, LEVEL) IS NOT NULL))       --?VKD
                                      AND (P_CIF IS NULL OR P_CIF = '' OR CC.CIF = P_CIF)        --CIF
                                      AND (P_ID_CARD IS NULL OR P_ID_CARD = '' OR CCD.DOC_ID LIKE '%'||P_ID_CARD||'%')    --CCCD
                                      AND (P_CUSTOMER_NAME IS NULL OR P_CUSTOMER_NAME = '' OR CC.NAME LIKE '%'||P_CUSTOMER_NAME||'%')   --TÊN KH
--                                AND (P_PRODUCT_NAME IS NULL OR P_PRODUCT_NAME = '' OR AC1.PRODUCT_NAME LIKE '%'||P_PRODUCT_NAME||'%')
                                      AND (P_PRODUCT_NAME = '' OR P_PRODUCT_NAME IS NULL OR LOWER(CA.PRODUCT_NAME) IN (
                                        SELECT regexp_substr(LOWER(P_PRODUCT_NAME),'[^,]+', 1, LEVEL) FROM dual
                                        CONNECT BY regexp_substr(LOWER(P_PRODUCT_NAME), '[^,]+', 1, LEVEL) IS NOT NULL))    --TÊN SP
                                      AND (P_FROM_DATE IS NULL OR P_FROM_DATE = '' OR TO_DATE(P_FROM_DATE, 'dd/mm/yy') <= CA.APPROVAL_DATE)    --T? NGÀY
                                      AND (P_TO_DATE IS NULL OR P_TO_DATE = '' OR (TO_DATE(P_TO_DATE, 'dd/mm/yy')+1) >= CA.APPROVAL_DATE);     --??N NGÀY
    P_TOTAL_PAGE:=1;
    P_TOTAL_ROWS :=4;
END SP_GET_GNCN_CREDIT_APPROVAL_INFO_SYNC_PAGING;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GNCN_EMPLOYEE_PROCESS_CONFIG
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_GNCN_EMPLOYEE_PROCESS_CONFIG" (
    p_json_array IN CLOB,
    OUT_DATA OUT SYS_REFCURSOR
) AS BEGIN 
    IF p_json_array IS NOT NULL THEN OPEN OUT_DATA FOR
        SELECT
            t.USER_NAME AS userName,
            t.FULL_NAME AS fullName,
            t.BRANCH_MAIN AS branchCode,
            t.BRANCHS,
            t.ROLE,
            t.POSITION_CODE AS positionCode,
            t.USER_MANAGER AS userManager
        FROM
            GNCN_EMPLOYEE_PROCESS_CONFIG t
            INNER JOIN json_table(p_json_array, '$[*]' COLUMNS (value PATH '$')) temp on LOWER(t.USER_NAME) = LOWER(temp.value)
        WHERE
            USE_STATUS = 1;
    END IF;

    IF p_json_array IS NULL THEN OPEN OUT_DATA FOR
        SELECT
            t.USER_NAME AS userName,
            t.FULL_NAME AS fullName,
            t.BRANCH_MAIN AS branchCode,
            t.BRANCHS,
            t.ROLE,
            t.POSITION_CODE AS positionCode,
            t.USER_MANAGER AS userManager
        FROM
            GNCN_EMPLOYEE_PROCESS_CONFIG t
        WHERE
            USE_STATUS = 1;
    END IF;

END SP_GET_GNCN_EMPLOYEE_PROCESS_CONFIG;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GNCN_LOAN_PURPOSE_DETAIL
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_GNCN_LOAN_PURPOSE_DETAIL" 
(
    P_JSON_OBJECT IN CLOB, --Mã gi?i ngân tín d?ng
    O_POST_INSPECTION_UNIT OUT SYS_REFCURSOR,
    O_COOPERATIVE_PARTNER OUT SYS_REFCURSOR,
    O_LOAN_PROGRAM OUT SYS_REFCURSOR,
    O_PRODUCT_CODE OUT SYS_REFCURSOR,
    O_PURPOSE_INTEREST_SUPPORT OUT SYS_REFCURSOR,
    O_CAR_AGENCY OUT SYS_REFCURSOR,
    O_CUSTOMER_BUY_DEBT OUT SYS_REFCURSOR,
    O_ORIGIN_KHCN_CODE OUT SYS_REFCURSOR,
    O_ORIGIN_KHDN_CODE OUT SYS_REFCURSOR,
    O_POOL_CODE OUT SYS_REFCURSOR,
    O_EXPERTNAME OUT SYS_REFCURSOR,
    O_PRODUCT_FCC OUT SYS_REFCURSOR,
    O_PG_SEGMT OUT SYS_REFCURSOR,
    O_CC_SEGMT OUT SYS_REFCURSOR,
    O_3C_SEGMT OUT SYS_REFCURSOR
) AS 
    json_obj                    JSON_OBJECT_T;
    P_POST_INSPECTION_UNIT      VARCHAR2(200) DEFAULT '';   --??n v? h?u ki?m
    P_COOPERATIVE_PARTNER       VARCHAR2(50)  DEFAULT '';   --??i tác h?p tác
    P_LOAN_PROGRAM              VARCHAR2(50)  DEFAULT '';   --Ch??ng trình loan 
    P_PRODUCT_CODE              VARCHAR2(50)  DEFAULT '';   --S?n ph?m c? th?
    P_PURPOSE_INTEREST_SUPPORT  VARCHAR2(50)  DEFAULT '';   --M?c ?ích vay ???c h? tr? lãi su?t
    P_CAR_AGENCY                VARCHAR2(50)  DEFAULT '';   --??i lý ô tô
    P_CUSTOMER_BUY_DEBT         VARCHAR2(50)  DEFAULT '';   --Khách hàng mua n?
    P_ORIGIN_KHCN_CODE          VARCHAR2(50)  DEFAULT '';   --Mã SP g?c KHCN
    P_ORIGIN_KHDN_CODE          VARCHAR2(50)  DEFAULT '';   --Mã SP g?c KHDN
    P_POOL_CODE                 VARCHAR2(50)  DEFAULT '';   --Pool code
    P_EXPERTNAME                VARCHAR2(200) DEFAULT '';   --Tên CGPD
    P_PRODUCT_FCC               VARCHAR2(50)  DEFAULT '';   --Mã SP FCC
    P_PG_SEGMT                  VARCHAR2(50)  DEFAULT '';   --PG_SEGMT
    P_CC_SEGMT                  VARCHAR2(50)  DEFAULT '';   --CC_SEGMT
    P_3C_SEGMT                  VARCHAR2(50)  DEFAULT '';   --3C_SEGMT
BEGIN
    json_obj := JSON_OBJECT_T.parse(P_JSON_OBJECT);
    P_POST_INSPECTION_UNIT := json_obj.get_String('postInspectionUnit');
    P_COOPERATIVE_PARTNER := json_obj.get_String('cooperativePartner');
    P_LOAN_PROGRAM := json_obj.get_String('loanProgram');
    P_PRODUCT_CODE := json_obj.get_String('productCode');
    P_PURPOSE_INTEREST_SUPPORT := json_obj.get_String('purposeInterestSupport');
    P_CAR_AGENCY := json_obj.get_String('carAgency');
    P_CUSTOMER_BUY_DEBT := json_obj.get_String('customerBuyDebt');
    P_ORIGIN_KHCN_CODE := json_obj.get_String('originKhcnCode');
    P_ORIGIN_KHDN_CODE := json_obj.get_String('originKhdnCode');
    P_POOL_CODE := json_obj.get_String('poolCode');
    P_EXPERTNAME := json_obj.get_String('expertName');
    P_PRODUCT_FCC := json_obj.get_String('productCodeFcc');
    P_PG_SEGMT := json_obj.get_String('pgSeGmt');
    P_CC_SEGMT := json_obj.get_String('ccSeGmt');
    P_3C_SEGMT := json_obj.get_String('_3cSeGmt');

    OPEN O_POST_INSPECTION_UNIT FOR SELECT NAME, VALUE FROM TD_MASTERDATA.FCC_DANHMUC 
    WHERE VALUE = P_POST_INSPECTION_UNIT AND LABLE = 'DON VI HAU KIEM';

    OPEN O_COOPERATIVE_PARTNER FOR SELECT (VALUE || ' - ' || NAME) as NAME, VALUE FROM TD_MASTERDATA.FCC_DANHMUC 
    WHERE VALUE = P_COOPERATIVE_PARTNER AND LABLE = 'HOP TAC DOI TAC';

    OPEN O_LOAN_PROGRAM FOR SELECT (VALUE || ' - ' || NAME) as NAME, VALUE FROM TD_MASTERDATA.FCC_DANHMUC 
    WHERE VALUE = P_LOAN_PROGRAM AND LABLE = 'CHUONG TRINH LOAN';

    OPEN O_PRODUCT_CODE FOR SELECT (VALUE || ' - ' || NAME) as NAME, VALUE FROM TD_MASTERDATA.FCC_DANHMUC 
    WHERE VALUE = P_PRODUCT_CODE AND LABLE = 'SAN PHAM CU THE';

    OPEN O_PURPOSE_INTEREST_SUPPORT FOR SELECT NAME, VALUE FROM TD_MASTERDATA.FCC_DANHMUC 
    WHERE VALUE = P_PURPOSE_INTEREST_SUPPORT AND LABLE = 'MUC DICH VAY DUOC HTLS';

    OPEN O_CAR_AGENCY FOR SELECT NAME, VALUE FROM TD_MASTERDATA.FCC_DANHMUC 
    WHERE VALUE = P_CAR_AGENCY AND LABLE = 'DAI LY XE O TO';

    OPEN O_CUSTOMER_BUY_DEBT FOR SELECT NAME, VALUE FROM TD_MASTERDATA.FCC_DANHMUC 
    WHERE VALUE = P_CUSTOMER_BUY_DEBT AND LABLE = 'KH MUA NO';

    OPEN O_ORIGIN_KHCN_CODE FOR SELECT NAME, VALUE FROM TD_MASTERDATA.FCC_DANHMUC 
    WHERE VALUE = P_ORIGIN_KHCN_CODE AND LABLE = 'MA SAN PHAM GOC KHCN';

    OPEN O_ORIGIN_KHDN_CODE FOR SELECT NAME, VALUE FROM TD_MASTERDATA.FCC_DANHMUC 
    WHERE VALUE = P_ORIGIN_KHDN_CODE AND LABLE = 'MA SAN PHAM GOC KHDN';

    OPEN O_POOL_CODE FOR SELECT NAME, VALUE FROM TD_MASTERDATA.FCC_DANHMUC 
    WHERE VALUE = P_POOL_CODE AND LABLE = 'POOL_CODE';

    OPEN O_EXPERTNAME FOR SELECT (VALUE || ' - ' || NAME) as NAME, VALUE FROM TD_MASTERDATA.FCC_DANHMUC 
    WHERE VALUE = P_EXPERTNAME AND LABLE = 'TEN CGPD';
    
    OPEN O_PRODUCT_FCC FOR SELECT (VALUE || ' - ' || NAME) as NAME, VALUE FROM TD_MASTERDATA.FCC_DANHMUC 
    WHERE VALUE = P_PRODUCT_FCC AND FCC_TYPE = 'TAO_MOI_KHOAN_VAY' AND LABLE = 'CL_PRODUCT';
    
    OPEN O_PG_SEGMT FOR SELECT (VALUE || ' - ' || NAME) as NAME, VALUE FROM TD_MASTERDATA.FCC_DANHMUC 
    WHERE VALUE = P_PG_SEGMT AND FCC_TYPE = 'TAO_MOI_KHOAN_VAY' AND LABLE = 'PG_SEGMT';
    
    OPEN O_CC_SEGMT FOR SELECT (VALUE || ' - ' || NAME) as NAME, VALUE FROM TD_MASTERDATA.FCC_DANHMUC 
    WHERE VALUE = P_CC_SEGMT AND FCC_TYPE = 'TAO_MOI_KHOAN_VAY' AND LABLE = 'CC_SEGMT';
    
    OPEN O_3C_SEGMT FOR SELECT (VALUE || ' - ' || NAME) as NAME, VALUE FROM TD_MASTERDATA.FCC_DANHMUC 
    WHERE VALUE = P_3C_SEGMT AND FCC_TYPE = 'TAO_MOI_KHOAN_VAY' AND LABLE = '3C_SEGMT';
    
END SP_GET_GNCN_LOAN_PURPOSE_DETAIL;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GNCN_OVERDUE_CA_DISBURSEMENT_DOCUMENTS_PAGING
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_GNCN_OVERDUE_CA_DISBURSEMENT_DOCUMENTS_PAGING" 
(
    P_PDTD_CODE     IN VARCHAR,
    P_PAGING_CURSOR OUT PAGINGPACKAGE.PAGING_CURSOR
) AS 
BEGIN
  OPEN P_PAGING_CURSOR FOR 
		SELECT
            GCDD.ID ID,
            GCDD.GNTD_CODE gntdCode, --Code giao d?ch Gi?i ngân
            GCDD.DOC_NAME docName,
            CASE WHEN GCDD.DOC_CATEGORY = 1 THEN 'Quy ??nh s?n ph?m'
                 WHEN GCDD.DOC_CATEGORY = 2 THEN 'Phê duy?t c?a c?p PDTD'
                 ELSE 'Phê duy?t c?a c?p phê duy?t GNTD'
            END docCategory,
            TO_CHAR(GCDD.DEADLINE, 'DD/MM/YYYY') AS deadline,
            GCD.APPROVAL_BY approvalBy           
        FROM GNCN_CA_DISBURSEMENT_DOCUMENTS  GCDD
        LEFT JOIN GNCN_CA_DISBURSEMENT GCD ON GCD.GNTD_CODE = GCDD.GNTD_CODE
        WHERE 
            GCDD.PDTD_CODE = P_PDTD_CODE 
            AND GCD.STATUS <> 'GNCN_HUY'
            AND trunc(GCDD.DEADLINE) < trunc(SYSDATE) 
--            AND GCDD.STATUS_DOC <> 'DA_BO_SUNG'
            AND GCDD.STATUS IN ('HSSGN_CHO_BO_SUNG', 'HSSGN_CHO_PHE_DUYET');
END SP_GET_GNCN_OVERDUE_CA_DISBURSEMENT_DOCUMENTS_PAGING;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GNCN_SLL_OF_CUSTOMER
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_GNCN_SLL_OF_CUSTOMER" (
    P_CUSTOMER_CODE IN VARCHAR,
    OUT_DATA OUT SYS_REFCURSOR
) AS BEGIN
OPEN OUT_DATA FOR
WITH
trans_filtered AS (
SELECT t.*
    FROM GNCN_TRANSACTION t
    WHERE t.customer_code = P_CUSTOMER_CODE
        AND t.STATUS = 'GNCN_CHO_XU_LY'
        AND (t.TRANSACTION_TYPE1 = 'Giainganthauchi' OR JSON_VALUE(t.LIMIT_JSON_DATA, '$.limitType') <> 2)
)

    SELECT SUM(NVL(JSON_VALUE(T.LIMIT_JSON_DATA, '$.limitValue'), P.TOTAL_AMOUNT)) AS VALUE
    FROM trans_filtered T
    LEFT JOIN gncn_transaction_purpose P ON T.GNTD_CODE = P.GNTD_CODE;

END SP_GET_GNCN_SLL_OF_CUSTOMER;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GNCN_TRANSACTION_ATTACHMENT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_GNCN_TRANSACTION_ATTACHMENT" 
(
    P_GNCN_CODE IN VARCHAR2,
    P_PDTD_CODE IN VARCHAR2,
    P_PAGING_CURSOR OUT PAGINGPACKAGE.PAGING_CURSOR
)
AS 
BEGIN
  OPEN P_PAGING_CURSOR FOR 
    SELECT GTA.ID AS ID,
        GTA.GNCN_CODE AS GNCN_CODE,  --Mã giao d?ch gi?i ngân
        GTA.GROUP_NAME AS GROUP_NAME, --Tên nhóm h? s? c?p 1: "H? s? gi?i ngân tín d?ng" ho?c Tên nhóm h? s? c?p 1 trên ECM
        CASE
            WHEN GTA.ECM_PATH LIKE '%H? S? GI?I NGÂN TÍN D?NG%' AND GTA.DOC_NAME <> 'H? s? khác' THEN GCDC.DOCUMENT
            ELSE GTA.DOC_NAME
        END AS DOC_NAME,  --Danh sách Checklist: Tên checklist ?ã ???c c?u hình ho?c Tên c?a file tài li?u trên ECM
        GCDC.MANDATORY AS MANDATORY,
        GTA.FILE_NAME AS FILE_NAME,  --DisplayName
        GTA.DOC_ID AS DOC_ID,     --ECM ID file
        GTA.ECM_PATH AS ECM_PATH,
        GTA.FILE_SIZE AS FILE_SIZE,
        GTA.DOC_SOURCE AS DOC_SOURCE, --Ngu?n file: BPM, ECM,...
        GTA.CREATED_BY AS CREATED_BY,
        GTA.CREATED_DATE AS CREATED_DATE,
        GTA.MODIFIED_BY AS MODIFIED_BY,
        GTA.MODIFIED_DATE AS MODIFIED_DATE,
        GT.STATUS AS STATUS,
        (SELECT GTH.CREATED_DATE FROM GNCN_TRANSACTION_HISTORY GTH WHERE GTH.GNTD_CODE = GTA.GNCN_CODE 
        AND GTH.ACTION NOT IN ('Kh?i t?o', 'L?u') ORDER BY GTH.CREATED_DATE DESC FETCH FIRST 1 ROWS ONLY) AS APPROVAL_SUBMIT_TIME
    FROM (SELECT TRAN.*, ROW_NUMBER() OVER (PARTITION BY TRAN.DOC_ID ORDER BY TRAN.CREATED_BY DESC) AS rn FROM GNCN_TRANSACTION_ATTACHMENT TRAN) GTA
    LEFT JOIN GNCN_CHECKLIST_DISBURSEMENT_CONFIG GCDC ON GTA.DOC_NAME = TO_CHAR(GCDC.ID)
    LEFT JOIN GNCN_TRANSACTION GT ON GTA.GNCN_CODE = GT.GNTD_CODE
    WHERE GTA.FILE_NAME IS NOT NULL AND GTA.DOC_SOURCE <> 'BPM_PDNL'
    AND rn=1
    AND (P_GNCN_CODE IS NULL OR UPPER(GNCN_CODE)=UPPER(P_GNCN_CODE) OR (GTA.GNCN_CODE IS NULL AND UPPER(GTA.PDTD_CODE)=UPPER(P_PDTD_CODE)));
END SP_GET_GNCN_TRANSACTION_ATTACHMENT;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GNCN_TRANSACTION_BLOCK_ACCOUNT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_GNCN_TRANSACTION_BLOCK_ACCOUNT" (
  p_json_object IN CLOB,
  OUT_DATA OUT SYS_REFCURSOR
)
AS 
  json_obj                JSON_OBJECT_T;
  P_GNTD_CODE             VARCHAR2(50);   --Mã gi?i ngân tín d?ng
  P_PDTD_CODE             VARCHAR2(50);   --Mã PDTD (LOS, BPM, ECM)
  P_CUSTOMER_CODE         VARCHAR2(50);   --Mã Khách Hàng
  P_CUSTOMER_NAME         VARCHAR2(50);   --Tên Khách Hàng
  P_TRANSACTION_TYPE1     VARCHAR2(50);   --Lo?i GD C?p 1
  P_TRANSACTION_FLOW      VARCHAR2(50);   --Mã S?n Ph?m
  P_BRANCH_CODE           VARCHAR2(200);   --Mã ?VKD - Mã chi nhánh
  P_PROCESSING_USER       VARCHAR2(50);   -- USER x? lý
  P_PROCESSING_GROUP      VARCHAR2(50);   -- Nhóm x? lý t?p trung
  P_STATUS                VARCHAR2(50);   -- USER locked
  P_FROM_DATE             VARCHAR2(50);
  P_TO_DATE               VARCHAR2(50);

BEGIN 
  json_obj := JSON_OBJECT_T.parse(p_json_object);
  P_GNTD_CODE := json_obj.get_String('transactionCode');
  P_PDTD_CODE := json_obj.get_String('approvalCode');
  P_CUSTOMER_NAME := json_obj.get_String('customerName');
  P_CUSTOMER_CODE := json_obj.get_String('customerCode');
  P_TRANSACTION_TYPE1 := json_obj.get_String('transactionType');
  P_TRANSACTION_FLOW := json_obj.get_String('transactionFlow');
  P_BRANCH_CODE := json_obj.get_String('branchCode');
  P_PROCESSING_USER := json_obj.get_String('userId');
  P_PROCESSING_GROUP := json_obj.get_String('processGroup');
  P_STATUS := json_obj.get_String('status');
  P_FROM_DATE := json_obj.get_String('fromDate');
  P_TO_DATE := json_obj.get_String('toDate');

  OPEN OUT_DATA FOR 
    WITH
    trans_filtered AS (
    SELECT 
      a.*,
      t.NAME AS TRANSACTION_TYPE1_NAME,
      s.NAME AS STATUS_NAME,
      c.NAME AS TRANSACTION_FLOW_NAME
    FROM (
        SELECT 
            GT.ID,
            GT.STATUS,
            GT.GNTD_CODE,
            GT.BRANCH_CODE,
            GT.BRANCH_NAME,
            GT.TRANSACTION_FLOW,
            GT.ID_CARD,
            GT.CUSTOMER_CODE,
            GT.CUSTOMER_NAME,
            (GT.CUSTOMER_CODE || '<br/>' || GT.CUSTOMER_NAME) AS customerDisplay,
            GT.CUSTOMER_TYPE,
            GT.PRODUCT_CODE,
            GT.PRODUCT_NAME,
            GT.TRANSACTION_TYPE1,
            GT.PDTD_CODE,
            GT.CURRENCY,
            GT.APPROVER_SUGGEST,
            GT.PROCESSING_USER ,
            GT.PROCESS_GROUP AS processGroup,
            GT.PROCESSING_OWNER,
            TO_CHAR(GT.PROCESSING_DATE, 'DD-MM-YYYY HH24:MI:SS') AS processingDate,
            GT.USER_LOCKED,
            GT.DESCRIPTION,
            GT.CREATED_BY,
            TO_CHAR(GT.CREATED_DATE, 'DD-MM-YYYY HH24:MI:SS') AS CREATED_DATE,
            GT.MODIFIED_BY,
            TO_CHAR(GT.MODIFIED_DATE, 'DD-MM-YYYY HH24:MI:SS') AS MODIFIED_DATE
            FROM GNCN_TRANSACTION GT
            WHERE ((P_STATUS IS NULL AND GT.STATUS IN ('GNCN_LOI_HACH_TOAN_KHOAN_VAY', 'GNCN_LOI_HACH_TOAN_THAU_CHI', 'GNCN_LOI_CHUYEN_TIEN', 'GNCN_HOAN_TAT_KHOAN_VAY', 'GNCN_HOAN_THANH'))
                        OR UPPER(GT.STATUS) = UPPER(P_STATUS))
                AND ((P_TRANSACTION_TYPE1 IS NULL AND GT.TRANSACTION_TYPE1 IN ('Giainganthauchi', 'Giaingankhoanvay')) OR UPPER(GT.TRANSACTION_TYPE1) = UPPER(P_TRANSACTION_TYPE1))
                AND (P_GNTD_CODE IS NULL OR LOWER(GT.GNTD_CODE) LIKE '%' || LOWER(P_GNTD_CODE) || '%')
                AND (P_PDTD_CODE IS NULL OR LOWER(GT.PDTD_CODE) LIKE '%' || LOWER(P_PDTD_CODE) || '%')
                AND (P_CUSTOMER_CODE IS NULL OR LOWER(GT.CUSTOMER_CODE) LIKE '%' || LOWER(P_CUSTOMER_CODE) || '%')
                AND (P_CUSTOMER_NAME IS NULL OR LOWER(GT.CUSTOMER_NAME) LIKE '%' || LOWER(P_CUSTOMER_NAME) || '%')
                AND (P_TRANSACTION_FLOW IS NULL OR UPPER(GT.TRANSACTION_FLOW) = UPPER(P_TRANSACTION_FLOW))
                AND (P_PROCESSING_GROUP IS NULL OR UPPER(GT.PROCESS_GROUP) = UPPER(P_PROCESSING_GROUP))
                AND (P_PROCESSING_USER  IS NULL OR LOWER(GT.PROCESSING_OWNER) = LOWER(P_PROCESSING_USER))
                AND (P_BRANCH_CODE = '' OR P_BRANCH_CODE IS NULL OR INSTR(P_BRANCH_CODE, GT.BRANCH_CODE) > 0)
                AND (P_FROM_DATE IS NULL OR TRUNC(GT.PROCESSING_DATE) >= TO_DATE(P_FROM_DATE, 'YYYY-MM-DD'))
                AND (P_TO_DATE IS NULL OR TRUNC(GT.PROCESSING_DATE) <= TO_DATE(P_TO_DATE, 'YYYY-MM-DD'))
              ORDER BY APPROVAL_SUBMIT_TIME DESC
              FETCH FIRST 1000 ROWS ONLY
        ) a
        LEFT JOIN GNCN_STATUS s ON s.CODE = a.STATUS
        LEFT JOIN (SELECT * FROM GNCN_TRANSACTION_TYPE WHERE LEVEL_TYPE = 1 AND USE_STATUS = 1) t ON t.CODE = a.TRANSACTION_TYPE1
        LEFT JOIN (SELECT * FROM GNCN_CONFIG_COMMONS WHERE SCOPE = 'TRAN_FLOW') c ON c.CODE = a.TRANSACTION_FLOW
    ),
    trans_block_account AS (
        SELECT DISTINCT GNCN_CODE, REF_NO_FCC_LOCK
        FROM GNCN_TRANSACTION_PAYMENT_DEAIL
        WHERE RECEIVE_LOCK = 1
          AND REF_NO_FCC_LOCK IS NOT NULL
    )

    SELECT t.*, bc.REF_NO_FCC_LOCK as refNoFccLock
    FROM trans_block_account bc
    JOIN trans_filtered t ON t.GNTD_CODE = bc.GNCN_CODE;

END SP_GET_GNCN_TRANSACTION_BLOCK_ACCOUNT;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GNCN_TRANSACTION_DETAIL
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_GNCN_TRANSACTION_DETAIL" 
(
  P_GNTD_CODE IN VARCHAR2, --Mã gi?i ngân tín d?ng
  P_TRANSACTION_BO OUT SYS_REFCURSOR,
  P_TRANS_APPROVAL OUT SYS_REFCURSOR,
  P_REASON_REFUSE OUT SYS_REFCURSOR,
  P_TRANS_FCC OUT SYS_REFCURSOR,
  P_TRANSACTION_PURPOSES OUT SYS_REFCURSOR,
  P_TRANS_PAYMENT OUT SYS_REFCURSOR,
  P_TRANS_PAYMENT_DETAIL OUT SYS_REFCURSOR
) AS 
BEGIN
  OPEN P_TRANSACTION_BO FOR 
    SELECT t.*, s.NAME AS STATUS_NAME, c.NAME AS TRANSACTION_FLOW_NAME
    FROM (SELECT * FROM GNCN_TRANSACTION WHERE GNTD_CODE = P_GNTD_CODE) t
    LEFT JOIN GNCN_STATUS s ON s.CODE = t.STATUS
    LEFT JOIN GNCN_CONFIG_COMMONS c ON c.CODE = t.TRANSACTION_FLOW AND c.SCOPE = 'TRAN_FLOW';
    
  OPEN P_TRANS_APPROVAL FOR 
    SELECT *
    FROM GNCN_TRANSACTION_APPROVAL
    WHERE GNTD_CODE = P_GNTD_CODE
    ORDER BY CREATED_DATE DESC
    FETCH FIRST 1 ROW ONLY;

  OPEN P_REASON_REFUSE FOR
    SELECT * FROM GNCN_REASON_REFUSE R
    WHERE R.TRANS_APPROVAL_ID IN 
    (SELECT A.ID FROM GNCN_TRANSACTION_APPROVAL A WHERE A.GNTD_CODE = P_GNTD_CODE 
    ORDER BY A.CREATED_DATE DESC FETCH FIRST 1 ROW ONLY);

  OPEN P_TRANS_FCC FOR SELECT * FROM GNCN_TRANSACTION_FCC WHERE GNTD_CODE = P_GNTD_CODE;

  OPEN P_TRANSACTION_PURPOSES FOR SELECT * FROM GNCN_TRANSACTION_PURPOSE WHERE GNTD_CODE = P_GNTD_CODE;
  
  OPEN P_TRANS_PAYMENT FOR SELECT * FROM GNCN_TRANSACTION_PAYMENT WHERE GNTD_CODE = P_GNTD_CODE;

  OPEN P_TRANS_PAYMENT_DETAIL FOR SELECT * FROM GNCN_TRANSACTION_PAYMENT_DEAIL PD WHERE PD.GNCN_CODE = P_GNTD_CODE;

END SP_GET_GNCN_TRANSACTION_DETAIL;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GNCN_TRANSACTION_DISCUSSION
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_GNCN_TRANSACTION_DISCUSSION" 
(
    P_GNCN_CODE IN VARCHAR2,
    P_PAGING_CURSOR OUT PAGINGPACKAGE.PAGING_CURSOR
)
AS 
BEGIN
  OPEN P_PAGING_CURSOR FOR 
    SELECT ID,
        GNCN_CODE AS GNCNCODE,
        USER_NAME AS USERNAME,
        DISPLAY_NAME AS DISPLAYNAME,
        CONTENT,
        VOTE,
        RATING,
        DESCRIPTION,
        CREATED_BY AS CREATEDBY,
        CREATED_DATE AS CREATEDDATE,
        MODIFIED_BY AS MODIFIEDBY,
        MODIFIED_DATE AS MODIFIED_DATE 
    FROM GNCN_TRANSACTION_DISSCUSTION WHERE P_GNCN_CODE IS NULL OR UPPER(GNCN_CODE)=UPPER(P_GNCN_CODE) ORDER BY created_date DESC;
END SP_GET_GNCN_TRANSACTION_DISCUSSION;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GNCN_TRANSACTION_DOC
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_GNCN_TRANSACTION_DOC" 
(  
    P_GNTD_CODE       IN  VARCHAR2,
    P_PAGING_CURSOR   OUT SYS_REFCURSOR
) AS
BEGIN
    OPEN P_PAGING_CURSOR FOR 
    SELECT
    TD.ID,
    TD.PDTD_CODE,
    TD.GNCN_CODE,
    TD.DOCUMENT_GROUP,
    TD.DOCUMENT_CATEGORY,
    TD.COMPLETED_TIME,
    TD.COMPLETED_USER,
    TD.STATUS,
    TD.REASON,
    TD.OTHER_REASON,
    NVL(
        (SELECT JSON_ARRAYAGG(
            JSON_OBJECT('gncnCode' VALUE lq.GNCN_CODE, 'docId' VALUE lq.DOC_ID, 'fileName' VALUE lq.file_name,
            'id' VALUE lq.ID, 'docName' VALUE lq.DOC_NAME, 'fileSize' VALUE lq.FILE_SIZE, 'transactionDocId' VALUE lq.TRANSACTION_DOC_ID)
        )
        FROM GNCN_TRANSACTION_ATTACHMENT lq
        WHERE lq.TRANSACTION_DOC_ID = TD.id),
        null
    ) AS infoAttachment
    FROM 
        GNCN_TRANSACTION_DOC TD
    WHERE 
        TD.GNCN_CODE = P_GNTD_CODE;
END SP_GET_GNCN_TRANSACTION_DOC;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GNCN_TRANSACTION_DOC_AND_ATTACHMENT_BY_PDTD
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_GNCN_TRANSACTION_DOC_AND_ATTACHMENT_BY_PDTD" 
(  
    P_PDTD            IN  VARCHAR2,
    P_PAGING_CURSOR   OUT SYS_REFCURSOR
) AS
BEGIN
    OPEN P_PAGING_CURSOR FOR 
    SELECT
    UF.ID,
    uf.PDTD_CODE,
    UF.DOCUMENT_GROUP,
    UF.DOCUMENT_CATEGORY,
    UF.COMPLETED_TIME,
    UF.COMPLETED_USER,
    UF.STATUS,
    UF.REASON,
    UF.OTHER_REASON,
    NVL(
        (SELECT JSON_ARRAYAGG(
            JSON_OBJECT('gncnCode' VALUE lq.GNCN_CODE, 'docId' VALUE lq.DOC_ID, 'fileName' VALUE lq.file_name,
            'id' VALUE lq.ID, 'docName' VALUE lq.DOC_NAME, 'fileSize' VALUE lq.FILE_SIZE, 'transactionDocId' VALUE lq.TRANSACTION_DOC_ID)
        )
        FROM GNCN_TRANSACTION_ATTACHMENT lq
        WHERE lq.TRANSACTION_DOC_ID = UF.id),
        null
    ) AS infoAttachment
    FROM 
        gncn_transaction_doc UF
    WHERE 
        UF.PDTD_CODE = P_PDTD;
END SP_GET_GNCN_TRANSACTION_DOC_AND_ATTACHMENT_BY_PDTD;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GNCN_TRANSACTION_LOCKED
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_GNCN_TRANSACTION_LOCKED" (
  p_json_object IN CLOB,
  OUT_DATA OUT SYS_REFCURSOR
)
AS 
  json_obj                JSON_OBJECT_T;
  P_GNTD_CODE             VARCHAR2(50);   --Mã gi?i ngân tín d?ng
  P_PDTD_CODE             VARCHAR2(50);   --Mã PDTD (LOS, BPM, ECM)
  P_CUSTOMER_CODE         VARCHAR2(50);   --Mã Khách Hàng
  P_CUSTOMER_NAME         VARCHAR2(50);   --Tên Khách Hàng
  P_TRANSACTION_TYPE1     VARCHAR2(50);   --Lo?i GD C?p 1
  P_TRANSACTION_FLOW      VARCHAR2(50);   --Mã S?n Ph?m
  P_BRANCH_CODE           VARCHAR2(200);   --Mã ?VKD - Mã chi nhánh
  P_PROCESSING_USER       VARCHAR2(50);   -- USER x? lý
  P_PROCESSING_GROUP      VARCHAR2(50);   -- Nhóm x? lý t?p trung
  P_USER_LOCKED           VARCHAR2(50);   -- USER locked
  P_FROM_DATE             VARCHAR2(50);
  P_TO_DATE               VARCHAR2(50);

BEGIN 
  json_obj := JSON_OBJECT_T.parse(p_json_object);
  P_GNTD_CODE := json_obj.get_String('transactionCode');
  P_PDTD_CODE := json_obj.get_String('approvalCode');
  P_CUSTOMER_NAME := json_obj.get_String('customerName');
  P_CUSTOMER_CODE := json_obj.get_String('customerCode');
  P_TRANSACTION_TYPE1 := json_obj.get_String('transactionType');
  P_TRANSACTION_FLOW := json_obj.get_String('transactionFlow');
  P_BRANCH_CODE := json_obj.get_String('branchCode');
  P_PROCESSING_USER := json_obj.get_String('userId');
  P_PROCESSING_GROUP := json_obj.get_String('processGroup');
  P_USER_LOCKED := json_obj.get_String('userLocked');
  P_FROM_DATE := json_obj.get_String('fromDate');
  P_TO_DATE := json_obj.get_String('toDate');

  OPEN OUT_DATA FOR 
		SELECT 
      a.*,
      t.NAME AS TRANSACTION_TYPE1_NAME,
      s.NAME AS STATUS_NAME,
      c.NAME AS TRANSACTION_FLOW_NAME
    FROM (
      SELECT
        GT.ID,
        GT.STATUS,
        GT.GNTD_CODE,
        GT.BRANCH_CODE,
        GT.BRANCH_NAME,
        GT.TRANSACTION_FLOW,
        GT.ID_CARD,
        GT.CUSTOMER_CODE,
        GT.CUSTOMER_NAME,
        (GT.CUSTOMER_CODE || '<br/>' || GT.CUSTOMER_NAME) AS customerDisplay,
        GT.CUSTOMER_TYPE,
        GT.PRODUCT_CODE,
        GT.PRODUCT_NAME,
        GT.TRANSACTION_TYPE1,
        GT.PDTD_CODE,
        GT.CURRENCY,
        GT.APPROVER_SUGGEST,
        GT.PROCESSING_USER ,
        GT.PROCESS_GROUP AS processGroup,
        GT.PROCESSING_OWNER,
        TO_CHAR(GT.PROCESSING_DATE, 'DD-MM-YYYY HH24:MI:SS') AS processingDate,
        GT.USER_LOCKED,
        GT.DESCRIPTION,
        GT.CREATED_BY,
        TO_CHAR(GT.CREATED_DATE, 'DD-MM-YYYY HH24:MI:SS') AS CREATED_DATE,
        GT.MODIFIED_BY,
        TO_CHAR(GT.MODIFIED_DATE, 'DD-MM-YYYY HH24:MI:SS') AS MODIFIED_DATE
      FROM
        GNCN_TRANSACTION GT
      WHERE      
        GT.STATUS = 'GNCN_CHO_XU_LY' AND GT.USER_LOCKED IS NOT NULL
        AND (P_GNTD_CODE IS NULL OR LOWER(GT.GNTD_CODE) LIKE '%' || LOWER(P_GNTD_CODE) || '%')
        AND (P_PDTD_CODE IS NULL OR LOWER(GT.PDTD_CODE) LIKE '%' || LOWER(P_PDTD_CODE) || '%')
        AND (P_CUSTOMER_CODE IS NULL OR LOWER(GT.CUSTOMER_CODE) LIKE '%' || LOWER(P_CUSTOMER_CODE) || '%')
        AND (P_CUSTOMER_NAME IS NULL OR LOWER(GT.CUSTOMER_NAME) LIKE '%' || LOWER(P_CUSTOMER_NAME) || '%')
        AND (P_TRANSACTION_TYPE1 IS NULL OR UPPER(GT.TRANSACTION_TYPE1) = UPPER(P_TRANSACTION_TYPE1))
        AND (P_TRANSACTION_FLOW IS NULL OR UPPER(GT.TRANSACTION_FLOW) = UPPER(P_TRANSACTION_FLOW))
        AND (P_PROCESSING_GROUP IS NULL OR UPPER(GT.PROCESS_GROUP) = UPPER(P_PROCESSING_GROUP))
        AND (P_PROCESSING_USER  IS NULL OR LOWER(GT.PROCESSING_OWNER) = LOWER(P_PROCESSING_USER))
        AND (P_USER_LOCKED  IS NULL OR LOWER(GT.USER_LOCKED) = LOWER(P_USER_LOCKED))
        AND (P_BRANCH_CODE = '' OR P_BRANCH_CODE IS NULL OR INSTR(P_BRANCH_CODE, GT.BRANCH_CODE) > 0)
        AND (P_FROM_DATE IS NULL OR TRUNC(GT.PROCESSING_DATE) >= TO_DATE(P_FROM_DATE, 'YYYY-MM-DD'))
        AND (P_TO_DATE IS NULL OR TRUNC(GT.PROCESSING_DATE) <= TO_DATE(P_TO_DATE, 'YYYY-MM-DD'))
      ORDER BY APPROVAL_SUBMIT_TIME DESC
      FETCH FIRST 1000 ROWS ONLY
    ) a
    LEFT JOIN GNCN_STATUS s ON s.CODE = a.STATUS
    LEFT JOIN (SELECT * FROM GNCN_TRANSACTION_TYPE WHERE LEVEL_TYPE = 1 AND USE_STATUS = 1) t ON t.CODE = a.TRANSACTION_TYPE1
    LEFT JOIN (SELECT * FROM GNCN_CONFIG_COMMONS WHERE SCOPE = 'TRAN_FLOW') c ON c.CODE = a.TRANSACTION_FLOW;

END SP_GET_GNCN_TRANSACTION_LOCKED;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GNCN_TRANSACTION_PAGING_V2
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_GNCN_TRANSACTION_PAGING_V2" 
(
    p_json_object IN CLOB,
    OUT_DATA OUT SYS_REFCURSOR,
    PAGINATION_INFO OUT SYS_REFCURSOR
)
AS 
    json_obj                JSON_OBJECT_T;
    P_STATUS                VARCHAR2(200) DEFAULT '';   --Tr?ng thái

    P_GNTD_CODE             VARCHAR2(50);   --Mã gi?i ngân tín d?ng
    P_PDTD_CODE             VARCHAR2(50);   --Mã PDTD (LOS, BPM, ECM)
    P_CUSTOMER_CODE         VARCHAR2(50);   --Mã Khách Hàng
    P_CUSTOMER_NAME         VARCHAR2(50);   --Tên Khách Hàng
    P_TRANSACTION_TYPE1     VARCHAR2(50);   --Lo?i GD C?p 1
    P_TRANSACTION_TYPE2     VARCHAR2(50);   --Lo?i GD C?p 2
    P_TRANSACTION_FLOW      VARCHAR2(50);   --Mã S?n Ph?m
    P_BRANCH_CODE           VARCHAR2(200);   --Mã ?VKD - Mã chi nhánh
    P_HOME_BRANCH_CODE      VARCHAR2(50);   --Mã ?VKD - Mã chi nhánh chính
    P_PROCESSING_USER       VARCHAR2(50);   -- USER x? lý
    P_PROCESSING_GROUP      VARCHAR2(50);   -- Nhóm x? lý t?p trung
    -- Th?i ?i?m chuy?n ch? x? lý. Tr??ng h?p ch?a chuy?n ch? x? lý thì l?y ngày t?o
    P_FROM_PROCESSING_DATE  DATE;
    P_TO_PROCESSING_DATE    DATE;

    P_PAGE_INDEX            NUMBER DEFAULT 1;      -- CURRENT PAGE 
    P_PAGE_SIZES            NUMBER DEFAULT 20;     -- NUMBER OF RECORDS PER PAGE
    P_PAGE_OFFSET           NUMBER DEFAULT 0;
    v_checkStatus           VARCHAR2(2) DEFAULT '0';
    
BEGIN 
    json_obj := JSON_OBJECT_T.parse(p_json_object);
    P_STATUS := json_obj.get_String('status');
    P_GNTD_CODE := json_obj.get_String('gntdCode');
    P_PDTD_CODE := json_obj.get_String('pdtdCode');
    P_CUSTOMER_NAME := json_obj.get_String('customerName');
    P_CUSTOMER_CODE := json_obj.get_String('customerCode');
    P_TRANSACTION_TYPE1 := json_obj.get_String('transactionType1');
    P_TRANSACTION_TYPE2 := json_obj.get_String('transactionType2');
    P_TRANSACTION_FLOW := json_obj.get_String('transactionFlow');
    P_BRANCH_CODE := json_obj.get_String('branchs');
    --P_HOME_BRANCH_CODE := json_obj.get_String('homeBranchCode'); (S? d?ng cho ?u tiên s?p x?p th? t? giao d?ch
    P_PROCESSING_USER := json_obj.get_String('processingUser');
    P_PROCESSING_GROUP := json_obj.get_String('processingGroup');
    P_FROM_PROCESSING_DATE := json_obj.get_Date('fromProcessingDate');
    P_TO_PROCESSING_DATE := json_obj.get_Date('toProcessingDate');
    
    IF (
      P_STATUS IS NULL AND P_GNTD_CODE IS NULL AND P_PDTD_CODE IS NULL
      AND P_CUSTOMER_CODE IS NULL AND P_CUSTOMER_NAME IS NULL
    ) THEN v_checkStatus := '1'; END IF;
    
    P_PAGE_INDEX := json_obj.get_Number('pageIndex');
    IF (P_PAGE_INDEX IS NULL) THEN P_PAGE_INDEX := 1; END IF;
    P_PAGE_SIZES := json_obj.get_Number('pageSize');
    IF (P_PAGE_SIZES IS NULL) THEN P_PAGE_SIZES := 2000; END IF;
    P_PAGE_OFFSET := P_PAGE_INDEX * P_PAGE_SIZES;
    
    OPEN OUT_DATA FOR 
		SELECT
            GT.ID                           id, --ID giao d?ch Gi?i ngân
            GT.STATUS                       status, --Tr?ng thái
            GT.GNTD_CODE                    gntdCode, --Mã gi?i ngân tín d?ng
            GT.BRANCH_CODE                  branchCode, --Mã ?VKD - Mã chi nhánh
            GT.BRANCH_NAME                  branchName, --Tên ?VKD - Tên chi nhánh
            GT.TRANSACTION_FLOW             transactionFlow, -- Phân lu?ng phê duy?t
            GT.ID_CARD                      idCard, --C?n c??c công dân
            GT.CUSTOMER_CODE                customerCode, --Mã Khách Hàng
            GT.CUSTOMER_NAME                customerName, --Tên Khách Hàng
            GT.CUSTOMER_TYPE                customerType, --Lo?i Khách Hàng
            GT.PRODUCT_CODE                 productCode, --Mã S?n Ph?m
            GT.PRODUCT_NAME                 productName, --Tên S?n Ph?m
            GT.TRANSACTION_TYPE1            transactionType1, --Lo?i GD C?p 1
            GT.TRANSACTION_TYPE2            transactionType2, --Lo?i GD C?p 2
            GT.TRANSACTION_TYPE3            transactionType3, --Lo?i GD C?p 3
            GT.USE_PDTD                     usePdtd, --Dùng mã PDTD (True/False)
            GT.PDTD_CODE                    pdtdCode, --Mã PDTD (LOS, BPM, ECM)
            GT.CURRENCY                     currency, --Lo?? ti?n PDTD
            GT.APPROVER_SUGGEST             approverSuggest, -- User PD ???c ?? xu?t
            GT.PROCESSING_USER              processingUser, -- User x? lý
            GT.PROCESS_GROUP                processGroup, -- Nhóm x? lý t?p trung
            GT.PROCESSING_OWNER             processingOwner, -- User ?? xu?t
            GT.PROCESSING_DATE              processingDate, --L?u ngày t?i tr?ng thái ch? x? lý. Tr??ng h?p ch?a chuy?n b??c ch? x? lý thì giá tr? này = null
            GT.APPROVAL_BY                  approvalBy, -- Ng??i phê duy?t
            GT.APPROVAL_DATE                approvalDate, -- Th?i gian phê duy?t
            GT.USER_LOCKED                  userLocked,
            GT.DESCRIPTION                  description,
            GT.CREATED_BY                   createdBy,
            GT.CREATED_DATE                 createdDate,
            GT.MODIFIED_BY                  modifiedBy,
            GT.MODIFIED_DATE                modifiedDate,
            GT.YELLOW_FLAG_DATE             yellowFlagDate, -- C?nh báo SLA
            GT.RED_FLAG_DATE                redFlagDate -- C?nh báo SLA

        FROM GNCN_TRANSACTION GT
        WHERE      
            (v_checkStatus = '0' OR (v_checkStatus = '1' AND INSTR('GNCN_HUY,GNCN_HOAN_THANH', GT.STATUS) = 0))
            AND (P_STATUS = '' OR P_STATUS IS NULL OR INSTR(P_STATUS, GT.STATUS) > 0)
            AND (P_GNTD_CODE            IS NULL OR LOWER(GT.GNTD_CODE)     LIKE '%' || LOWER(P_GNTD_CODE) || '%')
            AND (P_PDTD_CODE            IS NULL OR LOWER(GT.PDTD_CODE)     LIKE '%' || LOWER(P_PDTD_CODE) || '%')
            AND (P_CUSTOMER_CODE        IS NULL OR LOWER(GT.CUSTOMER_CODE) LIKE '%' || LOWER(P_CUSTOMER_CODE) || '%')
            AND (P_CUSTOMER_NAME        IS NULL OR LOWER(GT.CUSTOMER_NAME) LIKE '%' || LOWER(P_CUSTOMER_NAME) || '%')
            AND (P_TRANSACTION_TYPE1    IS NULL OR GT.TRANSACTION_TYPE1    LIKE P_TRANSACTION_TYPE1)
            AND (P_TRANSACTION_TYPE2    IS NULL OR GT.TRANSACTION_TYPE2    LIKE P_TRANSACTION_TYPE2)
            AND (P_TRANSACTION_FLOW     IS NULL OR GT.TRANSACTION_FLOW     LIKE P_TRANSACTION_FLOW)
            AND (P_PROCESSING_GROUP     IS NULL OR GT.PROCESS_GROUP        LIKE P_PROCESSING_GROUP)
            AND (P_BRANCH_CODE = '' OR P_BRANCH_CODE IS NULL OR INSTR(P_BRANCH_CODE, GT.BRANCH_CODE) > 0)
            AND (P_PROCESSING_USER  IS NULL OR LOWER(GT.PROCESSING_OWNER) LIKE '%' || LOWER(P_PROCESSING_USER) || '%')
            AND (P_FROM_PROCESSING_DATE IS NULL OR TRUNC(GT.PROCESSING_DATE) >= TRUNC(P_FROM_PROCESSING_DATE))
            AND (P_TO_PROCESSING_DATE   IS NULL OR TRUNC(GT.PROCESSING_DATE) <= TRUNC(P_TO_PROCESSING_DATE))
          ORDER BY COALESCE(GT.MODIFIED_DATE, GT.CREATED_DATE) DESC
        FETCH FIRST P_PAGE_SIZES ROWS ONLY;

     OPEN PAGINATION_INFO FOR
     SELECT COUNT(*) AS TOTAL_RECORD
        FROM GNCN_TRANSACTION GT
        WHERE   
            (v_checkStatus = '0' OR (v_checkStatus = '1' AND INSTR('GNCN_HUY,GNCN_HOAN_THANH', GT.STATUS) = 0))
            AND (P_STATUS = '' OR P_STATUS IS NULL OR INSTR(P_STATUS, GT.STATUS) > 0)
            AND (P_GNTD_CODE            IS NULL OR LOWER(GT.GNTD_CODE)     LIKE '%' || LOWER(P_GNTD_CODE) || '%')
            AND (P_PDTD_CODE            IS NULL OR LOWER(GT.PDTD_CODE)     LIKE '%' || LOWER(P_PDTD_CODE) || '%')
            AND (P_CUSTOMER_CODE        IS NULL OR LOWER(GT.CUSTOMER_CODE) LIKE '%' || LOWER(P_CUSTOMER_CODE) || '%')
            AND (P_CUSTOMER_NAME        IS NULL OR LOWER(GT.CUSTOMER_NAME) LIKE '%' || LOWER(P_CUSTOMER_NAME) || '%')
            AND (P_TRANSACTION_TYPE1    IS NULL OR GT.TRANSACTION_TYPE1    LIKE P_TRANSACTION_TYPE1)
            AND (P_TRANSACTION_TYPE2    IS NULL OR GT.TRANSACTION_TYPE2    LIKE P_TRANSACTION_TYPE2)
            AND (P_TRANSACTION_FLOW     IS NULL OR GT.TRANSACTION_FLOW     LIKE P_TRANSACTION_FLOW)
            AND (P_PROCESSING_GROUP     IS NULL OR GT.PROCESS_GROUP        LIKE P_PROCESSING_GROUP)
            AND (P_BRANCH_CODE = '' OR P_BRANCH_CODE IS NULL OR INSTR(P_BRANCH_CODE, GT.BRANCH_CODE) > 0)
            AND (P_PROCESSING_USER  IS NULL OR LOWER(GT.PROCESSING_OWNER) LIKE '%' || LOWER(P_PROCESSING_USER) || '%')
            AND (P_FROM_PROCESSING_DATE IS NULL OR TRUNC(GT.PROCESSING_DATE) >= TRUNC(P_FROM_PROCESSING_DATE))
            AND (P_TO_PROCESSING_DATE   IS NULL OR TRUNC(GT.PROCESSING_DATE) <= TRUNC(P_TO_PROCESSING_DATE));

END SP_GET_GNCN_TRANSACTION_PAGING_V2;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GNCN_TRANSACTION_USER_SEND_NOTIFICATION
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_GNCN_TRANSACTION_USER_SEND_NOTIFICATION" (
    P_GNCN_CODE IN VARCHAR2,
    P_USER_NAME IN VARCHAR2,
    P_PAGING_CURSOR OUT SYS_REFCURSOR
)
AS
    V_CREATED_BY VARCHAR2(100);
BEGIN
    -- Get user create transaction
    SELECT CREATED_BY INTO V_CREATED_BY
    FROM GNCN_TRANSACTION WHERE GNTD_CODE = P_GNCN_CODE;

    -- Send noti to list related users + user created transaction
   OPEN P_PAGING_CURSOR FOR 
		SELECT DISTINCT USER_NAME FROM GNCN_TRANSACTION_DISSCUSTION GTD
        LEFT JOIN GNCN_TRANSACTION GT ON GTD.GNCN_CODE = GT.GNTD_CODE
        WHERE (P_GNCN_CODE IS NULL OR GNCN_CODE = P_GNCN_CODE) 
        AND (P_USER_NAME IS NULL OR USER_NAME <> P_USER_NAME)
        UNION
        SELECT V_CREATED_BY FROM DUAL WHERE V_CREATED_BY <> P_USER_NAME;
END SP_GET_GNCN_TRANSACTION_USER_SEND_NOTIFICATION;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GNCN_WORKLOAD_USER
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_GNCN_WORKLOAD_USER" (
    p_json_array IN CLOB,
    OUT_DATA OUT SYS_REFCURSOR
) AS BEGIN
OPEN OUT_DATA FOR
WITH
trans_filtered AS (
SELECT t.*,
    LOWER(t.USER_LOCKED) AS USER_LOCKED_LOWER, LOWER(t.APPROVAL_BY) AS APPROVAL_BY_LOWER
    FROM GNCN_TRANSACTION t
    WHERE t.APPROVAL_SUBMIT_TIME >= TRUNC(SYSDATE)
        AND t.APPROVAL_SUBMIT_TIME < TRUNC(SYSDATE)+1
        AND t.STATUS NOT IN ('GNCN_KHOI_TAO','GNCN_HUY','GNCN_CHO_BO_SUNG')
),
mapping_config_filtered AS (
SELECT
      TRANS_LEVEL_CODE_1,
      TRANS_LEVEL_CODE_2,
      TRANS_LEVEL_CODE_3,
      PRODUCT_NAME,
      MAX(COEFFICIENT) AS COEFFICIENT
    FROM
      GNCN_MAPPING_CONFIG
    WHERE USE_STATUS = 1
    GROUP BY TRANS_LEVEL_CODE_1, TRANS_LEVEL_CODE_2, TRANS_LEVEL_CODE_3, PRODUCT_NAME
)

    SELECT
        usr.account,
        usr.factor,
        usr.switchFactor,
        usr.maxSwitchFactor,
        NVL(SUM(usr.FACTOR * mc.coefficient),0) AS workVolume
    FROM json_table(
        p_json_array, 
        '$[*]' COLUMNS (
            account          VARCHAR2(100) PATH '$.account',
            factor           NUMBER  PATH '$.factor',
            switchFactor     NUMBER  PATH '$.switchFactor',
            maxSwitchFactor  NUMBER  PATH '$.maxSwitchFactor'
        )
    ) usr
    LEFT JOIN trans_filtered t
        ON (
            CASE
                WHEN t.STATUS = 'GNCN_CHO_XU_LY'
                    THEN COALESCE(t.USER_LOCKED_LOWER, t.APPROVER_SUGGEST)
                ELSE t.APPROVAL_BY_LOWER
            END
        ) = usr.account
    LEFT JOIN mapping_config_filtered mc
        ON t.TRANSACTION_TYPE1 = mc.TRANS_LEVEL_CODE_1 AND t.TRANSACTION_TYPE2 = mc.TRANS_LEVEL_CODE_2 AND t.TRANSACTION_TYPE3 = mc.TRANS_LEVEL_CODE_3 AND t.PRODUCT_NAME = mc.PRODUCT_NAME
    GROUP BY usr.account, usr.factor, usr.switchFactor, usr.maxSwitchFactor
    ORDER BY workVolume, usr.factor;
END SP_GET_GNCN_WORKLOAD_USER;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_GN_LIMIT_TRANS_BY_PDTD_CODE
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_GN_LIMIT_TRANS_BY_PDTD_CODE" (
  I_PDTD_CODE IN VARCHAR,
  I_STATUS IN VARCHAR,
  OUT_DATA OUT SYS_REFCURSOR
) AS BEGIN OPEN OUT_DATA FOR
  SELECT
    t.GNTD_CODE AS gntdCode,
    t.PDTD_CODE AS pdtdCode,
    t.CUSTOMER_CODE AS customerCode,
    t.BRANCH_CODE AS branchCode,
    t.TRANSACTION_FLOW AS transactionFlow,
    t.TRANSACTION_TYPE1 AS transactionType1,
    t.TRANSACTION_TYPE2 AS transactionType2,
    t.TRANSACTION_TYPE3 AS transactionType3,
    t.LIMIT_CODE AS limitCode,
    t.STATUS,
    s.NAME AS statusName,
    t.CREATED_BY AS createdBy,
    t.CREATED_DATE AS createdDate,
    t.APPROVAL_BY AS approvalBy,
    t.APPROVAL_SUBMIT_TIME AS approvalSubmitTime,
    t.APPROVAL_DATE AS approvalDate,
    t.PROCESSING_OWNER AS processingOwner
  FROM
    (
      SELECT
        *
      FROM
        GNCN_TRANSACTION
      WHERE
        PDTD_CODE = I_PDTD_CODE
        AND LIMIT_CODE IS NOT NULL
        AND STATUS IS NOT NULL
        AND STATUS <> I_STATUS
    ) t
    LEFT JOIN GNCN_STATUS s ON s.CODE = t.STATUS
    ORDER BY t.APPROVAL_DATE DESC;

END SP_GET_GN_LIMIT_TRANS_BY_PDTD_CODE;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_HAU_KIEM_TRANSACTION_BY_STATUSES
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_HAU_KIEM_TRANSACTION_BY_STATUSES" (
    in_statuses_str IN VARCHAR2,
    sys_cursor      OUT SYS_REFCURSOR
) AS
BEGIN
    OPEN sys_cursor FOR
    WITH trans AS (
        SELECT *
        FROM hkcn_transaction
        WHERE submit_date >= trunc(sysdate) - 1 + INTERVAL '21' HOUR
          AND submit_date < trunc(sysdate) + INTERVAL '21' HOUR
          AND pa_status IN (
                SELECT TRIM(REGEXP_SUBSTR(in_statuses_str, '[^,]+', 1, LEVEL))
                FROM dual
                CONNECT BY LEVEL <= REGEXP_COUNT(in_statuses_str, ',') + 1
          )
    )
    SELECT
        gcais.truong_nhom,
        gcais.chuyen_vien_khach_hang,
        gt.branch_code,
        gt.branch_name,
        gt.gntd_code,
        gt.customer_code,
        gt.customer_name,
        gt.pdtd_code,
        gt.processing_date                 AS ngaypheduyetgn,
        gt.processing_owner                AS userdexuatgn,
        gt.approval_by                     AS userpheduyetgn,
        hth_last_hk.user_hau_kiem_gan_nhat AS userhaukiem,
        CASE
            WHEN ht.pa_status = 'HOAN_THANH' THEN
                'Không phát sinh l?i HK c?n hoàn thi?n'
            ELSE
                'Có phát sinh l?i h?u ki?m c?n hoàn thi?n'
        END                                AS ketqua,
        hth_agg.listusercc                 AS listusercc,
        ht.submit_date                     AS ngayhaukiem,
        hth_last_hk.user_hau_kiem_gan_nhat AS userhaukiemgannhat,
        hth_last_kp.user_khac_phuc         AS userkhacphuchaukiem,
        ht.user_assign                     AS userphancong
    FROM trans ht
    LEFT JOIN gncn_credit_approval_info_sync gcais
        ON gcais.pdtd_code = ht.pdtd_code
    LEFT JOIN gncn_transaction gt
        ON gt.gntd_code = ht.gntd_code

    -- L?y user H?u ki?m g?n nh?t
    LEFT JOIN (
        SELECT
            gntd_code,
            created_by AS user_hau_kiem_gan_nhat
        FROM (
            SELECT
                h.gntd_code,
                h.created_by,
                ROW_NUMBER() OVER (
                    PARTITION BY h.gntd_code
                    ORDER BY h.created_date DESC, h.id DESC
                ) AS rn
            FROM hkcn_transaction_history h
            INNER JOIN trans t
                ON t.gntd_code = h.gntd_code
            WHERE h.action = 'Chuy?n b??c'
              AND h.to_step IN ('HK - Ch? b? sung', 'HK - Hoàn thành')
        )
        WHERE rn = 1
    ) hth_last_hk
        ON hth_last_hk.gntd_code = ht.gntd_code

    -- L?y user KH?C PH?C h?u ki?m
    LEFT JOIN (
        SELECT
            gntd_code,
            created_by AS user_khac_phuc
        FROM (
            SELECT
                h.gntd_code,
                h.created_by,
                ROW_NUMBER() OVER (
                    PARTITION BY h.gntd_code
                    ORDER BY h.created_date DESC, h.id DESC
                ) AS rn
            FROM hkcn_transaction_history h
            INNER JOIN trans t
                ON t.gntd_code = h.gntd_code
            WHERE h.action = 'Chuy?n b??c'
              AND h.from_step = 'HK - Ch? b? sung'
        )
        WHERE rn = 1
    ) hth_last_kp
        ON hth_last_kp.gntd_code = ht.gntd_code

    -- Danh sách user CC
    LEFT JOIN (
        SELECT
            gntd_code,
            LISTAGG(created_by, ',')
                WITHIN GROUP (ORDER BY created_by) AS listusercc
        FROM (
            SELECT DISTINCT
                h.gntd_code,
                h.created_by
            FROM hkcn_transaction_history h
            INNER JOIN trans t
                ON t.gntd_code = h.gntd_code
            WHERE h.action = 'Chuy?n b??c'
              AND h.to_step IN ('HK - Ch? b? sung', 'HK - Hoàn thành')
        )
        GROUP BY gntd_code
    ) hth_agg
        ON hth_agg.gntd_code = ht.gntd_code;

END sp_get_hau_kiem_transaction_by_statuses;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_HAU_KIEM_TRANSACTION_BY_STATUSES_OLD
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_HAU_KIEM_TRANSACTION_BY_STATUSES_OLD" (
    in_statuses_str IN VARCHAR2,
    sys_cursor      OUT SYS_REFCURSOR
) AS
BEGIN
    OPEN sys_cursor FOR SELECT
                                                gcais.truong_nhom,
                                                gcais.chuyen_vien_khach_hang,
                                                gt.branch_code,
                                                gt.branch_name,
                                                gt.gntd_code,
                                                gt.customer_code,
                                                gt.customer_name,
                                                gt.pdtd_code,
                                                gt.processing_date                 AS ngaypheduyetgn,
                                                gt.processing_owner                AS userdexuatgn,
                                                gt.approval_by                     AS userpheduyetgn,
                                                hth_last_hk.user_hau_kiem_gan_nhat AS userhaukiem,
                                                CASE
                                                    WHEN ht.pa_status = 'HOAN_THANH' THEN
                                                        'Không phát sinh l?i HK c?n hoàn thi?n'
                                                    ELSE
                                                        'Có phát sinh l?i h?u ki?m c?n hoàn thi?n'
                                                END                                AS ketqua,
                                                hth_agg.listusercc                 AS listusercc,
                                                ht.submit_date                     AS ngayhaukiem,
                                                hth_last_hk.user_hau_kiem_gan_nhat AS userhaukiemgannhat,
                                                hth_last_kp.user_khac_phuc         AS userkhacphuchaukiem,
                                                ht.user_assign                     AS userphancong
                                            FROM
                                                hkcn_transaction               ht
                                                LEFT JOIN gncn_credit_approval_info_sync gcais ON gcais.pdtd_code = ht.pdtd_code
                                                LEFT JOIN gncn_transaction               gt ON gt.gntd_code = ht.gntd_code
                                                
                                                -- L?y user H?u ki?m g?n nh?t là CREATED_BY c?a b?n ghi cu?i cùng trong l?ch s? có to_step = 'HK - Ch? b? sung'
                                                LEFT JOIN (
                                                    SELECT
                                                        gntd_code,
                                                        created_by AS user_hau_kiem_gan_nhat
                                                    FROM
                                                        (
                                                            SELECT
                                                                h.gntd_code,
                                                                h.created_by,
                                                                ROW_NUMBER()
                                                                OVER(PARTITION BY h.gntd_code
                                                                     ORDER BY
                                                                         h.created_date DESC, h.id DESC
                                                                ) AS rn
                                                            FROM
                                                                hkcn_transaction_history h
                                                            WHERE
                                                                    h.created_date >= trunc(sysdate) - 15 + INTERVAL '21' HOUR
                                                                AND h.created_date < trunc(sysdate) + INTERVAL '21' HOUR
                                                                AND h.action = 'Chuy?n b??c'
                                                                AND h.to_step = 'HK - Ch? b? sung'
                                                        )
                                                    WHERE
                                                        rn = 1
                                                )                              hth_last_hk ON hth_last_hk.gntd_code = ht.gntd_code
                
                                                -- L?y user KH?C PH?C h?u ki?m là CREATED_BY c?a b?n ghi cu?i cùng trong l?ch s?
                                                LEFT JOIN (
                                                    SELECT
                                                        gntd_code,
                                                        created_by AS user_khac_phuc
                                                    FROM
                                                        (
                                                            SELECT
                                                                h.gntd_code,
                                                                h.created_by,
                                                                ROW_NUMBER()
                                                                OVER(PARTITION BY h.gntd_code
                                                                     ORDER BY
                                                                         h.created_date DESC, h.id DESC
                                                                ) AS rn
                                                            FROM
                                                                hkcn_transaction_history h
                                                            WHERE
                                                                    h.created_date >= trunc(sysdate) - 15 + INTERVAL '21' HOUR
                                                                AND h.created_date < trunc(sysdate) + INTERVAL '21' HOUR
                                                                AND h.action = 'Chuy?n b??c'
                                                                AND h.from_step = 'HK - Ch? b? sung'
                                                        )
                                                    WHERE
                                                        rn = 1
                                                )                              hth_last_kp ON hth_last_kp.gntd_code = ht.gntd_code
                
                                                -- Subquery gom chu?i danh sách user ?ã lo?i trùng
                                                LEFT JOIN (
                                                    SELECT
                                                        gntd_code,
                                                        LISTAGG(created_by, ',') WITHIN GROUP(
                                                        ORDER BY
                                                            created_by
                                                        ) AS listusercc
                                                    FROM
                                                        (
                                                            SELECT DISTINCT
                                                                gntd_code,
                                                                created_by
                                                            FROM
                                                                hkcn_transaction_history
                                                            WHERE
                                                                    created_date >= trunc(sysdate) - 15 + INTERVAL '21' HOUR
                                                                AND created_date < trunc(sysdate) + INTERVAL '21' HOUR
                                                                AND action = 'Chuy?n b??c'
                                                                AND to_step IN ( 'HK - Ch? b? sung', 'HK - Hoàn thành' )
                                                        )
                                                    GROUP BY
                                                        gntd_code
                                                )                              hth_agg ON hth_agg.gntd_code = ht.gntd_code
                        WHERE 
                                --         TRUNC(ht.SUBMIT_DATE) = TRUNC(SYSDATE)
                                ht.submit_date >= trunc(sysdate) - 1 + INTERVAL '21' HOUR
                            AND ht.submit_date < trunc(sysdate) + INTERVAL '21' HOUR
                            AND ht.pa_status IN (
                                SELECT
                                    TRIM(regexp_substr(in_statuses_str, '[^,]+', 1, level))
                                FROM
                                    dual
                                CONNECT BY
                                    level <= regexp_count(in_statuses_str, ',') + 1
                            );

END sp_get_hau_kiem_transaction_by_statuses_old;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_HKCN_JOB_HISTORY
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_HKCN_JOB_HISTORY" (
    p_USER IN VARCHAR2 DEFAULT NULL,
    p_BRANCH_CODE IN VARCHAR2 DEFAULT NULL,
    p_FROM_DATE IN DATE DEFAULT NULL,
    p_TO_DATE IN DATE DEFAULT NULL,
    OUT_DATA OUT SYS_REFCURSOR
)
AS
    v_from_date_trunc DATE;
    v_to_date_trunc   DATE;
BEGIN
    -- chu?n hoá ngày (m?c ??nh = TRUNC(SYSDATE) - 3)
    v_from_date_trunc := TRUNC(NVL(p_FROM_DATE, TRUNC(SYSDATE) - 7));
    v_to_date_trunc   := TRUNC(NVL(p_TO_DATE, TRUNC(SYSDATE)));
    OPEN OUT_DATA FOR
        SELECT 
            GN.APPROVAL_BY, 
            GN.BRANCH_CODE, 
            TRUNC(GN.APPROVAL_DATE) AS APPROVAL_DATE,
            COUNT(GN.GNTD_CODE) AS TOTAL_GN,
            SUM(CASE WHEN HK.GNTD_CODE IS NOT NULL THEN 1 ELSE 0 END) AS TOTAL_HK
        FROM 
            GNCN_TRANSACTION GN
        LEFT JOIN 
            HKCN_TRANSACTION HK ON GN.GNTD_CODE = HK.GNTD_CODE
        WHERE 
            GN.APPROVAL_DATE >= v_from_date_trunc
            AND GN.APPROVAL_DATE < v_to_date_trunc + 1
            AND GN.APPROVAL_DATE IS NOT NULL
            AND GN.APPROVAL_BY IS NOT NULL
            AND (p_BRANCH_CODE IS NULL OR GN.BRANCH_CODE = p_BRANCH_CODE)
            AND (p_USER IS NULL OR LOWER(GN.APPROVAL_BY) = p_USER)
             
        GROUP BY 
            TRUNC(GN.APPROVAL_DATE), GN.APPROVAL_BY, GN.BRANCH_CODE
        ORDER BY 
            TRUNC(GN.APPROVAL_DATE) DESC, GN.APPROVAL_BY, GN.BRANCH_CODE;
END SP_GET_HKCN_JOB_HISTORY;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_HKCN_JOB_HISTORY_DETAIL
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_HKCN_JOB_HISTORY_DETAIL" (
    p_USER IN VARCHAR2 DEFAULT NULL,
    p_BRANCH_CODE IN VARCHAR2 DEFAULT NULL,
    p_APPROVAL_DATE IN DATE,
    OUT_DATA OUT SYS_REFCURSOR
)
AS
BEGIN
    OPEN OUT_DATA FOR
        SELECT 
            GN.GNTD_CODE, 
            GN.PDTD_CODE, 
            GN.BRANCH_CODE, 
            GN.TRANSACTION_TYPE1, 
            GN.TRANSACTION_TYPE2,
            GN.PRODUCT_NAME, 
            GN.TRANSACTION_FLOW, 
            GN.PROCESSING_OWNER, 
            GN.APPROVAL_BY, 
            GT.NAME STATUS, 
            'Không có thông tin' as STATUS_DOC,
            (SELECT MAX(PA_TYPE_CODE) FROM HKCN_TRANSACTION_CONFIG 
             WHERE USE_STATUS = 1
             AND TRANS_LEVEL_CODE_1 = GN.TRANSACTION_TYPE1 
             AND TRANS_LEVEL_CODE_2 = GN.TRANSACTION_TYPE2
             AND TRANS_LEVEL_CODE_3 = GN.TRANSACTION_TYPE3 
             AND PRODUCT_CODE = GN.PRODUCT_NAME) AS PA_TYPE,
             HK.PA_RATE,
            CASE WHEN HK.GNTD_CODE IS NOT NULL THEN 'Có' ELSE 'Không' END AS IS_HK
        FROM 
            GNCN_TRANSACTION GN
        LEFT JOIN 
            HKCN_TRANSACTION HK ON GN.GNTD_CODE = HK.GNTD_CODE
        LEFT JOIN 
            GNCN_STATUS GT ON GN.STATUS = GT.CODE
        WHERE
             GN.APPROVAL_DATE >= TRUNC(p_APPROVAL_DATE)
            AND GN.APPROVAL_DATE < TRUNC(p_APPROVAL_DATE) + 1
            AND (p_USER IS NULL OR LOWER(GN.APPROVAL_BY) = LOWER(p_USER))
            AND (p_BRANCH_CODE IS NULL OR GN.BRANCH_CODE = p_BRANCH_CODE)
            AND GN.STATUS IN ('GNCN_LOI_CHUYEN_TIEN','GNCN_HOAN_THANH','GNCN_HOAN_TAT_KHOAN_VAY')
            
        ORDER BY GN.ID;
END SP_GET_HKCN_JOB_HISTORY_DETAIL;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_HK_SYNC_TASK_HUB
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_HK_SYNC_TASK_HUB" (
  P_GNTD_CODE IN VARCHAR2,
  OUT_DATA OUT SYS_REFCURSOR
) AS BEGIN OPEN OUT_DATA FOR
  WITH
  type_leve1 AS (SELECT CODE, NAME FROM GNCN_TRANSACTION_TYPE WHERE USE_STATUS=1 AND LEVEL_TYPE = 1)
  SELECT
    HK.GNTD_CODE,
    HK.PDTD_CODE,
    TL.NAME AS TRANSACTION_TYPE1,
    HK.CUSTOMER_CODE,
    HK.CUSTOMER_NAME,
    HK.BRANCH_CODE,
    CASE WHEN HK.PA_STATUS <> 'CHO_BO_SUNG' THEN NVL(HK.USER_PA, HK.USER_ASSIGN) ELSE null END ISSUED_BY,
    CASE WHEN HK.PA_STATUS = 'HOAN_THANH' THEN NVL(HK.USER_PA, HK.USER_ASSIGN) ELSE null END APPROVAL_BY,
    CASE WHEN HK.PA_STATUS = 'HOAN_THANH' THEN TO_CHAR(HK.UPDATED_DATE, 'DD/MM/YYYY HH24:MI:SS') END AS APPROVAL_DATE,
    HK.PA_STATUS as STATUS,
    HK.PA_EXPIRY_DATE AS DUE_DATE,
    RTRIM(
         NVL2(HK.USER_ASSIGN, HK.USER_ASSIGN || ',', NULL)
      || CASE WHEN HK.GN_APPROVAL_BY IS NOT NULL
               AND HK.GN_APPROVAL_BY <> NVL(HK.USER_ASSIGN, CHR(0))
              THEN HK.GN_APPROVAL_BY || ',' END
      || CASE WHEN HK.UPDATED_BY IS NOT NULL
               AND HK.UPDATED_BY NOT IN (NVL(HK.USER_ASSIGN, CHR(0)),
                                         NVL(HK.GN_APPROVAL_BY, CHR(0)))
              THEN HK.UPDATED_BY || ',' END
      || CASE WHEN HK.USER_PA IS NOT NULL
               AND HK.USER_PA NOT IN (NVL(HK.USER_ASSIGN, CHR(0)),
                                              NVL(HK.GN_APPROVAL_BY, CHR(0)),
                                              NVL(HK.UPDATED_BY, CHR(0)))
              THEN HK.USER_PA || ',' END
    , ',') AS participant,
    CASE WHEN HK.PA_STATUS <> 'CHO_BO_SUNG' THEN HK.USER_ASSIGN END as approverSuggest,
    HK.UPDATED_DATE as MODIFIED_DATE,
    HK.PA_RESULT as result
  FROM HKCN_TRANSACTION HK
  LEFT JOIN type_leve1 TL ON TL.CODE = HK.TRANS_LEVEL_CODE_1
  WHERE HK.GNTD_CODE = P_GNTD_CODE;

END SP_GET_HK_SYNC_TASK_HUB;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_HSSGN_SYNC_TASK_HUB
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_HSSGN_SYNC_TASK_HUB" (
  P_CODE IN VARCHAR2,
  OUT_DATA OUT SYS_REFCURSOR
) AS BEGIN OPEN OUT_DATA FOR
  WITH
  type_leve1 AS (SELECT CODE, NAME FROM GNCN_TRANSACTION_TYPE WHERE USE_STATUS=1 AND LEVEL_TYPE = 1)
  SELECT
    DD.ID,
    cd.GNTD_CODE,
    cd.PDTD_CODE,
    TL.NAME AS TRANSACTION_TYPE1,
    cd.CUSTOMER_CODE,
    cd.CUSTOMER_NAME,
    cd.BRANCH_CODE,
    cd.BRANCH_NAME,
    CASE WHEN dd.STATUS = 'HSSGN_CHO_PHE_DUYET' THEN NVL(dd.ASSIGNEE_USER_BY, dd.APPROVAL_BY)
        ELSE CD.PROCESSING_USERNAME
    END ISSUED_BY,
    TO_CHAR((NVL(NVL(dd.approval_submit_date, dd.assignee_date), dd.created_date)), 'DD/MM/YYYY HH24:MI:SS') AS ISSUE_DATE,
    dd.APPROVAL_BY,
    TO_CHAR(dd.APPROVAL_DATE, 'DD/MM/YYYY HH24:MI:SS') AS APPROVAL_DATE,
    dd.STATUS,
    dd.DEADLINE AS DUE_DATE,
    RTRIM(
         NVL2(cd.CREDIT_USER, cd.CREDIT_USER || ',', NULL)
      || CASE WHEN CD.PROCESSING_USERNAME IS NOT NULL
               AND CD.PROCESSING_USERNAME <> NVL(cd.CREDIT_USER, CHR(0))
              THEN CD.PROCESSING_USERNAME || ',' END
      || CASE WHEN dd.APPROVAL_BY IS NOT NULL
               AND dd.APPROVAL_BY NOT IN (NVL(cd.CREDIT_USER, CHR(0)),
                                         NVL(CD.PROCESSING_USERNAME, CHR(0)))
              THEN dd.APPROVAL_BY || ',' END
      || CASE WHEN dd.ASSIGNEE_USER_BY IS NOT NULL
               AND dd.ASSIGNEE_USER_BY NOT IN (NVL(cd.CREDIT_USER, CHR(0)),
                                              NVL(CD.PROCESSING_USERNAME, CHR(0)),
                                              NVL(dd.APPROVAL_BY, CHR(0)))
              THEN dd.ASSIGNEE_USER_BY || ',' END
      || CASE WHEN dd.APPROVAL_SUBMIT_BY IS NOT NULL
               AND dd.APPROVAL_SUBMIT_BY NOT IN (NVL(cd.CREDIT_USER, CHR(0)),
                                           NVL(CD.PROCESSING_USERNAME, CHR(0)),
                                           NVL(dd.APPROVAL_BY, CHR(0)),
                                           NVL(dd.ASSIGNEE_USER_BY, CHR(0)))
              THEN dd.APPROVAL_SUBMIT_BY || ',' END
    , ',') AS participant,
    dd.ASSIGNEE_USER_BY as approverSuggest,
    dd.MODIFIED_DATE,
    CD.ID_CARD AS cusIdCard,
    DD.DOC_NAME,
    DD.status_doc,
    DD.group_doc_name,
    cd.credit_user,
    dd.frequency,
    dd.frequency_unit,
    dd.DOC_CATEGORY
  FROM GNCN_CA_DISBURSEMENT_DOCUMENTS  DD
  LEFT JOIN GNCN_CA_DISBURSEMENT CD ON CD.gntd_code = CD.gntd_code
  LEFT JOIN type_leve1 TL ON TL.CODE = CD.TRANSACTION_TYPE1
  WHERE DD.ID = P_CODE; 

END SP_GET_HSSGN_SYNC_TASK_HUB;

/
