/
--------------------------------------------------------
--  DDL for Procedure SP_GET_LOAN_ACCOUNTING_BY_PDTD_CODE
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_LOAN_ACCOUNTING_BY_PDTD_CODE" (
  P_PDTD_CODE IN VARCHAR2,
  OUT_DATA OUT SYS_REFCURSOR
) AS 
    v_leadId VARCHAR2(50);
BEGIN 
  BEGIN
    SELECT
      LEAD_ID INTO v_leadId
    FROM
      CREDIT_APPROVAL_INFO_RAW
    WHERE
      LOS_ID = P_PDTD_CODE
    FETCH FIRST 1 ROWS ONLY;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN v_leadId := NULL;
  END;

  OPEN OUT_DATA FOR
    SELECT
      t.CUSTOMER_CODE,
      t.GNTD_CODE,
      t.STATUS,
      to_char(t.APPROVAL_DATE, 'DD/MM/YYYY HH24:MI') APPROVAL_DATE,
      p.TOTAL_AMOUNT AS LOAN_AMOUNT,
      p.CURRENCY,
      t.PDTD_CODE AS LOS_ID,
      v_leadId AS LEAD_ID
    FROM
      (
        SELECT
          *
        FROM
          GNCN_TRANSACTION_PURPOSE
        WHERE
          LOAN_DATA IS NOT NULL
      ) p
      INNER JOIN (
        SELECT
          *
        FROM
          GNCN_TRANSACTION
        WHERE
          TRANSACTION_TYPE1 = 'Giaingankhoanvay'
          AND STATUS IN (
            'GNCN_HOAN_THANH',
            'GNCN_HOAN_TAT_KHOAN_VAY',
            'GNCN_LOI_CHUYEN_TIEN'
          )
          AND PDTD_CODE = P_PDTD_CODE
      ) t ON t.GNTD_CODE = p.GNTD_CODE;

END SP_GET_LOAN_ACCOUNTING_BY_PDTD_CODE;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_MONEY_TRANSFER_FEE_CONFIG
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_MONEY_TRANSFER_FEE_CONFIG" (
    i_id            IN   NUMBER DEFAULT 0,   --
    i_tranfer_type  IN   VARCHAR2 DEFAULT NULL,   --
    i_udf_code      IN   VARCHAR2 DEFAULT NULL,   --

    out_data        OUT  pagingpackage.paging_cursor
    --OUT_DATA OUT SYS_REFCURSOR
) AS

    
BEGIN
    
    
    OPEN out_data FOR SELECT
                          id        AS id,
                          type      AS type,
                          type      AS transfertype,
                          charge    AS charge,
                          minimum   AS minimum,
                          maximum   AS maximum,
                          udf_code  AS udfcode
                      FROM
                          gncn_money_transfer_fee_schedule_config cdc
                      WHERE
                          ( i_id < 1
                            OR cdc.id = i_id )
                          AND ( i_tranfer_type IS NULL
                                OR cdc.type LIKE '%'
                                                 || i_tranfer_type
                                                 || '%' )
                          AND ( i_udf_code IS NULL
                                OR cdc.udf_code LIKE '%'
                                                     || i_udf_code
                                                     || '%' )
                          AND cdc.is_active = 1;

END sp_get_money_transfer_fee_config;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_PRODUCT_SYNC_BY_CODE
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_PRODUCT_SYNC_BY_CODE" (
    p_json_array IN VARCHAR2,
    p_lable IN VARCHAR2,
    p_fcc_type IN VARCHAR2,
    OUT_DATA OUT SYS_REFCURSOR
) AS BEGIN
    IF p_json_array IS NOT NULL THEN OPEN OUT_DATA FOR
        SELECT
            t.*
        FROM
            (
                SELECT
                    VALUE,
                    NAME
                FROM
                    TD_MASTERDATA.FCC_DANHMUC
                WHERE
                    LABLE = p_lable
                    AND FCC_TYPE = p_fcc_type
            ) t
            INNER JOIN json_table(p_json_array, '$[*]' COLUMNS (value PATH '$')) ip on t.value = ip.value;
    END IF;

    IF p_json_array IS NULL THEN OPEN OUT_DATA FOR
        SELECT
            VALUE,
            NAME
        FROM
            TD_MASTERDATA.FCC_DANHMUC
        WHERE
            LABLE = p_lable
            AND FCC_TYPE = p_fcc_type;
    END IF;

END SP_GET_PRODUCT_SYNC_BY_CODE;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_REF_NUM_FCC_LOAN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_REF_NUM_FCC_LOAN" 
(  
    SYS_CURSOR   OUT SYS_REFCURSOR
) AS
BEGIN
    OPEN SYS_CURSOR FOR 
    SELECT DISTINCT GTP.FCC_REF_NUM AS entryNumFcc, GTP.GNTD_CODE as gntdCode
    FROM GNCN_TRANSACTION_PURPOSE GTP
    LEFT JOIN GNCN_CA_DISBURSEMENT_DOCUMENTS GCDD ON GCDD.GNTD_CODE = GTP.GNTD_CODE
    LEFT JOIN GNCN_CA_DISBURSEMENT GCD ON GCD.GNTD_CODE = GCDD.GNTD_CODE
    WHERE GTP.LOAN_DATA IS NOT NULL  
    AND GCDD.STATUS_DOC = 'CHUA_BO_SUNG'
    AND GTP.FCC_REF_NUM IS NOT NULL;
END SP_GET_REF_NUM_FCC_LOAN;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_REPORT_HK_DETAIL
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_REPORT_HK_DETAIL" (
    p_FROM_DATE IN DATE DEFAULT NULL,
    p_TO_DATE   IN DATE DEFAULT NULL,
    p_BRANCH_CODE IN VARCHAR2,
    OUT_DATA    OUT SYS_REFCURSOR
)
AS
BEGIN
    OPEN OUT_DATA FOR
    WITH HK_DATA AS (
        SELECT 
            HK.*,
            CASE 
                WHEN HK.PA_STATUS = 'HOAN_THANH' THEN HK.SUBMIT_DATE
                ELSE (
                    SELECT h.CREATED_DATE 
                    FROM HKCN_TRANSACTION_HISTORY h 
                    WHERE h.GNTD_CODE = HK.GNTD_CODE 
                      AND (h.ACTION = 'Chuy?n b??c' 
                           OR h.ACTION = 'L?u thông tin và Chuy?n b??c giao d?ch h?u ki?m')
                      AND h.TO_STEP = 'HK - Ch? b? sung'
                    ORDER BY h.CREATED_DATE DESC 
                    FETCH FIRST 1 ROWS ONLY
                )
            END AS SUBMIT_DATE_CALC
        FROM HKCN_TRANSACTION HK
    )
    SELECT 
        ROW_NUMBER() OVER (ORDER BY HK_DATA.SUBMIT_DATE_CALC, HK_DATA.GNTD_CODE, NVL(HKE.ID, 0)) AS STT,
        HK_DATA.SUBMIT_DATE_CALC AS SUBMIT_DATE, -- Ngày phát sinh
        HK_DATA.GNTD_CODE,
        GN.BRANCH_CODE,
        GN.CUSTOMER_TYPE,
        GN.ID_CARD,
        GN.CUSTOMER_CODE,
        GN.CUSTOMER_NAME,
        GN.PDTD_CODE,
        GN.TRANSACTION_FLOW,
        CASE CREDIT.LOAN_FLOW
            WHEN 'f0_flow'            THEN 'Branch Approval'
            WHEN 'f1_flow'            THEN 'F1 Flow'
            WHEN 'f2_flow'            THEN 'F2 Flow'
            WHEN 'f3_flow'            THEN 'F3 Flow'
            WHEN 'n_flow'             THEN 'N Flow'
            WHEN 'returnToSupplement' THEN 'Returned'
            ELSE CREDIT.LOAN_FLOW
        END AS PHAN_LUONG_GD,
        GN.PRODUCT_NAME,
        CREDIT.BANK_PRODUCT_NAME AS SAN_PHAM_CU_THE,
        CREDIT.LOAN_PURPOSE AS MUC_DICH_VAY,
        GN.APPROVAL_LOAN_METHOD,
        GN.TRANSACTION_TYPE1,
        GN.TRANSACTION_TYPE2,
        GN.TRANSACTION_TYPE3,
        (
            CASE
                WHEN GN.TRANSACTION_TYPE1 IN ('Giainganthauchi', 'Giaingankhoanvay') 
                     THEN GNP.TOTAL_AMOUNT
                WHEN GN.TRANSACTION_TYPE1 = 'Khoitaohanmuc' 
                     THEN TO_NUMBER(JSON_VALUE(GN.LIMIT_JSON_DATA, '$.limitValue'))
                ELSE 0
            END
        ) AS GIA_TRI_GD,
--        HK_DATA.AMOUNT AS GIA_TRI_GD,-- l?y luôn ? ?ây cho ??n gi?n(tr??ng này m?i thêm)
        (
            CASE
                WHEN GN.TRANSACTION_TYPE1 IN ('Giainganthauchi', 'Giaingankhoanvay') 
                     THEN GNP.CURRENCY
                WHEN GN.TRANSACTION_TYPE1 = 'Khoitaohanmuc' 
                     THEN JSON_VALUE(GN.LIMIT_JSON_DATA, '$.limitCcy')
                ELSE 'VND'
            END
        ) AS LOAI_TIEN,
        GN.PROCESSING_OWNER,
        GN.APPROVAL_BY,
        (CASE 
            WHEN GN.STATUS = 'GNCN_CHO_XU_LY' THEN NULL
            ELSE GN.APPROVAL_DATE
        END) AS APPROVAL_DATE,
        (SELECT NAME FROM GNCN_STATUS WHERE CODE = GN.STATUS) AS STATUS,
        (
            SELECT COUNT(*) 
            FROM HKCN_TRANSACTION_HISTORY 
            WHERE GNTD_CODE = HK_DATA.GNTD_CODE 
              AND ACTION = 'Chuy?n b??c'
              AND TO_STEP IN ('HK - Ch? b? sung', 'HK - Hoàn thành')
        ) AS SO_LAN_PHAN_HOI,
        (CASE 
            WHEN GN.TRANSACTION_TYPE1 = 'Giaingankhoanvay' 
                 THEN JSON_VALUE(GNP.LOAN_DATA, '$.entryNumFcc')
            WHEN GN.TRANSACTION_TYPE1 = 'Giainganthauchi' 
                 THEN JSON_VALUE(GNP.OVERDRAFT_DATA, '$.overdraftAccount')
            ELSE NULL
        END) AS SO_REF_KHOAN_VAY,
        (SELECT NAME FROM GNCN_CONFIG_COMMONS 
         WHERE SCOPE = 'HK_TYPE_CONFIG' 
           AND CODE = (
                SELECT MAX(PA_TYPE_CODE) 
                FROM hkcn_transaction_config 
                WHERE USE_STATUS = 1 
                  AND trans_level_code_1 = GN.TRANSACTION_TYPE1 
                  AND trans_level_code_2 = GN.TRANSACTION_TYPE2 
                  AND trans_level_code_3 = GN.TRANSACTION_TYPE3 
                  AND product_code = GN.PRODUCT_NAME
            )
           AND STATUS = 1) AS LOAI_HAU_KIEM,
--        (CASE 
--            WHEN HK_DATA.PA_STATUS = 'HOAN_THANH' THEN HK_DATA.UPDATED_BY
--            ELSE HK_DATA.USER_PA
--        END) AS UPDATED_BY,
        (
            SELECT h.CREATED_BY
            FROM HKCN_TRANSACTION_HISTORY h
            WHERE h.GNTD_CODE = HK_DATA.GNTD_CODE
              AND h.ACTION = 'Chuy?n b??c'
              AND h.TO_STEP IN ('HK - Ch? b? sung', 'HK - Hoàn thành')
            ORDER BY h.CREATED_DATE DESC, h.ID DESC
            FETCH FIRST 1 ROWS ONLY
        ) AS UPDATED_BY,
        
        HK_DATA.CREATED_DATE AS THOI_DIEM_LAY_MAU,
        CASE 
            WHEN HK_DATA.PA_STATUS = 'HOAN_THANH' THEN HK_DATA.SUBMIT_DATE
            ELSE NULL
        END AS THOI_DIEM_HOAN_THANH,
        (SELECT NAME FROM GNCN_CONFIG_COMMONS 
         WHERE SCOPE = 'HKCN_STATUS' 
           AND CODE = HK_DATA.PA_STATUS 
           AND STATUS = 1) AS PA_STATUS,
        HKE.GROUP_DOC_CODE,
        HKE.ERROR_INFO,
        HKE.ERROR_GROUP,
        HKE.RISK_LEVEL,
        HKE.ERROR_TEXT,
        HKE.EXPIRED_DATE,
        (SELECT NAME FROM GNCN_CONFIG_COMMONS 
         WHERE SCOPE = 'HKCN_ERROR_STATUS' 
           AND CODE = HKE.STATUS_ERROR 
           AND STATUS = 1) AS TRANG_THAI_LOI,
        HKE.DISBURSEMENT_COMMENT,
        (SELECT NAME FROM GNCN_CONFIG_COMMONS 
         WHERE SCOPE = 'HKCN_ERROR_APPROVAL' 
           AND CODE = HKE.STATUS_APPROVAL 
           AND STATUS = 1) AS DUYET_TRANG_THAI_LOI,
        HKE.PA_COMMENT
    FROM HK_DATA
    LEFT JOIN GNCN_TRANSACTION GN 
           ON HK_DATA.GNTD_CODE = GN.GNTD_CODE
    LEFT JOIN GNCN_CREDIT_APPROVAL_INFO_SYNC CREDIT 
           ON HK_DATA.PDTD_CODE = CREDIT.PDTD_CODE
    LEFT JOIN GNCN_TRANSACTION_PURPOSE GNP 
           ON HK_DATA.GNTD_CODE = GNP.GNTD_CODE
    LEFT JOIN HKCN_ERROR HKE 
           ON HK_DATA.GNTD_CODE = HKE.GNTD_CODE
           AND HK_DATA.PA_RESULT = 'PHAT_SINH_LOI'
    WHERE 
        (p_FROM_DATE IS NULL OR TRUNC(HK_DATA.SUBMIT_DATE_CALC) >= TRUNC(p_FROM_DATE))
        AND (p_TO_DATE   IS NULL OR TRUNC(HK_DATA.SUBMIT_DATE_CALC) <= TRUNC(p_TO_DATE))
        AND (p_BRANCH_CODE IS NULL OR INSTR(p_BRANCH_CODE, GN.BRANCH_CODE) > 0)
        AND (HK_DATA.PA_STATUS IS NOT NULL AND HK_DATA.PA_STATUS != 'CHUA_HAU_KIEM')
    ORDER BY HK_DATA.SUBMIT_DATE_CALC, HK_DATA.GNTD_CODE, NVL(HKE.ID, 0);
END SP_GET_REPORT_HK_DETAIL;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_REPORT_HK_TRANSACTION
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_REPORT_HK_TRANSACTION" (
    p_FROM_DATE IN DATE,
    p_TO_DATE IN DATE,
    p_BRANCH_CODE IN VARCHAR2,
    OUT_DATA OUT SYS_REFCURSOR
)
AS
BEGIN
    OPEN OUT_DATA FOR
    -- Tính s? l??ng tài s?n b?o ??m t? JSON
    with tran_with_json AS (
        SELECT
            tran.GNTD_CODE,
            COUNT(TSBD.maTS) AS SL_TSBD,
            LISTAGG(TSBD.maTS, ', ') WITHIN GROUP (ORDER BY TSBD.maTS) AS MA_TSBD
        FROM
            GNCN_TRANSACTION tran
            LEFT JOIN (
                SELECT t.GNTD_CODE, jt.poolCode as maTS
                FROM GNCN_TRANSACTION t,
                    JSON_TABLE(
                        t.LIMIT_JSON_DATA,
                        '$.pools[*]' COLUMNS (
                            poolCode VARCHAR2(100) PATH '$.poolCode'
                        )
                    ) jt
                UNION ALL
                SELECT t.GNTD_CODE, jt.collateralCode as maTS
                FROM GNCN_TRANSACTION t,
                    JSON_TABLE(
                        t.LIMIT_JSON_DATA,
                        '$.collaterals[*]' COLUMNS (
                            collateralCode VARCHAR2(100) PATH '$.collateralCode'
                        )
                    ) jt
            ) TSBD ON TSBD.GNTD_CODE = tran.GNTD_CODE
        GROUP BY tran.GNTD_CODE
    ),
    HK_DATA AS (
        SELECT 
            HK.*,
            CASE 
                WHEN HK.PA_STATUS = 'HOAN_THANH' THEN HK.SUBMIT_DATE
                ELSE (
                    SELECT h.CREATED_DATE 
                    FROM HKCN_TRANSACTION_HISTORY h 
                    WHERE h.GNTD_CODE = HK.GNTD_CODE 
                      AND (h.ACTION = 'Chuy?n b??c' 
                           OR h.ACTION = 'L?u thông tin và Chuy?n b??c giao d?ch h?u ki?m')
                      AND h.TO_STEP = 'HK - Ch? b? sung'
                    ORDER BY h.CREATED_DATE DESC 
                    FETCH FIRST 1 ROWS ONLY
                )
            END AS SUBMIT_DATE_CALC
        FROM HKCN_TRANSACTION HK
    )
    SELECT 
        ROW_NUMBER() OVER (ORDER BY HK.SUBMIT_DATE_CALC, HK.GNTD_CODE) AS STT,
        HK.SUBMIT_DATE_CALC AS SUBMIT_DATE, -- Ngày phát sinh
        HK.GNTD_CODE,
        GN.BRANCH_CODE,
        GN.CUSTOMER_TYPE,
        GN.ID_CARD,
        GN.CUSTOMER_CODE,
        GN.CUSTOMER_NAME,
        GN.PDTD_CODE,
        GN.TRANSACTION_FLOW ,
        CASE CREDIT.LOAN_FLOW
        WHEN 'f0_flow'            THEN 'Branch Approval'
        WHEN 'f1_flow'            THEN 'F1 Flow'
        WHEN 'f2_flow'            THEN 'F2 Flow'
        WHEN 'f3_flow'            THEN 'F3 Flow'
        WHEN 'n_flow'             THEN 'N Flow'
        WHEN 'returnToSupplement' THEN 'Returned'
        ELSE CREDIT.LOAN_FLOW
        END AS PHAN_LUONG_GD,
        GN.PRODUCT_NAME,
        CREDIT.BANK_PRODUCT_NAME AS SAN_PHAM_CU_THE,
        CREDIT.LOAN_PURPOSE AS MUC_DICH_VAY,
        GN.APPROVAL_LOAN_METHOD,
        GN.TRANSACTION_TYPE1,
        GN.TRANSACTION_TYPE2,
        GN.TRANSACTION_TYPE3,
        (
        CASE
            WHEN GN.TRANSACTION_TYPE1 IN ('Giainganthauchi', 'Giaingankhoanvay') THEN GNP.TOTAL_AMOUNT
            WHEN GN.TRANSACTION_TYPE1 = 'Khoitaohanmuc' THEN TO_NUMBER(JSON_VALUE(GN.LIMIT_JSON_DATA, '$.limitValue'))
            ELSE 0
        END
        ) AS GIA_TRI_GD,
        (
            CASE
                WHEN GN.TRANSACTION_TYPE1 IN ('Giainganthauchi', 'Giaingankhoanvay') THEN GNP.CURRENCY
                WHEN GN.TRANSACTION_TYPE1 = 'Khoitaohanmuc' THEN JSON_VALUE(GN.LIMIT_JSON_DATA, '$.limitCcy')
                ELSE 'VND'
            END
        ) AS LOAI_TIEN,
        GN.PROCESSING_OWNER,
        GN.APPROVAL_BY,
        (CASE 
            WHEN GN.STATUS = 'GNCN_CHO_XU_LY' THEN NULL
            ELSE GN.APPROVAL_DATE
        END) AS APPROVAL_DATE, --Th?i gian phê duy?t gi?i ngân
        (SELECT NAME FROM GNCN_STATUS WHERE CODE = GN.STATUS) AS STATUS,
        twj.SL_TSBD AS SO_LUONG_TSBD,
        ( CASE
            WHEN GN.TRANSACTION_TYPE1 = 'Giaingankhoanvay' THEN JSON_VALUE(GNP.LOAN_DATA, '$.entryNumFcc')
            WHEN GN.TRANSACTION_TYPE1 = 'Giainganthauchi' THEN JSON_VALUE(GNP.OVERDRAFT_DATA, '$.overdraftAccount')
            ELSE NULL
        END) AS SO_REF_KHOAN_VAY,
        (SELECT NAME FROM GNCN_CONFIG_COMMONS WHERE SCOPE = 'HK_TYPE_CONFIG' AND CODE = 
        (SELECT MAX(PA_TYPE_CODE) FROM hkcn_transaction_config WHERE USE_STATUS = 1 AND trans_level_code_1 = GN.TRANSACTION_TYPE1 
        and trans_level_code_2 = GN.TRANSACTION_TYPE2 and trans_level_code_3 = GN.TRANSACTION_TYPE3 and product_code = GN.PRODUCT_NAME)
        AND STATUS = 1) AS LOAI_HAU_KIEM,
        (CASE 
            WHEN HK.PA_STATUS = 'HOAN_THANH' THEN HK.UPDATED_BY
            ELSE HK.USER_PA
        END) AS UPDATED_BY, --user h?u ki?m
        HK.created_date AS THOI_DIEM_LAY_MAU,
        (CASE 
            WHEN HK.PA_STATUS = 'HOAN_THANH' THEN HK.SUBMIT_DATE
            ELSE NULL
        END) AS THOI_DIEM_HOAN_THANH,
        (SELECT NAME FROM GNCN_CONFIG_COMMONS WHERE SCOPE = 'HKCN_STATUS' AND CODE = HK.PA_STATUS AND STATUS = 1) AS PA_STATUS
    FROM HK_DATA HK
    LEFT JOIN GNCN_TRANSACTION GN ON HK.GNTD_CODE = GN.GNTD_CODE
    LEFT JOIN GNCN_CREDIT_APPROVAL_INFO_SYNC CREDIT ON HK.PDTD_CODE = CREDIT.PDTD_CODE    
    LEFT JOIN GNCN_TRANSACTION_PURPOSE GNP ON HK.GNTD_CODE = GNP.GNTD_CODE
    LEFT JOIN tran_with_json twj ON HK.GNTD_CODE = twj.GNTD_CODE
    WHERE 
        (HK.PA_STATUS IS NOT NULL AND HK.PA_STATUS != 'CHUA_HAU_KIEM')
        AND (p_BRANCH_CODE IS NULL OR INSTR(p_BRANCH_CODE, GN.BRANCH_CODE) > 0)
        AND (p_FROM_DATE IS NULL OR TRUNC(HK.SUBMIT_DATE_CALC) >= TRUNC(p_FROM_DATE))
        AND (p_TO_DATE   IS NULL OR TRUNC(HK.SUBMIT_DATE_CALC) <= TRUNC(p_TO_DATE))
    ORDER BY HK.SUBMIT_DATE_CALC, HK.GNTD_CODE;
END SP_GET_REPORT_HK_TRANSACTION;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_REPORT_PR01
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_REPORT_PR01" (
    P_FROM_DATE IN VARCHAR2,
    P_TO_DATE IN VARCHAR2,
    P_STATUS IN VARCHAR2,
    P_TYPE_CUSTOMER IN VARCHAR2,
    P_BRANCH IN VARCHAR2,
    P_USER_SUGGESTED IN VARCHAR2,
    P_USER_APPROVAL IN VARCHAR2,
    OUT_DATA OUT SYS_REFCURSOR
) AS json_obj JSON_OBJECT_T;

BEGIN OPEN OUT_DATA FOR
SELECT
    TO_CHAR(t.APPROVAL_SUBMIT_TIME, 'DD/MM/YYYY HH24:MI') NGAY_PHAT_SINH,
    t.GNTD_CODE AS MA_YEU_CAU,
    t.BRANCH_CODE as MA_CHI_NHANH,
    t.CUSTOMER_TYPE AS LOAI_KH,
    t.ID_CARD AS CCCD,
    t.CUSTOMER_CODE AS CIF,
    t.CUSTOMER_NAME AS TEN_KH,
    (
        CASE
            WHEN t.SOURCE_SYNC IS NULL THEN 'BPM'
            ELSE t.SOURCE_SYNC
        END
    ) AS NGUON_PDTD,
    t.PDTD_CODE AS MA_PDTD,
    cc.NAME AS PHAN_LUONG_GD,
    c.LOAN_FLOW AS LUONG_PD,
    t.PRODUCT_CODE AS TEN_SAN_PHAM,
    t.PRODUCT_NAME AS SP_CU_THE,
    c.LOAN_PURPOSE AS MUC_DICH_VAY,
--    c.LOAN_METHOD,
    t.APPROVAL_LOAN_METHOD AS LH_CAP_TIN_DUNG,
    tt1.NAME AS LOAI_GD_CAP_1,
    tt2.NAME AS LOAI_GD_CAP_2,
    tt3.NAME AS LOAI_GD_CAP_3,
    (
        CASE
            WHEN t.TRANSACTION_TYPE1 IN ('Giainganthauchi', 'Giaingankhoanvay') THEN gtp.TOTAL_AMOUNT
            WHEN t.TRANSACTION_TYPE1 = 'Khoitaohanmuc' THEN TO_NUMBER(JSON_VALUE(t.LIMIT_JSON_DATA, '$.limitValue'))
            ELSE 0
        END
    ) AS GIA_TRI_GD,
    (
        CASE
            WHEN t.TRANSACTION_TYPE1 IN ('Giainganthauchi', 'Giaingankhoanvay') THEN gtp.CURRENCY
            WHEN t.TRANSACTION_TYPE1 = 'Khoitaohanmuc' THEN JSON_VALUE(t.LIMIT_JSON_DATA, '$.limitCcy')
            ELSE 'VND'
        END
    ) AS LOAI_TIEN,
    t.PROCESSING_OWNER AS USER_DE_XUAT,
    t.APPROVAL_BY AS USER_PHE_DUYET,
    TO_CHAR(t.APPROVAL_DATE, 'DD/MM/YYYY HH24:MI') AS TG_PHE_DUYET,
    s.NAME AS TRANG_THAI,
    1 AS SL_MUC_DICH,
    (
        CASE
            WHEN JSON_VALUE(t.LIMIT_JSON_DATA, '$.limitType') = 0 THEN 'C?p m?i'
            WHEN JSON_VALUE(t.LIMIT_JSON_DATA, '$.limitType') = 1 THEN 'S?a ??i'
            WHEN JSON_VALUE(t.LIMIT_JSON_DATA, '$.limitType') = 2 THEN 'Gán h?n m?c'
            ELSE NULL
        END
    ) AS LOAI_HM,
    (
        CASE
            WHEN JSON_VALUE(t.LIMIT_JSON_DATA, '$.limitType') = 2 THEN t.LINE_CODE
            ELSE t.LIMIT_CODE
        END
    ) AS MA_HM,
    (
        CASE
            WHEN t.TRANSACTION_TYPE1 IN ('Khoitaohanmuc', 'Giaingankhoanvay') THEN JSON_VALUE(t.LIMIT_JSON_DATA, '$.limitValue')
            ELSE NULL
        END
    ) AS GIA_TRI_HM,
    (
        CASE
            WHEN gtp.ALLOW_INTERFACE = 1 THEN 'Có'
            ELSE 'Không'
        END
    ) AS ALLOW_INTERFACE,
    (
        CASE
            WHEN t.TRANSACTION_TYPE1 = 'Giaingankhoanvay' THEN JSON_VALUE(gtp.LOAN_DATA, '$.entryNumFcc')
            WHEN t.TRANSACTION_TYPE1 = 'Giainganthauchi' THEN JSON_VALUE(gtp.OVERDRAFT_DATA, '$.overdraftAccount')
            ELSE NULL
        END
    ) AS SO_REF_KV,
    ref_num.REF_NUM_FEE_FCC AS SO_REF_THU_PHI_CT,
    ref_num.REF_NUM_TRANSFER_FCC AS SO_REF_CT,
    (
        CASE
            WHEN t.TRANSACTION_TYPE1 = 'Giaingankhoanvay' AND t.STATUS = 'GNCN_HOAN_THANH' THEN 'Chuy?n ti?n thành công'
            WHEN t.TRANSACTION_TYPE1 = 'Giaingankhoanvay' AND t.STATUS = 'GNCN_LOI_CHUYEN_TIEN' THEN 'Chuy?n ti?n th?t b?i'
            ELSE NULL
        END
    ) AS KET_QUA_CT,
    (
        CASE
            WHEN ref_num.RESULT_INTERFACE IS NOT NULL THEN ref_num.RESULT_INTERFACE
            ELSE tp.RESULT_INTERFACE
        END
    ) AS CHI_TIET_LOI_CT,
    (
        CASE
            WHEN tp.REF_NUM_MBNT IS NOT NULL AND tp.TRANSFER_TYPE_MBNT = 2 THEN tp.REF_NUM_MBNT || ' - T? ??ng'
            WHEN tp.REF_NUM_MBNT IS NOT NULL AND tp.TRANSFER_TYPE_MBNT = 1 THEN tp.REF_NUM_MBNT || ' - Th? công'
            ELSE NULL
        END
    ) AS SO_REF_MBNT,
    th.CREATED_BY AS USER_DUYET_CT,
    to_char(th.CREATED_DATE, 'DD/MM/YYYY') AS TG_DUYET_CT
FROM
    GNCN_TRANSACTION t
    LEFT JOIN GNCN_TRANSACTION_PURPOSE gtp ON gtp.GNTD_CODE = t.GNTD_CODE
    LEFT JOIN GNCN_TRANSACTION_PAYMENT tp ON t.GNTD_CODE = tp.GNTD_CODE
    LEFT JOIN GNCN_CREDIT_APPROVAL_INFO_SYNC c ON t.PDTD_CODE = c.PDTD_CODE
    LEFT JOIN GNCN_STATUS s ON t.STATUS = s.CODE
    LEFT JOIN (
        SELECT
            *
        FROM
            GNCN_CONFIG_COMMONS
        WHERE
            SCOPE = 'TRAN_FLOW'
    ) cc ON cc.CODE = t.TRANSACTION_FLOW
    LEFT JOIN (
        SELECT
            *
        FROM
            GNCN_TRANSACTION_TYPE
        WHERE
            USE_STATUS = 1
            AND LEVEL_TYPE = 1
    ) tt1 ON tt1.CODE = t.TRANSACTION_TYPE1
    LEFT JOIN (
        SELECT
            *
        FROM
            GNCN_TRANSACTION_TYPE
        WHERE
            USE_STATUS = 1
            AND LEVEL_TYPE = 2
    ) tt2 ON tt2.CODE = t.TRANSACTION_TYPE2
    AND tt2.PARENT_ID = t.TRANSACTION_TYPE1
    LEFT JOIN (
        SELECT
            *
        FROM
            GNCN_TRANSACTION_TYPE
        WHERE
            USE_STATUS = 1
            AND LEVEL_TYPE = 3
    ) tt3 ON tt3.CODE = t.TRANSACTION_TYPE3
    AND INSTR(tt3.PARENT_ID, t.TRANSACTION_TYPE2) > 0
    LEFT JOIN (
        SELECT
            h.GNTD_CODE,
            h.CREATED_DATE,
            h.CREATED_BY
        FROM
            GNCN_TRANSACTION_HISTORY h
            INNER JOIN (
                SELECT
                    GNTD_CODE,
                    MAX(CREATED_DATE) AS CREATED_DATE
                FROM
                    GNCN_TRANSACTION_HISTORY
                WHERE
                    ACTION = 'PAYMENT'
                GROUP BY
                    GNTD_CODE
            ) tmp ON tmp.GNTD_CODE = h.GNTD_CODE
            AND tmp.CREATED_DATE = h.CREATED_DATE
    ) th ON th.GNTD_CODE = t.GNTD_CODE
    LEFT JOIN (
        SELECT
            gtpt.GNCN_CODE,
            LISTAGG(
                CASE 
                    WHEN gtpt.REF_NUM_FEE_FCC IS NOT NULL THEN
                        gtpt.REF_NUM_FEE_FCC || 
                        CASE 
                            WHEN gtpt.REF_TRANSFER_TYPE = 1 THEN ' - Th? công'
                            WHEN gtpt.REF_TRANSFER_TYPE = 2 THEN ' - T? ??ng'
                            ELSE ''
                        END
                    ELSE NULL
                END,
                CHR(13) || CHR(10)
            ) WITHIN GROUP (ORDER BY gtpt.REF_NUM_FEE_FCC) AS REF_NUM_FEE_FCC,
            LISTAGG(
                CASE 
                    WHEN gtpt.REF_NUM_TRANSFER_FCC IS NOT NULL THEN
                        gtpt.REF_NUM_TRANSFER_FCC || 
                        CASE 
                            WHEN gtpt.REF_TRANSFER_TYPE = 1 THEN ' - Th? công'
                            WHEN gtpt.REF_TRANSFER_TYPE = 2 THEN ' - T? ??ng'
                            ELSE ''
                        END
                    ELSE NULL
                END,
                CHR(13) || CHR(10)
            ) WITHIN GROUP (ORDER BY gtpt.REF_NUM_TRANSFER_FCC) AS REF_NUM_TRANSFER_FCC,
            LISTAGG(
                CASE 
                    WHEN gtpt.RESULT_INTERFACE IS NOT NULL THEN
                        gtpt.ACCOUNT_NUM || ' - ' || gtpt.RESULT_INTERFACE
                    ELSE NULL
                END,
                CHR(13) || CHR(10)
            ) WITHIN GROUP (ORDER BY gtpt.RESULT_INTERFACE) AS RESULT_INTERFACE
        FROM
            GNCN_TRANSACTION_PAYMENT_DEAIL gtpt
--        WHERE
--            gtpt.REF_NUM_FEE_FCC IS NOT NULL OR REF_NUM_TRANSFER_FCC IS NOT NULL
        GROUP BY gtpt.GNCN_CODE
    ) ref_num ON ref_num.GNCN_CODE = t.GNTD_CODE
WHERE
    1 = 1
    AND (
        P_FROM_DATE IS NULL
        OR TRUNC(t.APPROVAL_SUBMIT_TIME) >= TO_DATE(P_FROM_DATE, 'dd/MM/yyyy')
    )
    AND (
        P_TO_DATE IS NULL
        OR TRUNC(t.APPROVAL_SUBMIT_TIME) <= TO_DATE(P_TO_DATE, 'dd/MM/yyyy')
    )
    AND (
        P_STATUS IS NULL
        OR INSTR(',' || P_STATUS || ',', ',' || t.STATUS || ',') > 0
    )
    AND (
        P_BRANCH IS NULL
        OR INSTR(
            ',' || P_BRANCH || ',',
            ',' || t.BRANCH_CODE || ','
        ) > 0
    )
    AND (
        P_USER_SUGGESTED IS NULL
        OR UPPER(t.PROCESSING_OWNER) = UPPER(P_USER_SUGGESTED)
    )
    AND (
        P_USER_APPROVAL IS NULL
        OR UPPER(t.APPROVAL_BY) = UPPER(P_USER_APPROVAL)
    )
ORDER BY t.APPROVAL_SUBMIT_TIME ASC;
END SP_GET_REPORT_PR01;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_REPORT_PR02
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_REPORT_PR02" (
    P_FROM_DATE        IN VARCHAR2,
    P_TO_DATE          IN VARCHAR2,
    P_APPROVAL_FROM    IN VARCHAR2,
    P_APPROVAL_TO      IN VARCHAR2,
    P_STATUS           IN VARCHAR2,
    P_TYPE_CUSTOMER    IN VARCHAR2,
    P_BRANCH           IN VARCHAR2,
    P_CVKH_RECEIPT     IN VARCHAR2,
    OUT_DATA           OUT SYS_REFCURSOR
) AS
    V_FROM_DATE        DATE;
    V_TO_DATE          DATE;
    V_APPROVAL_FROM    DATE;
    V_APPROVAL_TO      DATE;
    V_CVKH_RECEIPT     DATE;
BEGIN
    V_FROM_DATE := CASE
        WHEN P_FROM_DATE IS NOT NULL THEN TO_DATE(P_FROM_DATE,'DD/MM/YYYY')
        WHEN P_TO_DATE IS NULL AND P_APPROVAL_FROM IS NULL AND P_APPROVAL_TO IS NULL THEN SYSDATE - 7
        ELSE NULL
    END;

    V_TO_DATE := CASE WHEN P_TO_DATE IS NOT NULL THEN TO_DATE(P_TO_DATE,'DD/MM/YYYY') + 1 END;
    V_APPROVAL_FROM := CASE WHEN P_APPROVAL_FROM IS NOT NULL THEN TO_DATE(P_APPROVAL_FROM,'DD/MM/YYYY') END;
    V_APPROVAL_TO   := CASE WHEN P_APPROVAL_TO   IS NOT NULL THEN TO_DATE(P_APPROVAL_TO,'DD/MM/YYYY') + 1 END;
    V_CVKH_RECEIPT  := CASE WHEN P_CVKH_RECEIPT  IS NOT NULL THEN TO_DATE(P_CVKH_RECEIPT,'DD/MM/YYYY') END;

OPEN OUT_DATA FOR
WITH
-- =========================================================
-- 1. TRANSACTION FILTER
-- =========================================================
trans_filtered AS (
    SELECT t.*
    FROM GNCN_TRANSACTION t
    WHERE (V_FROM_DATE IS NULL OR t.APPROVAL_SUBMIT_TIME >= V_FROM_DATE)
      AND (V_TO_DATE   IS NULL OR t.APPROVAL_SUBMIT_TIME <  V_TO_DATE)
      AND (P_TYPE_CUSTOMER IS NULL OR t.CUSTOMER_TYPE = P_TYPE_CUSTOMER)
      AND (V_CVKH_RECEIPT IS NULL OR t.EMP_RECEIPT_DATE = V_CVKH_RECEIPT)
      AND (
            P_STATUS IS NULL OR
            t.STATUS IN (
                SELECT REGEXP_SUBSTR(P_STATUS,'[^,]+',1,LEVEL)
                FROM dual
                CONNECT BY REGEXP_SUBSTR(P_STATUS,'[^,]+',1,LEVEL) IS NOT NULL
            )
      )
      AND (
            P_BRANCH IS NULL OR
            t.BRANCH_CODE IN (
                SELECT REGEXP_SUBSTR(P_BRANCH,'[^,]+',1,LEVEL)
                FROM dual
                CONNECT BY REGEXP_SUBSTR(P_BRANCH,'[^,]+',1,LEVEL) IS NOT NULL
            )
      )
),

-- =========================================================
-- 2. APPROVAL HISTORY
-- =========================================================
history_base AS (
    SELECT
        h.GNTD_CODE,
        h.CREATED_DATE,
        h.CREATED_BY,
        ROW_NUMBER() OVER (PARTITION BY h.GNTD_CODE ORDER BY h.CREATED_DATE) rn,
        COUNT(*)    OVER (PARTITION BY h.GNTD_CODE) total_records
    FROM GNCN_TRANSACTION_HISTORY h
    JOIN trans_filtered tf ON tf.GNTD_CODE = h.GNTD_CODE
    WHERE h.ACTION IN ('APPROVE','REJECT')
      AND (V_APPROVAL_FROM IS NULL OR h.CREATED_DATE >= V_APPROVAL_FROM)
      AND (V_APPROVAL_TO   IS NULL OR h.CREATED_DATE <  V_APPROVAL_TO)
),

history_details AS (
    SELECT
        GNTD_CODE,
        MAX(CASE WHEN rn = 1 THEN TO_CHAR(CREATED_DATE,'DD/MM/YYYY HH24:MI') END) PD_DATE_1,
        MAX(CASE WHEN rn = 1 THEN CREATED_BY END) PD_BY_1,
        MAX(CASE WHEN rn = 2 THEN TO_CHAR(CREATED_DATE,'DD/MM/YYYY HH24:MI') END) PD_DATE_2,
        MAX(CASE WHEN rn = 2 THEN CREATED_BY END) PD_BY_2,
        MAX(CASE WHEN rn = 3 THEN TO_CHAR(CREATED_DATE,'DD/MM/YYYY HH24:MI') END) PD_DATE_3,
        MAX(CASE WHEN rn = 3 THEN CREATED_BY END) PD_BY_3,
        MAX(CASE WHEN rn = total_records AND rn >= 4 THEN TO_CHAR(CREATED_DATE,'DD/MM/YYYY HH24:MI') END) LAST_PD_DATE,
        MAX(CASE WHEN rn = total_records AND rn >= 4 THEN CREATED_BY END) LAST_PD_BY
    FROM history_base
    GROUP BY GNTD_CODE
),

-- =========================================================
-- 2. SUBMIT FLOW HISTORY
-- =========================================================
history_submit_base AS (
    SELECT
        h.GNTD_CODE,
        h.CREATED_DATE,
        h.CREATED_BY,
        ROW_NUMBER() OVER (PARTITION BY h.GNTD_CODE ORDER BY h.CREATED_DATE) rn,
        COUNT(*)    OVER (PARTITION BY h.GNTD_CODE) total_records
    FROM GNCN_TRANSACTION_HISTORY h
    JOIN trans_filtered tf ON tf.GNTD_CODE = h.GNTD_CODE
    WHERE h.ACTION = 'SUBMIT'
      AND (V_APPROVAL_FROM IS NULL OR h.CREATED_DATE >= V_APPROVAL_FROM)
      AND (V_APPROVAL_TO   IS NULL OR h.CREATED_DATE <  V_APPROVAL_TO)
),

history_submit_detail AS (
    SELECT
        GNTD_CODE,
         -- ===== L?n 1 =====
        MAX(CASE WHEN rn = 1 THEN CREATED_BY END)                                               AS DX_BY_1,
        MAX(CASE WHEN rn = 1 THEN TO_CHAR(CREATED_DATE,'DD/MM/YYYY HH24:MI') END)               AS DX_DATE_1,
        -- ===== L?n 2 =====
        MAX(CASE WHEN rn = 2 THEN CREATED_BY END)                                               AS DX_BY_2,
        MAX(CASE WHEN rn = 2 THEN TO_CHAR(CREATED_DATE,'DD/MM/YYYY HH24:MI') END)               AS DX_DATE_2,
        -- ===== L?n 3 =====
        MAX(CASE WHEN rn = 3 THEN CREATED_BY END)                                               AS DX_BY_3,
        MAX(CASE WHEN rn = 3 THEN TO_CHAR(CREATED_DATE,'DD/MM/YYYY HH24:MI') END)               AS DX_DATE_3,
        -- ===== L?n cu?i (>=4) =====
        MAX(CASE WHEN rn = total_records AND rn >= 4 THEN CREATED_BY END)                       AS DX_BY_4,
        MAX(CASE WHEN rn = total_records AND rn >= 4 THEN TO_CHAR(CREATED_DATE,'DD/MM/YYYY HH24:MI') END)   AS DX_DATE_4
    FROM history_submit_base
    GROUP BY GNTD_CODE
),

-- =========================================================
-- 3. ASSIGNMENT HISTORY
-- =========================================================
assignment_base AS (
    SELECT
        a.GNTD_CODE,
        a.CREATED_DATE,
        a.CREATED_BY,
        a.EMP_RECEIPT_DATE,
        ROW_NUMBER() OVER (PARTITION BY a.GNTD_CODE ORDER BY a.CREATED_DATE) rn,
        COUNT(*)    OVER (PARTITION BY a.GNTD_CODE) total_records
    FROM GNCN_TRANSACTION_ASSIGNMENT_LOG a
    JOIN trans_filtered tf ON tf.GNTD_CODE = a.GNTD_CODE
),

assignment_details AS (
    SELECT
        GNTD_CODE,
        -- ===== L?n 1 =====
        MAX(CASE WHEN rn = 1 THEN TO_CHAR(EMP_RECEIPT_DATE,'DD/MM/YYYY HH24:MI') END) AS BG_DATE_1,
        -- ===== L?n 2 =====
        MAX(CASE WHEN rn = 2 THEN TO_CHAR(EMP_RECEIPT_DATE,'DD/MM/YYYY HH24:MI') END) AS BG_DATE_2,
        -- ===== L?n 3 =====
        MAX(CASE WHEN rn = 3 THEN TO_CHAR(EMP_RECEIPT_DATE,'DD/MM/YYYY HH24:MI') END) AS BG_DATE_3,
        -- ===== L?n cu?i (>=4) =====
        MAX(CASE WHEN rn = total_records AND rn >= 4 THEN TO_CHAR(EMP_RECEIPT_DATE,'DD/MM/YYYY HH24:MI') END) AS BG_DATE_4
    FROM assignment_base
    GROUP BY GNTD_CODE
),

-- =========================================================
-- 4. JSON COLLATERAL (PARSE 1 L?N)
-- =========================================================
tran_with_json AS (
    SELECT
        tf.GNTD_CODE,
        COUNT(DISTINCT maTS) SL_TSBD,
        LISTAGG(maTS, ', ') WITHIN GROUP (ORDER BY maTS) MA_TSBD
    FROM trans_filtered tf
    LEFT JOIN (
        SELECT GNTD_CODE, poolCode maTS
        FROM trans_filtered,
             JSON_TABLE(LIMIT_JSON_DATA,'$.pools[*]'
                COLUMNS (poolCode VARCHAR2(100) PATH '$.poolCode'))
        UNION ALL
        SELECT GNTD_CODE, collateralCode
        FROM trans_filtered,
             JSON_TABLE(LIMIT_JSON_DATA,'$.collaterals[*]'
                COLUMNS (collateralCode VARCHAR2(100) PATH '$.collateralCode'))
    ) j ON j.GNTD_CODE = tf.GNTD_CODE
    GROUP BY tf.GNTD_CODE
),

-- =========================================================
-- 5. SUBMIT COUNT / COMPLETION
-- =========================================================
submit_count AS (
    SELECT h.GNTD_CODE, COUNT(*) SL
    FROM GNCN_TRANSACTION_HISTORY h
    JOIN trans_filtered tf ON tf.GNTD_CODE = h.GNTD_CODE
    WHERE h.ACTION = 'SUBMIT'
    GROUP BY h.GNTD_CODE
),

completion_history AS (
    SELECT h.GNTD_CODE, MAX(h.CREATED_DATE) CREATED_DATE
    FROM GNCN_TRANSACTION_HISTORY h
    JOIN trans_filtered tf ON tf.GNTD_CODE = h.GNTD_CODE
    WHERE h.STATUS = 'GNCN_HOAN_THANH'
    GROUP BY h.GNTD_CODE
),

approval_summary AS (
    SELECT
        GNTD_CODE,
        LISTAGG(
            'L?n ' || RN || ':' || CHR(13) || CHR(10) ||
            CASE
                WHEN IS_APPROVED = 1 THEN COMMENTS
                ELSE ERROR_DETAILS
            END,
            CHR(13) || CHR(10)
        ) WITHIN GROUP (ORDER BY RN) AS Y_KIEN,
        LISTAGG(
            'L?n ' || RN || ': ' || ERROR_CODES,
            CHR(13) || CHR(10)
        ) WITHIN GROUP (ORDER BY RN) AS NHOM_LOI
    FROM (
        SELECT
            a.GNTD_CODE,
            a.IS_APPROVED,
            a.COMMENTS,
            re.ERROR_CODES,
            re.ERROR_DETAILS,
            ROW_NUMBER() OVER (
                PARTITION BY a.GNTD_CODE
                ORDER BY a.ID
            ) RN
        FROM GNCN_TRANSACTION_APPROVAL a
        JOIN trans_filtered tf
             ON tf.GNTD_CODE = a.GNTD_CODE
        LEFT JOIN (
            SELECT
                rr.TRANS_APPROVAL_ID,
                LISTAGG(
                    rr.GROUP_CODE || ' - ' || rr.ERROR_DETAIL,
                    CHR(13) || CHR(10)
                ) WITHIN GROUP (ORDER BY rr.GROUP_CODE) AS ERROR_DETAILS,
                LISTAGG(
                    CASE
                        WHEN rr.ERROR_CODE = 'TRONG_YEU' THEN 'Tr?ng y?u'
                        ELSE 'Không tr?ng y?u'
                    END,
                    '; '
                ) WITHIN GROUP (ORDER BY rr.ERROR_CODE) AS ERROR_CODES
            FROM (
                SELECT DISTINCT
                    rr.TRANS_APPROVAL_ID,
                    rr.GROUP_CODE,
                    rr.ERROR_DETAIL,
                    rr.ERROR_CODE
                FROM GNCN_REASON_REFUSE rr
                JOIN trans_filtered tf
                     ON tf.GNTD_CODE = rr.GNTD_CODE
            ) rr
            GROUP BY rr.TRANS_APPROVAL_ID
        ) re
            ON re.TRANS_APPROVAL_ID = a.ID
        WHERE re.ERROR_CODES IS NOT NULL
           OR a.COMMENTS IS NOT NULL
    )
    GROUP BY GNTD_CODE
)

-- =========================================================
-- MAIN SELECT
-- =========================================================
  SELECT
    TO_CHAR(tf.APPROVAL_SUBMIT_TIME,'DD/MM/YYYY HH24:MI') NGAY_PHAT_SINH,
    tf.GNTD_CODE AS MA_YEU_CAU,
    tf.BRANCH_CODE AS MA_CHI_NHANH,
    tf.CUSTOMER_TYPE AS LOAI_KH,
    tf.ID_CARD AS CCCD,
    tf.CUSTOMER_CODE AS CIF,
    tf.CUSTOMER_NAME AS TEN_KH,
    tf.PDTD_CODE AS MA_PDTD,
    -- Thông tin s?n ph?m
    c.PRODUCT_NAME AS TEN_SAN_PHAM,
    c.BANK_PRODUCT_NAME AS SP_CU_THE,
    c.LOAN_PURPOSE AS MUC_DICH_VAY,
    c.LOAN_FLOW AS LUONG_PD,
    -- Phân lo?i
    cc.NAME AS PHAN_LUONG_GD,
    tf.APPROVAL_LOAN_METHOD AS LH_CAP_TIN_DUNG,
    tt1.NAME AS LOAI_GD_CAP_1,
    tt2.NAME AS LOAI_GD_CAP_2,
    tt3.NAME AS LOAI_GD_CAP_3,
    -- Giá tr? giao d?ch
    (
      CASE
        WHEN tf.TRANSACTION_TYPE1 IN ('Giainganthauchi', 'Giaingankhoanvay') THEN gtp.TOTAL_AMOUNT
        WHEN tf.TRANSACTION_TYPE1 = 'Khoitaohanmuc' THEN TO_NUMBER(JSON_VALUE(tf.LIMIT_JSON_DATA, '$.limitValue'))
        ELSE 0
      END
    ) AS GIA_TRI_GD,
    (
      CASE
        WHEN tf.TRANSACTION_TYPE1 IN ('Giainganthauchi', 'Giaingankhoanvay') THEN gtp.CURRENCY
        WHEN tf.TRANSACTION_TYPE1 = 'Khoitaohanmuc' THEN JSON_VALUE(tf.LIMIT_JSON_DATA, '$.limitCcy')
        ELSE 'VND'
      END
    ) AS LOAI_TIEN,
    -- Thông tin phê duy?t
    hd.LAST_PD_DATE AS NGAY_PHE_DUYET_GAN_NHAT,
    hd.PD_DATE_1 AS TG_PD_LAN_1,
    hd.PD_BY_1 AS USER_PD_LAN_1,
    hd.PD_DATE_2 AS TG_PD_LAN_2,
    hd.PD_BY_2 AS USER_PD_LAN_2,
    hd.PD_DATE_3 AS TG_PD_LAN_3,
    hd.PD_BY_3 AS USER_PD_LAN_3,
    hd.LAST_PD_DATE AS TG_PD_LAN_4,
    hd.LAST_PD_BY AS USER_PD_LAN_4,
    -- Thông tin CV HTTD ti?p nh?n h? s?
    ad.BG_DATE_1 AS TG_BAN_GIAO_LAN_1,
    ad.BG_DATE_2 AS TG_BAN_GIAO_LAN_2,
    ad.BG_DATE_3 AS TG_BAN_GIAO_LAN_3,
    ad.BG_DATE_4 AS TG_BAN_GIAO_LAN_4,
    -- Thông tin chuy?n phê duy?t
    sd.DX_BY_1 AS USER_DE_XUAT_LAN_1,
    sd.DX_DATE_1 AS TG_DE_XUAT_LAN_1,
    sd.DX_BY_2 AS USER_DE_XUAT_LAN_2,
    sd.DX_DATE_2 AS TG_DE_XUAT_LAN_2,
    sd.DX_BY_3 AS USER_DE_XUAT_LAN_3,
    sd.DX_DATE_3 AS TG_DE_XUAT_LAN_3,
    sd.DX_BY_4 AS USER_DE_XUAT_LAN_4,
    sd.DX_DATE_4 AS TG_DE_XUAT_LAN_4,
    --------------------------
    TO_CHAR(ch.CREATED_DATE,'DD/MM/YYYY HH24:MI') TG_HOAN_THANH_GD,
    -- Ý ki?n
    asum.Y_KIEN AS Y_KIEN,
    asum.NHOM_LOI AS NHOM_LOI,
    -- Tr?ng thái
    s.NAME AS TRANG_THAI,
    -- S? l??ng
    1 AS SL_MUC_DICH,
    -- Tài s?n b?o ??m
    COALESCE(tj.SL_TSBD, 0) AS SL_TSBD,
    tj.MA_TSBD AS MA_TSBD,
    -- S? l?n phê duy?t
    COALESCE(sc.SL, 0) AS SO_LAN_PD,
    -- Thông tin reference
    (
      CASE
        WHEN tf.TRANSACTION_TYPE1 = 'Giainganthauchi' THEN JSON_VALUE(gtp.OVERDRAFT_DATA, '$.overdraftAccount')
        ELSE JSON_VALUE(gtp.LOAN_DATA, '$.entryNumFcc')
      END
    ) AS MA_REF_HT
  FROM trans_filtered tf
  LEFT JOIN GNCN_TRANSACTION_PURPOSE gtp ON gtp.GNTD_CODE = tf.GNTD_CODE
  LEFT JOIN GNCN_CREDIT_APPROVAL_INFO_SYNC c ON c.PDTD_CODE = tf.PDTD_CODE
  LEFT JOIN GNCN_STATUS s ON tf.STATUS = s.CODE
  LEFT JOIN GNCN_CONFIG_COMMONS cc ON cc.CODE = tf.TRANSACTION_FLOW AND cc.SCOPE = 'TRAN_FLOW'
  LEFT JOIN GNCN_TRANSACTION_TYPE tt1 ON tt1.CODE = tf.TRANSACTION_TYPE1 AND tt1.USE_STATUS = 1 AND tt1.LEVEL_TYPE = 1
  LEFT JOIN GNCN_TRANSACTION_TYPE tt2 ON tt2.CODE = tf.TRANSACTION_TYPE2 AND tt2.USE_STATUS = 1 AND tt2.LEVEL_TYPE = 2 
  LEFT JOIN GNCN_TRANSACTION_TYPE tt3 ON tt3.CODE = tf.TRANSACTION_TYPE3 AND tt3.USE_STATUS = 1 AND tt3.LEVEL_TYPE = 3
  LEFT JOIN history_details hd ON hd.GNTD_CODE = tf.GNTD_CODE
  LEFT JOIN history_submit_detail sd ON sd.GNTD_CODE = tf.GNTD_CODE
  LEFT JOIN assignment_details ad ON ad.GNTD_CODE = tf.GNTD_CODE
  LEFT JOIN tran_with_json tj ON tj.GNTD_CODE = tf.GNTD_CODE
  LEFT JOIN submit_count sc ON sc.GNTD_CODE = tf.GNTD_CODE
  LEFT JOIN completion_history ch ON ch.GNTD_CODE = tf.GNTD_CODE
  LEFT JOIN approval_summary asum ON asum.GNTD_CODE = tf.GNTD_CODE
  ORDER BY tf.APPROVAL_SUBMIT_TIME DESC;
  
  EXCEPTION
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('===== SP_GET_REPORT_PR02 ERROR =====');
END SP_GET_REPORT_PR02;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_REPORT_PR03
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_REPORT_PR03" (
  P_DEADLINE_FROM_DATE IN VARCHAR2,
  P_DEADLINE_TO_DATE IN VARCHAR2,
  P_STATUS IN VARCHAR2,
  P_TYPE_CUSTOMER IN VARCHAR2,
  P_BRANCH IN VARCHAR2,
  P_FROM_APPROVAL IN VARCHAR2,
  P_TO_APPROVAL IN VARCHAR2,
  P_CIF IN VARCHAR2,
  P_USER_CVKH IN VARCHAR2,
  OUT_DATA OUT SYS_REFCURSOR
) AS 
  json_obj JSON_OBJECT_T;
BEGIN 
  OPEN OUT_DATA FOR
    SELECT
      DISTINCT GCD.BRANCH_CODE AS MA_CHI_NHANH,
      'KHCN' AS LOAI_KH,
      GCD.CUSTOMER_CODE AS CIF,
      GCD.CUSTOMER_NAME AS TEN_KH,
      GCD.CREDIT_USER AS CVKH,
      GCDD.PDTD_CODE AS MA_PDTD,
      GCDD.GNTD_CODE AS MA_GNTD,
      TO_CHAR(GCD.APPROVAL_DATE, 'DD/MM/YYYY') AS NGAY_PD_GN,
      GCD.CREATED_BY AS USER_TAO_GN,
      GCD.APPROVAL_BY AS USER_PD_GN,
      GCDD.DOC_NAME AS TEN_CT_NO,
      (
        CASE
          WHEN GCDD.DOC_CATEGORY = 1 THEN 'Quy ??nh s?n ph?m'
          WHEN GCDD.DOC_CATEGORY = 2 THEN 'Phê duy?t c?a c?p PDTD'
          ELSE 'Phê duy?t c?a c?p phê duy?t GNTD'
        END
      ) AS PHAN_LOAI_CT_NO,
      TO_CHAR(GCDD.DEADLINE, 'DD/MM/YYYY') AS NGAY_DEN_HAN_HT,
      GCDD.FREQUENCY AS TAN_SUAT,
      TO_CHAR(GCDD.DEADLINE_EXT, 'DD/MM/YYYY') AS GIA_HAN_BS_DEN,
      (
        CASE
          GCDD.STATUS
          WHEN 'HSSGN_CHO_BO_SUNG' THEN 'Ch? b? sung'
          WHEN 'HSSGN_CHO_PHE_DUYET' THEN 'Ch? phê duy?t'
          WHEN 'HSSGN_HOAN_THANH' THEN 'Hoàn thành'
          WHEN 'HSSGN_HUY_DK_BO_SUNG' THEN 'H?y ?i?u ki?n b? sung'
          ELSE ''
        END
      ) AS TRANG_THAI_HS,
      (
        CASE
          WHEN GCDD.STATUS = 'HSSGN_CHO_BO_SUNG' THEN NULL
          ELSE GCDD.APPROVAL_SUBMIT_BY
        END
      ) AS USER_BS,
      (
        CASE
          WHEN GCDD.STATUS = 'HSSGN_CHO_BO_SUNG' THEN NULL
          ELSE TO_CHAR(GCDD.APPROVAL_SUBMIT_DATE, 'DD/MM/YYYY')
        END
      ) AS THOI_GIAN_BS,
      (
        CASE
          WHEN GCDD.STATUS = 'HSSGN_HOAN_THANH'
          OR GCDD.STATUS = 'HSSGN_HUY_DK_BO_SUNG' THEN GCDD.APPROVAL_BY
          ELSE NULL
        END
      ) AS USER_PD_BS,
      (
        CASE
          WHEN GCDD.STATUS = 'HSSGN_HOAN_THANH'
          OR GCDD.STATUS = 'HSSGN_HUY_DK_BO_SUNG' THEN TO_CHAR(GCDD.APPROVAL_DATE, 'DD/MM/YYYY')
          ELSE NULL
        END
      ) AS TG_DUYET_BS,
      (
        CASE
          WHEN (
            GCDD.STATUS = 'HSSGN_HOAN_THANH'
            OR GCDD.STATUS = 'HSSGN_HUY_DK_BO_SUNG'
          ) THEN NULL
          WHEN (
            GCDD.STATUS_DOC = 'GIA_HAN_BO_SUNG'
            AND GCDD.STATUS_APPROVAL = 'DONG Y'
            AND GCDD.DEADLINE_EXT < TRUNC(SYSDATE)
          ) THEN 'Quá h?n'
          WHEN (
            GCDD.STATUS_DOC = 'GIA_HAN_BO_SUNG'
            AND GCDD.STATUS_APPROVAL = 'DONG Y'
            AND GCDD.DEADLINE_EXT >= TRUNC(SYSDATE)
            AND GCDD.DEADLINE_EXT < TRUNC(SYSDATE + 1)
          ) THEN '??n h?n'
          WHEN (
            GCDD.STATUS_DOC = 'GIA_HAN_BO_SUNG'
            AND GCDD.STATUS_APPROVAL = 'DONG Y'
            AND GCDD.DEADLINE_EXT >= TRUNC(SYSDATE + 1)
          ) THEN 'S?p ??n h?n'
          WHEN (GCDD.DEADLINE < TRUNC(SYSDATE)) THEN 'Quá h?n'
          WHEN (
            GCDD.DEADLINE >= TRUNC(SYSDATE)
            AND GCDD.DEADLINE < TRUNC(SYSDATE + 1)
          ) THEN '??n h?n'
          WHEN (GCDD.DEADLINE >= TRUNC(SYSDATE + 1)) THEN 'S?p ??n h?n'
        END
      ) AS TINH_TRANG_HS
    FROM
      GNCN_CA_DISBURSEMENT_DOCUMENTS GCDD
      LEFT JOIN GNCN_CA_DISBURSEMENT GCD ON GCDD.GNTD_CODE = GCD.GNTD_CODE
    WHERE
      (P_DEADLINE_FROM_DATE IS NULL OR GCDD.DEADLINE >= TO_DATE(P_DEADLINE_FROM_DATE, 'dd/MM/yyyy'))
      AND (P_DEADLINE_TO_DATE IS NULL OR GCDD.DEADLINE < TO_DATE(P_DEADLINE_TO_DATE, 'dd/MM/yyyy') + 1)
      
      AND (P_FROM_APPROVAL IS NULL OR GCDD.APPROVAL_DATE >= TO_DATE(P_FROM_APPROVAL, 'dd/MM/yyyy'))
      AND (P_TO_APPROVAL IS NULL OR GCDD.APPROVAL_DATE < TO_DATE(P_TO_APPROVAL, 'dd/MM/yyyy') + 1)
      AND GCD.STATUS IN ('GNCN_HOAN_THANH', 'GNCN_LOI_HACH_TOAN_HAN_MUC', 'GNCN_LOI_HACH_TOAN_KHOAN_VAY', 'GNCN_LOI_HACH_TOAN_THAU_CHI', 'GNCN_LOI_CHUYEN_TIEN', 'GNCN_HOAN_TAT_KHOAN_VAY')
      AND (
        P_BRANCH IS NULL
        OR INSTR(
          ',' || P_BRANCH || ',',
          ',' || GCD.BRANCH_CODE || ','
        ) > 0
      )
      AND (
        P_STATUS IS NULL
        OR INSTR(
          ',' || P_STATUS || ',',
          ',' || GCDD.STATUS || ','
        ) > 0
      )
      AND (
        P_CIF IS NULL
        OR GCD.CUSTOMER_CODE = P_CIF
      )
      AND (
        P_USER_CVKH IS NULL
        OR UPPER(GCD.CREDIT_USER) = UPPER(P_USER_CVKH)
      );

END SP_GET_REPORT_PR03;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_REPORT_TRANS_HISTORY
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_REPORT_TRANS_HISTORY" (
    P_FROM_DATE      IN VARCHAR2,
    P_TO_DATE        IN VARCHAR2,
    P_STATUS         IN VARCHAR2,
    P_TYPE_CUSTOMER  IN VARCHAR2,
    P_BRANCH         IN VARCHAR2,
    OUT_DATA         OUT SYS_REFCURSOR
) AS
  V_FROM_DATE DATE;
  V_TO_DATE   DATE;
BEGIN
  V_FROM_DATE := CASE WHEN P_FROM_DATE IS NOT NULL THEN TO_DATE(P_FROM_DATE,'DD/MM/YYYY') END;
  V_TO_DATE   := CASE WHEN P_TO_DATE IS NOT NULL THEN TO_DATE(P_TO_DATE,'DD/MM/YYYY') + 1 END;

OPEN OUT_DATA FOR
WITH
-- =====================================================
-- 1. TRANSACTION FILTER
-- =====================================================
trans_filtered AS (
  SELECT t.*
  FROM GNCN_TRANSACTION t
  WHERE 1 = 1
    AND (V_FROM_DATE IS NULL OR t.PROCESSING_DATE >= V_FROM_DATE)
    AND (V_TO_DATE   IS NULL OR t.PROCESSING_DATE <  V_TO_DATE)
    AND (P_TYPE_CUSTOMER IS NULL OR t.CUSTOMER_TYPE = P_TYPE_CUSTOMER)
    AND (
      P_STATUS IS NULL OR
      t.STATUS IN (
        SELECT REGEXP_SUBSTR(P_STATUS,'[^,]+',1,LEVEL)
        FROM dual
        CONNECT BY REGEXP_SUBSTR(P_STATUS,'[^,]+',1,LEVEL) IS NOT NULL
      )
    )
    AND (
      P_BRANCH IS NULL OR
      t.BRANCH_CODE IN (
        SELECT REGEXP_SUBSTR(P_BRANCH,'[^,]+',1,LEVEL)
        FROM dual
        CONNECT BY REGEXP_SUBSTR(P_BRANCH,'[^,]+',1,LEVEL) IS NOT NULL
      )
    )
),

-- =====================================================
-- 2. HISTORY – DÙNG LEAD
-- =====================================================
history_step AS (
  SELECT
    h.GNTD_CODE,
    h.STATUS               AS FROM_STEP,
    h.CREATED_BY           AS CREATED_BY_1,
    h.CREATED_DATE         AS CREATED_DATE_1,
    LEAD(h.STATUS)       OVER (PARTITION BY h.GNTD_CODE ORDER BY h.CREATED_DATE) AS TO_STEP,
    LEAD(h.CREATED_BY)   OVER (PARTITION BY h.GNTD_CODE ORDER BY h.CREATED_DATE) AS CREATED_BY_2,
    LEAD(h.CREATED_DATE) OVER (PARTITION BY h.GNTD_CODE ORDER BY h.CREATED_DATE) AS CREATED_DATE_2
  FROM GNCN_TRANSACTION_HISTORY h
  JOIN trans_filtered tf ON tf.GNTD_CODE = h.GNTD_CODE
),

history_filtered AS (
  SELECT *
  FROM history_step
  WHERE FROM_STEP = 'GNCN_CHO_XU_LY'
)

-- =====================================================
-- MAIN QUERY
-- =====================================================
  SELECT
    TO_CHAR(t.APPROVAL_SUBMIT_TIME,'DD/MM/YYYY HH24:MI') NGAY_PHAT_SINH,
    t.GNTD_CODE MA_YEU_CAU,
    t.BRANCH_CODE MA_CHI_NHANH,
    t.ID_CARD CCCD,
    t.CUSTOMER_CODE CIF,
    t.CUSTOMER_NAME TEN_KH,
    t.CUSTOMER_TYPE LOAI_KH,
    t.PDTD_CODE MA_PDTD,
    cc.NAME PHAN_LUONG_GD,
    c.LOAN_FLOW LUONG_PD,
    c.PRODUCT_NAME TEN_SAN_PHAM,
    c.BANK_PRODUCT_NAME SP_CU_THE,
    c.LOAN_PURPOSE MUC_DICH_VAY,
    tt1.NAME LOAI_GD_CAP_1,
    tt2.NAME LOAI_GD_CAP_2,
    tt3.NAME LOAI_GD_CAP_3,
    CASE
        WHEN t.TRANSACTION_TYPE1 IN ('Giainganthauchi','Giaingankhoanvay')
            THEN gtp.TOTAL_AMOUNT
        WHEN t.TRANSACTION_TYPE1 = 'Khoitaohanmuc'
            THEN TO_NUMBER(JSON_VALUE(t.LIMIT_JSON_DATA,'$.limitValue'))
        ELSE 0
    END GIA_TRI_GD,
    CASE
        WHEN t.TRANSACTION_TYPE1 IN ('Giainganthauchi','Giaingankhoanvay')
            THEN gtp.CURRENCY
        WHEN t.TRANSACTION_TYPE1 = 'Khoitaohanmuc'
            THEN JSON_VALUE(t.LIMIT_JSON_DATA,'$.limitCcy')
        ELSE 'VND'
    END LOAI_TIEN,
    TO_CHAR(h.CREATED_DATE_1,'DD/MM/YYYY HH24:MI') TG_DE_XUAT,
    h.CREATED_BY_1 USER_DE_XUAT,
    TO_CHAR(h.CREATED_DATE_2,'DD/MM/YYYY HH24:MI') TG_PHE_DUYET,
    h.CREATED_BY_2 USER_PHE_DUYET,
    NVL(h.TO_STEP, h.FROM_STEP) TRANG_THAI
  FROM trans_filtered t
  JOIN history_filtered h ON h.GNTD_CODE = t.GNTD_CODE
  LEFT JOIN GNCN_TRANSACTION_PURPOSE gtp ON gtp.GNTD_CODE = t.GNTD_CODE
  LEFT JOIN GNCN_CREDIT_APPROVAL_INFO_SYNC c ON c.PDTD_CODE = t.PDTD_CODE
  LEFT JOIN GNCN_CONFIG_COMMONS cc ON cc.CODE = t.TRANSACTION_FLOW AND cc.SCOPE = 'TRAN_FLOW'
  LEFT JOIN GNCN_TRANSACTION_TYPE tt1 ON tt1.CODE = t.TRANSACTION_TYPE1 AND tt1.LEVEL_TYPE = 1 AND tt1.USE_STATUS = 1
  LEFT JOIN GNCN_TRANSACTION_TYPE tt2 ON tt2.CODE = t.TRANSACTION_TYPE2 AND tt2.LEVEL_TYPE = 2 AND tt2.USE_STATUS = 1
  LEFT JOIN GNCN_TRANSACTION_TYPE tt3 ON tt3.CODE = t.TRANSACTION_TYPE3 AND tt3.LEVEL_TYPE = 3 AND tt3.USE_STATUS = 1
  ORDER BY h.CREATED_DATE_1;

END SP_GET_REPORT_TRANS_HISTORY;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_SELECTION_BRANCH
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_SELECTION_BRANCH" (
  P_REGION IN VARCHAR2,
  OUT_DATA OUT SYS_REFCURSOR
) AS BEGIN
  OPEN OUT_DATA FOR
    SELECT
      BRANCHCODE AS VALUE,
      BRANCHNAME AS NAME
    FROM
      CNTT_MASTERDATA.BRANCH
    WHERE
      STATUS = 'A'
      AND BRANCHCODE <> 'ALL_BRANCH'
      AND (P_REGION IS NULL OR REGION = P_REGION)
    ORDER BY
      BRANCHCODE ASC;
END SP_GET_SELECTION_BRANCH;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TAB_GNCN_CA_DISBURSEMENT_DOCUMENTS
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_TAB_GNCN_CA_DISBURSEMENT_DOCUMENTS" 
(
    P_GNTD_CODE             IN VARCHAR,
    P_PAGING_CURSOR         OUT SYS_REFCURSOR
) AS 
BEGIN
  OPEN P_PAGING_CURSOR FOR 
		SELECT
            rownum STT,
            GCDD.ID ID,
            GCDD.GNTD_CODE gntdCode,
            GCDD.COMPLETED_AFTER_DISBURSEMENT_ID completedAfterDisbursementId,
            GCDD.DOC_CODE docCode, --Mã Ch?ng t?
            GCDD.DOC_NAME docName, --Tên ch?ng t?
            GCDD.DOC_NAME docNameDisplay,
            GCDD.STATUS status,
            GCDD.DOC_CATEGORY docCategory,
            CASE WHEN GCDD.DOC_CATEGORY = 1 THEN 'Quy ??nh s?n ph?m'
                 WHEN GCDD.DOC_CATEGORY = 2 THEN 'Phê duy?t c?a c?p PDTD'
                 ELSE 'Phê duy?t c?a c?p phê duy?t GNTD'
            END docCategoryDisplayText,
            GCDD.DEADLINE deadline,
            CASE WHEN (GCDD.status_approval = 'DONG_Y' AND GCDD.DEADLINE_EXT IS NOT NULL) THEN TO_CHAR(GCDD.DEADLINE_EXT, 'DD/MM/YYYY')
                 ELSE TO_CHAR(GCDD.DEADLINE, 'DD/MM/YYYY')
            END AS deadlineDisplayText,
            GCDD.FREQUENCY frequency, --T?n su?t ??ng b? t? b?ng c?u hình
            GCDD.FREQUENCY_UNIT frequencyUnit,
            GCDD.FREQUENCY frequencyDisplay,
            CASE 
                WHEN GCDD.FREQUENCY IS NOT NULL THEN 
                    GCDD.FREQUENCY || ' ' ||
                    CASE 
                        WHEN GCDD.FREQUENCY_UNIT = 'TUAN' THEN 'Tu?n/l?n'
                        WHEN GCDD.FREQUENCY_UNIT = 'THANG' THEN 'Tháng/l?n'
                        WHEN GCDD.FREQUENCY_UNIT = 'QUY' THEN 'Quý/l?n'
                        WHEN GCDD.FREQUENCY_UNIT = 'NAM' THEN 'N?m/l?n'
                        ELSE ''
                    END
                ELSE ''
            END AS frequencyDisplaytext,
            GCDD.DESCRIPTION description, --Ý ki?n
            GCDD.GROUP_DOC_CODE groupDocCode,
            GCDD.GROUP_DOC_NAME groupDocName,
            GCDD.GROUP_DOC_NAME groupDocCategory,
            GCDD.GROUP_DOC_NAME groupDocCategoryDisplay,
            GCDD.CREATED_BY createdBy,
            GCDD.CREATED_DATE createdDate,
            TO_CHAR(GCDD.CREATED_DATE, 'DD/MM/YYYY') createdDateDisplayText,
            GCDD.MODIFIED_BY modifiedBy,
            GCDD.MODIFIED_DATE modifiedDate,
            TO_CHAR(GCDD.MODIFIED_DATE, 'DD/MM/YYYY') modifiedDateDisplayText,
            GCDD.status_verify statusVerify,
            GCDD.ASSIGNEE_ROLE_BY roles,
            GCDD.assignee_user_by assigneeUserBy,
            GCDD.approval_by approvalBy,
            GCDD.DEADLINE_EXT deadlineExt,
            GCDD.STATUS_DOC statusDoc,
            CASE WHEN GCDD.STATUS_DOC = 'DA_BO_SUNG' THEN '?ã b? sung'
                 WHEN GCDD.STATUS_DOC = 'GIA_HAN_BO_SUNG' THEN 'Gia h?n b? sung'
                 WHEN GCDD.STATUS_DOC = 'HUY_TAN_SUAT' THEN 'H?y t?n su?t'
                 WHEN GCDD.STATUS_DOC = 'HUY_DIEU_KIEN_BO_SUNG' THEN 'H?y ?i?u ki?n b? sung'
                 ELSE 'Ch?a b? sung'
            END statusDocDisplay,
            'NONE' AS visibleSave,
            GCD.PROCESSING_USERNAME as userKhoiTao,
            CASE WHEN GCDD.assignee_user_by IS NOT NULL THEN GCDD.assignee_user_by
                 ELSE GCDD.ASSIGNEE_ROLE_BY
            END userXuLy,
            CASE WHEN GCDD.status_approval = 'DONG_Y' THEN '??ng ý'
                 WHEN GCDD.status_approval = 'TU_CHOI' THEN 'Không ??ng ý'
                 WHEN GCDD.status_approval = 'CHO_PHE_DUYET' THEN 'Ch? phê duy?t'
                 ELSE ''
            END statusDisplayPrimary,
            GCDD.status_approval statusApproval,
            GCDD.ecm_folder ecmFolder
        FROM GNCN_CA_DISBURSEMENT_DOCUMENTS  GCDD
        LEFT JOIN GNCN_CA_DISBURSEMENT GCD ON gcd.gntd_code = gcdd.gntd_code
        WHERE  P_GNTD_CODE IS NULL OR P_GNTD_CODE = '' OR GCDD.GNTD_CODE = P_GNTD_CODE
        ORDER BY GCDD.created_by ASC;
END SP_GET_TAB_GNCN_CA_DISBURSEMENT_DOCUMENTS;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TRANSACTION_BY_REF_LOAN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_TRANSACTION_BY_REF_LOAN" (
  P_REF_LOAN IN VARCHAR2,
  OUT_DATA OUT SYS_REFCURSOR
) AS BEGIN OPEN OUT_DATA FOR
SELECT
  p.*,
  t.PDTD_CODE
FROM
  (
    SELECT
      r.GNTD_CODE, r.FCC_REF_NUM, r.APPROVAL_DATE
    FROM (
      SELECT
        FCC_REF_NUM,
        GNTD_CODE,
        TO_CHAR(INTERFACE_DATE, 'YYYY-MM-DD HH24:MI:SS') AS APPROVAL_DATE,
        ROW_NUMBER() OVER (PARTITION BY FCC_REF_NUM ORDER BY INTERFACE_DATE DESC) AS rn
      FROM
        GNCN_TRANSACTION_PURPOSE
      WHERE
        FCC_REF_NUM IS NOT NULL
    ) r
    INNER JOIN json_table(P_REF_LOAN, '$[*]' COLUMNS (value PATH '$')) ip on r.FCC_REF_NUM = ip.value
    WHERE r.rn = 1
  ) p
  INNER JOIN GNCN_TRANSACTION t ON t.GNTD_CODE = p.GNTD_CODE;

END SP_GET_TRANSACTION_BY_REF_LOAN;

