--------------------------------------------------------
--  DDL for Procedure SP_GET_TRANSACTION_DOC_FOR_UPDATE_FREQUENCY
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_TRANSACTION_DOC_FOR_UPDATE_FREQUENCY" (
  P_DATE IN VARCHAR2,
  OUT_DATA OUT SYS_REFCURSOR
) AS BEGIN OPEN OUT_DATA FOR
  SELECT
    ID, GNTD_CODE, PDTD_CODE, STATUS, STATUS_DOC, DOC_CATEGORY, 
    DOC_CODE, DOC_NAME, FREQUENCY, FREQUENCY_UNIT, TO_CHAR(DEADLINE, 'YYYY-MM-DD') AS DEADLINE
  FROM
    GNCN_CA_DISBURSEMENT_DOCUMENTS
  WHERE
    STATUS_DOC NOT IN ('HUY_DIEU_KIEN_BO_SUNG', 'HUY_TAN_SUAT')
    AND FREQUENCY IS NOT NULL AND FREQUENCY > 0
    AND FREQUENCY_UNIT IS NOT NULL
    AND DEADLINE IS NOT NULL
    AND TO_CHAR(DEADLINE, 'YYYY-MM-DD') = P_DATE
  ORDER BY
    ID DESC;

END SP_GET_TRANSACTION_DOC_FOR_UPDATE_FREQUENCY;

