--  DDL for Procedure SP_GET_TRANSACTION_SYNC_HO_SO_VAT_LY
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_TRANSACTION_SYNC_HO_SO_VAT_LY" (
  P_DATE IN VARCHAR2,
  OUT_DATA OUT SYS_REFCURSOR
) AS BEGIN OPEN OUT_DATA FOR
  SELECT 
    GNTD_CODE,
    PDTD_CODE,
    CUSTOMER_CODE,
