/
--------------------------------------------------------
--  DDL for Procedure SP_GET_TRANSACTION_SYNC_TASK_HUB
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_TRANSACTION_SYNC_TASK_HUB" (
  P_GNTD_CODE IN VARCHAR2,
  OUT_DATA OUT SYS_REFCURSOR
) AS BEGIN OPEN OUT_DATA FOR
  SELECT
    t.GNTD_CODE,
    t.PDTD_CODE,
    t.TRANSACTION_TYPE1,
    t.CUSTOMER_CODE,
    t.CUSTOMER_NAME,
    t.BRANCH_CODE,
    t.BRANCH_NAME,
    t.PROCESSING_OWNER AS ISSUED_BY,
    TO_CHAR(t.PROCESSING_DATE, 'DD/MM/YYYY HH24:MI:SS') AS ISSUE_DATE,
    t.APPROVAL_BY,
    TO_CHAR(t.APPROVAL_DATE, 'DD/MM/YYYY HH24:MI:SS') AS APPROVAL_DATE,
    t.STATUS,
    t.RED_FLAG_DATE AS dueDate,
    RTRIM(
         NVL2(t.created_by, t.created_by || ',', NULL)
      || CASE WHEN t.modified_by IS NOT NULL
               AND t.modified_by <> NVL(t.created_by, CHR(0))
              THEN t.modified_by || ',' END
      || CASE WHEN t.approval_by IS NOT NULL
               AND t.approval_by NOT IN (NVL(t.created_by, CHR(0)),
                                         NVL(t.modified_by, CHR(0)))
              THEN t.approval_by || ',' END
      || CASE WHEN t.approver_suggest IS NOT NULL
               AND t.approver_suggest NOT IN (NVL(t.created_by, CHR(0)),
                                              NVL(t.modified_by, CHR(0)),
                                              NVL(t.approval_by, CHR(0)))
              THEN t.approver_suggest || ',' END
      || CASE WHEN t.recent_editor IS NOT NULL
               AND t.recent_editor NOT IN (NVL(t.created_by, CHR(0)),
                                           NVL(t.modified_by, CHR(0)),
                                           NVL(t.approval_by, CHR(0)),
                                           NVL(t.approver_suggest, CHR(0)))
              THEN t.recent_editor || ',' END
    , ',') AS participant,
    t.APPROVER_SUGGEST,
    t.MODIFIED_DATE,
    t.ID_CARD AS cusIdCard,
    t.PRODUCT_NAME,
    t.LIMIT_CODE
  FROM GNCN_TRANSACTION t
  WHERE t.GNTD_CODE = P_GNTD_CODE;
  
END SP_GET_TRANSACTION_SYNC_TASK_HUB;

/
--------------------------------------------------------
--  DDL for Procedure SP_GET_USER_HAU_KIEM_BY_ROLES
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GET_USER_HAU_KIEM_BY_ROLES" (
    IN_ROLES_STR IN  VARCHAR2,
    SYS_CURSOR   OUT SYS_REFCURSOR
)
AS
BEGIN
    OPEN SYS_CURSOR FOR
        SELECT DISTINCT
            gepc.USER_NAME,
            ht.BRANCH_CODE
        FROM 
            GNCN_EMPLOYEE_PROCESS_CONFIG gepc
            JOIN HKCN_TRANSACTION ht 
                ON (
                    -- N?u BRANCHS ch?a ALL_BRANCH thì th?a m?i chi nhánh
                    INSTR(gepc.BRANCHS, 'ALL_BRANCH') > 0
                    OR
                    -- N?u không thì ki?m tra ht.BRANCH_CODE có n?m trong danh sách BRANCHS
                    INSTR(',' || gepc.BRANCHS || ',', ',' || ht.BRANCH_CODE || ',') > 0
                )
        WHERE 
            gepc.USE_STATUS = 1
            AND EXISTS (
                SELECT 1
                FROM (
                    SELECT TRIM(REGEXP_SUBSTR(IN_ROLES_STR, '[^,]+', 1, LEVEL)) AS input_role
                    FROM dual
                    CONNECT BY LEVEL <= REGEXP_COUNT(IN_ROLES_STR, ',') + 1
                ) t
                WHERE INSTR(',' || gepc.ROLE || ',', ',' || t.input_role || ',') > 0
            )
            AND ht.SUBMIT_DATE >= TRUNC(SYSDATE) - 1 + INTERVAL '21' HOUR
            AND ht.SUBMIT_DATE <  TRUNC(SYSDATE) + INTERVAL '21' HOUR;
END;

/
--------------------------------------------------------
--  DDL for Procedure SP_GNCN_CA_DISBURSEMENT_GET_USER_BY_ROLE_AND_BRANCH
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GNCN_CA_DISBURSEMENT_GET_USER_BY_ROLE_AND_BRANCH" (
    P_ID IN NUMBER,
    P_BRANCH_CODE IN NVARCHAR2,
    P_GNTD_CODE IN NVARCHAR2,
    P_USER_NAME IN NVARCHAR2,
    P_PDTD_CODE IN NVARCHAR2,
    P_PAGING_CURSOR_TO OUT PAGINGPACKAGE.PAGING_CURSOR,
    P_PAGING_CURSOR_CC OUT PAGINGPACKAGE.PAGING_CURSOR
) AS
    v_assignee_user VARCHAR2(200);
    v_assignee_role VARCHAR2(200);
    v_trancflow VARCHAR2(200);
    p_name VARCHAR2(200);
BEGIN
    IF P_ID is not null THEN
        SELECT ASSIGNEE_USER_BY,ASSIGNEE_ROLE_BY INTO v_assignee_user, v_assignee_role
        FROM gncn_ca_disbursement_documents gtp
        WHERE gtp.ID = P_ID;
    
        IF v_assignee_role is not null THEN -- VH DVKD, G? ?VKD
            OPEN P_PAGING_CURSOR_TO FOR 
            SELECT DISTINCT * FROM (
                SELECT DISTINCT USER_NAME as USER_NAME_TO from GNCN_EMPLOYEE_PROCESS_CONFIG
                where USE_STATUS = 1 
                AND role in ('GNCN_QL_HTTD_DVKD') -- Role QL HTTD ?VKD
                AND (UPPER(P_BRANCH_CODE) IN (
									SELECT REGEXP_SUBSTR(UPPER(branchs),'[^,]+', 1, LEVEL) FROM dual
									CONNECT BY REGEXP_SUBSTR(UPPER(branchs), '[^,]+', 1, LEVEL) IS NOT NULL))
                UNION ALL
                SELECT ASSIGNEE_USER_BY as USER_NAME_TO FROM gncn_ca_disbursement_documents gtp WHERE gtp.ID = P_ID --  User x? lý (User có action cu?i cùng)
--                UNION ALL
--                SELECT MODIFIED_BY as USER_NAME_TO FROM gncn_ca_disbursement_documents gtp WHERE gtp.ID = P_ID -- User kh?i t?o giao d?ch h? s? thi?u
            );
            OPEN P_PAGING_CURSOR_CC FOR
            SELECT DISTINCT * FROM (
               SELECT DISTINCT USER_NAME from GNCN_EMPLOYEE_PROCESS_CONFIG
               where USE_STATUS = 1 
--               AND role in ('GNCN_CV_HTTD_DVKD','GNCN_GD_DVKD','GNCN_QL_HTTD_DVKD')
               AND EXISTS (
                    SELECT 1 FROM (
                        SELECT REGEXP_SUBSTR(role, '[^,]+', 1, LEVEL) AS single_role
                        FROM dual
                        CONNECT BY REGEXP_SUBSTR(role, '[^,]+', 1, LEVEL) IS NOT NULL
                          AND PRIOR dbms_random.value IS NOT NULL
                          AND PRIOR role = role
                    ) WHERE single_role IN ('GNCN_CV_HTTD_DVKD','GNCN_GD_DVKD','GNCN_QL_HTTD_DVKD')
                )
               AND (UPPER(P_BRANCH_CODE) IN (
									SELECT REGEXP_SUBSTR(UPPER(branchs),'[^,]+', 1, LEVEL) FROM dual
									CONNECT BY REGEXP_SUBSTR(UPPER(branchs), '[^,]+', 1, LEVEL) IS NOT NULL))
               UNION ALL
               SELECT DISTINCT USER_NAME FROM GNCN_TRANSACTION_DISSCUSTION WHERE (P_GNTD_CODE IS NULL OR GNCN_CODE = P_GNTD_CODE) AND (P_USER_NAME IS NULL OR USER_NAME <> P_USER_NAME)
               UNION ALL
               SELECT DISTINCT (TRUONG_NHOM) AS USER_NAME from gncn_credit_approval_info_sync where pdtd_code = P_PDTD_CODE
               UNION ALL
               SELECT DISTINCT USER_NAME from GNCN_EMPLOYEE_PROCESS_CONFIG where POSITION_CODE in ('GD.PKD')
               AND USE_STATUS = 1
               AND (UPPER(P_BRANCH_CODE) IN (
									SELECT REGEXP_SUBSTR(UPPER(branchs),'[^,]+', 1, LEVEL) FROM dual
									CONNECT BY REGEXP_SUBSTR(UPPER(branchs), '[^,]+', 1, LEVEL) IS NOT NULL))
               UNION ALL
               SELECT DISTINCT USER_NAME from GNCN_EMPLOYEE_PROCESS_CONFIG where USE_STATUS = 1 AND role in ('GNCN_ADMIN')
               UNION ALL
               SELECT DISTINCT LOWER(REPLACE(CHUYEN_VIEN_KHACH_HANG, ' ', '')) AS USER_NAME from gncn_credit_approval_info_sync where pdtd_code = P_PDTD_CODE -- 4
            );
        ELSIF v_assignee_user is not null THEN -- luong tap trung
            OPEN P_PAGING_CURSOR_TO FOR 
            SELECT DISTINCT * FROM (
                SELECT ASSIGNEE_USER_BY as USER_NAME_TO FROM gncn_ca_disbursement_documents gtp WHERE gtp.ID = P_ID -- User ???c phân công
                UNION ALL
                SELECT APPROVAL_BY as USER_NAME_TO FROM gncn_ca_disbursement_documents gtp WHERE gtp.ID = P_ID -- User x? lý (User có action cu?i cùng)
                UNION ALL
                SELECT APPROVAL_SUBMIT_BY as USER_NAME_TO FROM gncn_ca_disbursement_documents gtp WHERE gtp.ID = P_ID -- User chuy?n phê duy?t
                -- comment backup
--                UNION ALL
--                SELECT PROCESSING_USERNAME as USER_NAME_TO FROM GNCN_CA_DISBURSEMENT gcd WHERE gcd.GNTD_CODE = P_GNTD_CODE
--                UNION ALL
--                SELECT 
--                    CASE 
--                        WHEN MODIFIED_BY IS NOT NULL THEN MODIFIED_BY 
--                        ELSE (SELECT PROCESSING_USERNAME 
--                        FROM GNCN_CA_DISBURSEMENT gcd 
--                        WHERE gcd.GNTD_CODE = P_GNTD_CODE 
--                    AND ROWNUM = 1) 
--                END AS USER_NAME_TO
--                FROM gncn_ca_disbursement_documents gtp 
--                WHERE gtp.ID = P_ID  -- User kh?i t?o giao d?ch h? s? thi?u
            );
            OPEN P_PAGING_CURSOR_CC FOR
            SELECT DISTINCT * FROM (
                SELECT DISTINCT USER_NAME from GNCN_EMPLOYEE_PROCESS_CONFIG 
                where USE_STATUS = 1 
--                AND role in ('GNCN_CV_HTTD_DVKD','GNCN_GD_DVKD','GNCN_QL_HTTD_DVKD')
                AND EXISTS (
                    SELECT 1 FROM (
                        SELECT REGEXP_SUBSTR(role, '[^,]+', 1, LEVEL) AS single_role
                        FROM dual
                        CONNECT BY REGEXP_SUBSTR(role, '[^,]+', 1, LEVEL) IS NOT NULL
                          AND PRIOR dbms_random.value IS NOT NULL
                          AND PRIOR role = role
                    ) WHERE single_role IN ('GNCN_CV_HTTD_DVKD', 'GNCN_GD_DVKD', 'GNCN_QL_HTTD_DVKD')
                )
                AND (UPPER(P_BRANCH_CODE) IN (
									SELECT REGEXP_SUBSTR(UPPER(branchs),'[^,]+', 1, LEVEL) FROM dual
									CONNECT BY REGEXP_SUBSTR(UPPER(branchs), '[^,]+', 1, LEVEL) IS NOT NULL))
                UNION ALL
                SELECT DISTINCT USER_NAME FROM GNCN_TRANSACTION_DISSCUSTION WHERE (P_GNTD_CODE IS NULL OR GNCN_CODE = P_GNTD_CODE) AND (P_USER_NAME IS NULL OR USER_NAME <> P_USER_NAME)
                UNION ALL
                SELECT DISTINCT USER_NAME from GNCN_EMPLOYEE_PROCESS_CONFIG where USE_STATUS = 1 AND role in ('GNCN_ADMIN')
                UNION ALL
                SELECT DISTINCT (user_process) AS USER_NAME FROM gncn_user_group_config WHERE USE_STATUS = 1 AND BRANCH_CODE = P_BRANCH_CODE AND group_process = (
                  SELECT group_process FROM gncn_user_group_config WHERE USE_STATUS = 1 AND BRANCH_CODE = P_BRANCH_CODE AND user_process = p_name FETCH FIRST 1 ROWS ONLY
                )
                UNION ALL
                SELECT DISTINCT USER_PROCESS AS USER_NAME FROM GNCN_USER_GROUP_CONFIG WHERE GROUP_PROCESS = (
                    SELECT GROUP_PROCESS FROM GNCN_USER_GROUP_CONFIG WHERE UPPER(USER_PROCESS) = UPPER(
                        (SELECT ASSIGNEE_USER_BY FROM gncn_ca_disbursement_documents gtp WHERE gtp.ID = P_ID)
                    ) AND USE_STATUS = 1 AND BRANCH_CODE = P_BRANCH_CODE AND ROWNUM = 1
                ) AND BRANCH_CODE = P_BRANCH_CODE AND USE_STATUS = 1
                UNION ALL
                SELECT DISTINCT LOWER(REPLACE(TRUONG_NHOM, ' ', '')) AS USER_NAME from gncn_credit_approval_info_sync where pdtd_code = P_PDTD_CODE
                UNION ALL
                SELECT DISTINCT USER_NAME from GNCN_EMPLOYEE_PROCESS_CONFIG where POSITION_CODE in ('GD.PKD')
                AND USE_STATUS = 1
                AND (UPPER(P_BRANCH_CODE) IN (
									SELECT REGEXP_SUBSTR(UPPER(branchs),'[^,]+', 1, LEVEL) FROM dual
									CONNECT BY REGEXP_SUBSTR(UPPER(branchs), '[^,]+', 1, LEVEL) IS NOT NULL))
                UNION ALL
                SELECT DISTINCT LOWER(REPLACE(CHUYEN_VIEN_KHACH_HANG, ' ', '')) AS USER_NAME from gncn_credit_approval_info_sync where pdtd_code = P_PDTD_CODE -- 4
            );
        END IF;
        ELSIF v_assignee_user is not null and v_assignee_role is not null THEN -- TH 100% không vào
            OPEN P_PAGING_CURSOR_TO FOR
            SELECT DISTINCT * FROM (
                SELECT DISTINCT USER_NAME from GNCN_EMPLOYEE_PROCESS_CONFIG where branchs like '%'||P_BRANCH_CODE||'%' AND role in ('GNCN_QL_HTTD_DVKD','GNCN_GD_DVKD')
                UNION ALL
                SELECT ASSIGNEE_USER_BY AS USER_NAME FROM gncn_ca_disbursement_documents gtp WHERE gtp.ID = P_ID
            );
            OPEN P_PAGING_CURSOR_CC FOR
            SELECT DISTINCT * FROM (
                SELECT DISTINCT USER_NAME from GNCN_EMPLOYEE_PROCESS_CONFIG 
                where branchs like '%'||P_BRANCH_CODE||'%' 
--                AND role in ('GNCN_CV_HTTD_DVKD','GNCN_GD_DVKD','GNCN_QL_HTTD_DVKD')
                AND EXISTS (
                    SELECT 1 FROM (
                        SELECT REGEXP_SUBSTR(role, '[^,]+', 1, LEVEL) AS single_role
                        FROM dual
                        CONNECT BY REGEXP_SUBSTR(role, '[^,]+', 1, LEVEL) IS NOT NULL
                          AND PRIOR dbms_random.value IS NOT NULL
                          AND PRIOR role = role
                    ) WHERE single_role IN ('GNCN_CV_HTTD_DVKD', 'GNCN_GD_DVKD', 'GNCN_QL_HTTD_DVKD')
                )
                UNION ALL
                SELECT ASSIGNEE_USER_BY AS USER_NAME FROM gncn_ca_disbursement_documents gtp WHERE gtp.ID = P_ID
                UNION ALL
                SELECT DISTINCT (USER_NAME) AS USER_NAME FROM GNCN_TRANSACTION_DISSCUSTION WHERE (P_GNTD_CODE IS NULL OR GNCN_CODE = P_GNTD_CODE) AND (P_USER_NAME IS NULL OR USER_NAME <> P_USER_NAME)
            );
    ELSIF P_ID IS NULL THEN
    -- Get the transaction flow for the given GNTD code
    SELECT transaction_flow INTO v_trancflow
    FROM gncn_transaction
    WHERE gntd_code = P_GNTD_CODE;
    IF v_trancflow = 'DVKD' THEN
        OPEN P_PAGING_CURSOR_TO FOR
            SELECT DISTINCT USER_NAME
            FROM GNCN_EMPLOYEE_PROCESS_CONFIG
            WHERE role IN ('GNCN_QL_HTTD_DVKD')
            AND USE_STATUS = 1
            AND (UPPER(P_BRANCH_CODE) IN (
									SELECT REGEXP_SUBSTR(UPPER(branchs),'[^,]+', 1, LEVEL) FROM dual
									CONNECT BY REGEXP_SUBSTR(UPPER(branchs), '[^,]+', 1, LEVEL) IS NOT NULL));
        OPEN P_PAGING_CURSOR_CC FOR
        SELECT DISTINCT * FROM (
            SELECT DISTINCT USER_NAME
            FROM GNCN_EMPLOYEE_PROCESS_CONFIG
            WHERE 
--            role IN ('GNCN_CV_HTTD_DVKD','GNCN_GD_DVKD') -- 1,2
            EXISTS (
                SELECT 1 FROM (
                    SELECT REGEXP_SUBSTR(role, '[^,]+', 1, LEVEL) AS single_role
                    FROM dual
                    CONNECT BY REGEXP_SUBSTR(role, '[^,]+', 1, LEVEL) IS NOT NULL
                      AND PRIOR dbms_random.value IS NOT NULL
                      AND PRIOR role = role
                ) WHERE single_role IN ('GNCN_CV_HTTD_DVKD','GNCN_GD_DVKD')
            )
            AND USE_STATUS = 1
            AND (UPPER(P_BRANCH_CODE) IN (
									SELECT REGEXP_SUBSTR(UPPER(branchs),'[^,]+', 1, LEVEL) FROM dual
									CONNECT BY REGEXP_SUBSTR(UPPER(branchs), '[^,]+', 1, LEVEL) IS NOT NULL))
            UNION ALL
            SELECT DISTINCT USER_NAME
            FROM GNCN_TRANSACTION_DISSCUSTION
            WHERE (P_GNTD_CODE IS NULL OR GNCN_CODE = P_GNTD_CODE)
            AND (P_USER_NAME IS NULL OR USER_NAME <> P_USER_NAME) -- 5
            UNION ALL
            SELECT DISTINCT LOWER(REPLACE(TRUONG_NHOM, ' ', '')) AS USER_NAME from gncn_credit_approval_info_sync where pdtd_code = P_PDTD_CODE -- 4
            UNION ALL
            SELECT DISTINCT USER_NAME from GNCN_EMPLOYEE_PROCESS_CONFIG where role in ('GNCN_ADMIN') AND USE_STATUS = 1
            UNION ALL
            SELECT DISTINCT LOWER(REPLACE(CHUYEN_VIEN_KHACH_HANG, ' ', '')) AS USER_NAME from gncn_credit_approval_info_sync where pdtd_code = P_PDTD_CODE -- 3
            UNION ALL
            SELECT DISTINCT USER_NAME from GNCN_EMPLOYEE_PROCESS_CONFIG where POSITION_CODE in ('GD.PKD') AND USE_STATUS = 1
--            AND branchs LIKE '%' || P_BRANCH_CODE || '%'
            AND (UPPER(P_BRANCH_CODE) IN (
									SELECT REGEXP_SUBSTR(UPPER(branchs),'[^,]+', 1, LEVEL) FROM dual
									CONNECT BY REGEXP_SUBSTR(UPPER(branchs), '[^,]+', 1, LEVEL) IS NOT NULL))
        );
	 ELSIF v_trancflow = 'GD_DVKD' THEN
         OPEN P_PAGING_CURSOR_TO FOR
            SELECT DISTINCT USER_NAME
            FROM GNCN_EMPLOYEE_PROCESS_CONFIG
            WHERE role IN ('GNCN_GD_DVKD')
            AND USE_STATUS = 1
            AND (UPPER(P_BRANCH_CODE) IN (
									SELECT REGEXP_SUBSTR(UPPER(branchs),'[^,]+', 1, LEVEL) FROM dual
									CONNECT BY REGEXP_SUBSTR(UPPER(branchs), '[^,]+', 1, LEVEL) IS NOT NULL));
         OPEN P_PAGING_CURSOR_CC FOR
         SELECT DISTINCT * FROM (
            SELECT DISTINCT USER_NAME
            FROM GNCN_EMPLOYEE_PROCESS_CONFIG
            WHERE 
--            role IN ('GNCN_CV_HTTD_DVKD','GNCN_QL_HTTD_DVKD') -- 1,2
            EXISTS (
                SELECT 1 FROM (
                    SELECT REGEXP_SUBSTR(role, '[^,]+', 1, LEVEL) AS single_role
                    FROM dual
                    CONNECT BY REGEXP_SUBSTR(role, '[^,]+', 1, LEVEL) IS NOT NULL
                      AND PRIOR dbms_random.value IS NOT NULL
                      AND PRIOR role = role
                ) WHERE single_role IN ('GNCN_CV_HTTD_DVKD','GNCN_QL_HTTD_DVKD')
            )
            AND USE_STATUS = 1
            AND (UPPER(P_BRANCH_CODE) IN (
									SELECT REGEXP_SUBSTR(UPPER(branchs),'[^,]+', 1, LEVEL) FROM dual
									CONNECT BY REGEXP_SUBSTR(UPPER(branchs), '[^,]+', 1, LEVEL) IS NOT NULL))
            UNION ALL
            SELECT DISTINCT USER_NAME
            FROM GNCN_TRANSACTION_DISSCUSTION
            WHERE (P_GNTD_CODE IS NULL OR GNCN_CODE = P_GNTD_CODE)
            AND (P_USER_NAME IS NULL OR USER_NAME <> P_USER_NAME)
            UNION ALL
            SELECT DISTINCT LOWER(REPLACE(TRUONG_NHOM, ' ', '')) AS USER_NAME from gncn_credit_approval_info_sync where pdtd_code = P_PDTD_CODE --4
            UNION ALL
            SELECT DISTINCT USER_NAME from GNCN_EMPLOYEE_PROCESS_CONFIG where role in ('GNCN_ADMIN') AND USE_STATUS = 1 --5 
            UNION ALL
            SELECT DISTINCT LOWER(REPLACE(CHUYEN_VIEN_KHACH_HANG, ' ', '')) AS USER_NAME from gncn_credit_approval_info_sync where pdtd_code = P_PDTD_CODE -- 3
            UNION ALL
            SELECT DISTINCT USER_NAME from GNCN_EMPLOYEE_PROCESS_CONFIG where POSITION_CODE in ('GD.PKD')
            AND USE_STATUS = 1
            AND (UPPER(P_BRANCH_CODE) IN (
									SELECT REGEXP_SUBSTR(UPPER(branchs),'[^,]+', 1, LEVEL) FROM dual
									CONNECT BY REGEXP_SUBSTR(UPPER(branchs), '[^,]+', 1, LEVEL) IS NOT NULL))
		);
     ELSIF v_trancflow = 'TT' THEN
         OPEN P_PAGING_CURSOR_TO FOR
            SELECT gtp.approver_suggest INTO p_name FROM gncn_transaction gtp WHERE gtp.gntd_code = P_GNTD_CODE;
         OPEN P_PAGING_CURSOR_CC FOR
            SELECT DISTINCT * FROM (
            SELECT DISTINCT USER_NAME 
            from GNCN_EMPLOYEE_PROCESS_CONFIG 
            where 
--            role in ('GNCN_CV_HTTD_DVKD','GNCN_GD_DVKD','GNCN_QL_HTTD_DVKD') -- 1,2,3
            EXISTS (
                SELECT 1 FROM (
                    SELECT REGEXP_SUBSTR(role, '[^,]+', 1, LEVEL) AS single_role
                    FROM dual
                    CONNECT BY REGEXP_SUBSTR(role, '[^,]+', 1, LEVEL) IS NOT NULL
                      AND PRIOR dbms_random.value IS NOT NULL
                      AND PRIOR role = role
                ) WHERE single_role IN ('GNCN_CV_HTTD_DVKD','GNCN_GD_DVKD','GNCN_QL_HTTD_DVKD')
            )
            AND USE_STATUS = 1
            AND (UPPER(P_BRANCH_CODE) IN (
									SELECT REGEXP_SUBSTR(UPPER(branchs),'[^,]+', 1, LEVEL) FROM dual
									CONNECT BY REGEXP_SUBSTR(UPPER(branchs), '[^,]+', 1, LEVEL) IS NOT NULL))
            UNION ALL
            SELECT DISTINCT LOWER(REPLACE(TRUONG_NHOM, ' ', '')) AS USER_NAME from gncn_credit_approval_info_sync where pdtd_code = P_PDTD_CODE -- 5
            UNION ALL
            SELECT DISTINCT LOWER(REPLACE(CHUYEN_VIEN_KHACH_HANG, ' ', '')) AS USER_NAME from gncn_credit_approval_info_sync where pdtd_code = P_PDTD_CODE -- 4
            UNION ALL
            SELECT DISTINCT USER_NAME from GNCN_EMPLOYEE_PROCESS_CONFIG where role in ('GNCN_ADMIN') AND USE_STATUS = 1 --8
            UNION ALL
            SELECT DISTINCT user_process AS USER_NAME from GNCN_USER_GROUP_CONFIG where USE_STATUS = 1 AND BRANCH_CODE = P_BRANCH_CODE AND group_process IN (
                SELECT DISTINCT group_process from GNCN_USER_GROUP_CONFIG where USE_STATUS = 1 AND BRANCH_CODE = P_BRANCH_CODE AND UPPER(user_process) = UPPER(
                    (SELECT gtp.approver_suggest FROM gncn_transaction gtp WHERE gtp.gntd_code = P_GNTD_CODE))
                FETCH FIRST 1 ROW ONLY
            ) -- 7
            UNION ALL
            SELECT DISTINCT USER_NAME from GNCN_EMPLOYEE_PROCESS_CONFIG where POSITION_CODE in ('GD.PKD')
            AND USE_STATUS = 1
            AND (UPPER(P_BRANCH_CODE) IN (
									SELECT REGEXP_SUBSTR(UPPER(branchs),'[^,]+', 1, LEVEL) FROM dual
									CONNECT BY REGEXP_SUBSTR(UPPER(branchs), '[^,]+', 1, LEVEL) IS NOT NULL))
            );
     ELSE
        OPEN P_PAGING_CURSOR_TO FOR
            SELECT NULL AS ASSIGNEE_USER_BY FROM DUAL;
        OPEN P_PAGING_CURSOR_CC FOR
            SELECT NULL AS USER_NAME FROM DUAL;
    END IF;
END IF;
END SP_GNCN_CA_DISBURSEMENT_GET_USER_BY_ROLE_AND_BRANCH;

/
--------------------------------------------------------
--  DDL for Procedure SP_GNCN_GET_CA_DOCUMENT_DATA_BY_GNTD_CODE
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GNCN_GET_CA_DOCUMENT_DATA_BY_GNTD_CODE" (
    P_GNCN_CODE IN NVARCHAR2,
    P_MAILCODE IN NVARCHAR2,
    P_ID IN NUMBER,
    P_PAGING_CURSOR OUT PAGINGPACKAGE.PAGING_CURSOR
) AS
BEGIN
    OPEN P_PAGING_CURSOR FOR
    SELECT DISTINCT
        gcdd.id,
        gcd.gntd_code, 
        gcd.branch_code,
        NVL(gcd.CREDIT_USER, 'Không có CVKH') AS CREDIT_USER,
        CASE 
            WHEN P_MAILCODE = 'M7.1' THEN NVL(gcd.APPROVAL_BY, 'Không có PDGN')
            WHEN P_MAILCODE = 'M7.2' THEN NVL(gcdd.ASSIGNEE_USER_BY, 'Không có thông tin')
            ELSE 'Không có thông tin' 
        END AS APPROVAL_BY,
        NVL(gcd.PROCESSING_USERNAME, 'Không có ?XGN') AS PROCESSING_USERNAME,
        gcd.customer_code, 
        gcd.customer_name,
        CASE 
            WHEN gcdd.doc_category = 1 THEN 'Quy ??nh s?n ph?m' 
            WHEN gcdd.doc_category = 2 THEN 'Phê duy?t c?a c?p PDTD'
            WHEN gcdd.doc_category = 3 THEN 'Phê duy?t c?a c?p phê duy?t GNTD'
            ELSE 'Không rõ ch?ng t?' 
        END AS doc_category,
        gcdd.doc_name,
        CASE 
            WHEN gcdd.status = 'HSSGN_CHO_PHE_DUYET' THEN 'HSSGN - Ch? phê duy?t' 
            WHEN gcdd.status = 'HSSGN_CHO_BO_SUNG' THEN 'HSSGN - Ch? b? sung'
            WHEN gcdd.status = 'HSSGN_HUY_DK_BO_SUNG' THEN 'HSSGN - H?y ?i?u ki?n b? sung'
            WHEN gcdd.status = 'HSSGN_HOAN_THANH' THEN 'HSSGN - Hoàn thành'
            ELSE 'HSSGN - Ch? b? sung' 
        END AS status,
        CASE
            WHEN P_MAILCODE = 'M7.1' THEN TO_CHAR(gcdd.deadline, 'YYYY-MM-DD')
            ELSE ' '
        END AS deadline, 
        CASE 
            WHEN gcdd.status_doc = 'CHUA_BO_SUNG' THEN 'Ch?a b? sung' 
            WHEN gcdd.status_doc = 'DA_BO_SUNG' THEN '?ã b? sung h? s?'
            WHEN gcdd.status_doc = 'GIA_HAN_BO_SUNG' THEN 'Gia h?n b? sung'
            WHEN gcdd.status_doc = 'HUY_TAN_SUAT' THEN 'H?y t?n su?t'
            WHEN gcdd.status_doc = 'HUY_DIEU_KIEN_BO_SUNG' THEN 'H?y ?i?u ki?n b? sung'
            ELSE 'Ch?a b? sung' 
        END AS status_doc,
--        NVL(gcdd.user_idea, 'Không có ý ki?n') AS USER_IDEA,
        CASE
            WHEN P_MAILCODE = 'M7.2' THEN TO_NCHAR(NVL(gcdd.APPROVAL_IDEA, ' '))
            WHEN P_MAILCODE = 'M7.1' THEN TO_NCHAR(NVL(gcdd.user_idea, ' '))
            ELSE to_nchar('Không có ý ki?n')
        END AS USER_IDEA,
        CASE 
            WHEN gcdd.STATUS_APPROVAL = 'DONG_Y' THEN '??ng ý' 
            WHEN gcdd.STATUS_APPROVAL = 'TU_CHOI' THEN 'Không ??ng ý'
            WHEN gcdd.STATUS_APPROVAL = 'CHO_PHE_DUYET' THEN 'Ch? phê duy?t'
            ELSE 'Ch? phê duy?t' 
        END AS STATUS_APPROVAL,
        TO_CHAR(SYSDATE, 'YYYY-MM-DD') AS ngay_bo_sung
    FROM 
        GNCN_CA_DISBURSEMENT gcd
    LEFT JOIN 
        GNCN_CA_DISBURSEMENT_DOCUMENTS gcdd 
    ON 
        gcd.GNTD_CODE = gcdd.GNTD_CODE
    WHERE 
        gcd.GNTD_CODE = P_GNCN_CODE
        AND gcdd.ID = P_ID;
END SP_GNCN_GET_CA_DOCUMENT_DATA_BY_GNTD_CODE;

/
--------------------------------------------------------
--  DDL for Procedure SP_GNCN_GET_PAYMENT_DETAIL_DATA_BY_GNTD_CODE
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GNCN_GET_PAYMENT_DETAIL_DATA_BY_GNTD_CODE" (
    P_GNCN_CODE IN NVARCHAR2,
    P_PAGING_CURSOR OUT PAGINGPACKAGE.PAGING_CURSOR
) AS
BEGIN
    OPEN P_PAGING_CURSOR FOR
    SELECT DISTINCT
        gtpu.gntd_code,
        gtpd.trans_payment_id,
        gtpa.TRANSFER_ACCOUNT_NUM,
        gtpu.total_amount as Total_money,
        gtpa.currency,
        gtpu.currency as category_money,
        gtpu.ALLOW_INTERFACE,
        gtpa.RECEIVE_ACCOUNT_NUM,
        gtpa.RATE,
        gtpd.RESULT_INTERFACE,
        gtpa.REF_NUM_MBNT,
        gtpd.ACCOUNT_NUM,
        gtpd.ACCOUNT_NAME,
        gtpd.AMOUNT,
        gtpd.CONTENT,
        gtpa.FEE_ACCOUNT_NUM,
        gtpd.FEE,
        gtpd.REF_NUM_TRANSFER_FCC,
        gtpd.REF_NUM_FEE_FCC,
        gtpd.bank_code,
        gtpd.BANK_NAME as bank_name_en,
        CASE
            WHEN  gtpd.REF_NUM_TRANSFER_FCC IS NOT NULL AND gtpd.REF_NUM_FEE_FCC IS NOT NULL THEN NVL(gtpd.REF_NUM_TRANSFER_FCC, '') || ' - ' || NVL(gtpd.REF_NUM_FEE_FCC, '')
            WHEN gtpd.REF_NUM_TRANSFER_FCC IS NOT NULL THEN NVL(gtpd.REF_NUM_TRANSFER_FCC, '')
            WHEN gtpd.REF_NUM_FEE_FCC IS NOT NULL THEN NVL(gtpd.REF_NUM_FEE_FCC, '')
            ELSE gt.MESSAGE
        END AS TRANSFER_FEE_CODE,
        CASE 
            WHEN gtpu.currency = gtpa.currency THEN '1'
            ELSE '0'
        END AS visable_mbnt
    FROM 
        GNCN_TRANSACTION_PAYMENT gtpa
    LEFT JOIN 
        GNCN_TRANSACTION_PURPOSE gtpu ON gtpa.gntd_code = gtpu.gntd_code
    LEFT JOIN 
        GNCN_TRANSACTION_PAYMENT_DEAIL gtpd ON gtpa.gntd_code = gtpd.gncn_code
    LEFT JOIN 
        GNCN_TRANSACTION gt ON gtpa.gntd_code = gt.gntd_code
    WHERE 
        gtpa.gntd_code = P_GNCN_CODE; 
END SP_GNCN_GET_PAYMENT_DETAIL_DATA_BY_GNTD_CODE;

/
--------------------------------------------------------
--  DDL for Procedure SP_GNCN_GET_TRANSACTION_PURPOSE_DATA_BY_GNTD_CODE
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_GNCN_GET_TRANSACTION_PURPOSE_DATA_BY_GNTD_CODE" (
  P_GNCN_CODE IN VARCHAR2,
  P_TYPE_TRANSACTION IN VARCHAR2,
  P_PAGING_CURSOR OUT PAGINGPACKAGE.PAGING_CURSOR
) AS 
  v_record_gtp_count INTEGER;
  v_record_gt_count INTEGER;
  v_record_gta_count INTEGER;
BEGIN
  SELECT COUNT(*) INTO v_record_gtp_count
  FROM GNCN_TRANSACTION_PURPOSE gtp
  WHERE gtp.GNTD_CODE = P_GNCN_CODE;

  SELECT COUNT(*) INTO v_record_gt_count
  FROM GNCN_TRANSACTION gt
  WHERE gt.GNTD_CODE = P_GNCN_CODE;

  SELECT COUNT(*) INTO v_record_gta_count
  FROM GNCN_TRANSACTION_APPROVAL gta
  WHERE gta.GNTD_CODE = P_GNCN_CODE;

  IF v_record_gt_count > 0 AND v_record_gtp_count > 0 AND v_record_gta_count > 0 THEN OPEN P_PAGING_CURSOR FOR
    SELECT
      gtpa.GNTD_CODE,
      gtpa.contract_code,
      CASE
        WHEN P_TYPE_TRANSACTION = 'limit' THEN TO_NUMBER(JSON_VALUE(gt.limit_json_data, '$.limitValue'))
        WHEN P_TYPE_TRANSACTION = 'overdraft' THEN gtpa.total_money
        WHEN P_TYPE_TRANSACTION = 'loan' THEN gtpa.total_money
        ELSE gtpa.total_money
      END AS total_money,
      gtpa.comments,
      CASE
        WHEN gcais.CURRENCY IS NOT NULL THEN gcais.CURRENCY
        WHEN gt.currency IS NOT NULL THEN gt.currency
        WHEN gtpa.currency IS NOT NULL THEN gtpa.currency
        ELSE 'VND'
      END AS category_money,
      CASE
        WHEN gt.transaction_type1 = 'Giaingankhoanvay'
        or gt.transaction_type1 = 'Giainganthauchi' THEN gtpa.reason
        ELSE gcais.loan_purpose
      END AS reason,
      CASE
        WHEN P_TYPE_TRANSACTION = 'limit' THEN NULL
        ELSE gtpa.deadline
      END AS deadline,
      CASE
        WHEN P_TYPE_TRANSACTION = 'limit' THEN JSON_VALUE(gt.limit_json_data, '$.durationDisplay')
        WHEN P_TYPE_TRANSACTION = 'overdraft'
        AND gtpa.deadline IS NULL THEN ' '
        WHEN P_TYPE_TRANSACTION = 'loan'
        AND gtpa.deadline IS NULL THEN ' '
        ELSE gtpa.deadline_unit
      END AS deadline_unit,
      gtpa.is_approved,
      gtpa.group_id,
      CASE
        WHEN gtpa.is_approved = '??ng ý' THEN 'Không'
        ELSE grr.ERROR_DETAIL
      END AS ERROR_CODE,
      CASE
        WHEN gtpa.is_approved = '??ng ý' THEN 'Không'
        WHEN grr.ERROR_CODE = 'TRONG_YEU' THEN 'Tr?ng y?u'
        ELSE 'Không tr?ng y?u'
      END AS GROUP_CODE,
      gt.MESSAGE
    FROM
      (
        SELECT DISTINCT
          gtp.GNTD_CODE,
          gtp.total_amount as total_money,
          gtp.currency,
          gta.group_id,
          gta.comments,
          CASE
            WHEN gtp.contract_code = 'KHAC' THEN gtp.contract_code_text
            ELSE gtp.contract_code
          END AS contract_code,
          gtp.deadline,
          CASE
            WHEN gtp.DURATION_UNIT = 'day' THEN 'Ngày'
            WHEN gtp.DURATION_UNIT = 'month' THEN 'Tháng'
            WHEN gtp.DURATION_UNIT = 'year' THEN 'N?m'
            ELSE 'Tháng'
          END AS deadline_unit,
          gtp.reason,
          CASE
            WHEN gta.is_approved = 1 THEN '??ng ý'
            ELSE 'Không ??ng ý'
          END AS is_approved
        FROM
          GNCN_TRANSACTION_PURPOSE gtp
          LEFT JOIN (SELECT *
                        FROM GNCN_TRANSACTION_APPROVAL
                        WHERE GNTD_CODE = P_GNCN_CODE
                        ORDER BY CREATED_DATE DESC
                        FETCH FIRST 1 ROW ONLY) gta ON gtp.GNTD_CODE = gta.GNTD_CODE
        WHERE
          gtp.GNTD_CODE = P_GNCN_CODE
      ) gtpa
      LEFT JOIN (SELECT * FROM GNCN_REASON_REFUSE R
                    WHERE R.TRANS_APPROVAL_ID IN 
                    (SELECT A.ID FROM GNCN_TRANSACTION_APPROVAL A WHERE A.GNTD_CODE = P_GNCN_CODE 
                    ORDER BY A.CREATED_DATE DESC FETCH FIRST 1 ROW ONLY)) grr ON gtpa.GNTD_CODE = grr.GNTD_CODE
      LEFT JOIN GNCN_TRANSACTION gt ON gtpa.GNTD_CODE = gt.GNTD_CODE
      LEFT JOIN GNCN_CREDIT_APPROVAL_INFO_SYNC gcais ON gt.pdtd_code = gcais.pdtd_code
    WHERE
      gtpa.GNTD_CODE = P_GNCN_CODE;
  ELSIF v_record_gt_count > 0 AND v_record_gta_count > 0 THEN OPEN P_PAGING_CURSOR FOR
    SELECT
      P_GNCN_CODE AS GNTD_CODE,
      CASE
        WHEN P_TYPE_TRANSACTION = 'limit' THEN JSON_VALUE(gt.limit_json_data, '$.limitContractCode')
        ELSE ' '
      END AS contract_code,
      CASE
        WHEN P_TYPE_TRANSACTION = 'limit' THEN TO_NUMBER(JSON_VALUE(gt.limit_json_data, '$.limitValue'))
        WHEN P_TYPE_TRANSACTION = 'overdraft' THEN gt.approval_total_amount
        WHEN P_TYPE_TRANSACTION = 'loan' THEN gt.approval_total_amount
        ELSE gt.approval_total_amount
      END AS total_money,
      gta.comments,
      CASE
        WHEN gcais.CURRENCY IS NOT NULL THEN gcais.CURRENCY
        WHEN gt.currency IS NOT NULL THEN gt.currency
        ELSE 'VND'
      END AS category_money,
      CASE
        WHEN gt.transaction_type1 = 'Giaingankhoanvay'
        or gt.transaction_type1 = 'Giainganthauchi' THEN '-'
        ELSE gcais.loan_purpose
      END AS reason,
      ' ' AS deadline,
      CASE
        WHEN P_TYPE_TRANSACTION = 'limit' THEN JSON_VALUE(gt.limit_json_data, '$.durationDisplay')
        ELSE '-'
      END AS deadline_unit,
      CASE
        WHEN gta.is_approved = 1 THEN '??ng ý'
        ELSE 'Không ??ng ý'
      END AS is_approved,
      gta.group_id,
      CASE
        WHEN gta.is_approved = 1 THEN 'Không'
        ELSE grr.ERROR_DETAIL
      END AS ERROR_CODE,
      CASE
        WHEN gta.is_approved = 1 THEN 'Không'
        WHEN grr.ERROR_CODE = 'TRONG_YEU' THEN 'Tr?ng y?u'
        ELSE 'Không tr?ng y?u'
      END AS GROUP_CODE,
      gt.MESSAGE
    FROM
      GNCN_TRANSACTION GT
      INNER JOIN (SELECT *
                    FROM GNCN_TRANSACTION_APPROVAL
                    WHERE GNTD_CODE = P_GNCN_CODE
                    ORDER BY CREATED_DATE DESC
                    FETCH FIRST 1 ROW ONLY) GTA ON GT.gntd_code = GTA.gntd_code
      LEFT JOIN (SELECT * FROM GNCN_REASON_REFUSE R
                    WHERE R.TRANS_APPROVAL_ID IN 
                    (SELECT A.ID FROM GNCN_TRANSACTION_APPROVAL A WHERE A.GNTD_CODE = P_GNCN_CODE 
                    ORDER BY A.CREATED_DATE DESC FETCH FIRST 1 ROW ONLY)) grr ON gt.GNTD_CODE = grr.GNTD_CODE
      LEFT JOIN GNCN_CREDIT_APPROVAL_INFO_SYNC gcais ON gt.pdtd_code = gcais.pdtd_code
    WHERE
      gt.GNTD_CODE = P_GNCN_CODE;
  ELSIF v_record_gt_count > 0 AND v_record_gtp_count > 0 THEN OPEN P_PAGING_CURSOR FOR
    SELECT
      P_GNCN_CODE AS GNTD_CODE,
      CASE
        WHEN gtp.contract_code = 'KHAC' THEN gtp.contract_code_text
        ELSE gtp.contract_code
      END AS contract_code,
      gtp.total_amount as total_money,
      ' ' AS comments,
      CASE
        WHEN gt.currency IS NOT NULL THEN gt.currency
        WHEN gtp.currency IS NOT NULL THEN gtp.currency
        ELSE 'VND'
      END AS category_money,
      CASE
        WHEN gt.transaction_type1 = 'Giaingankhoanvay'
        or gt.transaction_type1 = 'Giainganthauchi' THEN gtp.reason
        ELSE gcais.loan_purpose
      END AS reason,
      gtp.deadline,
      CASE
        WHEN gtp.DURATION_UNIT = 'day' THEN 'Ngày'
        WHEN gtp.DURATION_UNIT = 'month' THEN 'Tháng'
        WHEN gtp.DURATION_UNIT = 'year' THEN 'N?m'
        ELSE 'Tháng'
      END AS deadline_unit,
      ' ' AS is_approved,
      ' ' AS group_id,
      ' ' AS GROUP_CODE,
      ' ' AS ERROR_CODE,
      gt.MESSAGE
    FROM
      GNCN_TRANSACTION GT
      INNER JOIN GNCN_TRANSACTION_PURPOSE GTP ON GT.gntd_code = GTP.gntd_code
      LEFT JOIN GNCN_CREDIT_APPROVAL_INFO_SYNC gcais ON gt.pdtd_code = gcais.pdtd_code
    WHERE
      gt.GNTD_CODE = P_GNCN_CODE;
  ELSIF v_record_gt_count > 0 AND P_TYPE_TRANSACTION = 'limit' THEN OPEN P_PAGING_CURSOR FOR
    SELECT
      GT.GNTD_CODE,
      JSON_VALUE(gt.limit_json_data, '$.limitContractCode') AS contract_code,
      TO_NUMBER(JSON_VALUE(gt.limit_json_data, '$.limitValue'))AS total_money,
      ' ' AS comments,
      CASE
        WHEN gcais.CURRENCY IS NOT NULL THEN gcais.CURRENCY
        WHEN gt.currency IS NOT NULL THEN gt.currency
        ELSE 'VND'
      END AS category_money,
      gcais.loan_purpose AS reason,
      ' ' AS deadline,
      JSON_VALUE(gt.limit_json_data, '$.durationDisplay') AS deadline_unit,
      ' ' AS is_approved,
      ' ' AS group_id,
      ' ' AS ERROR_CODE,
      ' ' AS GROUP_CODE,
      gt.MESSAGE
    FROM
      GNCN_TRANSACTION GT
      LEFT JOIN GNCN_CREDIT_APPROVAL_INFO_SYNC gcais ON gt.pdtd_code = gcais.pdtd_code
    WHERE
      gt.GNTD_CODE = P_GNCN_CODE;
  ELSIF v_record_gt_count > 0 THEN OPEN P_PAGING_CURSOR FOR
    SELECT
      ' ' AS contract_code,
      '-' AS total_money,
      ' ' AS comments,
      'VND' AS category_money,
      '-' AS reason,
      ' ' AS deadline,
      ' ' AS deadline_unit,
      '??ng ý' AS is_approved,
      ' ' AS group_id,
      ' ' AS GROUP_CODE,
      ' ' AS ERROR_CODE,
      NULL AS MESSAGE
    FROM
      GNCN_TRANSACTION gt
    WHERE
      gt.GNTD_CODE = P_GNCN_CODE;

  ELSE OPEN P_PAGING_CURSOR FOR
    SELECT
      ' ' AS contract_code,
      '-' AS total_money,
      ' ' AS comments,
      '-' AS category_money,
      '-' AS reason,
      '-' AS deadline,
      '-' AS deadline_unit,
      ' ' AS is_approved,
      ' ' AS group_id,
      ' ' AS GROUP_CODE,
      ' ' AS ERROR_CODE,
      NULL AS MESSAGE
    FROM
      GNCN_TRANSACTION gt
    WHERE
      gt.GNTD_CODE = P_GNCN_CODE;

  END IF;
END SP_GNCN_GET_TRANSACTION_PURPOSE_DATA_BY_GNTD_CODE;

