--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_IMPORT_TDTD_FROM_ECM" (
  P_PDTD_CODE IN VARCHAR2,
  P_BRANCH_CODE IN VARCHAR2,
  P_CUSTOMER_CODE IN VARCHAR2,
  P_CUSTOMER_NAME IN VARCHAR2,
  P_CREDIT_USER IN VARCHAR2,
  p_SOURCE_SYNC IN VARCHAR2,
  p_PRODUCT_CODE IN VARCHAR2,
  p_PRODUCT_NAME IN VARCHAR2,
  p_BANK_PRODUCT_NAME IN VARCHAR2,
  p_SUB_PRODUCT_NAME IN VARCHAR2,
  p_LOAN_PURPOSE IN VARCHAR2,
  p_LOAN_TYPE_TEXT IN VARCHAR2,
  p_VEHICLE_CLASS IN VARCHAR2,
  p_VEHICLE_CONDITION IN VARCHAR2,
  p_MANUFACTURE_YEAR IN VARCHAR2,
  p_WITHDRAWAL_TERM IN NUMBER,
  p_LOAN_PRODUCT_ATTACH IN VARCHAR2,
  p_LOAN_PRODUCT_ATTACH_DESC IN VARCHAR2,
  p_LOAN_AMOUNT IN NUMBER,
  p_LOAN_PERCENTAGE IN NUMBER,
  -- FLOAT
  p_LOAN_METHOD IN VARCHAR2,
  p_AMOUNT_NEEDED IN NUMBER,
  p_AMOUNT_OWNED IN NUMBER,
  p_LOAN_TERM IN NUMBER,
  p_GRACE_PERIOD IN NUMBER,
  p_COMMISSION_FEE IN NUMBER,
  p_PRINCIPAL_REPAYMENT_METHOD IN VARCHAR2,
  p_INTEREST_REPAYMENT_METHOD IN VARCHAR2,
  p_ISSUE_DATE IN VARCHAR2,
  p_CURRENCY IN VARCHAR2,
  p_LOAN_INTEREST_RATE IN VARCHAR2,
  p_APPROVAL_LEVEL IN VARCHAR2,
  p_APPROVAL_DATE IN VARCHAR2,
  p_APPROVAL_RESULT IN VARCHAR2,
  p_APPROVAL_COMMENTS IN NVARCHAR2,
  p_ISSUED_BY IN NVARCHAR2,
  p_DOC_ID IN VARCHAR2,
  p_ADDRESS IN VARCHAR2,
  p_MODIFIED_DATE IN TIMESTAMP,
  p_FINANC_INFO IN VARCHAR2,
  p_TRUONG_NHOM IN VARCHAR2,
  p_SYS_NAME IN VARCHAR2,
  p_LOAN_FLOW IN VARCHAR2,
  p_CVKH IN VARCHAR2,
  p_EMAI_LQLTT IN VARCHAR2,
  p_TSBD_TYPE IN VARCHAR2,
  p_CUS_TYPE IN VARCHAR2
) IS 
  v_count NUMBER;
  v_count2 NUMBER;
  cus_id NUMBER;
  V_APPROVAL_DATE DATE DEFAULT NULL;
  V_ISSUE_DATE DATE DEFAULT NULL;

BEGIN

  IF (p_APPROVAL_DATE IS NOT NULL) THEN 
