--------------------------------------------------------
--  DDL for Procedure SP_INSERT_OR_UPDATE_GNCN_CA_DISBURSEMENT_DOCUMENTS
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_INSERT_OR_UPDATE_GNCN_CA_DISBURSEMENT_DOCUMENTS" (
    P_JSON_ARR      IN CLOB,
    P_GNTD_CODE     IN VARCHAR,
    P_PDTD_CODE     IN VARCHAR,
    P_USER          IN VARCHAR,
    P_MESS          OUT VARCHAR2  
) AS 
    json_arr JSON_ARRAY_T;
    json_obj JSON_OBJECT_T;
    countDocs                           NUMBER;
    currentDate                         DATE := SYSDATE;
    p_id                                NUMBER;
    p_completed_after_disbursement_id   NUMBER;
    p_doc_code                          VARCHAR(200);
    p_doc_name                          VARCHAR(500);
    p_status                            VARCHAR(100);
    p_doc_category                      NUMBER;
    p_deadline                          TIMESTAMP;
    p_frequency                         NUMBER;
    p_frequency_unit                    VARCHAR(50);
    p_frequency_displaytext             VARCHAR(100);
    p_status_doc                        VARCHAR(100);
    p_deadline_ext                      TIMESTAMP;
    p_group_doc_name                    VARCHAR(200);
    p_user_idea                         VARCHAR(100);
    p_approval_idea                     VARCHAR(2000);
    p_ecm_folder                        VARCHAR(500);
BEGIN
    SAVEPOINT SP_UPDATE_DATA;
    json_arr := json_array_t(P_JSON_ARR);
    FOR i IN 0..json_arr.get_size - 1
    LOOP
        json_obj := TREAT( json_arr.get ( i ) AS JSON_OBJECT_T );
        p_id := json_obj.get_Number('id');
        p_completed_after_disbursement_id := json_obj.get_Number('completedAfterDisbursementId');
        IF json_obj.get_String('docCode') IS NULL THEN 
            p_doc_code := P_GNTD_CODE || i || '1';
        ELSE 
            p_doc_code := json_obj.get_String('docCode');
        END IF;
        p_doc_name := json_obj.get_String('docName');
        IF json_obj.get_String('status') IS NULL THEN 
            p_status := 'HSSGN_CHO_BO_SUNG';
        ELSE 
            p_status := json_obj.get_String('status');
        END IF;
        IF json_obj.get_Number('docCategory') IS NULL THEN 
            p_doc_category := 1;
        ELSE 
            p_doc_category := json_obj.get_Number('docCategory');
        END IF;
--        p_deadline := json_obj.get_Date('deadline');
        p_deadline := TO_DATE(SUBSTR(json_obj.get_String('deadline'), 1, 10), 'YYYY-MM-DD');
        p_frequency := json_obj.get_String('frequency');
        p_frequency_unit := json_obj.get_String('frequencyUnit');
        p_frequency_displaytext := json_obj.get_String('frequencyDisplaytext');
        IF json_obj.get_String('statusDoc') IS NULL THEN 
            p_status_doc := 'CHUA_BO_SUNG';
        ELSE 
            p_status_doc := json_obj.get_String('statusDoc');
        END IF;
        p_deadline_ext := json_obj.get_Date('deadlineExt');
        p_group_doc_name := json_obj.get_String('groupDocCategory');
        p_user_idea := json_obj.get_String('userIdea');
        p_approval_idea := json_obj.get_String('approvalIdea');
        p_ecm_folder := json_obj.get_String('storeFolder');
        SELECT COUNT(*) INTO countDocs FROM GNCN_CA_DISBURSEMENT_DOCUMENTS WHERE ID = p_id;
        IF (P_ID IS NULL OR P_ID <= 0 OR countDocs < 1) THEN   
            INSERT INTO GNCN_CA_DISBURSEMENT_DOCUMENTS (
                gntd_code,
                completed_after_disbursement_id,
                doc_code,
                doc_name,
                status,
                doc_category,
                deadline,
                frequency,
                frequency_unit,
                frequency_displaytext,
                created_by,
                created_date,
                pdtd_code,
                status_doc,
                deadline_ext,
                group_doc_name,
                user_idea ,
                ecm_folder,
                approval_idea
            ) VALUES (
                P_GNTD_CODE,
                p_completed_after_disbursement_id,
                p_doc_code,
                p_doc_name,
                p_status,
                p_doc_category,
                p_deadline,
                p_frequency,
                p_frequency_unit,
                p_frequency_displaytext,
                p_user,
                currentDate,
                p_pdtd_code,
                p_status_doc,
                p_deadline_ext,
                p_group_doc_name,
                p_user_idea,
                p_ecm_folder,
                p_approval_idea
            );
        ELSE 
            UPDATE GNCN_CA_DISBURSEMENT_DOCUMENTS
            SET DOC_CODE = P_DOC_CODE,  
                DOC_NAME = P_DOC_NAME,
                completed_after_disbursement_id = P_completed_after_disbursement_id,
                STATUS = P_STATUS, 
                doc_category = p_doc_category,
                DEADLINE = P_DEADLINE,
                FREQUENCY = P_FREQUENCY,
                FREQUENCY_UNIT = P_FREQUENCY_UNIT,
                FREQUENCY_DISPLAYTEXT = P_FREQUENCY_DISPLAYTEXT,
                MODIFIED_DATE = currentDate,
                MODIFIED_BY = P_USER,
                status_doc = P_status_doc,
                deadline_ext = p_deadline_ext,
                group_doc_name = p_group_doc_name,
                user_idea = p_user_idea,
                approval_idea = p_approval_idea
            WHERE ID = P_ID;
        END IF;
    END LOOP;
    P_MESS := '1';
EXCEPTION
   WHEN OTHERS 
   THEN ROLLBACK  TO SP_UPDATE_DATA;
    P_MESS := SUBSTR(SQLERRM, 1, 500);
END SP_INSERT_OR_UPDATE_GNCN_CA_DISBURSEMENT_DOCUMENTS;

/
--------------------------------------------------------
--  DDL for Procedure SP_JOB_LAY_DANH_SACH_HK
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_JOB_LAY_DANH_SACH_HK" (
  SYS_CURSOR OUT SYS_REFCURSOR
) IS
    ---------------------------------------------------------------------
    -- 1. Khai báo các ki?u d? li?u record và table ?? l?u t?m
    ---------------------------------------------------------------------
    TYPE t_sample_rec IS RECORD (
        gntd_code         VARCHAR2(50),
        ptdt_code         VARCHAR2(50),
        branch_code       VARCHAR2(50),
        status            VARCHAR2(50),
        transaction_flow  VARCHAR2(50),
        transaction_type1 VARCHAR2(50),
        transaction_type2 VARCHAR2(50),
        transaction_type3 VARCHAR2(50),
        approval_by       VARCHAR2(100),
        approval_date     DATE,
        pa_type_code      VARCHAR2(50),
        customer_code     VARCHAR2(50),
        customer_name     VARCHAR2(250),
        process_group     VARCHAR2(50),
        product_name      VARCHAR2(500),
        amount            NUMBER,
        pa_rate           NUMBER,
        pa_day            NUMBER
    );

    TYPE t_sample_tab IS TABLE OF t_sample_rec;     -- table ch?a danh sách giao d?ch m?u

    TYPE t_cand_rec IS RECORD (                     -- record cho user ?ng viên
        user_name     VARCHAR2(100),
        factor        NUMBER,
        priority      NUMBER,
        approve_level VARCHAR2(100)
    );
    TYPE t_cand_tab IS TABLE OF t_cand_rec;         -- table ch?a danh sách user ?ng viên

    TYPE t_result_rec IS RECORD (                   -- record cho k?t qu? x? lý
        gntd_code VARCHAR2(50),
        msg       VARCHAR2(4000)
    );
    TYPE t_result_tab IS TABLE OF t_result_rec;
    v_results  t_result_tab := t_result_tab();      -- k?t qu? tr? v? (local)

    ---------------------------------------------------------------------
    -- 2. Khai báo bi?n s? d?ng trong x? lý
    ---------------------------------------------------------------------
    v_sampled  t_sample_tab;        -- danh sách giao d?ch ???c ch?n ?? h?u ki?m
    v_cands    t_cand_tab;          -- danh sách user ?ng viên cho 1 giao d?ch
    v_row      t_sample_rec;        -- bi?n t?m l?u 1 record giao d?ch trong vòng l?p

    
    TYPE t_workload IS TABLE OF NUMBER INDEX BY VARCHAR2(100);  -- map workload theo user
    v_workload t_workload;          -- workload hi?n t?i c?a t?ng user

    v_coeff_trans   NUMBER := 1;    -- h? s? giao d?ch (mapping t? b?ng config)
    v_pa_expiry     DATE;           -- h?n h?u ki?m
    v_user_assign   VARCHAR2(100);  -- user ???c phân công h?u ki?m

    v_sql CLOB := EMPTY_CLOB();     -- chu?i SQL ??ng ?? tr? k?t qu? ra cursor

BEGIN

    SELECT *
    BULK COLLECT INTO v_sampled
    FROM (
        WITH latest_hk AS ( SELECT gntd_code FROM HKCN_TRANSACTION
            WHERE CREATED_DATE >= TRUNC(SYSDATE) - 4 AND CREATED_DATE < TRUNC(SYSDATE) + 1 ),
        
        trans_data AS (
            SELECT DISTINCT
                trans.GNTD_CODE,
                trans.PDTD_CODE,
                trans.BRANCH_CODE,
                trans.STATUS,
                trans.TRANSACTION_FLOW,
                trans.TRANSACTION_TYPE1,
                trans.TRANSACTION_TYPE2,
                trans.TRANSACTION_TYPE3,
                trans.APPROVAL_BY,
                trans.APPROVAL_DATE,
                htc.PA_TYPE_CODE,
                trans.CUSTOMER_CODE,
                trans.CUSTOMER_NAME,
                trans.PROCESS_GROUP,
                trans.PRODUCT_NAME,
                CASE
                   WHEN trans.TRANSACTION_TYPE1 IN ('Giainganthauchi','Giaingankhoanvay') THEN gtp.TOTAL_AMOUNT
                   WHEN trans.TRANSACTION_TYPE1 = 'Khoitaohanmuc' and trans.LIMIT_JSON_DATA is not null THEN TO_NUMBER(JSON_VALUE(trans.LIMIT_JSON_DATA,'$.limitValue'))
                   ELSE 0
                END AS AMOUNT
            FROM GNCN_TRANSACTION trans
            LEFT JOIN GNCN_TRANSACTION_PURPOSE gtp ON trans.GNTD_CODE = gtp.GNTD_CODE
            INNER JOIN HKCN_TRANSACTION_CONFIG htc
                ON htc.GROUP_PROCESS_CODE = trans.TRANSACTION_FLOW
               AND htc.TRANS_LEVEL_CODE_1 = trans.TRANSACTION_TYPE1
               AND htc.TRANS_LEVEL_CODE_2 = trans.TRANSACTION_TYPE2
               AND htc.TRANS_LEVEL_CODE_3 = trans.TRANSACTION_TYPE3
               AND INSTR(',' || htc.PRODUCT_CODE || ',', ',' || trans.PRODUCT_NAME || ',') > 0
               AND htc.USE_STATUS = 1
            WHERE trans.STATUS IN ('GNCN_LOI_CHUYEN_TIEN','GNCN_HOAN_THANH','GNCN_HOAN_TAT_KHOAN_VAY')
--            WHERE trans.STATUS IN ('GNCN_LOI_CHUYEN_TIEN123')
--                AND trans.APPROVAL_DATE >= TRUNC(SYSDATE - 3)
--                AND trans.APPROVAL_DATE < TRUNC(SYSDATE)

--                AND TRUNC(trans.APPROVAL_DATE) = TRUNC(SYSDATE)-- uat ch?y luôn ngày hôm nay


                --LIVE l?y 1 ngày tr??c ?ó
--                 AND trans.APPROVAL_DATE >= TRUNC(SYSDATE - 1)

                --LIVE l?y tu?n 2 l?n
                AND trans.APPROVAL_DATE >= CASE
                    WHEN TO_CHAR(SYSDATE, 'DY', 'NLS_DATE_LANGUAGE=ENGLISH') = 'THU' THEN TRUNC(SYSDATE) - 4
                    WHEN TO_CHAR(SYSDATE, 'DY', 'NLS_DATE_LANGUAGE=ENGLISH') = 'SUN' THEN TRUNC(SYSDATE) - 3
                END
                
                AND trans.APPROVAL_DATE < TRUNC(SYSDATE)

                AND trans.GNTD_CODE NOT IN (SELECT gntd_code FROM latest_hk)
        ),
        
        -- danh sách t? l? & s? ngày h?u ki?m theo user
        -- ?u tiên l?y c?u hình ??c bi?t, n?u không có thì l?y c?u hình chu?n
         pa_rate_list AS (
             SELECT u.login_user,
                    u.branch_code,
                    u.pa_type_code,
                    NVL(
                      (SELECT spc.pa_rate
                         FROM HKCN_RATE_SPECIAL_CONFIG spc
                        WHERE spc.USE_STATUS = 1
                          AND UPPER(NVL(spc.LOGIN_USER,' ')) = UPPER(NVL(u.login_user,' '))
                          AND UPPER(NVL(spc.BRANCH_CODE,' ')) = UPPER(NVL(u.branch_code,' '))
                          AND UPPER(NVL(spc.PA_TYPE_CODE,' ')) = UPPER(NVL(u.pa_type_code,' '))
                          AND ROWNUM = 1
                      ),
                      (SELECT rsc.pa_rate
                         FROM HKCN_RATE_STANDARD_CONFIG rsc
                         JOIN GNCN_EMPLOYEE_PROCESS_CONFIG epc
                           ON epc.POSITION_CODE = rsc.JOB_TITLE
                        WHERE rsc.USE_STATUS = 1
                          AND epc.USE_STATUS = 1
                          AND UPPER(NVL(rsc.PA_TYPE_CODE,' ')) = UPPER(NVL(u.pa_type_code,' '))
                        AND (
                        INSTR(',' || REPLACE(NVL(epc.BRANCHS,''),' ','') || ',', ',ALL_BRANCH,') > 0
                        OR INSTR(',' || REPLACE(NVL(epc.BRANCHS,''),' ','') || ',', ',' || REPLACE(NVL(u.branch_code,''),' ','') || ',') > 0
                    )
                          AND UPPER(epc.USER_NAME) = UPPER(NVL(u.login_user,' '))
                          AND ROWNUM = 1
                      )
                    ) AS pa_rate,
                    NVL(
                      (SELECT spc.pa_day
                         FROM HKCN_RATE_SPECIAL_CONFIG spc
                        WHERE spc.USE_STATUS = 1
                          AND UPPER(NVL(spc.LOGIN_USER,' ')) = UPPER(NVL(u.login_user,' '))
                          AND UPPER(NVL(spc.BRANCH_CODE,' ')) = UPPER(NVL(u.branch_code,' '))
                          AND UPPER(NVL(spc.PA_TYPE_CODE,' ')) = UPPER(NVL(u.pa_type_code,' '))
                          AND ROWNUM = 1
                      ),
                      (SELECT rsc.pa_day
                         FROM HKCN_RATE_STANDARD_CONFIG rsc
                         JOIN GNCN_EMPLOYEE_PROCESS_CONFIG epc
                           ON epc.POSITION_CODE = rsc.JOB_TITLE
                        WHERE rsc.USE_STATUS = 1
                          AND epc.USE_STATUS = 1
                          AND UPPER(NVL(rsc.PA_TYPE_CODE,' ')) = UPPER(NVL(u.pa_type_code,' '))
                        AND (
                            INSTR(',' || REPLACE(NVL(epc.BRANCHS,''),' ','') || ',', ',ALL_BRANCH,') > 0
                            OR INSTR(',' || REPLACE(NVL(epc.BRANCHS,''),' ','') || ',', ',' || REPLACE(NVL(u.branch_code,''),' ','') || ',') > 0
                        )
                          AND UPPER(epc.USER_NAME) = UPPER(NVL(u.login_user,' '))
                          AND ROWNUM = 1
                      )
                    ) AS pa_day
             FROM (
                 SELECT DISTINCT APPROVAL_BY AS login_user,
                                 BRANCH_CODE AS branch_code,
                                 PA_TYPE_CODE AS pa_type_code
                 FROM trans_data
             ) u
         ),

        -- áp d?ng t? l? ch?n h?u ki?m (pa_rate) b?ng random
        sampled_pre AS (
            SELECT t.*,
                   NVL(p.pa_rate,0) AS pa_rate,
                   NVL(p.pa_day,0)  AS pa_day,
                   CEIL(COUNT(*) OVER (PARTITION BY t.APPROVAL_BY, t.BRANCH_CODE, t.PA_TYPE_CODE) * NVL(p.pa_rate,0) / 100) AS sample_size,
                   ROW_NUMBER() OVER (PARTITION BY t.APPROVAL_BY, t.BRANCH_CODE, t.PA_TYPE_CODE ORDER BY DBMS_RANDOM.VALUE) AS rn
            FROM trans_data t
            LEFT JOIN pa_rate_list p
               ON UPPER(t.APPROVAL_BY) = UPPER(p.login_user)
              AND UPPER(t.BRANCH_CODE) = UPPER(p.branch_code)
              AND UPPER(t.PA_TYPE_CODE) = UPPER(p.pa_type_code)
        )
    
        
        -- ch? l?y s? l??ng giao d?ch theo sample_size
        SELECT GNTD_CODE, PDTD_CODE, BRANCH_CODE, STATUS, TRANSACTION_FLOW,
               TRANSACTION_TYPE1, TRANSACTION_TYPE2, TRANSACTION_TYPE3,
               APPROVAL_BY, APPROVAL_DATE, PA_TYPE_CODE, CUSTOMER_CODE, CUSTOMER_NAME,
               PROCESS_GROUP, PRODUCT_NAME, AMOUNT, pa_rate, pa_day
        FROM sampled_pre
        WHERE rn <= sample_size
    );
    

    ---------------------------------------------------------------------
    -- 4. Vòng l?p qua t?ng giao d?ch ???c ch?n (v_sampled)
    --    X? lý phân công user, tính h?n h?u ki?m, insert k?t qu?
    ---------------------------------------------------------------------
     DBMS_OUTPUT.PUT_LINE('================ START JOB ================');
     DBMS_OUTPUT.PUT_LINE('v_sampled.COUNT = ' || NVL(v_sampled.COUNT,0));

    FOR i IN 1 .. NVL(v_sampled.COUNT,0) LOOP
        v_row := v_sampled(i);

        -- reset
        v_coeff_trans := 1;
        v_user_assign := NULL;
        v_pa_expiry   := NULL;

        -- (A) l?y h? s? giao d?ch t? b?ng mapping C?u hình mapping lo?i giao d?ch gi?i ngân (n?u không có thì m?c ??nh = 1)
        BEGIN
            SELECT NVL(m.coefficient,1)
            INTO v_coeff_trans
            FROM GNCN_MAPPING_CONFIG m
            WHERE m.use_status = 1
              AND m.trans_level_code_1 = v_row.transaction_type1
              AND m.trans_level_code_2 = v_row.transaction_type2
              AND m.trans_level_code_3 = v_row.transaction_type3
              AND m.product_name = v_row.product_name
              AND ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                v_coeff_trans := 1;
        END;

        -- (B) tìm danh sách user ?ng viên có th? nh?n giao d?ch này
        -- g?n ch?c danh + th?m quy?n phê duy?t + nhân s? lu?ng t?p trung + ch?c danh + nhóm lu?ng t?p trung - DISABLE_USER
        v_cands := t_cand_tab();
        BEGIN
            SELECT emp.user_name,
                   NVL(pos.factor,1) AS factor,
                   NVL(roleappr.priority, 9999) AS priority,
                   roleappr.approve_level AS approve_level
            BULK COLLECT INTO v_cands
            FROM GNCN_EMPLOYEE_PROCESS_CONFIG emp
            JOIN GNCN_ROLE_APPROVE_CONFIG roleappr
              ON roleappr.use_status = 1
             AND emp.use_status = 1
             AND roleappr.trans_level_code_1 = v_row.transaction_type1
             AND roleappr.trans_level_code_2 = v_row.transaction_type2
             AND roleappr.trans_level_code_3 = v_row.transaction_type3
             AND roleappr.product_name       = v_row.product_name
             AND roleappr.approve_level      = emp.position_code
             
            JOIN GNCN_USER_GROUP_CONFIG ugc
              ON ugc.user_process = emp.user_name
             AND ugc.use_status = 1
             AND UPPER(NVL(ugc.branch_code,' ')) = UPPER(NVL(v_row.branch_code,' '))
             AND ugc.group_process IN (
                 SELECT gpgc.code
                 FROM GNCN_PROCESSING_GROUP_CONFIG gpgc
                 WHERE gpgc.use_status = 1
                   AND gpgc.is_audit_later = 'Y'
             )
            LEFT JOIN GNCN_POSITION_CONFIG pos
              ON pos.code = emp.position_code
             AND pos.use_status = 1
            --  AND pos.tran_flow = v_row.transaction_flow -- vì th?ng này gây factor luôn NVL
            WHERE (v_row.amount BETWEEN NVL(roleappr.money_from * 1000000, 0) AND NVL(roleappr.money_to * 1000000, 0))
              AND NOT EXISTS (
                  SELECT 1 FROM GNCN_DISABLE_USER_CONFIG dis
                  WHERE dis.use_status = 1
                    AND UPPER(dis.login_user) = UPPER(emp.user_name)
                    AND TRUNC(SYSDATE) BETWEEN TRUNC(NVL(dis.begin_date, SYSDATE))
                                         AND TRUNC(NVL(dis.finish_date, SYSDATE + 1))
              );
        EXCEPTION
            WHEN OTHERS THEN
                -- Ghi l?i vào k?t qu? tr? ra
                v_results.EXTEND;
                v_results(v_results.COUNT).gntd_code := v_row.gntd_code;
                v_results(v_results.COUNT).msg := 'Error fetching candidates: ' || SQLERRM;

                -- v?n ?? v_cands r?ng ?? ti?p t?c x? lý
                v_cands := t_cand_tab();
        END;

        -- (C) Ch?n user t? danh sách ?ng viên (phân công chi ti?t)
        IF v_cands.COUNT > 0 THEN
            DECLARE
                v_best_metric BINARY_DOUBLE := NULL;
                TYPE t_idx_tab IS TABLE OF PLS_INTEGER;
                v_best_idxs t_idx_tab := t_idx_tab();
                v_metric BINARY_DOUBLE;
                v_min_priority BINARY_DOUBLE;
                v_final_idxs   t_idx_tab := t_idx_tab();
                v_final_idx PLS_INTEGER;
                v_user_factor NUMBER;
            BEGIN
                    -- DBMS_OUTPUT.PUT_LINE('v_workload: ' || v_workload.COUNT);
                    -- DBMS_OUTPUT.PUT_LINE('v_cands: ' || v_cands.COUNT);
                    -- DBMS_OUTPUT.PUT_LINE('v_cands user_name: ' || v_cands(v_best_idxs(1)).user_name);
                
                -- Step 1: ch?n theo workload + v_coeff_trans * factor(h? s? ch?c danh)
                -- và l?y nhóm nh? nh?t
                FOR i2 IN 1..v_cands.COUNT LOOP 
                        -- DBMS_OUTPUT.PUT_LINE('v_cands user_name: ' || v_cands(i2).user_name);
                        -- DBMS_OUTPUT.PUT_LINE('v_cands factor: ' || v_cands(i2).factor);
                    IF v_workload.EXISTS(v_cands(i2).user_name) THEN
                        v_metric := ROUND(v_workload(v_cands(i2).user_name)
                                    + v_coeff_trans * v_cands(i2).factor, 2);
                    ELSE
                        v_metric := ROUND(0 + v_coeff_trans * v_cands(i2).factor, 2);
                    END IF;
                    
                    -- DBMS_OUTPUT.PUT_LINE('v_metric: ' || v_metric);-- check v_metric

                    IF v_best_metric IS NULL OR v_metric < v_best_metric THEN
                        v_best_metric := v_metric;
                        -- reset list
                        v_best_idxs.DELETE;
                        v_best_idxs.EXTEND;
                        v_best_idxs(1) := i2;
                        
                    ELSIF v_metric = v_best_metric THEN
                        v_best_idxs.EXTEND;
                        v_best_idxs(v_best_idxs.COUNT) := i2;
                    END IF;
                END LOOP;
                -- DBMS_OUTPUT.PUT_LINE('v_best_idxs: ' || v_best_idxs.COUNT);
                -- DBMS_OUTPUT.PUT_LINE('v_metric: ' || v_metric);
                -- N?u ch? có 1 user -> gán luôn cho t?i ?u
                IF v_best_idxs.COUNT = 1 THEN
                    v_user_assign := v_cands(v_best_idxs(1)).user_name;
                    v_user_factor := v_cands(v_best_idxs(1)).factor;
                    -- DBMS_OUTPUT.PUT_LINE('v_user_assign: ' || v_user_assign);
                    -- DBMS_OUTPUT.PUT_LINE('v_user_factor: ' || v_user_factor);
                    
                    IF v_workload.EXISTS(v_user_assign) THEN
                        v_workload(v_user_assign) := ROUND(v_workload(v_user_assign) + (v_coeff_trans * v_user_factor), 2);
                    ELSE
                        v_workload(v_user_assign) := ROUND(v_coeff_trans * v_user_factor, 2);
                    END IF;
                    
                    -- DBMS_OUTPUT.PUT_LINE('Step 1 v_workload(v_user_assign): ' || v_workload(v_user_assign));
                ELSE
                    -- Step 2: ch?n theo priority nh? nh?t
                    v_min_priority := NULL;
                    FOR k IN 1 .. v_best_idxs.COUNT LOOP
                        IF v_min_priority IS NULL OR v_cands(v_best_idxs(k)).priority < v_min_priority THEN
                            v_min_priority := v_cands(v_best_idxs(k)).priority;
                        END IF;
                    END LOOP;
                    -- Step 3: gom danh sách final theo priority
                    FOR k IN 1 .. v_best_idxs.COUNT LOOP
                        IF v_cands(v_best_idxs(k)).priority = v_min_priority THEN
                            v_final_idxs.EXTEND;
                            v_final_idxs(v_final_idxs.COUNT) := v_best_idxs(k);
                        END IF;
                    END LOOP;
                    -- Step 4: random N?u còn nhi?u h?n 1 user
                    IF v_final_idxs.COUNT > 0 THEN
                        v_final_idx := v_final_idxs(
                            TRUNC(DBMS_RANDOM.VALUE(1, v_final_idxs.COUNT + 1))
                        );
                        v_user_assign := v_cands(v_final_idx).user_name;
                        v_user_factor := v_cands(v_final_idx).factor;

                        IF v_workload.EXISTS(v_user_assign) THEN
                            v_workload(v_user_assign) := ROUND(v_workload(v_user_assign) + (v_coeff_trans * v_user_factor) , 2);
                        ELSE
                            v_workload(v_user_assign) := ROUND(v_coeff_trans * v_user_factor, 2);
                        END IF;

                        -- DBMS_OUTPUT.PUT_LINE('Step 4 v_workload(v_user_assign): ' || v_workload(v_user_assign));
                    ELSE
                        v_user_assign := NULL;
                    END IF;
                END IF;
            EXCEPTION
                WHEN OTHERS THEN
                    v_user_assign := NULL;
                    DBMS_OUTPUT.PUT_LINE('Error: ' || SQLERRM);
            END;
        ELSE
            v_user_assign := NULL;
        END IF;

        -- (D) tính h?n h?u ki?m d?a trên approval_date + pa_day
        IF v_row.pa_day IS NOT NULL AND v_row.pa_day > 0 THEN
            IF v_row.approval_date IS NOT NULL THEN
                v_pa_expiry := TRUNC(v_row.approval_date) + v_row.pa_day;
            ELSE
                v_pa_expiry := TRUNC(SYSDATE) + v_row.pa_day;
            END IF;
        ELSE
            v_pa_expiry := NULL;
        END IF;

        -- (E) Insert k?t qu? vào b?ng HKCN_TRANSACTION (n?u ch?a t?n t?i)
        BEGIN
             INSERT INTO HKCN_TRANSACTION (
                 GNTD_CODE, PDTD_CODE, TRANS_LEVEL_CODE_1, BRANCH_CODE, CUSTOMER_CODE,
                 CUSTOMER_NAME, USER_ASSIGN, USER_PA, PA_EXPIRY_DATE, PA_STATUS,
                 COMMENT_TEXT, CREATED_BY, CREATED_DATE, UPDATED_BY, UPDATED_DATE,
                 PA_RESULT, SUBMIT_DATE, TRANSACTION_FLOW, GN_APPROVAL_BY, GN_APPROVAL_DATE,
                 TRANSACTION_TYPE2, TRANSACTION_TYPE3, DURATION, DURATION_UNIT, GROUP_PROCESS, PA_RATE, AMOUNT
             )
             SELECT v_row.gntd_code,
                    v_row.ptdt_code,
                    v_row.transaction_type1,
                    v_row.branch_code,
                    v_row.customer_code,
                    v_row.customer_name,
                    v_user_assign,
                    NULL,
                    v_pa_expiry,
                    'CHUA_HAU_KIEM',
                    NULL,
                    'SYSTEM',
                    SYSDATE,
                    'SYSTEM',
                    SYSDATE,
                    NULL,
                    NULL,
                    v_row.transaction_flow,
                    v_row.approval_by,
                    v_row.approval_date,
                    v_row.transaction_type2,
                    v_row.transaction_type3,
                    v_row.pa_day,
                    'DAY',
                    v_row.process_group,
                    v_row.pa_rate,
                    v_row.amount
             FROM DUAL
             WHERE NOT EXISTS (
                 SELECT 1 FROM HKCN_TRANSACTION hk WHERE hk.GNTD_CODE = v_row.gntd_code
             );

            -- ghi k?t qu? thành công
            IF v_user_assign IS NOT NULL THEN
                v_results.EXTEND;
                v_results(v_results.COUNT).gntd_code := v_row.gntd_code;
                v_results(v_results.COUNT).msg := 'Success (' || v_user_assign || ')';
            ELSE
                v_results.EXTEND;
                v_results(v_results.COUNT).gntd_code := v_row.gntd_code;
                v_results(v_results.COUNT).msg := 'Success (no user assigned)' || NVL(v_results(v_results.COUNT).msg,'');
            END IF;

        EXCEPTION
            WHEN OTHERS THEN
                v_results.EXTEND;
                v_results(v_results.COUNT).gntd_code := v_row.gntd_code;
                v_results(v_results.COUNT).msg := 'Error: ' || SQLERRM;
        END;
    END LOOP;

    ---------------------------------------------------------------------
    -- 3) Insert job history (group by USER_ASSIGN for today's SYSTEM-created rows)
    ---------------------------------------------------------------------
    BEGIN
        INSERT INTO HKCN_JOB_HISTORY (
            USER_NAME,
            BRANCH,
            APPROVAL_DATE,
            TOTAL_TRANS_HK,
            GNTD_CODE_REFER,
            CREATED_BY,
            CREATED_DATE,
            UPDATED_BY,
            UPDATED_DATE
        )
        SELECT USER_ASSIGN,
               BRANCH_CODE,
               SYSDATE,
               COUNT(*) AS total_trans_hk,
               NULL AS gntd_code_refer,
               'SYSTEM' AS created_by,
               SYSDATE AS created_date,
               'SYSTEM' AS updated_by,
               SYSDATE AS updated_date
        FROM HKCN_TRANSACTION
        WHERE CREATED_DATE >= TRUNC(SYSDATE) AND CREATED_DATE < TRUNC(SYSDATE) + 1
          AND CREATED_BY = 'SYSTEM'
          AND USER_ASSIGN IS NOT NULL
        GROUP BY USER_ASSIGN, BRANCH_CODE;
    EXCEPTION
        WHEN OTHERS THEN
            v_results.EXTEND;
            v_results(v_results.COUNT).gntd_code := '<JOB_HISTORY>';
            v_results(v_results.COUNT).msg := 'Job history insert error: ' || SQLERRM;
    END;

    ---------------------------------------------------------------------
    -- 4) Build dynamic SQL from v_results and Open SYS_CURSOR
    ---------------------------------------------------------------------
    IF v_results.COUNT = 0 THEN
        v_sql := 'SELECT NULL gntd_code, NULL msg FROM dual WHERE 1=0';
    ELSE
        v_sql := 'WITH t AS (';
        FOR idx IN 1 .. v_results.COUNT LOOP
            v_sql := v_sql
                     || 'SELECT '''
                     || REPLACE(v_results(idx).gntd_code, '''', '''''') || ''' gntd_code, '''
                     || REPLACE(NVL(v_results(idx).msg,' '), '''', '''''') || ''' msg FROM dual UNION ALL ';
        END LOOP;

        DECLARE
        l_len INTEGER := DBMS_LOB.GETLENGTH(v_sql);
        BEGIN
            IF l_len > 11 THEN
                v_sql := DBMS_LOB.SUBSTR(v_sql, l_len - 11, 1);
            ELSE
                v_sql := '';
            END IF;
            v_sql := v_sql || ') SELECT * FROM t';
        END;
    END IF;

    OPEN SYS_CURSOR FOR v_sql;
    COMMIT;
EXCEPTION
    WHEN OTHERS THEN
        BEGIN
            v_results.EXTEND;
            v_results(v_results.COUNT).gntd_code := '<GLOBAL>';
            v_results(v_results.COUNT).msg := 'SP failed: '||SQLERRM;

            v_sql := 'SELECT ''' || REPLACE(v_results(v_results.COUNT).gntd_code, '''', '''''')
                     || ''' gntd_code, ''' || REPLACE(v_results(v_results.COUNT).msg, '''', '''''') || ''' msg FROM dual';

            OPEN SYS_CURSOR FOR v_sql;
        EXCEPTION
            WHEN OTHERS THEN
                OPEN SYS_CURSOR FOR SELECT NULL gntd_code, NULL msg FROM dual WHERE 1=0;
        END;
        RAISE;
END SP_JOB_LAY_DANH_SACH_HK;

/
--------------------------------------------------------
--  DDL for Procedure SP_JOB_SYNC_HO_SO_VAT_LY
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_JOB_SYNC_HO_SO_VAT_LY" (
  P_DATE  IN  VARCHAR2,
  P_COUNT OUT INTEGER
) AS 
  C_DATE DATE := TO_DATE(P_DATE, 'YYYY-MM-DD');
BEGIN 

  -- INSERT
  INSERT INTO TD_MASTERDATA.GN_HOSOVATLY_BPM(
    DISBURSEMENT_CODE,
    CREDIT_APPROVAL_CODE,
    CUSTOMER_CODE,
    CUSTOMER_NAME,
    OFFICE_CODE,
    ISSUED_USER,
    APPROVED_DATE,
    DOCUMENT_TYPE,
    LIST_DOCUMENTS,
    SOURCE
  )
  SELECT 
    G.GNTD_CODE,
    G.PDTD_CODE,
    G.CUSTOMER_CODE,
    G.CUSTOMER_NAME,
    G.BRANCH_CODE,
    G.PROCESSING_OWNER,
    TO_CHAR(G.APPROVAL_DATE, 'YYYYMMDD'),
    'HO_SO_GIAI_NGAN',
    '{"documents":[]}',
    'KHCN'
  FROM GNCN_TRANSACTION G
  WHERE G.STATUS IN (
        -- 'GNCN_DA_PHE_DUYET',
        -- 'GNCN_LOI_HACH_TOAN_THAU_CHI',
        -- 'GNCN_LOI_HACH_TOAN_HAN_MUC',
        -- 'GNCN_LOI_HACH_TOAN_KHOAN_VAY',
        'GNCN_HOAN_TAT_KHOAN_VAY',
        'GNCN_LOI_CHUYEN_TIEN',
        'GNCN_HOAN_THANH'
    )
    AND G.APPROVAL_DATE >= C_DATE
    AND G.APPROVAL_DATE < C_DATE + 1
    AND G.IS_SYNC_FLEX = 0
    AND NOT EXISTS (
      SELECT 1
      FROM TD_MASTERDATA.GN_HOSOVATLY_BPM T
      WHERE T.DISBURSEMENT_CODE = G.GNTD_CODE
        AND T.SOURCE = 'KHCN'
    );

  P_COUNT := SQL%ROWCOUNT;

  -- UPDATE
  UPDATE GNCN_TRANSACTION G
  SET G.IS_SYNC_FLEX = 1
  WHERE G.IS_SYNC_FLEX = 0
    AND G.APPROVAL_DATE >= C_DATE
    AND G.APPROVAL_DATE < C_DATE + 1
    AND G.STATUS IN (
        -- 'GNCN_DA_PHE_DUYET',
        -- 'GNCN_LOI_HACH_TOAN_THAU_CHI',
        -- 'GNCN_LOI_HACH_TOAN_HAN_MUC',
        -- 'GNCN_LOI_HACH_TOAN_KHOAN_VAY',
        'GNCN_HOAN_TAT_KHOAN_VAY',
        'GNCN_LOI_CHUYEN_TIEN',
        'GNCN_HOAN_THANH'
    );

  COMMIT;

END SP_JOB_SYNC_HO_SO_VAT_LY;

/
--------------------------------------------------------
--  DDL for Procedure SP_JOB_UPDATE_FREQUENCY_TRANSACTION_DOC
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_JOB_UPDATE_FREQUENCY_TRANSACTION_DOC" (
  p_json_arr IN CLOB,
  P_MESS OUT VARCHAR2
) AS
  json_arr JSON_ARRAY_T;
  json_obj JSON_OBJECT_T;
  P_ID NUMBER;
  P_GNTD_CODE VARCHAR2(50);
  P_DEADLINE VARCHAR2(50);

BEGIN
  json_arr := JSON_ARRAY_T(p_json_arr);
  FOR i IN 0..json_arr.get_size - 1 LOOP
    -- Mapping input
    json_obj := JSON_OBJECT_T(json_arr.get(i));
    P_ID := json_obj.get_Number('id');
    P_GNTD_CODE := json_obj.get_String('gntdCode');
  	P_DEADLINE := json_obj.get_String('deadline');

    INSERT INTO GNCN_CA_DISBURSEMENT_DOCUMENTS ( 
      GNTD_CODE, COMPLETED_AFTER_DISBURSEMENT_ID, DOC_CODE, DOC_NAME, DOC_CATEGORY,
      GROUP_DOC_CODE, GROUP_DOC_NAME, DESCRIPTION, PDTD_CODE, ECM_FOLDER,
      FREQUENCY, FREQUENCY_UNIT, FREQUENCY_DISPLAYTEXT,
      DEADLINE, STATUS_DOC, STATUS,
--      DEADLINE_EXT, USER_IDEA, APPROVAL_IDEA,
--      ASSIGNEE_USER_BY, ASSIGNEE_DATE, ASSIGNEE_ROLE_BY,
--      STATUS_APPROVAL, STATUS_VERIFY,
--      APPROVAL_BY, APPROVAL_DATE,
--      APPROVAL_SUBMIT_BY, APPROVAL_SUBMIT_DATE,
      CREATED_BY, CREATED_DATE
    ) 
    SELECT 
      GNTD_CODE, COMPLETED_AFTER_DISBURSEMENT_ID, DOC_CODE, DOC_NAME, DOC_CATEGORY,
      GROUP_DOC_CODE, GROUP_DOC_NAME, DESCRIPTION, PDTD_CODE, ECM_FOLDER,
      FREQUENCY, FREQUENCY_UNIT, FREQUENCY_DISPLAYTEXT,
      TO_DATE(P_DEADLINE, 'YYYY-MM-DD') AS DEADLINE, 'CHUA_BO_SUNG' AS STATUS_DOC, 'HSSGN_CHO_BO_SUNG' AS STATUS,
--      NULL AS DEADLINE_EXT, NULL AS USER_IDEA, NULL AS APPROVAL_IDEA, 
--      ASSIGNEE_USER_BY, ASSIGNEE_DATE, ASSIGNEE_ROLE_BY,
--      STATUS_APPROVAL, 0 AS STATUS_VERIFY,
--      APPROVAL_BY, APPROVAL_DATE,
--      APPROVAL_SUBMIT_BY, APPROVAL_SUBMIT_DATE,
      CREATED_BY, SYSDATE AS CREATED_DATE
    FROM GNCN_CA_DISBURSEMENT_DOCUMENTS WHERE ID = P_ID;

  END LOOP;
  COMMIT;

  P_MESS := 'SUCCESS.';

EXCEPTION
  WHEN OTHERS THEN
    P_MESS := SUBSTR(SQLERRM, 1, 500);

END SP_JOB_UPDATE_FREQUENCY_TRANSACTION_DOC;

/
--------------------------------------------------------
--  DDL for Procedure SP_JOB_UPDATE_GNCN_TRANSACTION_DISBURSEMENT_DOCS
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_JOB_UPDATE_GNCN_TRANSACTION_DISBURSEMENT_DOCS" (
    P_REF_NUM_INFO IN CLOB,
    P_MESS OUT VARCHAR2
) AS 
    json_arr                        JSON_ARRAY_T;
    json_obj                        JSON_OBJECT_T;
    p_gntd_Code                      VARCHAR2(50) DEFAULT '';
BEGIN 
    SAVEPOINT SP_UPDATE_DATA;
    json_arr := json_array_t(P_REF_NUM_INFO);
    FOR i IN 0..json_arr.get_size - 1
    LOOP
        json_obj := TREAT( json_arr.get ( i ) AS JSON_OBJECT_T );
        p_gntd_Code := json_obj.get_String('gntdCode');
        UPDATE GNCN_CA_DISBURSEMENT_DOCUMENTS
            SET STATUS = 'HSSGN_HOAN_THANH',
                STATUS_DOC = 'HUY_DIEU_KIEN_BO_SUNG',
                APPROVAL_BY = 'System',
                APPROVAL_IDEA = 'Kho?n vay ?ã t?t toán',
                STATUS_APPROVAL = 'DONG_Y',
                APPROVAL_SUBMIT_BY = 'system'
        WHERE gntd_code = p_gntd_code;
--        UPDATE GNCN_CA_DISBURSEMENT
--            SET PROCESSING_USERNAME = 'System'
--        WHERE gntd_code = p_gntd_code;
    END LOOP;
    P_MESS := '1';
EXCEPTION
   WHEN OTHERS 
   THEN ROLLBACK  TO SP_UPDATE_DATA;
    P_MESS := SUBSTR(SQLERRM, 1, 500);
END SP_JOB_UPDATE_GNCN_TRANSACTION_DISBURSEMENT_DOCS;

/
--------------------------------------------------------
--  DDL for Procedure SP_KS_GET_APPROVAL_INFO
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_KS_GET_APPROVAL_INFO" (
  P_PDTD_CODE IN VARCHAR2,
  APPROVAL_INFO OUT SYS_REFCURSOR,
  BORROWER_INFO OUT SYS_REFCURSOR
) AS BEGIN
  OPEN APPROVAL_INFO FOR
    SELECT
      a.PDTD_CODE,
      a.SOURCE_SYNC,
      a.BRANCH_CODE,
      a.PRODUCT_NAME AS PRODUCT_CODE,
      a.BANK_PRODUCT_NAME AS PRODUCT_NAME,
      a.SUB_PRODUCT_NAME,
      a.CURRENCY,
      a.LOAN_AMOUNT AS TOTAL_AMOUNT,
      TO_CHAR(a.LOAN_AMOUNT, 'FM999G999G999G999') || ' ' || a.CURRENCY AS LOAN_AMOUNT,
      a.LOAN_TERM,
      a.LOAN_METHOD,
      a.APPROVAL_LEVEL,
      TO_CHAR(a.APPROVAL_DATE, 'DD-MM-YYYY') AS APPROVAL_DATE,
      a.CHUYEN_VIEN_KHACH_HANG
    FROM
      GNCN_CREDIT_APPROVAL_INFO_SYNC a
    WHERE
      a.PDTD_CODE = P_PDTD_CODE;

  OPEN BORROWER_INFO FOR
    SELECT
      ref.RELATIONSHIP,
      ref.CUS_ID,
      cus.CIF,
      cus.NAME AS FULL_NAME,
      CASE
        WHEN cus.DATE_OF_BIRTH IS NOT NULL THEN TO_CHAR(cus.DATE_OF_BIRTH, 'DD-MM-YYYY')
        ELSE NULL
      END AS DOB,
      cus.LIVING_ADDRESS AS ADDRESS,
      cus.ORIGINAL_HOMETOWN AS CITY,
      doc.SYS_NAME,
      doc.DOC_ID AS ID_CARD,
      doc.ISSUED_BY AS ISSUE_PLACE,
      CASE
        WHEN doc.ISSUE_DATE IS NOT NULL THEN TO_CHAR(doc.ISSUE_DATE, 'DD-MM-YYYY')
        ELSE NULL
      END AS ISSUE_DATE
    FROM
      (
        SELECT
          *
        FROM
          GNCN_CREDIT_APPROVAL_REF_CUSTOMER_SYNC
        WHERE
          PDTD_CODE = P_PDTD_CODE
      ) ref
      INNER JOIN (
        SELECT
          *
        FROM
          GNCN_CREDIT_CUSTOMER_SYNC
        WHERE
          ID IN (
            SELECT
              CUS_ID
            FROM
              GNCN_CREDIT_APPROVAL_REF_CUSTOMER_SYNC
            WHERE
              PDTD_CODE = P_PDTD_CODE
          )
      ) cus ON ref.CUS_ID = cus.ID
      LEFT JOIN (
        SELECT
          *
        FROM
          GNCN_CREDIT_CUSTOMER_DOC_SYNC
        WHERE
          IS_MAIN_DOC = 1
          AND CUS_ID IN (
            SELECT
              CUS_ID
            FROM
              GNCN_CREDIT_APPROVAL_REF_CUSTOMER_SYNC
            WHERE
              PDTD_CODE = P_PDTD_CODE
          )
      ) doc ON ref.CUS_ID = doc.CUS_ID;

END SP_KS_GET_APPROVAL_INFO;

