/
--------------------------------------------------------
--  DDL for Procedure SP_REASSIGN_USER
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_REASSIGN_USER" (
    P_GNTD_CODE   IN  VARCHAR2,
    P_USER_ASSIGN OUT SYS_REFCURSOR
) IS
    ---------------------------------------------------------------------
    -- Bi?n gi? thông tin giao d?ch
    ---------------------------------------------------------------------
    v_trans_flow        VARCHAR2(100);
    v_trans_level       VARCHAR2(100);
    v_trans_type2       VARCHAR2(100);
    v_trans_type3       VARCHAR2(100);
    v_user_last_assign  VARCHAR2(100);
    v_product_name      VARCHAR2(200);
    v_branch_code       VARCHAR2(50);
    

    ---------------------------------------------------------------------
    -- Bi?n h? s?
    ---------------------------------------------------------------------
    v_coeff_trans      NUMBER := 1;
    v_cnt              NUMBER := 0;
    v_amount           NUMBER := 0;
BEGIN
    ---------------------------------------------------------------------
    -- (1) L?y thông tin giao d?ch
    ---------------------------------------------------------------------
    SELECT hk.TRANSACTION_FLOW,
           hk.TRANS_LEVEL_CODE_1,
           hk.TRANSACTION_TYPE2,
           hk.TRANSACTION_TYPE3,
           NVL(hk.USER_PA, hk.USER_ASSIGN) AS user_last_assign,
           gn.product_name,
           hk.branch_code,
           CASE
               WHEN gn.TRANSACTION_TYPE1 IN ('Giainganthauchi', 'Giaingankhoanvay') THEN gtp.TOTAL_AMOUNT
               WHEN gn.TRANSACTION_TYPE1 = 'Khoitaohanmuc' THEN TO_NUMBER(JSON_VALUE(gn.LIMIT_JSON_DATA, '$.limitValue')) 
               ELSE 0
           END AS amount
      INTO v_trans_flow,
           v_trans_level,
           v_trans_type2,
           v_trans_type3,
           v_user_last_assign,
           v_product_name,
           v_branch_code,
           v_amount
      FROM hkcn_transaction hk
      LEFT JOIN gncn_transaction gn
        ON hk.gntd_code = gn.gntd_code
      LEFT JOIN GNCN_TRANSACTION_PURPOSE gtp
        ON hk.GNTD_CODE = gtp.GNTD_CODE
--      LEFT JOIN gncn_credit_approval_info_sync gnapp
--        ON gn.pdtd_code = gnapp.pdtd_code
     WHERE hk.gntd_code = P_GNTD_CODE;

    ---------------------------------------------------------------------
    -- (2) Ki?m tra user l?n tr??c còn h?p l?
    ---------------------------------------------------------------------
    SELECT COUNT(*)
      INTO v_cnt
      FROM GNCN_USER_GROUP_CONFIG ug
     WHERE ug.use_status = 1
       AND UPPER(ug.user_process) = UPPER(v_user_last_assign)
       AND ug.branch_code = v_branch_code
       AND ug.group_process IN (
           SELECT gpgc.code
             FROM GNCN_PROCESSING_GROUP_CONFIG gpgc
            WHERE gpgc.use_status = 1
              AND gpgc.is_audit_later = 'Y'
       )
       AND EXISTS (
           SELECT 1
             FROM hkcn_transaction_config hkc
            WHERE hkc.use_status = 1
              AND INSTR(',' || hkc.group_process_code || ',', ',' || v_trans_flow || ',') > 0
              AND hkc.trans_level_code_1 = v_trans_level
              AND (hkc.trans_level_code_2 = v_trans_type2 OR hkc.trans_level_code_2 IS NULL)
              AND (hkc.trans_level_code_3 = v_trans_type3 OR hkc.trans_level_code_3 IS NULL)
              AND (hkc.product_code = v_product_name OR hkc.product_code IS NULL)
       )
       AND NOT EXISTS (
           SELECT 1
             FROM GNCN_DISABLE_USER_CONFIG dis
            WHERE dis.use_status = 1
              AND ug.user_process = dis.login_user
              AND SYSDATE BETWEEN NVL(dis.begin_date, SYSDATE)
                              AND NVL(dis.finish_date, SYSDATE + 1)
       );

    IF v_cnt > 0 THEN
        OPEN P_USER_ASSIGN FOR
            SELECT v_user_last_assign AS user_name FROM dual;
        RETURN;
    END IF;

    ---------------------------------------------------------------------
    -- (3) L?y h? s? lo?i giao d?ch
    ---------------------------------------------------------------------
    BEGIN
        SELECT coefficient
          INTO v_coeff_trans
          FROM GNCN_MAPPING_CONFIG gmc
         WHERE gmc.use_status = 1
           AND gmc.trans_level_code_1 = v_trans_level
           AND gmc.trans_level_code_2 = v_trans_type2
           AND gmc.trans_level_code_3 = v_trans_type3
           AND gmc.product_name = v_product_name
           AND ROWNUM = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            v_coeff_trans := 1;
    END;
   ---------------------------------------------------------------------
-- (4) Ch?n user h?p l? theo workload + priority + approve_level
--     N?u nhi?u user cùng ?u tiên cao nh?t thì random trong nhóm ?ó
---------------------------------------------------------------------
OPEN P_USER_ASSIGN FOR
    SELECT user_name
      FROM (
        SELECT user_name,
               RANK() OVER (ORDER BY total_workload ASC, priority ASC, approve_level ASC) AS rnk,
               DBMS_RANDOM.VALUE() AS rnd
          FROM (
            SELECT emp.user_name,
                   -- workload c?a 1 giao d?ch m?i + workload trong ngày c?a user ?ó
                   (v_coeff_trans * NVL(pos.factor,1)) + NVL(w.workload_day_raw * NVL(pos.factor,1), 0) AS total_workload,
                   roleappr.priority,
                   roleappr.approve_level
              FROM GNCN_EMPLOYEE_PROCESS_CONFIG emp
              JOIN GNCN_ROLE_APPROVE_CONFIG roleappr
                ON roleappr.trans_level_code_1 = v_trans_level
               AND roleappr.use_status = 1
               AND emp.use_status = 1
               AND roleappr.trans_level_code_2 = v_trans_type2
               AND roleappr.trans_level_code_3 = v_trans_type3
               AND roleappr.product_name       = v_product_name
               AND roleappr.approve_level      = emp.position_code
               AND (v_amount BETWEEN NVL(roleappr.money_from * 1000000,0) AND NVL(roleappr.money_to * 1000000, 0))
               
              JOIN GNCN_USER_GROUP_CONFIG ugc
                ON ugc.user_process = emp.user_name
               AND ugc.use_status = 1
               AND ugc.branch_code = v_branch_code
               AND ugc.group_process IN (
                   SELECT gpgc.code
                     FROM GNCN_PROCESSING_GROUP_CONFIG gpgc
                    WHERE gpgc.use_status = 1
                      AND gpgc.is_audit_later = 'Y'
               )
              LEFT JOIN GNCN_POSITION_CONFIG pos
                ON pos.code = emp.position_code
                AND pos.tran_flow = v_trans_flow
                AND pos.use_status = 1
              /* T?ng workload các giao d?ch user ?ã làm trong ngày hôm nay */
              LEFT JOIN (
                  SELECT NVL(h.user_pa, h.user_assign) AS user_assign,
                         SUM(m.coefficient) AS workload_day_raw
                    FROM hkcn_transaction h
                    JOIN GNCN_MAPPING_CONFIG m
                      ON m.trans_level_code_1 = h.trans_level_code_1
                     AND m.trans_level_code_2 = h.transaction_type2
                     AND m.trans_level_code_3 = h.transaction_type3
                     AND m.product_name = v_product_name
                     AND m.use_status = 1
                   WHERE h.branch_code = v_branch_code
                     AND EXISTS (
                           SELECT 1
                             FROM HKCN_TRANSACTION_HISTORY hh
                            WHERE hh.gntd_code = h.gntd_code
                              AND hh.action = 'Chuy?n b??c'
                              AND hh.to_step IN ('HK - Ch? b? sung','HK - Hoàn thành')
                              AND TRUNC(hh.created_date) = TRUNC(SYSDATE)
                         )
                   GROUP BY NVL(h.user_pa, h.user_assign)
              ) w
                ON w.user_assign = emp.user_name
             WHERE emp.use_status = 1
          )
      )
     WHERE rnk = 1
     ORDER BY rnd
     FETCH FIRST 1 ROWS ONLY;
         
EXCEPTION
    WHEN OTHERS THEN
        OPEN P_USER_ASSIGN FOR
            SELECT NULL AS user_name FROM dual;
END SP_REASSIGN_USER;

/
--------------------------------------------------------
--  DDL for Procedure SP_REPORT_DASH_BOARD_CN
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_REPORT_DASH_BOARD_CN" (
    P_BRANCH   IN  VARCHAR2,
    P_USER     IN  VARCHAR2,
    P_ROLE     IN  VARCHAR2,
    O_TOTAL_1  OUT NUMBER, -- ch?a x? lý
    O_TOTAL_2  OUT NUMBER, -- c?n theo dõi
    O_TOTAL_3  OUT NUMBER, -- ?ã hoàn thành
    O_TOTAL_4  OUT NUMBER, -- ??n h?n T
    O_TOTAL_5  OUT NUMBER, -- s?p ??n h?n T-3
    O_TOTAL_6  OUT NUMBER  -- Quá h?n > T
) AS
BEGIN
    -----------------------------------------------------------------
    -- Tách danh sách chi nhánh thành b?ng BRANCHLIST
    -----------------------------------------------------------------
    WITH BRANCHLIST AS (
        SELECT TRIM(REGEXP_SUBSTR(P_BRANCH, '[^,]+', 1, LEVEL)) AS BRANCH_CODE
        FROM dual
        CONNECT BY LEVEL <= REGEXP_COUNT(P_BRANCH, ',') + 1
    )
    -----------------------------------------------------------------
    -- O_TOTAL_1: Ch?a x? lý
    -----------------------------------------------------------------
    SELECT COUNT(*)
    INTO O_TOTAL_1
    FROM GNCN_TRANSACTION t
    WHERE (
           EXISTS (SELECT 1 FROM BRANCHLIST b WHERE b.BRANCH_CODE = 'ALL_BRANCH')
           OR t.BRANCH_CODE IN (SELECT b.BRANCH_CODE FROM BRANCHLIST b)
          )
--      AND (TRUNC(t.PROCESSING_DATE) = TRUNC(SYSDATE) or t.PROCESSING_DATE IS NULL)
    AND (TRUNC(t.PROCESSING_DATE) >= TRUNC(SYSDATE) - 7 or t.PROCESSING_DATE IS NULL)
      AND t.STATUS NOT IN ('GNCN_HOAN_THANH', 'GNCN_HUY')
      AND (
            -- 1. Role Nhân viên (CV HTTD)
            (
                (INSTR(P_ROLE, 'GNCN_CV_HTTD_DVKD') > 0 OR INSTR(P_ROLE, 'GNCN_CV_HTTD_HO') > 0)
                AND t.STATUS IN ('GNCN_KHOI_TAO','GNCN_CHO_BO_SUNG','GNCN_LOI_HACH_TOAN_HAN_MUC','GNCN_LOI_HACH_TOAN_KHOAN_VAY')
                AND LOWER(t.CREATED_BY) = P_USER
            )
            OR
            -- 2. Role Qu?n lý (QL HTTD)
            (
                (INSTR(P_ROLE, 'GNCN_QL_HTTD_DVKD') > 0 OR INSTR(P_ROLE, 'GNCN_QL_HTTD_HO') > 0)
                AND t.STATUS IN ('GNCN_CHO_XU_LY','GNCN_LOI_CHUYEN_TIEN','GNCN_HOAN_TAT_KHOAN_VAY')
                AND ( (t.USER_LOCKED IS NOT NULL AND LOWER(t.USER_LOCKED) = P_USER)
                   OR (t.USER_LOCKED IS NULL AND t.APPROVER_SUGGEST IS NOT NULL AND LOWER(t.APPROVER_SUGGEST) = P_USER) )
            )
      );

    -----------------------------------------------------------------
    -- O_TOTAL_2: C?n theo dõi
    -----------------------------------------------------------------
    WITH BRANCHLIST AS (
        SELECT TRIM(REGEXP_SUBSTR(P_BRANCH, '[^,]+', 1, LEVEL)) AS BRANCH_CODE
        FROM dual
        CONNECT BY LEVEL <= REGEXP_COUNT(P_BRANCH, ',') + 1
    )
    SELECT COUNT(*)
    INTO O_TOTAL_2
    FROM GNCN_TRANSACTION t
    WHERE (
              EXISTS (SELECT 1 FROM BRANCHLIST b WHERE b.BRANCH_CODE = 'ALL_BRANCH')
           OR t.BRANCH_CODE IN (SELECT b.BRANCH_CODE FROM BRANCHLIST b)
          )
      AND t.STATUS NOT IN ('GNCN_HOAN_THANH', 'GNCN_HUY')
--      AND t.PROCESSING_DATE >= TRUNC(SYSDATE) - 7
--      AND INSTR(LOWER(t.VIEWER), P_USER) > 0
      AND ( INSTR(LOWER(t.VIEWER), P_USER) > 0 AND TRUNC( (SELECT MAX(GTH.CREATED_DATE) FROM GNCN_TRANSACTION_HISTORY GTH WHERE GTH.GNTD_CODE = t.GNTD_CODE AND LOWER(GTH.CREATED_BY) = P_USER) ) >= TRUNC(SYSDATE) - 7 )
      AND t.GNTD_CODE NOT IN (
            SELECT gt.GNTD_CODE
            FROM GNCN_TRANSACTION gt
            WHERE (
                      EXISTS (SELECT 1 FROM BRANCHLIST b WHERE b.BRANCH_CODE = 'ALL_BRANCH')
                   OR gt.BRANCH_CODE IN (SELECT b.BRANCH_CODE FROM BRANCHLIST b)
                  )
              AND gt.STATUS NOT IN ('GNCN_HOAN_THANH', 'GNCN_HUY')
              AND (
                    (INSTR(P_ROLE, 'GNCN_CV_HTTD_DVKD') > 0 OR INSTR(P_ROLE, 'GNCN_CV_HTTD_HO') > 0)
                    AND gt.STATUS IN ('GNCN_KHOI_TAO','GNCN_CHO_BO_SUNG','GNCN_LOI_HACH_TOAN_HAN_MUC','GNCN_LOI_HACH_TOAN_KHOAN_VAY')
                    AND LOWER(gt.CREATED_BY) = P_USER
                  OR
                    (INSTR(P_ROLE, 'GNCN_QL_HTTD_DVKD') > 0 OR INSTR(P_ROLE, 'GNCN_QL_HTTD_HO') > 0)
                    AND gt.STATUS IN ('GNCN_CHO_XU_LY','GNCN_LOI_CHUYEN_TIEN','GNCN_HOAN_TAT_KHOAN_VAY')
                    AND ( (gt.USER_LOCKED IS NOT NULL AND LOWER(gt.USER_LOCKED) = P_USER)
                       OR (gt.USER_LOCKED IS NULL AND gt.APPROVER_SUGGEST IS NOT NULL AND LOWER(gt.APPROVER_SUGGEST) = P_USER) )
                  )
      );

    -----------------------------------------------------------------
    -- O_TOTAL_3: ?ã hoàn thành
    -----------------------------------------------------------------
    WITH BRANCHLIST AS (
        SELECT TRIM(REGEXP_SUBSTR(P_BRANCH, '[^,]+', 1, LEVEL)) AS BRANCH_CODE
        FROM dual
        CONNECT BY LEVEL <= REGEXP_COUNT(P_BRANCH, ',') + 1
    )
    SELECT COUNT(*)
    INTO O_TOTAL_3
    FROM GNCN_TRANSACTION t
    WHERE (
              EXISTS (SELECT 1 FROM BRANCHLIST b WHERE b.BRANCH_CODE = 'ALL_BRANCH')
           OR t.BRANCH_CODE IN (SELECT b.BRANCH_CODE FROM BRANCHLIST b)
          )
      AND t.STATUS = 'GNCN_HOAN_THANH'
      AND TRUNC(t.APPROVAL_DATE) = TRUNC(SYSDATE)
      AND (LOWER(t.APPROVAL_BY) = P_USER OR LOWER(t.PROCESSING_OWNER) = P_USER);

    -----------------------------------------------------------------
    -- O_TOTAL_4: ??n h?n (T)
    -----------------------------------------------------------------
    WITH BRANCHLIST AS (
        SELECT TRIM(REGEXP_SUBSTR(P_BRANCH, '[^,]+', 1, LEVEL)) AS BRANCH_CODE
        FROM dual
        CONNECT BY LEVEL <= REGEXP_COUNT(P_BRANCH, ',') + 1
    )
    SELECT COUNT(*)
    INTO O_TOTAL_4
    FROM GNCN_CA_DISBURSEMENT_DOCUMENTS d
         LEFT JOIN GNCN_CA_DISBURSEMENT t ON t.GNTD_CODE = d.GNTD_CODE
    WHERE (
              EXISTS (SELECT 1 FROM BRANCHLIST b WHERE b.BRANCH_CODE = 'ALL_BRANCH')
           OR t.BRANCH_CODE IN (SELECT b.BRANCH_CODE FROM BRANCHLIST b)
          )
      AND d.STATUS NOT IN ('HSSGN_HOAN_THANH','HSSGN_HUY_DK_BO_SUNG')
      AND TRUNC(d.DEADLINE) = TRUNC(SYSDATE)
      AND (
            (INSTR(P_ROLE,'GNCN_CV_HTTD_DVKD') > 0 AND d.STATUS='HSSGN_CHO_BO_SUNG' AND LOWER(d.CREATED_BY)=P_USER)
         OR (INSTR(P_ROLE,'GNCN_QL_HTTD_DVKD') > 0 AND (
                (d.STATUS='HSSGN_CHO_BO_SUNG' AND LOWER(d.CREATED_BY)=P_USER)
             OR (d.STATUS='HSSGN_CHO_PHE_DUYET' AND LOWER(d.assignee_user_by)=P_USER)))
         OR ((INSTR(P_ROLE,'GNCN_CV_HTTD_HO') > 0 OR INSTR(P_ROLE,'GNCN_QL_HTTD_HO') > 0)
             AND d.STATUS='HSSGN_CHO_PHE_DUYET'
             AND LOWER(d.assignee_user_by)=P_USER)
      );

    -----------------------------------------------------------------
    -- O_TOTAL_5: S?p ??n h?n (T+1 ??n T+4)
    -----------------------------------------------------------------
    WITH BRANCHLIST AS (
        SELECT TRIM(REGEXP_SUBSTR(P_BRANCH, '[^,]+', 1, LEVEL)) AS BRANCH_CODE
        FROM dual
        CONNECT BY LEVEL <= REGEXP_COUNT(P_BRANCH, ',') + 1
    )
    SELECT COUNT(*)
    INTO O_TOTAL_5
    FROM GNCN_CA_DISBURSEMENT_DOCUMENTS d
         LEFT JOIN GNCN_CA_DISBURSEMENT t ON t.GNTD_CODE = d.GNTD_CODE
    WHERE (
              EXISTS (SELECT 1 FROM BRANCHLIST b WHERE b.BRANCH_CODE = 'ALL_BRANCH')
           OR t.BRANCH_CODE IN (SELECT b.BRANCH_CODE FROM BRANCHLIST b)
          )
      AND d.STATUS NOT IN ('HSSGN_HOAN_THANH','HSSGN_HUY_DK_BO_SUNG')
      AND TRUNC(d.DEADLINE) BETWEEN TRUNC(SYSDATE)+1 AND TRUNC(SYSDATE)+4
      AND (
            (INSTR(P_ROLE,'GNCN_CV_HTTD_DVKD') > 0 AND d.STATUS='HSSGN_CHO_BO_SUNG' AND LOWER(d.CREATED_BY)=P_USER)
         OR (INSTR(P_ROLE,'GNCN_QL_HTTD_DVKD') > 0 AND (
                (d.STATUS='HSSGN_CHO_BO_SUNG' AND LOWER(d.CREATED_BY)=P_USER)
             OR (d.STATUS='HSSGN_CHO_PHE_DUYET' AND LOWER(d.assignee_user_by)=P_USER)))
         OR ((INSTR(P_ROLE,'GNCN_CV_HTTD_HO') > 0 OR INSTR(P_ROLE,'GNCN_QL_HTTD_HO') > 0)
             AND d.STATUS='HSSGN_CHO_PHE_DUYET'
             AND LOWER(d.assignee_user_by)=P_USER)
      );

    -----------------------------------------------------------------
    -- O_TOTAL_6: Quá h?n (> T)
    -----------------------------------------------------------------
    WITH BRANCHLIST AS (
        SELECT TRIM(REGEXP_SUBSTR(P_BRANCH, '[^,]+', 1, LEVEL)) AS BRANCH_CODE
        FROM dual
        CONNECT BY LEVEL <= REGEXP_COUNT(P_BRANCH, ',') + 1
    )
    SELECT COUNT(*)
    INTO O_TOTAL_6
    FROM GNCN_CA_DISBURSEMENT_DOCUMENTS d
         LEFT JOIN GNCN_CA_DISBURSEMENT t ON t.GNTD_CODE = d.GNTD_CODE
    WHERE (
              EXISTS (SELECT 1 FROM BRANCHLIST b WHERE b.BRANCH_CODE = 'ALL_BRANCH')
           OR t.BRANCH_CODE IN (SELECT b.BRANCH_CODE FROM BRANCHLIST b)
          )
      AND d.STATUS NOT IN ('HSSGN_HOAN_THANH','HSSGN_HUY_DK_BO_SUNG')
      AND TRUNC(d.DEADLINE) < TRUNC(SYSDATE)
      AND (
            (INSTR(P_ROLE,'GNCN_CV_HTTD_DVKD') > 0 AND d.STATUS='HSSGN_CHO_BO_SUNG' AND LOWER(d.CREATED_BY)=P_USER)
         OR (INSTR(P_ROLE,'GNCN_QL_HTTD_DVKD') > 0 AND (
                (d.STATUS='HSSGN_CHO_BO_SUNG' AND LOWER(d.CREATED_BY)=P_USER)
             OR (d.STATUS='HSSGN_CHO_PHE_DUYET' AND LOWER(d.assignee_user_by)=P_USER)))
         OR ((INSTR(P_ROLE,'GNCN_CV_HTTD_HO') > 0 OR INSTR(P_ROLE,'GNCN_QL_HTTD_HO') > 0)
             AND d.STATUS='HSSGN_CHO_PHE_DUYET'
             AND LOWER(d.assignee_user_by)=P_USER)
      );

END SP_REPORT_DASH_BOARD_CN;

/
--------------------------------------------------------
--  DDL for Procedure SP_REPORT_LOAN_TRANSACTION
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_REPORT_LOAN_TRANSACTION" 
(
  p_json_object IN CLOB,
  OUT_DATA OUT SYS_REFCURSOR
)
AS 
  json_obj                JSON_OBJECT_T;
  P_STATUS                VARCHAR2(200) DEFAULT '';   --Tr?ng thái
  P_GNTD_CODE             VARCHAR2(50);   -- Mã gi?i ngân tín d?ng
  P_PDTD_CODE             VARCHAR2(50);   -- Mã PDTD (LOS, BPM, ECM)
  P_LIMIT_CODE            VARCHAR2(50);   -- Mã h?n m?c
  P_CUSTOMER_CODE         VARCHAR2(50);   -- Mã Khách Hàng
  P_CUSTOMER_NAME         VARCHAR2(50);   -- Tên Khách Hàng
  P_TRANSACTION_TYPE1     VARCHAR2(50);   -- Lo?i GD C?p 1
  P_BRANCH                VARCHAR2(200);  -- Mã ?VKD - Mã chi nhánh
  P_ISSUE_BY              VARCHAR2(50);   -- USER x? lý
  P_REF_NUM               VARCHAR2(50);   -- FCC REF NUM
  P_FROM_DATE             VARCHAR2(50) DEFAULT '';
  P_TO_DATE               VARCHAR2(50) DEFAULT '';
  V_FROM_DATE             DATE;
  V_TO_DATE               DATE;
    
BEGIN
  json_obj := JSON_OBJECT_T.parse(p_json_object);  
  P_GNTD_CODE := json_obj.get_String('gntdCode');
  P_PDTD_CODE := json_obj.get_String('pdtdCode');
  P_LIMIT_CODE := json_obj.get_String('limitCode');
  P_REF_NUM := json_obj.get_String('fccRefNum');
  
  P_BRANCH := json_obj.get_String('branch');
  P_CUSTOMER_CODE := json_obj.get_String('customerCode');
  P_CUSTOMER_NAME := json_obj.get_String('customerName');
  P_ISSUE_BY := json_obj.get_String('issueBy');

  P_STATUS := json_obj.get_String('status');
  P_TRANSACTION_TYPE1 := json_obj.get_String('transactionType1');
  P_FROM_DATE := json_obj.get_String('fromDate');
  P_TO_DATE := json_obj.get_String('toDate');

  IF P_FROM_DATE IS NOT NULL THEN 
    V_FROM_DATE := TO_DATE(P_FROM_DATE,'YYYY-MM-DD');
  END IF;

  IF P_TO_DATE IS NOT NULL THEN 
    V_TO_DATE := TO_DATE(P_TO_DATE,'YYYY-MM-DD') + 1;
  END IF;

  IF P_GNTD_CODE IS NOT NULL THEN P_GNTD_CODE := UPPER(P_GNTD_CODE); END IF;
  IF P_PDTD_CODE IS NOT NULL THEN P_PDTD_CODE := UPPER(P_PDTD_CODE); END IF;
  IF P_LIMIT_CODE IS NOT NULL THEN P_LIMIT_CODE := UPPER(P_LIMIT_CODE); END IF;
  IF P_REF_NUM IS NOT NULL THEN P_REF_NUM := UPPER(P_REF_NUM); END IF;
  IF P_ISSUE_BY IS NOT NULL THEN P_ISSUE_BY := UPPER(P_ISSUE_BY); END IF;
  IF P_CUSTOMER_CODE IS NOT NULL THEN P_CUSTOMER_CODE := UPPER(P_CUSTOMER_CODE); END IF;
  IF P_CUSTOMER_NAME IS NOT NULL THEN P_CUSTOMER_NAME := UPPER(P_CUSTOMER_NAME); END IF;
    
OPEN OUT_DATA FOR 

WITH branch_list AS (
  SELECT REGEXP_SUBSTR(P_BRANCH, '[^,]+', 1, LEVEL) AS BR
  FROM DUAL
  WHERE P_BRANCH IS NOT NULL
  CONNECT BY REGEXP_SUBSTR(P_BRANCH, '[^,]+', 1, LEVEL) IS NOT NULL
)

SELECT
  GNTD_CODE,
  STATUS,
  BRANCH_CODE,
  BRANCH_NAME,
  (BRANCH_CODE || '<br/>' || BRANCH_NAME) AS displayBranch,
  PDTD_CODE,
  LIMIT_CODE,
  CUS_ID_CARD,
  CUSTOMER_CODE,
  CUSTOMER_NAME,
  (CUSTOMER_CODE || '<br/>' || CUSTOMER_NAME) AS displayCustomer,
  PRODUCT_CODE,
  PRODUCT_NAME,
  APPROVAL_BY,
  TO_CHAR(APPROVAL_DATE, 'DD-MM-YYYY HH24:MI') APPROVAL_DATE,
  ISSUED_BY,
  TO_CHAR(ISSUED_DATE, 'DD-MM-YYYY HH24:MI') ISSUE_DATE,
  TRANSACTION_TYPE1 AS TRANS_TYPE_1,
  TRANSACTION_TYPE1_NAME AS TRANSACTION_TYPE1,
  TRANSACTION_TYPE2,
  TRANSACTION_TYPE3,
  STATUS_NAME,
  --
  FCC_REF_NUM,
  TOTAL_AMOUNT,
  CURRENCY,
  NVL(TO_CHAR(TOTAL_AMOUNT, '999,999,999,990.00'), '0') || ' ' || NVL(CURRENCY, '') AS DISPLAY_AMOUNT,
  DEADLINE,
  DURATION_UNIT,
  DURATION_DISPLAY,
  TO_CHAR(FROM_DATE, 'DD-MM-YYYY HH24:MI') FROM_DATE,
  TO_CHAR(TO_DATE, 'DD-MM-YYYY HH24:MI') TO_DATE,
  REASON,
  RATE_CODE,
  INTEREST_RATE,
  MARGIN_RATE,
  EARLY_REPAYMENT_FEE,
  (
    CASE 
      WHEN MARGIN_RATE IS NOT NULL THEN 
        TO_CHAR(MARGIN_RATE, 'FM999,999,999,990.00')
      ELSE NULL
    END
  ) AS RATE,
  MODIFIED_DATE,
  CREATED_DATE
FROM
  ETL_LOAN_TRANSACTION_REPORT
WHERE
  1 = 1
  AND (V_FROM_DATE IS NULL OR APPROVAL_DATE >= V_FROM_DATE)
  AND (V_TO_DATE IS NULL OR APPROVAL_DATE < V_TO_DATE)
  -- AND (P_GNTD_CODE IS NULL OR CONTAINS(GNTD_CODE, '*' || P_GNTD_CODE || '*') > 0)
  -- AND (P_PDTD_CODE IS NULL OR CONTAINS(PDTD_CODE, P_PDTD_CODE) > 0)
  -- AND (P_LIMIT_CODE IS NULL OR CONTAINS(LIMIT_CODE, P_LIMIT_CODE) > 0)
  -- AND (P_REF_NUM IS NULL OR CONTAINS(FCC_REF_NUM, P_REF_NUM) > 0)
  AND (P_GNTD_CODE IS NULL OR GNTD_CODE LIKE '%' || P_GNTD_CODE || '%')
  AND (P_PDTD_CODE IS NULL OR PDTD_CODE LIKE '%' || P_PDTD_CODE || '%')
  AND (P_LIMIT_CODE IS NULL OR LIMIT_CODE LIKE '%' || P_LIMIT_CODE || '%')
  AND (P_REF_NUM IS NULL OR FCC_REF_NUM LIKE '%' || P_REF_NUM || '%')
  AND (
    (P_TRANSACTION_TYPE1 IS NOT NULL AND TRANSACTION_TYPE1 = P_TRANSACTION_TYPE1)
    OR
    (P_TRANSACTION_TYPE1 IS NULL AND TRANSACTION_TYPE1 IN ('Giaingankhoanvay','Giainganthauchi'))
  )
  AND (P_STATUS IS NULL OR STATUS = P_STATUS)
  -- AND (P_ISSUE_BY IS NULL OR CONTAINS(APPROVAL_BY, P_ISSUE_BY) > 0)
  -- AND (P_CUSTOMER_CODE IS NULL OR CONTAINS(CUSTOMER_CODE, P_CUSTOMER_CODE) > 0)
  -- AND (P_CUSTOMER_NAME IS NULL OR CONTAINS(CUSTOMER_NAME, P_CUSTOMER_NAME) > 0)
  AND (P_ISSUE_BY IS NULL OR APPROVAL_BY LIKE '%' || P_ISSUE_BY || '%')
  AND (P_CUSTOMER_CODE IS NULL OR CUSTOMER_CODE LIKE '%' || P_CUSTOMER_CODE || '%')
  AND (P_CUSTOMER_NAME IS NULL OR CUSTOMER_NAME LIKE '%' || P_CUSTOMER_NAME || '%')
  AND (P_BRANCH IS NULL OR BRANCH_CODE IN (SELECT BR FROM branch_list))
  -- LEFT JOIN GNCN_STATUS s ON t.STATUS = s.CODE
  -- LEFT JOIN GNCN_TRANSACTION_TYPE tt1 ON tt1.CODE = t.TRANS_TYPE_1 AND tt1.USE_STATUS = 1 AND tt1.LEVEL_TYPE = 1
ORDER BY NVL(MODIFIED_DATE, CREATED_DATE) DESC;

END SP_REPORT_LOAN_TRANSACTION;

/
--------------------------------------------------------
--  DDL for Procedure SP_SEARCH_CREDIT_APPROVAL_INFO
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_SEARCH_CREDIT_APPROVAL_INFO" (
    p_json_object IN CLOB,
    OUT_DATA OUT SYS_REFCURSOR,
    PAGINATION_INFO OUT SYS_REFCURSOR
) AS 
    json_obj JSON_OBJECT_T;
    P_CODE VARCHAR2(200) DEFAULT '';
    P_SOURCE_SYNC VARCHAR2(50) DEFAULT '';
    P_BRANCH_CODE VARCHAR2(2000) DEFAULT '';
    P_CIF VARCHAR2(200) DEFAULT '';
    P_ID_CARD VARCHAR2(200) DEFAULT '';
    P_CUSTOMER_NAME VARCHAR2(200) DEFAULT '';
    P_FROM_DATE VARCHAR2(20) DEFAULT '';
    P_TO_DATE VARCHAR2(20) DEFAULT '';
    P_PAGE_INDEX NUMBER DEFAULT 0; -- CURRENT PAGE 
    P_PAGE_SIZE NUMBER DEFAULT 20;
    P_PAGE_OFFSET NUMBER DEFAULT 0;

BEGIN 
    json_obj := JSON_OBJECT_T.parse(p_json_object);
    P_CODE := json_obj.get_String('approvalCode');
    P_SOURCE_SYNC := json_obj.get_String('sourceSync');
    P_BRANCH_CODE := json_obj.get_String('branchCode');
    P_CIF := json_obj.get_String('customerCode');
    P_ID_CARD := json_obj.get_String('cusIdCard');
    P_CUSTOMER_NAME := json_obj.get_String('customerName');
    P_FROM_DATE := json_obj.get_String('fromDate');
    P_TO_DATE := json_obj.get_String('toDate');
    P_PAGE_INDEX := json_obj.get_Number('pageIndex');
    IF (P_PAGE_INDEX IS NULL) THEN P_PAGE_INDEX := 0; END IF;
    P_PAGE_SIZE := json_obj.get_Number('pageSize');
    IF (P_PAGE_SIZE IS NULL) THEN P_PAGE_SIZE := 2000; END IF;
    P_PAGE_OFFSET := P_PAGE_INDEX * P_PAGE_SIZE;

    OPEN OUT_DATA FOR
    SELECT
        a.PDTD_CODE,
        a.SOURCE_SYNC,
        a.BRANCH_CODE,
        a.PRODUCT_NAME AS PRODUCT_CODE,
        a.BANK_PRODUCT_NAME AS PRODUCT_NAME,
        a.SUB_PRODUCT_NAME,
        a.CURRENCY,
        a.LOAN_AMOUNT AS TOTAL_AMOUNT,
        a.LOAN_TERM,
        a.LOAN_METHOD,
        a.APPROVAL_LEVEL,
        a.APPROVAL_DATE,
        c.ID AS CUS_ID,
        c.CIF AS CUSTOMER_CODE,
        c.NAME AS CUSTOMER_NAME,
        c.DATE_OF_BIRTH,
        c.CUS_TYPE,
        c.LIVING_ADDRESS,
        c.PERMANENT_ADDRESS,
        c.ORIGINAL_HOMETOWN,
        d.SYS_NAME,
        d.DOC_ID AS ID_CARD,
        d.ISSUE_DATE,
        d.ISSUED_BY,
        d.IS_MAIN_DOC
    FROM
        GNCN_CREDIT_APPROVAL_INFO_SYNC a
        INNER JOIN (
            SELECT
                *
            FROM
                GNCN_CREDIT_APPROVAL_REF_CUSTOMER_SYNC
            WHERE
                RELATIONSHIP IS NULL
                AND (
                    P_CODE IS NULL
                    OR P_CODE = ''
                    OR PDTD_CODE = P_CODE
                )
        ) r ON r.PDTD_CODE = a.PDTD_CODE
        INNER JOIN (
            SELECT
                *
            FROM
                GNCN_CREDIT_CUSTOMER_SYNC
            WHERE
                1 = 1
                AND (
                    P_CIF IS NULL
                    OR P_CIF = ''
                    OR CIF = P_CIF
--                    OR CIF LIKE '%' || P_CIF || '%'
                )
                AND (
                    P_CUSTOMER_NAME IS NULL
                    OR P_CUSTOMER_NAME = ''
                    OR NAME LIKE '%' || P_CUSTOMER_NAME || '%'
                ) --TÊN KH
        ) c ON c.ID = r.CUS_ID
        LEFT JOIN (
            SELECT
                *
            FROM
                GNCN_CREDIT_CUSTOMER_DOC_SYNC
            WHERE
                IS_MAIN_DOC = 1
        ) d ON d.CUS_ID = c.ID
        WHERE
        1 = 1
        AND (
            P_CODE IS NULL
            OR P_CODE = '' -- OR a.PDTD_CODE = P_CODE
            OR a.PDTD_CODE LIKE '%' || P_CODE || '%'
        )
        AND (
            --P_SOURCE_SYNC IS NULL
            --OR P_SOURCE_SYNC = ''
            --OR a.SOURCE_SYNC = P_SOURCE_SYNC
            a.SOURCE_SYNC = 'LOS'
        )
        AND (
            P_BRANCH_CODE IS NULL
            OR P_BRANCH_CODE = ''
            OR INSTR(P_BRANCH_CODE, a.BRANCH_CODE) > 0
        )
        AND (
            P_ID_CARD IS NULL
            OR P_ID_CARD = ''
            OR DOC_ID LIKE '%' || P_ID_CARD || '%'
        )
        AND (
            P_FROM_DATE IS NULL
            OR P_FROM_DATE = ''
            OR TRUNC(TO_DATE(P_FROM_DATE, 'YYYY-MM-DD')) <= TRUNC(a.APPROVAL_DATE)
        )
        AND (
            P_TO_DATE IS NULL
            OR P_TO_DATE = ''
            OR TRUNC(TO_DATE(P_TO_DATE, 'YYYY-MM-DD')) >= TRUNC(a.APPROVAL_DATE)
        )
        ORDER BY COALESCE(a.MODIFIED_DATE, a.CREATED_DATE) DESC
        OFFSET P_PAGE_OFFSET ROWS FETCH NEXT P_PAGE_SIZE ROWS ONLY;


--        GET TOTAL RECORD
    OPEN PAGINATION_INFO FOR 
    SELECT COUNT(*) AS TOTAL_RECORD
    FROM
        GNCN_CREDIT_APPROVAL_INFO_SYNC a
        INNER JOIN (
            SELECT
                *
            FROM
                GNCN_CREDIT_APPROVAL_REF_CUSTOMER_SYNC
            WHERE
                RELATIONSHIP IS NULL
                AND (
                    P_CODE IS NULL
                    OR P_CODE = ''
                    OR PDTD_CODE = P_CODE
                )
        ) r ON r.PDTD_CODE = a.PDTD_CODE
        INNER JOIN (
            SELECT
                *
            FROM
                GNCN_CREDIT_CUSTOMER_SYNC
            WHERE
                1 = 1
                AND (
                    P_CIF IS NULL
                    OR P_CIF = ''
                    OR CIF = P_CIF
--                    OR CIF LIKE '%' || P_CIF || '%'
                )
                AND (
                    P_CUSTOMER_NAME IS NULL
                    OR P_CUSTOMER_NAME = ''
                    OR NAME LIKE '%' || P_CUSTOMER_NAME || '%'
                ) --TÊN KH
        ) c ON c.ID = r.CUS_ID
        LEFT JOIN (
            SELECT
                *
            FROM
                GNCN_CREDIT_CUSTOMER_DOC_SYNC
            WHERE
                IS_MAIN_DOC = 1
                AND (
                    P_ID_CARD IS NULL
                    OR P_ID_CARD = ''
                    OR DOC_ID LIKE '%' || P_ID_CARD || '%'
                )
        ) d ON d.CUS_ID = c.ID
        WHERE
        1 = 1
        AND (
            P_CODE IS NULL
            OR P_CODE = '' -- OR a.PDTD_CODE = P_CODE
            OR a.PDTD_CODE LIKE '%' || P_CODE || '%'
        )
        AND (
            P_SOURCE_SYNC IS NULL
            OR P_SOURCE_SYNC = ''
            OR a.SOURCE_SYNC = P_SOURCE_SYNC
        )
        AND (
            P_BRANCH_CODE IS NULL
            OR P_BRANCH_CODE = ''
            OR INSTR(P_BRANCH_CODE, a.BRANCH_CODE) > 0
        )
        AND (
            P_FROM_DATE IS NULL
            OR P_FROM_DATE = ''
            OR TRUNC(TO_DATE(P_FROM_DATE, 'YYYY-MM-DD')) <= TRUNC(a.APPROVAL_DATE)
        )
        AND (
            P_TO_DATE IS NULL
            OR P_TO_DATE = ''
            OR TRUNC(TO_DATE(P_TO_DATE, 'YYYY-MM-DD')) >= TRUNC(a.APPROVAL_DATE)
        );

END SP_SEARCH_CREDIT_APPROVAL_INFO;

