--------------------------------------------------------
--  DDL for Procedure SP_SEARCH_GNCN_CREDIT_APPROVAL_INFO_SYNC
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_SEARCH_GNCN_CREDIT_APPROVAL_INFO_SYNC" (
    p_json_object IN CLOB,
    OUT_DATA OUT SYS_REFCURSOR,
    PAGINATION_INFO OUT SYS_REFCURSOR
) AS 
    json_obj JSON_OBJECT_T;
    P_CODE VARCHAR2(200) DEFAULT '';
    P_SOURCE_SYNC VARCHAR2(50) DEFAULT '';
    P_BRANCH_CODE VARCHAR2(2000) DEFAULT '';
    P_BRANCHS JSON_ARRAY_T DEFAULT NULL;
    P_CIF VARCHAR2(200) DEFAULT '';
    P_ID_CARD VARCHAR2(200) DEFAULT '';
    P_CUSTOMER_NAME VARCHAR2(200) DEFAULT '';
    P_PRODUCT_NAME VARCHAR2(200) DEFAULT '';
    P_FROM_DATE VARCHAR2(20) DEFAULT '';
    P_TO_DATE VARCHAR2(20) DEFAULT '';
    P_PAGE_INDEX NUMBER DEFAULT 0; -- CURRENT PAGE 
    P_PAGE_SIZE NUMBER DEFAULT 20;
    P_PAGE_OFFSET NUMBER DEFAULT 0;

BEGIN 
    json_obj := JSON_OBJECT_T.parse(p_json_object);
    P_CODE := json_obj.get_String('approvalCode');
    P_SOURCE_SYNC := json_obj.get_String('sourceSync');
    P_BRANCH_CODE := json_obj.get_String('branchCode');
    P_BRANCHS := json_obj.get_Array('branchs');
    P_CIF := json_obj.get_String('customerCode');
    P_ID_CARD := json_obj.get_String('cusIdCard');
    P_CUSTOMER_NAME := json_obj.get_String('customerName');
    P_PRODUCT_NAME := json_obj.get_String('productCode');
    P_FROM_DATE := json_obj.get_String('fromDate');
--    DBMS_OUTPUT.PUT_LINE('P_FROM_DATE = ' || P_FROM_DATE);
    P_TO_DATE := json_obj.get_String('toDate');
--    DBMS_OUTPUT.PUT_LINE('P_TO_DATE = ' || P_TO_DATE);
    P_PAGE_INDEX := json_obj.get_Number('pageIndex');
    IF (P_PAGE_INDEX IS NULL) THEN P_PAGE_INDEX := 0; END IF;
    P_PAGE_SIZE := json_obj.get_Number('pageSize');
    IF (P_PAGE_SIZE IS NULL) THEN P_PAGE_SIZE := 2000; END IF;
    P_PAGE_OFFSET := P_PAGE_INDEX * P_PAGE_SIZE;
--    DBMS_OUTPUT.PUT_LINE('P_PAGE_INDEX = ' || P_PAGE_INDEX);
--    DBMS_OUTPUT.PUT_LINE('P_PAGE_SIZE = ' || P_PAGE_SIZE);
--    DBMS_OUTPUT.PUT_LINE('P_PAGE_OFFSET = ' || P_PAGE_OFFSET);

    OPEN OUT_DATA FOR
    SELECT
        a.PDTD_CODE,
        a.SOURCE_SYNC,
        a.BRANCH_CODE,
        a.PRODUCT_CODE,
        a.PRODUCT_NAME,
        a.BANK_PRODUCT_NAME,
        a.SUB_PRODUCT_NAME,
        a.CURRENCY,
        a.LOAN_AMOUNT,
        a.LOAN_TERM,
        a.LOAN_METHOD,
        a.APPROVAL_LEVEL,
        a.APPROVAL_DATE,
        c.ID AS CUS_ID,
        c.CIF,
        c.NAME AS CIF_NAME,
        c.DATE_OF_BIRTH,
        'KHCN', -- c.CUS_TYPE,
        c.LIVING_ADDRESS,
        c.PERMANENT_ADDRESS,
        c.ORIGINAL_HOMETOWN,
        d.SYS_NAME,
        d.DOC_ID,
        d.ISSUE_DATE,
        d.ISSUED_BY,
        d.IS_MAIN_DOC
    FROM
        GNCN_CREDIT_APPROVAL_INFO_SYNC a
        INNER JOIN (
            SELECT
                *
            FROM
                GNCN_CREDIT_APPROVAL_REF_CUSTOMER_SYNC
            WHERE
                RELATIONSHIP IS NULL
                AND (
                    P_CODE IS NULL
                    OR P_CODE = ''
                    -- OR PDTD_CODE = P_CODE
                    OR PDTD_CODE LIKE '%' || P_CODE || '%'
                )
        ) r ON r.PDTD_CODE = a.PDTD_CODE
        INNER JOIN (
            SELECT
                *
            FROM
                GNCN_CREDIT_CUSTOMER_SYNC
            WHERE
                1 = 1
                AND (
                    P_CIF IS NULL
                    OR P_CIF = ''
                    OR CIF = P_CIF
                    -- OR CIF LIKE '%' || P_CIF || '%'
                )
                AND (
                    P_CUSTOMER_NAME IS NULL
                    OR P_CUSTOMER_NAME = ''
                    OR LOWER(NAME) LIKE '%' || LOWER(P_CUSTOMER_NAME) || '%'
                ) --TÊN KH
        ) c ON c.ID = r.CUS_ID
        LEFT JOIN (
            SELECT
                *
            FROM
                GNCN_CREDIT_CUSTOMER_DOC_SYNC
            WHERE
                IS_MAIN_DOC = 1
        ) d ON d.CUS_ID = c.ID
        WHERE
        1 = 1
        AND (a.APPROVAL_RESULT IS NULL OR a.APPROVAL_RESULT <> 'Reject')
        AND (
            P_CODE IS NULL
            OR P_CODE = '' 
            -- OR a.PDTD_CODE = P_CODE
            OR a.PDTD_CODE LIKE '%' || P_CODE || '%'
        )
        AND (
            P_SOURCE_SYNC IS NULL
            OR P_SOURCE_SYNC = ''
            OR a.SOURCE_SYNC = P_SOURCE_SYNC
        )
        AND (
            P_BRANCH_CODE IS NULL
            OR P_BRANCH_CODE = ''
            OR INSTR(P_BRANCH_CODE, a.BRANCH_CODE) > 0
        )
        AND (
            P_ID_CARD IS NULL
            OR P_ID_CARD = ''
            OR DOC_ID LIKE '%' || P_ID_CARD || '%'
        )
        AND (
            P_FROM_DATE IS NULL
            OR P_FROM_DATE = ''
            OR TRUNC(TO_DATE(P_FROM_DATE, 'YYYY-MM-DD')) <= TRUNC(a.APPROVAL_DATE)
        )
        AND (
            P_TO_DATE IS NULL
            OR P_TO_DATE = ''
            OR TRUNC(TO_DATE(P_TO_DATE, 'YYYY-MM-DD')) >= TRUNC(a.APPROVAL_DATE)
        )
        ORDER BY COALESCE(a.MODIFIED_DATE, a.CREATED_DATE) DESC
        OFFSET P_PAGE_OFFSET ROWS FETCH NEXT P_PAGE_SIZE ROWS ONLY;
        
        
--        GET TOTAL RECORD
    OPEN PAGINATION_INFO FOR 
    SELECT COUNT(*) AS TOTAL_RECORD
    FROM
        GNCN_CREDIT_APPROVAL_INFO_SYNC a
        LEFT JOIN (
            SELECT
                *
            FROM
                GNCN_CREDIT_APPROVAL_REF_CUSTOMER_SYNC
            WHERE
                RELATIONSHIP IS NULL
                AND (
                    P_CODE IS NULL
                    OR P_CODE = ''
                    OR PDTD_CODE = P_CODE
                )
        ) r ON r.PDTD_CODE = a.PDTD_CODE
        LEFT JOIN (
            SELECT
                *
            FROM
                GNCN_CREDIT_CUSTOMER_SYNC
            WHERE
                1 = 1
                AND (
                    P_CIF IS NULL
                    OR P_CIF = ''
                    OR CIF = P_CIF
                )
                AND (
                    P_CUSTOMER_NAME IS NULL
                    OR P_CUSTOMER_NAME = ''
                    OR LOWER(NAME) LIKE '%' || LOWER(P_CUSTOMER_NAME) || '%'
                ) --TÊN KH
        ) c ON c.ID = r.CUS_ID
        LEFT JOIN (
            SELECT
                *
            FROM
                GNCN_CREDIT_CUSTOMER_DOC_SYNC
            WHERE
                IS_MAIN_DOC = 1
                AND (
                    P_ID_CARD IS NULL
                    OR P_ID_CARD = ''
                    OR DOC_ID LIKE '%' || P_ID_CARD || '%'
                )
        ) d ON d.CUS_ID = c.ID
        WHERE
        1 = 1
        AND (a.APPROVAL_RESULT IS NULL OR a.APPROVAL_RESULT <> 'Reject')
        AND (
            P_CODE IS NULL
            OR P_CODE = '' -- OR a.PDTD_CODE = P_CODE
            OR a.PDTD_CODE LIKE '%' || P_CODE || '%'
        )
        AND (
            P_SOURCE_SYNC IS NULL
            OR P_SOURCE_SYNC = ''
            OR a.SOURCE_SYNC = P_SOURCE_SYNC
        )
        AND (
            P_BRANCH_CODE IS NULL
            OR P_BRANCH_CODE = ''
            OR INSTR(P_BRANCH_CODE, a.BRANCH_CODE) > 0
        )
        AND (
            P_FROM_DATE IS NULL
            OR P_FROM_DATE = ''
            OR TRUNC(TO_DATE(P_FROM_DATE, 'YYYY-MM-DD')) <= TRUNC(a.APPROVAL_DATE)
        )
        AND (
            P_TO_DATE IS NULL
            OR P_TO_DATE = ''
            OR TRUNC(TO_DATE(P_TO_DATE, 'YYYY-MM-DD')) >= TRUNC(a.APPROVAL_DATE)
        );

END SP_SEARCH_GNCN_CREDIT_APPROVAL_INFO_SYNC;

