--  DDL for Procedure SP_SEARCH_GNCN_EMPLOYEE_PROCESS_CONFIG
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_SEARCH_GNCN_EMPLOYEE_PROCESS_CONFIG" (
  p_json_object IN VARCHAR,
  P_PAGING_CURSOR OUT SYS_REFCURSOR
) AS 
  json_obj JSON_OBJECT_T;
  P_USER_NAME VARCHAR2(100) DEFAULT '';
  P_FULL_NAME VARCHAR2(100) DEFAULT '';
  P_BRANCH_MAIN VARCHAR2(100) DEFAULT '';
  P_BRANCHS VARCHAR2(500) DEFAULT '';
  P_POSITION VARCHAR2(100) DEFAULT '';
  P_ROLE VARCHAR2(100) DEFAULT '';
  P_MANAGER VARCHAR2(100) DEFAULT '';
BEGIN 
  json_obj := JSON_OBJECT_T.parse(p_json_object);
  P_USER_NAME := json_obj.get_String('userName');
  P_FULL_NAME := json_obj.get_String('fullName');
  P_BRANCH_MAIN := json_obj.get_String('branchCode');
  P_BRANCHS := json_obj.get_String('branchs');
  P_POSITION := json_obj.get_String('positionCode');
  P_ROLE := json_obj.get_String('role');
  P_MANAGER := json_obj.get_String('userManager');

  OPEN P_PAGING_CURSOR FOR
    SELECT 
      ID, USER_NAME AS userName, FULL_NAME AS fullName, BRANCH_MAIN AS branchCode,
      BRANCHS, ROLE, POSITION_CODE as positionCode, USER_MANAGER as userManager,
      CREATED_BY AS CREATEDBY, CREATED_DATE AS CREATEDDATE,
      USE_STATUS AS STATUS
    FROM
      GNCN_EMPLOYEE_PROCESS_CONFIG
    WHERE 
      USE_STATUS = 1
      AND (
        P_USER_NAME IS NULL
        OR UPPER(USER_NAME) = UPPER(P_USER_NAME)
      )
      AND (
        P_FULL_NAME IS NULL
        OR UPPER(FULL_NAME) = UPPER(P_FULL_NAME)
      )
      AND (
        P_BRANCH_MAIN IS NULL
        OR UPPER(BRANCH_MAIN) = UPPER(P_BRANCH_MAIN)
      )
      AND (
        P_POSITION IS NULL
        OR UPPER(POSITION_CODE) = UPPER(P_POSITION)
      )
      AND (
        P_BRANCHS IS NULL
        OR INSTR(UPPER(BRANCHS), UPPER(P_BRANCHS)) > 0
      )
      AND (
        P_ROLE IS NULL
        OR INSTR(UPPER(ROLE), UPPER(P_ROLE)) > 0
      )
      AND (
        P_MANAGER IS NULL
        OR UPPER(USER_MANAGER) = UPPER(P_MANAGER)
      )
    ORDER BY
      ID DESC;

END SP_SEARCH_GNCN_EMPLOYEE_PROCESS_CONFIG;

