--  DDL for Procedure SP_SEARCH_GNCN_USER_CLERICAL_CONFIG
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_SEARCH_GNCN_USER_CLERICAL_CONFIG" (
  p_json_object IN VARCHAR,
  P_PAGING_CURSOR OUT SYS_REFCURSOR
) AS 
  json_obj JSON_OBJECT_T;
  P_USER_ID VARCHAR2(100) DEFAULT '';
  P_BRANCH_CODE VARCHAR2(100) DEFAULT '';
  P_ALLOW_BRANCH VARCHAR2(500) DEFAULT '';
  P_ACTIVE VARCHAR2(50) DEFAULT '1';
BEGIN 
  json_obj := JSON_OBJECT_T.parse(p_json_object);
  P_USER_ID := json_obj.get_String('userId');
  P_BRANCH_CODE := json_obj.get_String('branchCode');
  P_ALLOW_BRANCH := json_obj.get_String('allowBranch');
  P_ACTIVE := json_obj.get_String('isActive');

  IF (P_ACTIVE IS NULL) THEN P_ACTIVE := '1'; END IF;

  OPEN P_PAGING_CURSOR FOR
    SELECT 
      ID, USER_ID, BRANCH_CODE, ALLOW_BRANCH, STATUS, CREATED_BY,
      TO_CHAR(CREATED_DATE, 'DD/MM/YYYY HH24:MI') CREATED_DATE
    FROM
      GNCN_USER_CLERICAL_CONFIG
    WHERE 
      1 = 1
      AND (
        P_ACTIVE = '0'
        OR STATUS = 1
      )
      AND (
        P_USER_ID IS NULL
        OR UPPER(USER_ID) LIKE '%' || UPPER(P_USER_ID) || '%'
      )
      AND (
        P_BRANCH_CODE IS NULL
        OR UPPER(BRANCH_CODE) = UPPER(P_BRANCH_CODE)
      )
      AND (
        P_ALLOW_BRANCH IS NULL
        OR INSTR(UPPER(ALLOW_BRANCH), UPPER(P_ALLOW_BRANCH)) > 0
      )
    ORDER BY
      ID DESC;

END SP_SEARCH_GNCN_USER_CLERICAL_CONFIG;

