--------------------------------------------------------
--  DDL for Procedure SP_SEARCH_TRANSACTION_SYNC_TO_FLEX
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_SEARCH_TRANSACTION_SYNC_TO_FLEX" (
  p_json_object IN VARCHAR,
  OUT_DATA OUT SYS_REFCURSOR
) AS 
  json_obj JSON_OBJECT_T;
  P_FROM_DATE VARCHAR2(100) DEFAULT '';
  P_TO_DATE VARCHAR2(100) DEFAULT '';
  P_BRANCH VARCHAR2(100) DEFAULT '';
  P_ISSUE_BY VARCHAR2(100) DEFAULT '';
  P_SOURCE VARCHAR2(100) DEFAULT '';
  P_TRAN_ID VARCHAR2(100) DEFAULT '';
BEGIN 
  json_obj := JSON_OBJECT_T.parse(p_json_object);
  P_FROM_DATE := json_obj.get_String('fromDate');
  P_TO_DATE := json_obj.get_String('toDate');
  P_BRANCH := json_obj.get_String('branch');
  P_ISSUE_BY := json_obj.get_String('issueBy');
  P_SOURCE := json_obj.get_String('process');
  P_TRAN_ID := json_obj.get_String('transactionId');
OPEN OUT_DATA FOR
  SELECT
    t.SOURCE, t.GNTD_CODE, t.PDTD_CODE, t.BRANCH_CODE, t.CUSTOMER_CODE, t.CUSTOMER_NAME,
    t.APPROVAL_DATE, t.APPROVER, t.CREATED_AT, t.DOCUMENT_TYPE, t.LIST_DOCUMENTS
  FROM
    (SELECT
      SOURCE,
      DISBURSEMENT_CODE AS GNTD_CODE,
      CREDIT_APPROVAL_CODE AS PDTD_CODE,
      OFFICE_CODE AS BRANCH_CODE,
      CUSTOMER_CODE,
      CUSTOMER_NAME,
      APPROVED_DATE AS APPROVAL_DATE,
      ISSUED_USER AS APPROVER,
      TO_CHAR(CREATE_DATE, 'DD-MM-YYYY HH24:MI:SS') AS CREATED_AT,
      DOCUMENT_TYPE,
      LIST_DOCUMENTS,
      TO_DATE(APPROVED_DATE, 'YYYYMMDD') AS SORT_DATE
    FROM
      TD_MASTERDATA.GN_HOSOVATLY_BPM
    WHERE
      1 = 1
      AND (
        P_SOURCE IS NULL
        OR UPPER(SOURCE) = UPPER(P_SOURCE)
      )
      AND (
        P_ISSUE_BY IS NULL
        OR UPPER(ISSUED_USER) = UPPER(P_ISSUE_BY)
      )
      AND (
        P_TRAN_ID IS NULL
        OR UPPER(DISBURSEMENT_CODE) = UPPER(P_TRAN_ID)
      )
      AND (
        P_BRANCH IS NULL
        OR UPPER(OFFICE_CODE) = UPPER(P_BRANCH)
      )
      AND (
        P_FROM_DATE IS NULL
        OR TO_DATE(APPROVED_DATE, 'YYYYMMDD') >= TO_DATE(P_FROM_DATE, 'YYYY-MM-DD') 
      )
      AND (
        P_TO_DATE IS NULL
        OR TO_DATE(APPROVED_DATE, 'YYYYMMDD') <= TO_DATE(P_TO_DATE, 'YYYY-MM-DD')
      )
  ) t
  ORDER BY
    t.SORT_DATE DESC;

END SP_SEARCH_TRANSACTION_SYNC_TO_FLEX;

/
--------------------------------------------------------
--  DDL for Procedure SP_SIGN_CHECK_REPRESENT_COMPLETE
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_SIGN_CHECK_REPRESENT_COMPLETE" (
    P_TRANSACTION_CODE IN VARCHAR2,
    P_ACTION IN VARCHAR2,
    P_RES_MESSAGE OUT VARCHAR2
) IS
    v_total_docs NUMBER;
    v_signed_docs NUMBER;
    v_sign_fail NUMBER;
    v_process_type VARCHAR2(255);
BEGIN
    select process_type INTO v_process_type
    FROM SIGN_TRANSACTION where TRANSACTION_CODE = P_TRANSACTION_CODE;
    
    IF v_process_type = 'VNEID' THEN
        -- ??m t?ng s? DOC_ID c?n REPRESENT ký
        SELECT COUNT(*) INTO v_total_docs
        FROM SIGN_ATTACHMENT
        WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
        AND DOC_TYPE = 'NO_SIGN' AND REQUIRE_TPB_SIGN = 1 AND (MSG_FAIL IS NULL or MSG_FAIL != 'Ng??i dân t? ch?i ký');
    
        -- ??m s? DOC_ID ?ã REPRESENT ký thành công
        SELECT COUNT(*) INTO v_signed_docs
        FROM SIGN_ATTACHMENT
        WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
        AND DOC_TYPE = 'TPB_REPRESENT_SIGNED' AND REQUIRE_TPB_SIGN = 1;
        
         -- ??m s? DOC_ID ?ã ký thành công/ fail
        SELECT COUNT(*) INTO v_sign_fail
        FROM SIGN_ATTACHMENT
        WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
          AND (
          (DOC_TYPE = 'NO_SIGN' AND REQUIRE_TPB_SIGN = 1 AND REQUIRE_KH_SIGN = 0 AND STATUS = 'SIGN_FAILED')
          OR (DOC_TYPE = 'CUSTOMER_SIGNED' AND REQUIRE_KH_SIGN = 1 AND REQUIRE_TPB_SIGN = 1 AND STATUS = 'SIGN_FAILED')
          OR (DOC_TYPE = 'TPB_REPRESENT_SIGNED')
          );
    ELSIF v_process_type = 'HDBD' THEN
        -- ??m t?ng s? DOC_ID c?n REPRESENT ký
        SELECT COUNT(*) INTO v_total_docs
        FROM SIGN_ATTACHMENT
        WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
        AND DOC_TYPE = 'TPB_REPRESENT' AND REQUIRE_TPB_SIGN = 1;
    
        -- ??m s? DOC_ID ?ã REPRESENT ký thành công
        SELECT COUNT(*) INTO v_signed_docs
        FROM SIGN_ATTACHMENT
        WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
        AND DOC_TYPE = 'TPB_REPRESENT_SIGNED' AND REQUIRE_TPB_SIGN = 1 AND STATUS = 'NO_SIGN';
        
         -- ??m s? DOC_ID ?ã ký thành công/ fail
        SELECT COUNT(*) INTO v_sign_fail
        FROM SIGN_ATTACHMENT
        WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
          AND (
          (DOC_TYPE = 'TPB_REPRESENT' AND REQUIRE_TPB_SIGN = 1 AND STATUS = 'SIGN_FAILED')
          OR (DOC_TYPE = 'TPB_REPRESENT_SIGNED')
          );
    ELSIF v_process_type = 'KHDN' THEN
        -- ??m t?ng s? DOC_ID c?n REPRESENT ký
        SELECT COUNT(*) INTO v_total_docs
        FROM SIGN_ATTACHMENT
        WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
        AND DOC_TYPE IN ('NO_SIGN_TPB', 'CUSTOMER_SIGNED') AND REQUIRE_TPB_SIGN = 1;
    
        -- ??m s? DOC_ID ?ã REPRESENT ký thành công
        SELECT COUNT(*) INTO v_signed_docs
        FROM SIGN_ATTACHMENT
        WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
        AND DOC_TYPE = 'TPB_SIGNED' AND REQUIRE_TPB_SIGN = 1 AND STATUS = 'NO_SIGN';
        
         -- ??m s? DOC_ID ?ã ký thành công/ fail
        SELECT COUNT(*) INTO v_sign_fail
        FROM SIGN_ATTACHMENT
        WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
          AND (DOC_TYPE = 'TPB_SIGNED' OR STATUS = 'SIGN_FAILED') AND REQUIRE_TPB_SIGN = 1;
    END IF;
    
    IF P_ACTION IS NOT NULL THEN 
        IF v_total_docs > 0 AND v_total_docs = v_signed_docs THEN 
            P_RES_MESSAGE := 'SUCCESS';
            -- C?p nh?t tr?ng thái giao d?ch
            IF v_process_type = 'KHDN' THEN
                UPDATE SIGN_TRANSACTION SET APPROVAL_DATE = SYSDATE, STATUS = 'COMPLETE' WHERE TRANSACTION_CODE = P_TRANSACTION_CODE;
                INSERT INTO SIGN_HISTORY (TRANSACTION_CODE, ACTION, FRE_STATUS, STATUS) VALUES (P_TRANSACTION_CODE, 'TPB_REPRESENT_SIGNED', 'TPB_SIGN_REPRESENT', 'COMPLETE');
            ELSE
                UPDATE SIGN_TRANSACTION SET APPROVAL_DATE = SYSDATE WHERE TRANSACTION_CODE = P_TRANSACTION_CODE;
            END IF;
            COMMIT;
        ELSIF v_total_docs > 0 AND v_total_docs = v_sign_fail THEN
            P_RES_MESSAGE := 'SUCCESS_AND_FAIL';
        ELSE
            P_RES_MESSAGE := 'INCOMPLETE';
        END IF;
    ELSIF P_ACTION IS NULL THEN -- ONLY_CHECK
       -- Ki?m tra t?t c? ?ã ký ch?a
        IF v_total_docs > 0 AND v_total_docs = v_signed_docs and P_ACTION IS NULL THEN
            -- C?p nh?t tr?ng thái giao d?ch
            UPDATE SIGN_TRANSACTION SET STATUS = 'TPB_SIGN' WHERE TRANSACTION_CODE = P_TRANSACTION_CODE;
            -- C?p nh?t l?ch s? ký s?
            UPDATE SIGN_HISTORY SET MSG_FAIL = NULL WHERE TRANSACTION_CODE = P_TRANSACTION_CODE;
            -- Ghi l?ch s? ký s?
            INSERT INTO SIGN_HISTORY (TRANSACTION_CODE, ACTION, FRE_STATUS, STATUS) VALUES (P_TRANSACTION_CODE, 'TPB_REPRESENT_SIGNED', 'TPB_SIGN_REPRESENT', 'TPB_SIGN');
    
            COMMIT;
            P_RES_MESSAGE := 'SUCCESS';
        ELSIF v_total_docs > 0 AND v_total_docs = v_sign_fail THEN
            P_RES_MESSAGE := 'SUCCESS_AND_FAIL';
        ELSE
            P_RES_MESSAGE := 'INCOMPLETE';
        END IF;
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        P_RES_MESSAGE := 'ERROR: ' || SQLERRM;
END SP_SIGN_CHECK_REPRESENT_COMPLETE;

/
--------------------------------------------------------
--  DDL for Procedure SP_SIGN_CHECK_TPB_COMPLETE
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_SIGN_CHECK_TPB_COMPLETE" (
    P_TRANSACTION_CODE IN VARCHAR2,
    P_RES_MESSAGE OUT VARCHAR2
) IS
    v_total_docs NUMBER;
    v_signed_docs NUMBER;
    v_sign_fail NUMBER;
    v_sign_all NUMBER;
    v_process_type VARCHAR2(255);
    v_next_status  VARCHAR2(255);
BEGIN
    select process_type INTO v_process_type
    FROM SIGN_TRANSACTION where TRANSACTION_CODE = P_TRANSACTION_CODE;
    -- Xác ??nh tr?ng thái ti?p theo
    CASE v_process_type
        WHEN 'VNEID' THEN v_next_status := 'SEND_DOC_KH';
        WHEN 'HDBD' THEN v_next_status := 'COMPLETE';
    END CASE;
    
    -- ??m t?ng s? DOC_ID c?n TPB ký
    SELECT COUNT(*) INTO v_total_docs
    FROM SIGN_ATTACHMENT
    WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
      AND DOC_TYPE = 'TPB_REPRESENT_SIGNED'
      AND REQUIRE_TPB_SIGN = 1;

    -- ??m s? DOC_ID ?ã TPB ký thành công
    SELECT COUNT(*) INTO v_signed_docs
    FROM SIGN_ATTACHMENT
    WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
      AND DOC_TYPE = 'TPB_SIGNED'
      AND REQUIRE_TPB_SIGN = 1;
      
       -- ??m s? DOC_ID ?ã TPB ký l?i
    SELECT COUNT(*) INTO v_sign_fail
    FROM SIGN_ATTACHMENT
    WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
      AND DOC_TYPE = 'TPB_REPRESENT_SIGNED' AND STATUS = 'SIGN_FAILED'
      AND REQUIRE_TPB_SIGN = 1;
      
      -- ??m s? DOC_ID ?ã TPB ký thành công (c? l?i)
    SELECT COUNT(*) INTO v_sign_all
    FROM SIGN_ATTACHMENT
    WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
    AND (
	(DOC_TYPE = 'TPB_REPRESENT_SIGNED'
		AND REQUIRE_TPB_SIGN = 1
		AND STATUS = 'SIGN_FAILED')
	OR
	(DOC_TYPE = 'TPB_SIGNED'
		AND REQUIRE_TPB_SIGN = 1)
    );

    -- Ki?m tra t?t c? ?ã ký ch?a
    IF v_total_docs > 0 AND v_total_docs = v_signed_docs THEN
        -- C?p nh?t tr?ng thái giao d?ch
        UPDATE SIGN_TRANSACTION SET STATUS = v_next_status, SIGN_DATE_TPB = SYSDATE, UPDATED_DATE = SYSDATE WHERE TRANSACTION_CODE = P_TRANSACTION_CODE;
        -- C?p nh?t l?ch s? ký s?
        UPDATE SIGN_HISTORY SET MSG_FAIL = NULL WHERE TRANSACTION_CODE = P_TRANSACTION_CODE;
        -- Ghi l?ch s? ký s?
        INSERT INTO SIGN_HISTORY (TRANSACTION_CODE, ACTION, FRE_STATUS, STATUS) VALUES (P_TRANSACTION_CODE, 'TPB_SIGN', 'TPB_SIGN', v_next_status);

        P_RES_MESSAGE := 'SUCCESS';
    ELSE
        P_RES_MESSAGE := 'INCOMPLETE';
    END IF;
    
    -- Ki?m tra t?t c? ?ã ký ch?a (có l?i)
    IF v_total_docs > 0 AND v_sign_fail > 0 AND v_total_docs = v_sign_all THEN
        -- C?p nh?t th?i gian update giao d?ch
        UPDATE SIGN_TRANSACTION SET UPDATED_DATE = SYSDATE WHERE TRANSACTION_CODE = P_TRANSACTION_CODE;
        -- Ghi l?ch s? ký s?
        INSERT INTO SIGN_HISTORY (TRANSACTION_CODE, ACTION, FRE_STATUS, STATUS, MSG_FAIL) VALUES (P_TRANSACTION_CODE, 'TPB_SIGN', 'TPB_SIGN', 'TPB_SIGN', 'FAILED');
        P_RES_MESSAGE := 'DONE_FAILED';
    END IF;
COMMIT;
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        P_RES_MESSAGE := 'ERROR: ' || SQLERRM;
END SP_SIGN_CHECK_TPB_COMPLETE;

/
--------------------------------------------------------
--  DDL for Procedure SP_SIGN_CHECK_TRANSACTION_COMPLETE
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_SIGN_CHECK_TRANSACTION_COMPLETE" (
    P_TRANSACTION_CODE IN VARCHAR2,
    P_RES_MESSAGE OUT VARCHAR2
) IS
    v_total_docs NUMBER;
    v_signed_docs NUMBER;
BEGIN
    -- ??m t?ng s? DOC_ID c?n TPB ký
    SELECT COUNT(*) INTO v_total_docs
    FROM SIGN_ATTACHMENT
    WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
      AND DOC_TYPE = 'NO_SIGN'
      AND REQUIRE_TPB_SIGN = 1;

    -- ??m s? DOC_ID ?ã TPB ký thành công
    SELECT COUNT(*) INTO v_signed_docs
    FROM SIGN_ATTACHMENT
    WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
      AND DOC_TYPE = 'TPB_SIGNED'
      AND REQUIRE_TPB_SIGN = 1
      AND STATUS = 'SIGNED';

    -- Ki?m tra t?t c? ?ã ký ch?a
    IF v_total_docs > 0 AND v_total_docs = v_signed_docs THEN
        -- C?p nh?t tr?ng thái giao d?ch
        UPDATE SIGN_TRANSACTION
        SET STATUS = 'SEND_DOC_KH',
        SIGN_DATE_TPB = SYSDATE
        WHERE TRANSACTION_CODE = P_TRANSACTION_CODE;

        -- Ghi l?ch s? ký s?
        INSERT INTO SIGN_HISTORY (TRANSACTION_CODE, ACTION, FRE_STATUS, STATUS)
        VALUES (P_TRANSACTION_CODE, 'TPB_SIGN', 'TPB_SIGN', 'SEND_DOC_KH');

        COMMIT;
        P_RES_MESSAGE := 'SUCCESS';
    ELSE
        P_RES_MESSAGE := 'INCOMPLETE';
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        P_RES_MESSAGE := 'ERROR: ' || SQLERRM;
END SP_SIGN_CHECK_TRANSACTION_COMPLETE;

/
--------------------------------------------------------
--  DDL for Procedure SP_SIGN_CUSTOMER_REPLY_MAIL
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_SIGN_CUSTOMER_REPLY_MAIL" (
  p_json_object IN CLOB,
  P_RES_MESSAGE OUT VARCHAR2
) AS
  json_obj JSON_OBJECT_T;
  P_TRANSACTION_CODE VARCHAR2(100) DEFAULT '';
  P_MODIFIED_BY VARCHAR2(100) DEFAULT '';
  P_RS VARCHAR2(100) DEFAULT '0';
  P_STATUS VARCHAR2(100) DEFAULT '';
BEGIN
  json_obj := JSON_OBJECT_T.parse(p_json_object);
  P_TRANSACTION_CODE := json_obj.get_String('transactionCode');
  P_MODIFIED_BY := json_obj.get_String('modifiedBy');
  P_RS := json_obj.get_String('result');
  
  if (P_RS = '1') THEN
    UPDATE SIGN_TRANSACTION SET STATUS = 'KH_SIGN', UPDATED_DATE = SYSDATE WHERE TRANSACTION_CODE = P_TRANSACTION_CODE;
    INSERT INTO SIGN_HISTORY (TRANSACTION_CODE, ACTION, FRE_STATUS, STATUS, DESCRIPTION) VALUES (P_TRANSACTION_CODE, 'KH_CONFIRM', 'KH_CONFIRM', 'KH_SIGN', P_RS);
  ELSE
    UPDATE SIGN_TRANSACTION SET STATUS = 'CANCEL', UPDATED_BY = 'SYSTEM', UPDATED_DATE = SYSDATE WHERE TRANSACTION_CODE = P_TRANSACTION_CODE;
    INSERT INTO SIGN_HISTORY (TRANSACTION_CODE, ACTION, FRE_STATUS, STATUS, DESCRIPTION, MSG_FAIL) VALUES (P_TRANSACTION_CODE, 'KH_CONFIRM', 'KH_CONFIRM', 'KH_CONFIRM', P_RS, P_RS);
  END IF;

  UPDATE SIGN_RECEIVE_MAIL_KY_SO SET STATUS = 1, MODIFIED_DATE = SYSDATE WHERE MA_YC = P_TRANSACTION_CODE;

  COMMIT;

  P_RES_MESSAGE := 'SUCCESS';

EXCEPTION
  WHEN OTHERS THEN
    P_RES_MESSAGE := 'ERROR: ' || SQLERRM;

END SP_SIGN_CUSTOMER_REPLY_MAIL;

/
--------------------------------------------------------
--  DDL for Procedure SP_SIGN_EBANK_GET_HISTORY
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_SIGN_EBANK_GET_HISTORY" (
    p_cif              IN VARCHAR2,
    p_transaction_code IN VARCHAR2,
    p_from_date        IN VARCHAR2,
    p_to_date          IN VARCHAR2,
    p_status_kh        IN VARCHAR2,
    p_status_sign      IN VARCHAR2,
    p_page_number      IN NUMBER,
    p_page_size        IN NUMBER,
    p_total_records    OUT NUMBER,
    p_result           OUT CLOB
) AS
    v_from_date         DATE;
    v_to_date_exclusive DATE;
    v_page_number       NUMBER;
    v_page_size         NUMBER;
    v_offset            NUMBER;
BEGIN
    v_from_date :=
        CASE
            WHEN p_from_date IS NOT NULL THEN
                TO_DATE ( p_from_date, 'YYYY-MM-DD' )
        END;
    v_to_date_exclusive :=
        CASE
            WHEN p_to_date IS NOT NULL THEN
                TO_DATE ( p_to_date, 'YYYY-MM-DD' ) + 1
        END;

    /*
     * P_PAGE_NUMBER b?t ??u t? 1.
     *
     * Không truy?n pageNumber: m?c ??nh trang 1.
     * Không truy?n pageSize: m?c ??nh 100 b?n ghi.
     */
    v_page_number := nvl(p_page_number, 1);
    v_page_size := nvl(p_page_size, 100);
    v_offset := ( v_page_number - 1 ) * v_page_size;

    /*
     * ??m riêng t?ng s? b?n ghi.
     *
     * statusKH và statusSign là 2 ?i?u ki?n ??c l?p.
     *
     * statusKH:
     *   Filter tr?c ti?p theo ST.STATUS_KH.
     *
     * statusSign:
     *   COMPLETE    -> ST.STATUS = COMPLETE
     *   SIGNING     -> ST.STATUS thu?c nhóm ?ang ký
     *   SIGN_FAILED -> ST.STATUS = CREATE và có l?ch s? l?i
     *   CANCEL      -> ST.STATUS = CANCEL
     */
    SELECT
        COUNT(*)
    INTO p_total_records
    FROM
        sign_transaction st
    WHERE
        st.borrower_ebank IS NOT NULL
        AND ( p_cif IS NULL
              OR instr(','
                       || st.borrower_ebank
                       || ',', ','
                               || p_cif
                               || ',') > 0 )
        AND ( p_transaction_code IS NULL
              OR st.transaction_code = p_transaction_code )
        AND ( v_from_date IS NULL
              OR st.created_date >= v_from_date )
        AND ( v_to_date_exclusive IS NULL
              OR st.created_date < v_to_date_exclusive )
        AND st.process_type = 'VNEID'
        AND st.id > 6310
      -- Filter statusKH
        AND ( ( p_status_kh IS NULL
                AND st.status_kh IN ( 'PENDING', 'CONFIRMED', 'EXPIRED', 'REJECTED' ) )
              OR ( p_status_kh IS NOT NULL
                   AND instr(','
                             || p_status_kh
                             || ',', ','
                                     || st.status_kh
                                     || ',') > 0 ) )
    -- Filter statusSign
        AND ( p_status_sign IS NULL
              OR ( instr(','
                         || p_status_sign
                         || ',',
                         ','
                         ||
                         CASE
                                   WHEN st.status = 'COMPLETE' THEN 'COMPLETE'
                                   WHEN st.status IN('KH_CONFIRM', 'KH_SIGN', 'SEND_TO_VNEID', 'TPB_SIGN_REPRESENT', 'SEND_DOC_KH') THEN 'SIGNING'
                                   WHEN st.status = 'CREATE'
                                        AND(
                                       SELECT
                                           COUNT(*)
                                       FROM
                                           sign_history sh
                                       WHERE
                                           sh.transaction_code = st.transaction_code
                                   ) > 1 THEN
                                       'SIGN_FAILED'
                                   WHEN st.status = 'CANCEL'   THEN
                                       'CANCEL'
                                   ELSE
                                       ''
                         END
                         || ',') > 0 ) );

    WITH page_tx AS (
        /*
         * L?y danh sách giao d?ch thu?c trang hi?n t?i.
         *
         * Trang 1: OFFSET 0
         * Trang 2: OFFSET pageSize
         * Trang 3: OFFSET pageSize * 2
         */
        SELECT
            st.*
        FROM
            sign_transaction st
        WHERE
            st.borrower_ebank IS NOT NULL
            AND ( p_cif IS NULL
                  OR instr(','
                           || st.borrower_ebank
                           || ',', ','
                                   || p_cif
                                   || ',') > 0 )
            AND ( p_transaction_code IS NULL
                  OR st.transaction_code = p_transaction_code )
            AND ( v_from_date IS NULL
                  OR st.created_date >= v_from_date )
            AND ( v_to_date_exclusive IS NULL
                  OR st.created_date < v_to_date_exclusive )
            AND st.process_type = 'VNEID'
            AND st.id > 6310
          -- Filter statusKH
            AND ( ( p_status_kh IS NULL
                    AND st.status_kh IN ( 'PENDING', 'CONFIRMED', 'EXPIRED', 'REJECTED' ) )
                  OR ( p_status_kh IS NOT NULL
                       AND instr(','
                                 || p_status_kh
                                 || ',', ','
                                         || st.status_kh
                                         || ',') > 0 ) )
          -- Filter statusSign
            AND ( p_status_sign IS NULL
                  OR ( instr(','
                             || p_status_sign
                             || ',',
                             ','
                             ||
                             CASE
                                           WHEN st.status = 'COMPLETE' THEN 'COMPLETE'
                                           WHEN st.status IN ('KH_SIGN', 'SEND_TO_VNEID', 'TPB_SIGN_REPRESENT', 'SEND_DOC_KH') THEN 'SIGNING'
                                           WHEN st.status = 'CREATE' AND st.status_kh IS NOT NULL THEN 'SIGN_FAILED'
                                           WHEN st.status = 'CANCEL' THEN 'CANCEL'
                                           ELSE ''
                             END
                             || ',') > 0 ) )
        ORDER BY
            st.created_date DESC,
            st.transaction_code DESC
        OFFSET v_offset ROWS FETCH NEXT v_page_size ROWS ONLY
    ), history_agg AS (
        /*
         * T?ng h?p l?ch s? theo t?ng giao d?ch.
         *
         * Ch? ??c l?ch s? c?a các giao d?ch trong trang hi?n t?i.
         */
        SELECT
            sh.transaction_code,
            MAX(
                CASE
                    WHEN sh.action = 'NEXT_KH_SIGN'
                         AND sh.fre_status = 'CREATE'
                         AND sh.status = 'KH_CONFIRM' THEN
                        sh.created_date
                END
            ) AS sign_request_time,
            MAX(
                CASE
                    WHEN sh.action = 'KH_CONFIRM'
                         AND sh.fre_status = 'KH_CONFIRM'
                         AND(sh.status = 'KH_SIGN' OR sh.status = 'CANCEL')
                         THEN sh.created_date
                END
            ) AS customer_confirm_time,
            MAX(
                CASE
--                    WHEN sh.action = 'KH_CONFIRM' AND sh.fre_status = 'KH_SIGN' AND sh.action = 'CANCEL'
--                        THEN sh.created_date
                    WHEN sh.action = 'SEND_TO_VNEID' AND sh.msg_fail IS NOT NULL 
                        THEN sh.created_date
                    WHEN sh.action = 'SEND_TO_VNEID' AND sh.fre_status = 'KH_SIGN'
                        AND (sh.status = 'TPB_SIGN_REPRESENT' OR sh.status = 'SEND_DOC_KH' OR sh.status = 'CREATE')
                        THEN sh.created_date
                END
            ) AS customer_sign_time,
            MAX(
                CASE
                    WHEN sh.action = 'SEND_TO_VNEID'--SH.ACTION = 'KH_SIGN'
                         AND sh.msg_fail IS NOT NULL THEN
                        1
                    ELSE
                        0
                END
            ) AS has_sign_fail
        FROM
                 sign_history sh
            INNER JOIN page_tx t ON t.transaction_code = sh.transaction_code
        GROUP BY
            sh.transaction_code
    ), borrower_agg AS (
        SELECT
            t.transaction_code,
            LISTAGG(jt.full_name, ', ') WITHIN GROUP(
            ORDER BY
                jt.position
            )               AS customer_name,
            JSON_ARRAYAGG(
                JSON_OBJECT(
                    'cif' VALUE jt.cif,
                    'signerIdType' VALUE jt.doctype,
                    'signerId' VALUE jt.idcard,
                    'signerName' VALUE jt.full_name,
                    'signerStatus' VALUE jt.signer_status,
                    'reason' VALUE jt.reason
                RETURNING CLOB)
            ORDER BY
                jt.position
            RETURNING CLOB) AS signers
        FROM
            page_tx t
            CROSS APPLY
                JSON_TABLE ( t.borrower_data, '$[*]'
                    COLUMNS (
                        position FOR ORDINALITY,
                        cif VARCHAR2 ( 50 ) PATH '$.cif',
                        doctype VARCHAR2 ( 100 ) PATH '$.docType',
                        idcard VARCHAR2 ( 100 ) PATH '$.idCard',
                        full_name VARCHAR2 ( 255 ) PATH '$.fullName',
                        signer_status VARCHAR2 ( 100 ) PATH '$.signerStatus',
                        reason VARCHAR2 ( 2000 ) PATH '$.reason'
                    )
                )
            jt
        WHERE
            instr(','
                  || t.borrower_ebank
                  || ',', ','
                          || jt.cif
                          || ',') > 0
        GROUP BY
            t.transaction_code
    ), attachment_base AS (
        SELECT
            a.transaction_code,
            a.doc_id,
            a.doc_name,
            a.doc_type,
            a.created_date,
            JSON_VALUE(a.meta_data, '$.fileNameOrigin') AS file_name_origin,
            ROW_NUMBER()
            OVER(PARTITION BY a.transaction_code,
                       JSON_VALUE(a.meta_data, '$.fileNameOrigin')
                 ORDER BY
                     CASE a.doc_type
                         WHEN 'TPB_SIGNED'           THEN
                             1
                         WHEN 'TPB_REPRESENT_SIGNED' THEN
                             2
                         WHEN 'CUSTOMER_SIGNED'      THEN
                             3
                         WHEN 'NO_SIGN'              THEN
                             4
                         ELSE
                             99
                     END,
                     a.created_date DESC
            )                                           AS rn
        FROM
                 sign_attachment a
            INNER JOIN page_tx t ON t.transaction_code = a.transaction_code
        WHERE
                a.require_kh_sign = 1
            AND a.doc_type IN ( 'TPB_SIGNED', 'TPB_REPRESENT_SIGNED', 'CUSTOMER_SIGNED', 'NO_SIGN' )
    ), file_agg AS (
        SELECT
            a.transaction_code,
            JSON_ARRAYAGG(
                JSON_OBJECT(
                    -- 'ecmId' VALUE '{' || REPLACE(A.DOC_ID, 'idd_', '') || '}',
                    'ecmId' VALUE '{55C909F8-EDBD-C7A0-872E-9F89CAB00000}',
                    'fileName' VALUE a.doc_name
                RETURNING CLOB)
            ORDER BY
                a.created_date
            RETURNING CLOB) AS files
        FROM
            attachment_base a
        WHERE
            a.rn = 1
        GROUP BY
            a.transaction_code
    )
    SELECT
        nvl(JSON_ARRAYAGG(
            JSON_OBJECT(
                'transactionCode' VALUE t.transaction_code,
                        'pdtdCode' VALUE t.pdtd_code,
                        'signRequestTime' VALUE
                    CASE WHEN h.sign_request_time IS NOT NULL THEN
                            to_char(from_tz(CAST(h.sign_request_time AS TIMESTAMP), '+07:00') AT TIME ZONE 'UTC',
                                    'YYYY-MM-DD"T"HH24:MI:SS"Z"')
                    END,
                        'customerConfirmTime' VALUE
                    CASE WHEN h.customer_confirm_time IS NOT NULL THEN
                            to_char(from_tz(CAST(h.customer_confirm_time AS TIMESTAMP), '+07:00') AT TIME ZONE 'UTC',
                                    'YYYY-MM-DD"T"HH24:MI:SS"Z"')
                    END,
                        'customerSignTime' VALUE
                    CASE WHEN h.customer_sign_time IS NOT NULL THEN
                            to_char(from_tz(CAST(h.customer_sign_time AS TIMESTAMP), '+07:00') AT TIME ZONE 'UTC',
                                    'YYYY-MM-DD"T"HH24:MI:SS"Z"')
                    END,
                        'statusKH' VALUE t.status_kh,
                        'statusSign' VALUE
                    CASE WHEN t.status = 'COMPLETE' THEN 'COMPLETE'
                        WHEN t.status IN ('KH_CONFIRM', 'KH_SIGN', 'SEND_TO_VNEID', 'TPB_SIGN_REPRESENT', 'SEND_DOC_KH') THEN 'SIGNING'
--                        WHEN t.status = 'CREATE' AND t.status_kh IS NOT NULL THEN 'SIGN_FAILED'
                        WHEN t.status = 'CREATE' AND nvl(h.has_sign_fail, 0) = 1 THEN 'SIGN_FAILED'
                        WHEN t.status = 'CANCEL' THEN 'CANCEL'
                        ELSE ''
                    END,
                        'loanAmount' VALUE t.loan_amount,
                        'purposeEN' VALUE t.product_code,
                        'purpose' VALUE t.purpose_ebank,
                        'signMethodEN' VALUE 'VNEID',
                        'signMethod' VALUE 'Ký s? trên VNeID',
                        'customerName' VALUE nvl(b.customer_name, ''),
                        'signers' VALUE nvl(b.signers, to_clob('[]'))
            FORMAT JSON, 'files' VALUE nvl(f.files, to_clob('[]'))
            FORMAT JSON RETURNING CLOB)
        ORDER BY
            t.created_date DESC,
            t.transaction_code DESC
        RETURNING CLOB),
            to_clob('[]'))
    INTO p_result
    FROM
        page_tx      t
        LEFT JOIN history_agg  h ON h.transaction_code = t.transaction_code
        LEFT JOIN borrower_agg b ON b.transaction_code = t.transaction_code
        LEFT JOIN file_agg     f ON f.transaction_code = t.transaction_code;

END sp_sign_ebank_get_history;

/
--------------------------------------------------------
--  DDL for Procedure SP_SIGN_FETCH_MAIL_SIGNATURE_RECEIVE
--------------------------------------------------------
set define off;

  CREATE OR REPLACE NONEDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_SIGN_FETCH_MAIL_SIGNATURE_RECEIVE" (
  p_json_object IN CLOB,
  P_RES_MESSAGE OUT VARCHAR2
) AS
  json_obj JSON_OBJECT_T;
  
  P_TRANSACTION_CODE VARCHAR2(100) DEFAULT '';
  P_PRE_STATUS VARCHAR2(100) DEFAULT '';
  P_STATUS VARCHAR2(100) DEFAULT '';
  P_ECM_ID VARCHAR2(100) DEFAULT '';
  P_FILE_NAME VARCHAR2(500) DEFAULT '';
  P_SIGNATURE_INFO VARCHAR2(4000) DEFAULT '[]';
  P_META_DATA VARCHAR2(4000) DEFAULT '{}';
  P_REQUIRED_KH NUMBER DEFAULT 0;
  P_REQUIRED_TPB NUMBER DEFAULT 0;
  P_MODIFIED_BY VARCHAR2(500) DEFAULT '';
  P_FILES JSON_ARRAY_T DEFAULT NULL;
  v_object JSON_OBJECT_T;
  v_element JSON_ELEMENT_T;
  v_size PLS_INTEGER;
BEGIN
  json_obj := JSON_OBJECT_T.parse(p_json_object);
  P_MODIFIED_BY := json_obj.get_String('modifiedBy');
  P_TRANSACTION_CODE := json_obj.get_String('transactionCode');
  P_PRE_STATUS := json_obj.get_String('preStatus');
  P_STATUS := json_obj.get_String('status');
  P_FILES := json_obj.get_Array('files');
  v_size := P_FILES.get_size;

  IF (v_size > 0) THEN
    FOR i IN 0.. v_size -1 LOOP
      v_element := P_FILES.get(i);
      IF (v_element IS NOT NULL) THEN
        v_object := TREAT (v_element AS JSON_OBJECT_T);
        P_ECM_ID:= v_object.get_String('docId');
        P_FILE_NAME:= v_object.get_String('docName');
        P_SIGNATURE_INFO:= v_object.get_String('signatureInfo');
        P_META_DATA:= v_object.get_String('info');
        P_REQUIRED_KH:= v_object.get_Number('requireKHSign');
        P_REQUIRED_TPB:= v_object.get_Number('requireTpbSign');
        
        -- update row c? v? tr?ng thái m?i
        UPDATE SIGN_ATTACHMENT set DOC_TYPE = 'CUSTOMER_SIGNED', STATUS = 'SIGNED', DOC_NAME = P_FILE_NAME where DOC_ID = P_ECM_ID;
      END IF;
    END LOOP;
  END IF;

  -------------------------------------------------------------------
  DBMS_OUTPUT.PUT_LINE('v_size=' || v_size);
  UPDATE sign_transaction SET STATUS = P_STATUS, SIGN_DATE_KH = sysdate, UPDATED_DATE = sysdate WHERE TRANSACTION_CODE = P_TRANSACTION_CODE;
  
  INSERT INTO sign_history (
          TRANSACTION_CODE, ACTION, FRE_STATUS, STATUS
        ) VALUES (
          P_TRANSACTION_CODE,
          'SEND_TO_VNEID',
          P_PRE_STATUS,
          P_STATUS
        );

  COMMIT;

  P_RES_MESSAGE := 'SUCCESS';

EXCEPTION
  WHEN OTHERS THEN
    P_RES_MESSAGE := 'ERROR: ' || SQLERRM;

END SP_SIGN_FETCH_MAIL_SIGNATURE_RECEIVE;

/
--------------------------------------------------------
--  DDL for Procedure SP_SIGN_JOB_CANCEL_TRANSACTION
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_SIGN_JOB_CANCEL_TRANSACTION" (
    P_OUT_CURSOR OUT SYS_REFCURSOR,
    P_RES_MESSAGE OUT VARCHAR2
) AS
-- JOB này gi? dùng cho Ebank 24h
    CURSOR cur_trans IS
        SELECT TRANSACTION_CODE
        FROM SIGN_TRANSACTION
        WHERE STATUS = 'KH_CONFIRM'
          AND UPDATED_DATE <= SYSDATE - (72/24);   -- quá 72h (72/24)
--        AND UPDATED_DATE <= SYSDATE - 1;
BEGIN
    -------------------------------------------------------------------
    -- 1) M? cursor tr? ra cho Java
    -------------------------------------------------------------------
    OPEN P_OUT_CURSOR FOR
        SELECT TRANSACTION_CODE
        FROM SIGN_TRANSACTION
        WHERE STATUS = 'KH_CONFIRM'
        AND UPDATED_DATE <= SYSDATE - (72/24);
--        AND UPDATED_DATE <= SYSDATE - 1;
          

    -------------------------------------------------------------------
    -- 2) Loop t?ng record ?? update + insert l?ch s?
    -------------------------------------------------------------------
    FOR rec IN cur_trans LOOP
        UPDATE SIGN_TRANSACTION
           SET STATUS = 'CANCEL',
               UPDATED_DATE = SYSDATE
         WHERE TRANSACTION_CODE = rec.TRANSACTION_CODE;

        INSERT INTO SIGN_HISTORY (
            TRANSACTION_CODE,
            ACTION,
            FRE_STATUS,
            STATUS,
            MSG_FAIL
        ) VALUES (
            rec.TRANSACTION_CODE,
            'CANCEL',
            'KH_CONFIRM',
            'KH_CONFIRM',
            'Quá th?i gian ph?n h?i c?a KH t? Ebank'
        );
    END LOOP;

    COMMIT;
    P_RES_MESSAGE := 'SUCCESS';

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        P_RES_MESSAGE := 'ERROR: ' || SQLERRM;
END SP_SIGN_JOB_CANCEL_TRANSACTION;

/
--------------------------------------------------------
--  DDL for Procedure SP_SIGN_JOB_KH_CONFIRM_EBANK
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_SIGN_JOB_KH_CONFIRM_EBANK" (
    P_OUT_CURSOR OUT SYS_REFCURSOR,
    P_RES_MESSAGE OUT VARCHAR2
) AS
-- JOB này gi? dùng cho Ebank 24h
    CURSOR cur_trans IS
        SELECT TRANSACTION_CODE
        FROM SIGN_TRANSACTION
        WHERE STATUS = 'KH_CONFIRM'
        AND STATUS_KH = 'PENDING'
        AND PROCESS_TYPE = 'VNEID'
--        AND (TRANSACTION_CODE = 'KS07726100200002' or TRANSACTION_CODE = 'KS07726100200003')
        AND UPDATED_DATE >= SYSDATE - 2
        AND UPDATED_DATE <= SYSDATE - 1;
--        AND UPDATED_DATE <= SYSDATE - INTERVAL '1' MINUTE;
BEGIN
    -------------------------------------------------------------------
    -- 1) M? cursor tr? ra cho Java
    -------------------------------------------------------------------
    OPEN P_OUT_CURSOR FOR
        SELECT TRANSACTION_CODE
        FROM SIGN_TRANSACTION
        WHERE STATUS = 'KH_CONFIRM'
        AND STATUS_KH = 'PENDING'
        AND PROCESS_TYPE = 'VNEID'
--        AND (TRANSACTION_CODE = 'KS07726100200002' or TRANSACTION_CODE = 'KS07726100200003')
        AND UPDATED_DATE >= SYSDATE - 2
        AND UPDATED_DATE <= SYSDATE - 1;
--        AND UPDATED_DATE <= SYSDATE - INTERVAL '1' MINUTE;
    -------------------------------------------------------------------
    -- 2) Loop t?ng record ?? update + insert l?ch s?
    -------------------------------------------------------------------
    FOR rec IN cur_trans LOOP
        UPDATE SIGN_TRANSACTION
        SET STATUS = 'CANCEL',
            STATUS_KH = 'EXPIRED',
            UPDATED_DATE = SYSDATE,
            BORROWER_DATA = (
            SELECT JSON_SERIALIZE(
                       JSON_ARRAYAGG(
                           CASE
                               WHEN JSON_VALUE(obj, '$.signerStatus') = 'PENDING'
                               THEN JSON_TRANSFORM(
                                   obj,
                                   SET '$.signerStatus' = 'EXPIRED',
                                   SET '$.reason' = 'Quá th?i h?n nh?n ph?n h?i c?a KH'
                               )
                               ELSE obj
                           END FORMAT JSON
                           ORDER BY idx
                           RETURNING CLOB
                       )
                       RETURNING CLOB
                   )
            FROM JSON_TABLE(
                BORROWER_DATA,
                '$[*]'
                COLUMNS (
                    idx FOR ORDINALITY,
                    obj CLOB FORMAT JSON PATH '$'
                )
            )
        )
         WHERE TRANSACTION_CODE = rec.TRANSACTION_CODE;

        INSERT INTO SIGN_HISTORY (
            TRANSACTION_CODE,
            ACTION,
            FRE_STATUS,
            STATUS,
            description,
            MSG_FAIL
        ) VALUES (
            rec.TRANSACTION_CODE,
            'KH_CONFIRM',
            'KH_CONFIRM',
            'KH_CONFIRM',
            'Quá th?i h?n nh?n ph?n h?i c?a KH',
            'FAIL'
        );
        INSERT INTO SIGN_HISTORY (
            TRANSACTION_CODE,
            ACTION,
            FRE_STATUS,
            STATUS,
            description
        ) VALUES (
            rec.TRANSACTION_CODE,
            'CANCEL',
            'KH_CONFIRM',
            'CANCEL',
            'Quá th?i h?n nh?n ph?n h?i c?a KH'
        );
    END LOOP;

    COMMIT;
    P_RES_MESSAGE := 'SUCCESS';

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK;
        P_RES_MESSAGE := 'ERROR: ' || SQLERRM;
END SP_SIGN_JOB_KH_CONFIRM_EBANK;

/
--------------------------------------------------------
--  DDL for Procedure SP_SIGN_REQUEST_TO_VNEID
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_SIGN_REQUEST_TO_VNEID" (
  p_json_object IN CLOB,
  P_RES_MESSAGE OUT VARCHAR2
) AS
  json_obj JSON_OBJECT_T;
  P_TRANSACTION_CODE VARCHAR2(100) DEFAULT '';
  P_STATUS VARCHAR2(100) DEFAULT '';
  P_ACTION VARCHAR2(100) DEFAULT '';
  P_RS VARCHAR2(100) DEFAULT '0';
BEGIN
  json_obj := JSON_OBJECT_T.parse(p_json_object);
  P_TRANSACTION_CODE := json_obj.get_String('transactionCode');

  P_ACTION := json_obj.get_String('action');
  P_STATUS := json_obj.get_String('status');
  P_RS := json_obj.get_String('result');
  

IF (P_RS = 'SUCCESS') THEN
    INSERT INTO SIGN_HISTORY (TRANSACTION_CODE, ACTION, FRE_STATUS, STATUS, DESCRIPTION) SELECT
        TRANSACTION_CODE,
        P_ACTION AS ACTION,
        STATUS AS FRE_STATUS,
        P_STATUS AS STATUS,
        '??ng ý' AS DESCRIPTION FROM SIGN_TRANSACTION WHERE TRANSACTION_CODE = P_TRANSACTION_CODE;
      
    UPDATE SIGN_TRANSACTION SET STATUS = P_STATUS, UPDATED_DATE = SYSDATE WHERE TRANSACTION_CODE = P_TRANSACTION_CODE;
    
    UPDATE sign_attachment set MSG_FAIL = null, STATUS = 'NO_SIGN' where TRANSACTION_CODE = P_TRANSACTION_CODE and DOC_TYPE = 'NO_SIGN' and MSG_FAIL is not null and MSG_FAIL != 'Ng??i dân t? ch?i ký';-- reset l?i c?a b??c g?i tr??c - todo xóa MSG_FAIL
    P_RES_MESSAGE := 'SUCCESS';
    
ELSIF (P_RS = 'FAILED') THEN
    P_RES_MESSAGE := '';--x?y ra l?i m?i có giá tr?
    INSERT INTO SIGN_HISTORY (TRANSACTION_CODE, ACTION, FRE_STATUS, STATUS, DESCRIPTION, MSG_FAIL) SELECT
        TRANSACTION_CODE,
        P_ACTION AS ACTION,
        STATUS AS FRE_STATUS,
        P_STATUS AS STATUS,
        'Không ??ng ý' AS DESCRIPTION,
        P_RS AS MSG_FAIL FROM SIGN_TRANSACTION WHERE TRANSACTION_CODE = P_TRANSACTION_CODE;
        
    UPDATE SIGN_TRANSACTION SET STATUS = 'CREATE', UPDATED_DATE = SYSDATE WHERE TRANSACTION_CODE = P_TRANSACTION_CODE;
      
END IF;

COMMIT;

EXCEPTION
  WHEN OTHERS THEN
    P_RES_MESSAGE := 'ERROR: ' || SQLERRM;

END SP_SIGN_REQUEST_TO_VNEID;

/
--------------------------------------------------------
--  DDL for Procedure SP_SIGN_SAVE_ATTACHMENT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_SIGN_SAVE_ATTACHMENT" (
  p_json_object IN CLOB,
  P_MODIFIED_BY IN VARCHAR2,
  P_RES_MESSAGE OUT VARCHAR2
) AS 
  json_obj JSON_OBJECT_T;
  P_TRANSACTION_CODE VARCHAR2(200) DEFAULT '';
  P_STATUS VARCHAR2(200) DEFAULT '';
  P_DOC_ID VARCHAR2(200) DEFAULT '';
  P_DOC_NAME VARCHAR2(200) DEFAULT '';
  P_DOC_TYPE VARCHAR2(200) DEFAULT '';
  P_FILE_HASH VARCHAR2(200) DEFAULT '';
  P_META_DATA VARCHAR2(4000) DEFAULT '';
  P_SIGN_POSITION VARCHAR2(4000) DEFAULT '';
  P_REQUIRE_KH_SIGN INT DEFAULT 0;
  P_REQUIRE_TPB_SIGN INT DEFAULT 0;
  P_COUNT INT DEFAULT 0;
  P_RECORD_ID INT DEFAULT 0;
BEGIN 
  json_obj := JSON_OBJECT_T.parse(p_json_object);
  P_TRANSACTION_CODE := json_obj.get_String('transactionCode');
  P_STATUS := json_obj.get_String('status');
  P_DOC_ID := json_obj.get_String('docId');
  P_DOC_NAME := json_obj.get_String('docName');
  P_DOC_TYPE := json_obj.get_String('docType');
  P_META_DATA := json_obj.get_String('metaData');
  P_SIGN_POSITION := json_obj.get_String('signatureInfo');
  P_REQUIRE_KH_SIGN := json_obj.get_Number('requireKHSign');
  P_REQUIRE_TPB_SIGN := json_obj.get_Number('requireTpbSign');

  SELECT COUNT(*) INTO P_COUNT FROM SIGN_ATTACHMENT WHERE DOC_ID = P_DOC_ID;

  IF (P_COUNT IS NULL OR P_COUNT < 1) THEN
    INSERT INTO SIGN_ATTACHMENT (
      TRANSACTION_CODE,
      STATUS,
      DOC_ID,
      DOC_NAME,
      DOC_TYPE,
      SIGNATURE_INFO,
      META_DATA,
      REQUIRE_KH_SIGN,
	  REQUIRE_TPB_SIGN,
      CREATED_BY
    ) VALUES (
      P_TRANSACTION_CODE,
      P_STATUS,
      P_DOC_ID,
      P_DOC_NAME,
      P_DOC_TYPE,
      P_SIGN_POSITION,
      P_META_DATA,
      P_REQUIRE_KH_SIGN,
	  P_REQUIRE_TPB_SIGN,
      P_MODIFIED_BY
    )
    RETURNING ID INTO P_RECORD_ID;    
    COMMIT;
    P_RES_MESSAGE:='INSERT SUCCESSFULLY';
  ELSE
    UPDATE SIGN_ATTACHMENT 
    SET
      TRANSACTION_CODE = P_TRANSACTION_CODE,
      STATUS = P_STATUS,
      DOC_NAME = P_DOC_NAME,
      DOC_TYPE = P_DOC_TYPE,
      SIGNATURE_INFO = P_SIGN_POSITION,
      META_DATA = P_META_DATA,
      -- ch? update c?t Yêu c?u ký s? ? tr?ng thái ban ??u
      REQUIRE_KH_SIGN = CASE 
                          WHEN P_STATUS = 'CREATE' THEN P_REQUIRE_KH_SIGN 
                          ELSE REQUIRE_KH_SIGN 
                        END,
      REQUIRE_TPB_SIGN = CASE 
                           WHEN P_STATUS = 'CREATE' THEN P_REQUIRE_TPB_SIGN 
                           ELSE REQUIRE_TPB_SIGN 
                         END,
      UPDATED_BY = P_MODIFIED_BY,
      UPDATED_DATE = SYSDATE
    WHERE DOC_ID = P_DOC_ID;
    
    COMMIT;
    P_RES_MESSAGE:='UPDATE SUCCESSFULLY';
  END IF;

END SP_SIGN_SAVE_ATTACHMENT;

/
--------------------------------------------------------
--  DDL for Procedure SP_SIGN_SAVE_ATTACHMENT_SIGNED
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_SIGN_SAVE_ATTACHMENT_SIGNED" (
    p_json_object IN CLOB,
    p_modified_by IN VARCHAR2,
    p_res_message OUT VARCHAR2
) AS

    json_obj          json_object_t;
    p_doc_id          VARCHAR2(200) DEFAULT '';
    p_doc_name        VARCHAR2(300) DEFAULT '';
    p_ecm_signed      VARCHAR2(200) DEFAULT '';
    p_doc_type        VARCHAR2(200) DEFAULT '';
    p_status          VARCHAR2(200) DEFAULT '';
    p_meta_data       VARCHAR2(4000) DEFAULT '';
    v_signature_array json_array_t;
    v_signature_obj   json_object_t;
    v_new_signature   VARCHAR2(4000) DEFAULT '';
    i                 INTEGER;
BEGIN
    json_obj := json_object_t.parse(p_json_object);
    p_doc_id := json_obj.get_string('docId');
    p_doc_name := json_obj.get_string('docName');
    p_ecm_signed := json_obj.get_string('ecmSigned');
    p_doc_type := json_obj.get_string('docType');
    p_status := json_obj.get_string('docStatus');
    p_meta_data := json_obj.get_string('metaData');
    
    UPDATE sign_attachment SET status = p_status WHERE doc_id = p_doc_id;

    p_res_message := 'UPDATE SUCCESSFULLY';
    IF ( p_ecm_signed IS NOT NULL ) THEN
    -- L?y SIGNATURE_INFO c?a b?n ghi g?c
        SELECT signature_info INTO v_new_signature FROM sign_attachment
        WHERE doc_id = p_doc_id AND ROWNUM = 1;
     -- Parse ra JSON array
        v_signature_array := json_array_t.parse(v_new_signature);
        IF p_doc_type = 'TPB_REPRESENT_SIGNED' THEN
            -- Duy?t các ph?n t?
            FOR i IN 0..v_signature_array.get_size - 1 LOOP
                v_signature_obj := TREAT(v_signature_array.get(i) AS json_object_t);
                -- Ch? ch?nh ph?n t? có idCard = null
                IF v_signature_obj.get_string('idCard') IS NULL THEN
                    v_signature_obj.put('y', v_signature_obj.get_number('y') + 100);
                END IF;
            END LOOP;
        END IF;
    -- Chuy?n m?ng JSON v? VARCHAR2
        v_new_signature := v_signature_array.stringify;
        INSERT INTO sign_attachment (
            transaction_code,
            status,
            doc_id,
            doc_name,
            doc_type,
            signature_info,
            meta_data,
            require_kh_sign,
            require_tpb_sign,
            created_by,
            origin_doc_id
        )
            SELECT
                transaction_code,
                'NO_SIGN'       AS status,
                p_ecm_signed    AS doc_id,
                p_doc_name      AS doc_name,
                p_doc_type      AS doc_type,
                v_new_signature AS signature_info,
                p_meta_data     AS meta_data,
                require_kh_sign,
                require_tpb_sign,
                p_modified_by   AS created_by,
                origin_doc_id
            FROM
                sign_attachment
            WHERE
                doc_id = p_doc_id;

        p_res_message := 'INSERT SUCCESSFULLY';
    END IF;

    COMMIT;
END sp_sign_save_attachment_signed;

/
--------------------------------------------------------
--  DDL for Procedure SP_SIGN_SEARCH_CASE
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_SIGN_SEARCH_CASE" (
    p_activity           IN VARCHAR2,
    p_keyword            IN VARCHAR2,
    p_status             IN VARCHAR2,
    p_process_type       IN VARCHAR2,
    p_branch_code        IN VARCHAR2,
    p_assignee           IN VARCHAR2,
    p_username           IN VARCHAR2,
    p_is_admin           IN NUMBER DEFAULT 0,
    p_all_branch_access  IN NUMBER DEFAULT 0,
    p_user_branch_codes  IN VARCHAR2,
    p_page_number        IN NUMBER DEFAULT 0,
    p_page_size          IN NUMBER DEFAULT 25,
    sys_cursor           OUT SYS_REFCURSOR,
    summary_cursor       OUT SYS_REFCURSOR
) AS
    v_page_number NUMBER := GREATEST(NVL(p_page_number, 0), 0);
    v_page_size   NUMBER := NVL(p_page_size, 25);
    v_from_row    NUMBER;
    v_to_row      NUMBER;
BEGIN
    v_from_row := v_page_number * GREATEST(v_page_size, 1) + 1;
    v_to_row := (v_page_number + 1) * GREATEST(v_page_size, 1);

    OPEN sys_cursor FOR
        SELECT paged.ID,
               paged.TOTALELEMENTS
        FROM (
            SELECT base_query.ID,
                   COUNT(*) OVER () AS TOTALELEMENTS,
                   ROW_NUMBER() OVER (
                       ORDER BY base_query.SORT_UPDATED_AT DESC, base_query.ID DESC
                   ) AS RN
            FROM (
                SELECT sc.ID,
                       NVL(sc.UPDATED_AT, sc.CREATED_AT) AS SORT_UPDATED_AT
                FROM SIGN_CASE sc
                WHERE
                    (
                        p_keyword IS NULL
                        OR LOWER(sc.CASE_CODE) LIKE '%' || LOWER(TRIM(p_keyword)) || '%'
                        OR LOWER(sc.CUSTOMER_CODE) LIKE '%' || LOWER(TRIM(p_keyword)) || '%'
                        OR LOWER(sc.CUSTOMER_NAME) LIKE '%' || LOWER(TRIM(p_keyword)) || '%'
                        OR LOWER(sc.PRODUCT_CODE) LIKE '%' || LOWER(TRIM(p_keyword)) || '%'
                        OR LOWER(sc.PRODUCT_NAME) LIKE '%' || LOWER(TRIM(p_keyword)) || '%'
                        OR LOWER(sc.PDTD_CODE) LIKE '%' || LOWER(TRIM(p_keyword)) || '%'
                        OR LOWER(sc.BRANCH_CODE) LIKE '%' || LOWER(TRIM(p_keyword)) || '%'
                    )
                    AND (
                        p_status IS NULL
                        OR UPPER(sc.STATUS) IN (
                            SELECT UPPER(TRIM(REGEXP_SUBSTR(p_status, '[^,]+', 1, LEVEL)))
                            FROM dual
                            CONNECT BY REGEXP_SUBSTR(p_status, '[^,]+', 1, LEVEL) IS NOT NULL
                        )
                    )
                    AND (
                        p_process_type IS NULL
                        OR UPPER(sc.PROCESS_TYPE) = UPPER(TRIM(p_process_type))
                    )
                    AND (
                        p_branch_code IS NULL
                        OR UPPER(TRIM(p_branch_code)) IN ('ALL', 'ALL_BRANCH')
                        OR UPPER(sc.BRANCH_CODE) IN (
                            SELECT UPPER(TRIM(REGEXP_SUBSTR(p_branch_code, '[^,]+', 1, LEVEL)))
                            FROM dual
                            CONNECT BY REGEXP_SUBSTR(p_branch_code, '[^,]+', 1, LEVEL) IS NOT NULL
                        )
                    )
                    AND (
                        p_assignee IS NULL
                        OR LOWER(sc.CURRENT_ASSIGNEE) = LOWER(TRIM(p_assignee))
                    )
                    AND (
                        NVL(p_is_admin, 0) = 1
                        OR NVL(p_all_branch_access, 0) = 1
                        OR LOWER(sc.CREATED_BY) = LOWER(TRIM(p_username))
                        OR LOWER(sc.CURRENT_ASSIGNEE) = LOWER(TRIM(p_username))
                        OR (
                            p_user_branch_codes IS NOT NULL
                            AND UPPER(sc.BRANCH_CODE) IN (
                                SELECT UPPER(TRIM(REGEXP_SUBSTR(p_user_branch_codes, '[^,]+', 1, LEVEL)))
                                FROM dual
                                CONNECT BY REGEXP_SUBSTR(p_user_branch_codes, '[^,]+', 1, LEVEL) IS NOT NULL
                            )
                        )
                    )
                    AND (
                        p_activity IS NULL
                        OR UPPER(TRIM(p_activity)) = 'ALL'
                        OR (
                            UPPER(TRIM(p_activity)) = 'KH_CONFIRM_EMAIL'
                            AND UPPER(sc.STATUS) = 'KH_CONFIRM_EMAIL'
                        )
                        OR (
                            UPPER(TRIM(p_activity)) = 'RETURN'
                            AND UPPER(sc.STATUS) = 'RETURN'
                        )
                        OR (
                            UPPER(TRIM(p_activity)) = 'COMPLETED'
                            AND UPPER(sc.STATUS) IN ('COMPLETE', 'REJECTED', 'CANCEL')
                        )
                    )
            ) base_query
        ) paged
        WHERE v_page_size <= 0
           OR paged.RN BETWEEN v_from_row AND v_to_row
        ORDER BY paged.RN;

    OPEN summary_cursor FOR
        SELECT
            NVL(SUM(
                CASE
                    WHEN p_activity IS NULL OR UPPER(TRIM(p_activity)) = 'ALL' THEN 1
                    WHEN UPPER(TRIM(p_activity)) = 'KH_CONFIRM_EMAIL'
                         AND UPPER(base_query.STATUS) = 'KH_CONFIRM_EMAIL' THEN 1
                    WHEN UPPER(TRIM(p_activity)) = 'RETURN'
                         AND UPPER(base_query.STATUS) = 'RETURN' THEN 1
                    WHEN UPPER(TRIM(p_activity)) = 'COMPLETED'
                         AND UPPER(base_query.STATUS) IN ('COMPLETE', 'REJECTED', 'CANCEL') THEN 1
                    ELSE 0
                END
            ), 0) AS TOTAL_ELEMENTS,
            COUNT(*) AS TOTAL_ALL,
            NVL(SUM(CASE WHEN UPPER(base_query.STATUS) = 'KH_CONFIRM_EMAIL' THEN 1 ELSE 0 END), 0)
                AS KH_CONFIRM_EMAIL_TOTAL,
            NVL(SUM(CASE WHEN UPPER(base_query.STATUS) = 'RETURN' THEN 1 ELSE 0 END), 0)
                AS RETURN_TOTAL,
            NVL(SUM(CASE WHEN UPPER(base_query.STATUS) IN ('COMPLETE', 'REJECTED', 'CANCEL') THEN 1 ELSE 0 END), 0)
                AS COMPLETED_TOTAL
        FROM (
            SELECT sc.STATUS
            FROM SIGN_CASE sc
            WHERE
                (
                    p_keyword IS NULL
                    OR LOWER(sc.CASE_CODE) LIKE '%' || LOWER(TRIM(p_keyword)) || '%'
                    OR LOWER(sc.CUSTOMER_CODE) LIKE '%' || LOWER(TRIM(p_keyword)) || '%'
                    OR LOWER(sc.CUSTOMER_NAME) LIKE '%' || LOWER(TRIM(p_keyword)) || '%'
                    OR LOWER(sc.PRODUCT_CODE) LIKE '%' || LOWER(TRIM(p_keyword)) || '%'
                    OR LOWER(sc.PRODUCT_NAME) LIKE '%' || LOWER(TRIM(p_keyword)) || '%'
                    OR LOWER(sc.PDTD_CODE) LIKE '%' || LOWER(TRIM(p_keyword)) || '%'
                    OR LOWER(sc.BRANCH_CODE) LIKE '%' || LOWER(TRIM(p_keyword)) || '%'
                )
                AND (
                    p_status IS NULL
                    OR UPPER(sc.STATUS) IN (
                        SELECT UPPER(TRIM(REGEXP_SUBSTR(p_status, '[^,]+', 1, LEVEL)))
                        FROM dual
                        CONNECT BY REGEXP_SUBSTR(p_status, '[^,]+', 1, LEVEL) IS NOT NULL
                    )
                )
                AND (
                    p_process_type IS NULL
                    OR UPPER(sc.PROCESS_TYPE) = UPPER(TRIM(p_process_type))
                )
                AND (
                    p_branch_code IS NULL
                    OR UPPER(TRIM(p_branch_code)) IN ('ALL', 'ALL_BRANCH')
                    OR UPPER(sc.BRANCH_CODE) IN (
                        SELECT UPPER(TRIM(REGEXP_SUBSTR(p_branch_code, '[^,]+', 1, LEVEL)))
                        FROM dual
                        CONNECT BY REGEXP_SUBSTR(p_branch_code, '[^,]+', 1, LEVEL) IS NOT NULL
                    )
                )
                AND (
                    p_assignee IS NULL
                    OR LOWER(sc.CURRENT_ASSIGNEE) = LOWER(TRIM(p_assignee))
                )
                AND (
                    NVL(p_is_admin, 0) = 1
                    OR NVL(p_all_branch_access, 0) = 1
                    OR LOWER(sc.CREATED_BY) = LOWER(TRIM(p_username))
                    OR LOWER(sc.CURRENT_ASSIGNEE) = LOWER(TRIM(p_username))
                    OR (
                        p_user_branch_codes IS NOT NULL
                        AND UPPER(sc.BRANCH_CODE) IN (
                            SELECT UPPER(TRIM(REGEXP_SUBSTR(p_user_branch_codes, '[^,]+', 1, LEVEL)))
                            FROM dual
                            CONNECT BY REGEXP_SUBSTR(p_user_branch_codes, '[^,]+', 1, LEVEL) IS NOT NULL
                        )
                    )
                )
        ) base_query;
END SP_SIGN_SEARCH_CASE;

/
--------------------------------------------------------
--  DDL for Procedure SP_SIGN_UPDATE_CASE_ERROR
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_SIGN_UPDATE_CASE_ERROR" (
  p_json_object IN CLOB,
  P_RES_MESSAGE OUT VARCHAR2
) AS 
  json_obj JSON_OBJECT_T;
  P_TRANSACTION_CODE VARCHAR2(50) DEFAULT '';
  P_STEP_ERROR VARCHAR2(200) DEFAULT '';
  P_ECMID VARCHAR2(200) DEFAULT '';-- file g?c
  P_MSG_FAIL VARCHAR2(3000) DEFAULT '';
  P_ALL_REJECT VARCHAR2(50) DEFAULT '';
  v_total_docs NUMBER;
  v_signed_docs NUMBER;
  v_signed_fail NUMBER;
  v_sign_all NUMBER;
  v_status VARCHAR2(200) DEFAULT '';
  v_process_type VARCHAR2(255);

BEGIN 
  json_obj := JSON_OBJECT_T.parse(p_json_object);
  P_TRANSACTION_CODE := json_obj.get_String('transactionCode');
  P_STEP_ERROR := json_obj.get_String('stepError');
  P_ECMID := json_obj.get_String('ecmID');
  P_MSG_FAIL := json_obj.get_String('msgFail');
  P_ALL_REJECT := json_obj.get_String('allReject');
    
IF (P_ECMID IS NOT NULL) THEN
        IF (P_STEP_ERROR = 'KH_SIGN') THEN
            IF (P_ALL_REJECT = '1') THEN
                v_status := 'CANCEL';
            ELSE
                v_status := 'CREATE';
            END IF;
            
            UPDATE SIGN_TRANSACTION SET STATUS = v_status, UPDATED_DATE = SYSDATE WHERE TRANSACTION_CODE = P_TRANSACTION_CODE;
            UPDATE SIGN_ATTACHMENT SET STATUS = 'SIGN_FAILED', UPDATED_DATE = SYSDATE, MSG_FAIL = P_MSG_FAIL WHERE DOC_ID = P_ECMID;
             -- ??m t?ng s? DOC_ID c?n ký
            SELECT COUNT(*) INTO v_total_docs
            FROM SIGN_ATTACHMENT
            WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
            AND DOC_TYPE = 'NO_SIGN'
            AND REQUIRE_KH_SIGN = 1;
        
            -- ??m s? DOC_ID ?ã ký thành công/ fail
            SELECT COUNT(*) INTO v_signed_docs
            FROM SIGN_ATTACHMENT
            WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
              AND DOC_TYPE = 'NO_SIGN'
              AND REQUIRE_KH_SIGN = 1
              AND (STATUS = 'SIGNED' or STATUS = 'SIGN_FAILED');
          
            -- Ki?m tra t?t c? ch?a
            IF v_total_docs > 0 AND v_total_docs = v_signed_docs THEN
                -- C?p nh?t tr?ng thái giao d?ch
                UPDATE SIGN_TRANSACTION SET STATUS = v_status WHERE TRANSACTION_CODE = P_TRANSACTION_CODE;
                -- Ghi l?ch s? ký s?
                INSERT INTO SIGN_HISTORY (TRANSACTION_CODE, ACTION, FRE_STATUS, STATUS, MSG_FAIL)
                VALUES (P_TRANSACTION_CODE, 'SEND_TO_VNEID', 'KH_SIGN', 'KH_SIGN', 'FAILED');
                
                P_RES_MESSAGE := 'SUCCESS';
            ELSE
                P_RES_MESSAGE := 'INCOMPLETE';
            END IF;
        
        ELSIF (P_STEP_ERROR = 'TPB_SIGN_REPRESENT') THEN
            UPDATE SIGN_TRANSACTION SET UPDATED_DATE = SYSDATE WHERE TRANSACTION_CODE = P_TRANSACTION_CODE;
            UPDATE SIGN_ATTACHMENT SET STATUS = 'SIGN_FAILED', UPDATED_DATE = SYSDATE, MSG_FAIL = P_MSG_FAIL WHERE DOC_ID = P_ECMID;
            
            SELECT process_type INTO v_process_type
            FROM SIGN_TRANSACTION where TRANSACTION_CODE = P_TRANSACTION_CODE;
            
            IF v_process_type = 'VNEID' THEN
                -- ??m t?ng s? DOC_ID c?n REPRESENT ký
                SELECT COUNT(*) INTO v_total_docs
                FROM SIGN_ATTACHMENT
                WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
                AND DOC_TYPE = 'NO_SIGN' AND REQUIRE_TPB_SIGN = 1;
            
                -- ??m s? DOC_ID ?ã ký thành công/ fail
                SELECT COUNT(*) INTO v_signed_docs
                FROM SIGN_ATTACHMENT
                WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
                  AND ((DOC_TYPE = 'NO_SIGN' AND REQUIRE_KH_SIGN = 0 AND REQUIRE_TPB_SIGN = 1 AND STATUS = 'SIGN_FAILED')
                  OR (DOC_TYPE = 'CUSTOMER_SIGNED' AND REQUIRE_KH_SIGN = 1 AND REQUIRE_TPB_SIGN = 1 AND STATUS = 'SIGN_FAILED')
                  OR (DOC_TYPE = 'TPB_REPRESENT_SIGNED'));     
            ELSIF v_process_type = 'HDBD' THEN
                -- ??m t?ng s? DOC_ID c?n REPRESENT ký
                SELECT COUNT(*) INTO v_total_docs
                FROM SIGN_ATTACHMENT
                WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
                AND DOC_TYPE = 'TPB_REPRESENT' AND REQUIRE_TPB_SIGN = 1;
            
                -- ??m s? DOC_ID ?ã ký thành công/ fail
                SELECT COUNT(*) INTO v_signed_docs
                FROM SIGN_ATTACHMENT
                WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
                  AND (
                  (DOC_TYPE = 'TPB_REPRESENT' AND REQUIRE_TPB_SIGN = 1 AND STATUS = 'SIGN_FAILED')
                  OR (DOC_TYPE = 'TPB_REPRESENT_SIGNED')
                  );
            ELSIF v_process_type = 'KHDN' THEN
                -- ??m t?ng s? DOC_ID c?n REPRESENT ký
                SELECT COUNT(*) INTO v_total_docs
                FROM SIGN_ATTACHMENT
                WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
                AND DOC_TYPE IN ('NO_SIGN_TPB', 'CUSTOMER_SIGNED') AND REQUIRE_TPB_SIGN = 1;
            
                -- ??m s? DOC_ID ?ã ký thành công/ fail
                SELECT COUNT(*) INTO v_signed_docs
                FROM SIGN_ATTACHMENT
                WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
                  AND (DOC_TYPE = 'TPB_SIGNED' OR STATUS = 'SIGN_FAILED') AND REQUIRE_TPB_SIGN = 1;
            END IF;
             
          
            -- Ki?m tra t?t c? ch?a
            IF v_total_docs > 0 AND v_total_docs = v_signed_docs THEN
                -- Ghi l?ch s? ký s? l?i ??i di?n TPB
                INSERT INTO SIGN_HISTORY (TRANSACTION_CODE, ACTION, FRE_STATUS, STATUS, MSG_FAIL)
                VALUES (P_TRANSACTION_CODE, 'TPB_REPRESENT_SIGNED', 'TPB_SIGN_REPRESENT', 'TPB_SIGN_REPRESENT', 'FAILED');
                
                P_RES_MESSAGE := 'SUCCESS_AND_FAIL';
            ELSE
                P_RES_MESSAGE := 'INCOMPLETE';
            END IF;
        
        ELSIF (P_STEP_ERROR = 'TPB_SIGN') THEN
            UPDATE SIGN_TRANSACTION SET UPDATED_DATE = SYSDATE WHERE TRANSACTION_CODE = P_TRANSACTION_CODE;
            UPDATE SIGN_ATTACHMENT SET STATUS = 'SIGN_FAILED', UPDATED_DATE = SYSDATE, MSG_FAIL = P_MSG_FAIL WHERE DOC_ID = P_ECMID;
            P_RES_MESSAGE := 'INCOMPLETE';
            -- ??m t?ng s? DOC_ID c?n TPB ký
            SELECT COUNT(*) INTO v_total_docs
            FROM SIGN_ATTACHMENT
            WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
              AND DOC_TYPE = 'TPB_REPRESENT_SIGNED'
              AND REQUIRE_TPB_SIGN = 1;

            -- ??m s? DOC_ID ?ã ký fail
            SELECT COUNT(*) INTO v_signed_fail
            FROM SIGN_ATTACHMENT
            WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
              AND DOC_TYPE = 'TPB_REPRESENT_SIGNED' AND REQUIRE_TPB_SIGN = 1 AND STATUS = 'SIGN_FAILED';
              
            -- ??m s? DOC_ID ?ã ký thành công + fail
            SELECT COUNT(*) INTO v_sign_all
            FROM SIGN_ATTACHMENT
            WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
--            AND (
--            (DOC_TYPE = 'TPB_REPRESENT_SIGNED'
--                AND REQUIRE_TPB_SIGN = 1
--                AND STATUS = 'SIGN_FAILED')
--            OR
--            (DOC_TYPE = 'TPB_SIGNED'
--                AND REQUIRE_TPB_SIGN = 1)
--            )
              AND ( DOC_TYPE = 'TPB_SIGNED' OR (DOC_TYPE = 'TPB_REPRESENT_SIGNED' AND REQUIRE_TPB_SIGN = 1 AND STATUS = 'SIGN_FAILED') );
          
            IF v_signed_fail = 0 THEN
                -- Ghi l?ch s? ký s? l?i TPB
                INSERT INTO SIGN_HISTORY (TRANSACTION_CODE, ACTION, FRE_STATUS, STATUS, MSG_FAIL) VALUES (P_TRANSACTION_CODE, 'TPB_SIGN', 'TPB_SIGN', 'TPB_SIGN', 'FAILED');
            END IF;
            
            -- Ki?m tra t?t c? ?ã ký ch?a (có l?i)
            IF v_total_docs > 0 AND v_signed_fail > 0 AND v_total_docs = v_sign_all THEN
                -- C?p nh?t th?i gian update giao d?ch
                -- UPDATE SIGN_TRANSACTION SET UPDATED_DATE = SYSDATE WHERE TRANSACTION_CODE = P_TRANSACTION_CODE;
                -- Ghi l?ch s? ký s?
                INSERT INTO SIGN_HISTORY (TRANSACTION_CODE, ACTION, FRE_STATUS, STATUS, MSG_FAIL) VALUES (P_TRANSACTION_CODE, 'TPB_SIGN', 'TPB_SIGN', 'TPB_SIGN', 'FAILED');
                P_RES_MESSAGE := 'DONE_FAILED';
            END IF;
                
        END IF;
        
        COMMIT;
        
END IF;

EXCEPTION
  WHEN OTHERS THEN
    ROLLBACK;
    P_RES_MESSAGE := 'ERROR: ' || SQLERRM;

END SP_SIGN_UPDATE_CASE_ERROR;

/
--------------------------------------------------------
--  DDL for Procedure SP_SIGN_UPDATE_TRANSACTION
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_SIGN_UPDATE_TRANSACTION" (
  p_json_object IN CLOB,
  P_MODIFIED_BY IN VARCHAR2,
  P_RECORD_ID OUT NUMBER,
  P_RES_MESSAGE OUT VARCHAR2
) AS 
  json_obj JSON_OBJECT_T;
  P_ID NUMBER DEFAULT NULL;
  P_TRANSACTION_CODE VARCHAR2(200) DEFAULT '';
  P_STATUS VARCHAR2(200) DEFAULT '';
  P_PDTD_CODE VARCHAR2(50) DEFAULT '';
  P_BRANCH_CODE VARCHAR2(20) DEFAULT '';
  P_PRODUCT_CODE VARCHAR2(200) DEFAULT '';
  P_PRODUCT_NAME VARCHAR2(200) DEFAULT '';
  P_CUSTOMER_CODE VARCHAR2(50) DEFAULT '';
  P_CUSTOMER_NAME VARCHAR2(500) DEFAULT '';
  P_ID_CARD VARCHAR2(50) DEFAULT '';
  P_TOTAL_AMOUNT NUMBER DEFAULT NULL;
  P_CURRENCY VARCHAR2(50) DEFAULT '';
  P_LOAN_AMOUNT VARCHAR2(200) DEFAULT '';
  P_LOAN_METHOD VARCHAR2(50) DEFAULT '';
  P_ID_FOLDER_KH VARCHAR2(200) DEFAULT '';
  P_ID_FOLDER_HS VARCHAR2(200) DEFAULT '';
  P_CUS_EMAIL VARCHAR2(255) DEFAULT '';
  P_EMAIL_VPCC VARCHAR2(255) DEFAULT '';
  P_BORROWERS CLOB DEFAULT NULL;
  P_BORROWER_DATA VARCHAR2(4000) DEFAULT NULL;
  P_CHUYEN_VIEN_KHACH_HANG VARCHAR2(255) DEFAULT '';
  P_PROCESS_TYPE VARCHAR2(200) DEFAULT '';
  P_DOC_TYPE VARCHAR2(100) DEFAULT '';
  P_BORROWER_EBANK VARCHAR2(255) DEFAULT '';
  P_PURPOSE_EBANK VARCHAR2(255) DEFAULT '';
BEGIN 
  json_obj := JSON_OBJECT_T.parse(p_json_object);
  P_ID := json_obj.get_Number('id');
  P_TRANSACTION_CODE := json_obj.get_String('transactionCode');
  P_PDTD_CODE := json_obj.get_String('pdtdCode');
  P_STATUS := json_obj.get_String('status');
  P_BRANCH_CODE := json_obj.get_String('branchCode');
  -- P_BRANCH_NAME := json_obj.get_String('branchName');
  P_PRODUCT_CODE := json_obj.get_String('productCode');
  P_PRODUCT_NAME := json_obj.get_String('productName');
  P_CUSTOMER_CODE := json_obj.get_String('customerCode');
  P_CUSTOMER_NAME := json_obj.get_String('customerName');
  P_ID_CARD := json_obj.get_String('idCard');
  P_TOTAL_AMOUNT := json_obj.get_Number('totalAmount');
  P_CURRENCY := json_obj.get_String('currency');
  P_LOAN_AMOUNT := json_obj.get_String('loanAmount');
  P_LOAN_METHOD := json_obj.get_String('loanMethod');
  P_ID_FOLDER_KH := json_obj.get_String('idFolderKH');
  P_ID_FOLDER_HS := json_obj.get_String('idFolderHS');
  P_CUS_EMAIL := json_obj.get_String('cusEmail');
  P_EMAIL_VPCC := json_obj.get_String('emailVPCC');
  -- P_BORROWERS := TO_CLOB(json_obj.get_String('borrowerData'));
  P_BORROWER_DATA := json_obj.get_String('borrowerData');
  P_CHUYEN_VIEN_KHACH_HANG := json_obj.get_String('chuyenVienKhachHang');
  P_PROCESS_TYPE := json_obj.get_String('processType');
  P_DOC_TYPE := json_obj.get_String('docType');
  P_BORROWER_EBANK := json_obj.get_String('borrowerEbank');
  P_PURPOSE_EBANK := json_obj.get_String('purposeEbank');

  IF (P_ID IS NULL OR P_ID < 1) THEN
    INSERT INTO SIGN_TRANSACTION (
      TRANSACTION_CODE, --Mã giao d?ch
      PDTD_CODE, --Mã PDTD (LOS, BPM, ECM)
      STATUS, --Tr?ng thái
      BRANCH_CODE, --Mã ?VKD - Mã chi nhánh
      PRODUCT_CODE, --Nhóm S?n Ph?m
      PRODUCT_NAME, --Tên S?n Ph?m
      CUSTOMER_CODE, --Mã Khách Hàng
      CUSTOMER_NAME, --Tên Khách Hàng
      ID_CARD, --C?n c??c công dân
      TOTAL_AMOUNT, -- S? ti?n PDTD
      CURRENCY, -- Lo?i ti?n PDTD
      LOAN_AMOUNT, -- S? ti?n PDTD + CURRENCY
      LOAN_METHOD,
      ID_FOLDER_KH,
      ID_FOLDER_HS,
      CUS_EMAIL,
      EMAIL_VPCC,
      BORROWER_DATA,
      BORROWER_EBANK,
      PURPOSE_EBANK,
      CHUYEN_VIEN_KHACH_HANG,
      PROCESS_TYPE,
      DOC_TYPE,
      CREATED_BY,
      UPDATED_DATE
    ) VALUES (
      P_TRANSACTION_CODE, --Mã giao d?ch
      P_PDTD_CODE, --Mã PDTD (LOS, BPM, ECM)
      P_STATUS, --Tr?ng thái
      P_BRANCH_CODE, --Mã ?VKD - Mã chi nhánh
      P_PRODUCT_CODE, --Nhóm S?n Ph?m
      P_PRODUCT_NAME, --Tên S?n Ph?m
      REGEXP_REPLACE(P_CUSTOMER_CODE, '[]~!@#$%^&*()_+=\ {}[:”;’<,>./?]+', ''),--Mã Khách Hàng
      REGEXP_REPLACE(P_CUSTOMER_NAME, '[]~!@#$%^&*()_+=\{}[:”;’<,>./?]+', ''),--Tên Khách Hàng
      P_ID_CARD, --C?n c??c công dân
      P_TOTAL_AMOUNT,
      P_CURRENCY,
      P_LOAN_AMOUNT,
      P_LOAN_METHOD,
      P_ID_FOLDER_KH,
      P_ID_FOLDER_HS,
      P_CUS_EMAIL,
      P_EMAIL_VPCC,
      P_BORROWER_DATA,
      P_BORROWER_EBANK,
      P_PURPOSE_EBANK,
      P_CHUYEN_VIEN_KHACH_HANG,
      P_PROCESS_TYPE,
      P_DOC_TYPE,
      P_MODIFIED_BY,
      SYSDATE
    )
    RETURNING ID INTO P_RECORD_ID;    
    -- Ghi l?ch s? INSERT
    INSERT INTO SIGN_HISTORY (
      TRANSACTION_CODE, ACTION, FRE_STATUS, STATUS, DESCRIPTION, CREATED_BY
    ) VALUES (
      P_TRANSACTION_CODE, 'CREATE', 'CREATE', P_STATUS, 'T?o giao d?ch m?i', P_MODIFIED_BY
    );
    COMMIT;    
    P_RES_MESSAGE:='INSERT SUCCESSFULLY';
  ELSE
    UPDATE SIGN_TRANSACTION 
    SET
      PDTD_CODE = P_PDTD_CODE, --Mã PDTD (LOS, BPM, ECM)
      STATUS = P_STATUS, --Tr?ng thái
      BRANCH_CODE = P_BRANCH_CODE, --Mã ?VKD - Mã chi nhánh
      -- BRANCH_NAME = P_BRANCH_NAME, --Tên ?VKD - Tên chi nhánh
      PRODUCT_CODE = P_PRODUCT_CODE, --Mã S?n Ph?m
      PRODUCT_NAME = P_PRODUCT_NAME, --Tên S?n Ph?m
      CUSTOMER_CODE = REGEXP_REPLACE(P_CUSTOMER_CODE, '[]~!@#$%^&*()_+=\ {}[:”;’<,>./?]+', ''), --Mã Khách Hàng
      CUSTOMER_NAME = REGEXP_REPLACE(P_CUSTOMER_NAME, '[]~!@#$%^&*()_+=\{}[:”;’<,>./?]+', ''), --Tên Khách Hàng
      ID_CARD = P_ID_CARD, --C?n c??c công dân
      TOTAL_AMOUNT = P_TOTAL_AMOUNT,
      CURRENCY = P_CURRENCY,
      LOAN_AMOUNT = P_LOAN_AMOUNT,
      LOAN_METHOD = P_LOAN_METHOD,
      ID_FOLDER_KH = P_ID_FOLDER_KH,
      ID_FOLDER_HS = P_ID_FOLDER_HS,
      CUS_EMAIL = P_CUS_EMAIL,
      EMAIL_VPCC = P_EMAIL_VPCC,
      BORROWER_DATA = P_BORROWER_DATA,
      BORROWER_EBANK = P_BORROWER_EBANK,
      CHUYEN_VIEN_KHACH_HANG = P_CHUYEN_VIEN_KHACH_HANG,
      DOC_TYPE = P_DOC_TYPE,
      UPDATED_DATE = SYSDATE
    WHERE TRANSACTION_CODE = P_TRANSACTION_CODE;
    COMMIT;
    P_RECORD_ID:= P_ID;
    P_RES_MESSAGE:='UPDATE SUCCESSFULLY';
  END IF;

END SP_SIGN_UPDATE_TRANSACTION;

/
--------------------------------------------------------
--  DDL for Procedure SP_SIGN_VNEID_CALLBACK
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_SIGN_VNEID_CALLBACK" (
    p_message_id             IN sign_log.extra_info%TYPE,
    p_trace_number           IN sign_attachment.trace_number%TYPE,
    p_request_content        IN sign_log.request_content%TYPE,
    p_response_content       IN sign_log.response_content%TYPE,
    p_log_code               IN sign_log.code%TYPE,
    p_log_message            IN sign_log.message%TYPE,
    p_created_by             IN sign_log.created_by%TYPE,
    p_transaction_code       IN sign_transaction.transaction_code%TYPE,
    p_transaction_status_pre IN sign_transaction.status%TYPE,
    p_doc_id_origin          IN sign_attachment.doc_id%TYPE,
    p_doc_name_origin        IN sign_attachment.doc_name%TYPE,
    p_signature_info         IN sign_attachment.signature_info%TYPE,
    p_meta_data              IN sign_attachment.meta_data%TYPE,
    p_require_kh             IN sign_attachment.require_kh_sign%TYPE,
    p_require_tpb            IN sign_attachment.require_tpb_sign%TYPE,
    p_callback_result        IN VARCHAR2,
    p_pre_process_error      IN VARCHAR2,
    p_ecm_id_signed          IN sign_attachment.doc_id%TYPE,
    p_signed_doc_name        IN sign_attachment.doc_name%TYPE,
    p_signed_doc_type        IN sign_attachment.doc_type%TYPE,
    p_error_message          IN sign_attachment.msg_fail%TYPE,
    p_all_reject_file        IN NUMBER,
    p_kh_cancel_msg          IN VARCHAR2,
    o_result_code            OUT VARCHAR2,
    o_result_message         OUT VARCHAR2,
    o_business_result        OUT VARCHAR2,
    o_new_status             OUT VARCHAR2,
    o_callback_complete      OUT NUMBER,
    o_noti_type              OUT VARCHAR2,
    o_mail_codes             OUT VARCHAR2,
    o_mail_error_detail      OUT VARCHAR2,
    o_sp_log                 OUT VARCHAR2
) IS

    v_old_status         VARCHAR2(50);
    v_file_status        VARCHAR2(50);
    v_new_status         VARCHAR2(50);
    v_result             VARCHAR2(50) := 'INCOMPLETE';
    v_msg_history        VARCHAR2(1000);
    v_history_status     VARCHAR2(50);
    v_total              NUMBER := 0;
    v_signed             NUMBER := 0;
    v_failed             NUMBER := 0;
    v_processed          NUMBER := 0;
    v_reject             NUMBER := 0;
    v_fail_other         NUMBER := 0;
    v_signed_require_tpb NUMBER := 0;
    v_skip_tpb           NUMBER := 1;
    v_all_reject         NUMBER := 0;
    v_set_sign_date      NUMBER := 0;
    v_error              sign_attachment.msg_fail%TYPE;

    PROCEDURE add_log (
        p_text VARCHAR2
    ) IS
    BEGIN
        IF o_sp_log IS NULL THEN
            o_sp_log := p_text;
        ELSE
            o_sp_log := o_sp_log
                        || chr(10)
                        || p_text;
        END IF;
    END;

    PROCEDURE save_callback_log IS
        PRAGMA autonomous_transaction;
    BEGIN
        INSERT INTO sign_log (
            trans_id,
            transaction_code,
            step_code,
            action_code,
            request_content,
            response_content,
            code,
            message,
            extra_info,
            created_by
        ) VALUES (
            p_trace_number,
            p_transaction_code,
            'KH_KY_SO',
            'CB_SIGN_VNEID',
            p_request_content,
            p_response_content,
            p_log_code,
            p_log_message,
            p_message_id,
            p_created_by
        );

        COMMIT;
    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE;
    END;

BEGIN
    /* =========================================================
       STEP 0 - INIT
       ========================================================= */
    o_sp_log := '================ SP_SIGN_VNEID_CALLBACK ================';
    o_result_code := '0';
    o_result_message := 'SUCCESS';
    o_business_result := 'INCOMPLETE';
    o_new_status := p_transaction_status_pre;
    o_callback_complete := 0;
    o_noti_type := NULL;
    o_mail_codes := NULL;
    o_mail_error_detail := NULL;
    add_log('STEP 0 - INIT OUTPUT');
    add_log('STEP 0 - SUCCESS');
    SAVEPOINT sp_business;

    /* =========================================================
       STEP 1 - SAVE CALLBACK LOG
       Luôn log callback tr??c business
       ========================================================= */
    add_log('STEP 1 - SAVE CALLBACK LOG');
    save_callback_log;
    add_log('STEP 1 - SUCCESS');

    /* STEP 1.1 - Insert callback history tu?n t? */
    INSERT INTO sign_history (
        action,
        fre_status,
        status,
        description,
        transaction_code
    ) VALUES (
        'CB_VNEID',
        'KH_SIGN',
        'KH_SIGN',
        p_doc_name_origin
        || nvl2(p_error_message, ' - ' || p_error_message, ''),
        p_transaction_code
    );

    add_log('STEP 1.1 - INSERT CALLBACK HISTORY SUCCESS');

    /* =========================================================
       STEP 2 - PRE PROCESS ERROR
       Ch? log callback, không update business
       ========================================================= */
    add_log('STEP 2 - CHECK PRE_PROCESS_ERROR');
    IF p_pre_process_error IS NOT NULL THEN
        IF p_pre_process_error = 'TRACE_NUMBER_NOT_FOUND' THEN
            o_result_code := 'TRACE_NUMBER_NOT_FOUND';
            o_result_message := 'Trace number not found: ' || p_trace_number;
        ELSIF p_pre_process_error = 'TRACE_NUMBER_NOT_UNIQUE' THEN
            o_result_code := 'TRACE_NUMBER_NOT_UNIQUE';
            o_result_message := 'Trace number is not unique: ' || p_trace_number;
        ELSE
            o_result_code := 'PRE_PROCESS_ERROR';
            o_result_message := p_pre_process_error;
        END IF;

        o_business_result := 'NO_ACTION';
        add_log('STEP 2 - NO_ACTION - ' || o_result_code);
        RETURN;
    END IF;

    add_log('STEP 2 - SUCCESS');

    /* =========================================================
       STEP 3 - VALIDATE COMMON INPUT
       ========================================================= */
    add_log('STEP 3 - VALIDATE INPUT');
    add_log('STEP 3 - callbackResult: ' || nvl(p_callback_result, 'NULL'));
    add_log('STEP 3 - transactionCode: ' || nvl(p_transaction_code, 'NULL'));
    add_log('STEP 3 - transactionStatusPre: ' || nvl(p_transaction_status_pre, 'NULL'));
    add_log('STEP 3 - requireKH: '
            || CASE
        WHEN p_require_kh = 1 THEN
            'true'
        ELSE 'false'
    END);
    add_log('STEP 3 - requireTPB: '
            || CASE
        WHEN p_require_tpb = 1 THEN
            'true'
        ELSE 'false'
    END);
    IF p_trace_number IS NULL OR nvl(upper(p_callback_result),
                                     '#') NOT IN ( 'SUCCESS', 'FAIL' ) OR p_transaction_code IS NULL OR p_doc_id_origin IS NULL OR nvl
                                     (p_require_kh, - 1) NOT IN ( 0, 1 ) OR nvl(p_require_tpb, - 1) NOT IN ( 0, 1 ) OR nvl(p_all_reject_file
                                     , - 1) NOT IN ( 0, 1 ) THEN
        o_result_code := 'INVALID_INPUT';
        o_result_message := 'Invalid callback/context input';
        o_business_result := 'NO_ACTION';
        add_log('STEP 3 - INVALID_INPUT');
        RETURN;
    END IF;

    add_log('STEP 3 - SUCCESS');

    /* =========================================================
       STEP 4 - LOCK TRANSACTION
       ========================================================= */
    add_log('STEP 4 - LOCK TRANSACTION');
    SELECT
        status
    INTO v_old_status
    FROM
        sign_transaction
    WHERE
        transaction_code = p_transaction_code
    FOR UPDATE;

    add_log('STEP 4 - oldStatus: ' || v_old_status);

    /* =========================================================
       STEP 5 - CHECK TRANSACTION STATUS
       ========================================================= */
    add_log('STEP 5 - VALIDATE TRANSACTION STATUS');
    IF v_old_status <> 'KH_SIGN' THEN
        o_result_code := 'INVALID_STATUS';
        o_result_message := 'Current status='
                            || v_old_status
                            || ', expected KH_SIGN';
        o_business_result := 'NO_ACTION';
        o_new_status := v_old_status;
        add_log('STEP 5 - NO_ACTION - ' || o_result_message);
        ROLLBACK TO sp_business;
        RETURN;
    END IF;

    add_log('STEP 5 - SUCCESS');

    /* =========================================================
       STEP 6 - LOCK ORIGINAL ATTACHMENT
       ========================================================= */
    add_log('STEP 6 - LOCK ORIGINAL ATTACHMENT');
    SELECT
        status
    INTO v_file_status
    FROM
        sign_attachment
    WHERE
            transaction_code = p_transaction_code
        AND trace_number = p_trace_number
        AND doc_id = p_doc_id_origin
        AND doc_type = 'NO_SIGN'
    FOR UPDATE;

    add_log('STEP 6 - docId: ' || p_doc_id_origin);
    add_log('STEP 6 - fileStatus: ' || v_file_status);

    /* =========================================================
       STEP 7 - IDEMPOTENCY
       ========================================================= */
    add_log('STEP 7 - IDEMPOTENCY CHECK');
    IF v_file_status IN ( 'SIGNED' ) THEN--, 'SIGN_FAILED'
        o_result_code := 'ALREADY_PROCESSED';
        o_result_message := 'File already processed: ' || v_file_status;
        o_business_result := 'NO_ACTION';
        o_new_status := v_old_status;
        add_log('STEP 7 - NO_ACTION - already processed');
        ROLLBACK TO sp_business;
        RETURN;
    END IF;

    add_log('STEP 7 - SUCCESS - file not processed');

    /* =========================================================
       STEP 8 - APPLY CALLBACK
       ========================================================= */
    add_log('STEP 8 - APPLY CALLBACK');
    IF upper(p_callback_result) = 'SUCCESS' THEN

        /* Validate output ECM ch? sau khi ?ã lock/recheck */
        IF p_ecm_id_signed IS NULL OR p_signed_doc_name IS NULL OR p_signed_doc_type IS NULL THEN
            ROLLBACK TO sp_business;
            o_result_code := 'INVALID_INPUT';
            o_result_message := 'Missing signed ECM input';
            o_business_result := 'NO_ACTION';
            o_new_status := v_old_status;
            add_log('STEP 8 - INVALID_INPUT - missing signed ECM input');
            RETURN;
        END IF;

        /* Insert file ?ã ký */
        INSERT INTO sign_attachment (
            transaction_code,
            doc_id,
            doc_name,
            doc_type,
            status,
            signature_info,
            meta_data,
            created_by,
            created_date,
            require_kh_sign,
            require_tpb_sign
        ) VALUES (
            p_transaction_code,
            p_ecm_id_signed,
            p_signed_doc_name,
            p_signed_doc_type,
            'NO_SIGN',
            p_signature_info,
            p_meta_data,
            p_created_by,
            sysdate,
            p_require_kh,
            p_require_tpb
        );

        /* Mark file g?c ?ã ký */
        UPDATE sign_attachment
        SET
            status = 'SIGNED',
            msg_fail = NULL,
            updated_date = sysdate
        WHERE
                transaction_code = p_transaction_code
            AND trace_number = p_trace_number
            AND doc_id = p_doc_id_origin
            AND doc_type = 'NO_SIGN';

        add_log('STEP 8 - SUCCESS');
        add_log('STEP 8 - ECM_ID: ' || p_ecm_id_signed);
    ELSE

        /* Normalize error */
        v_error :=
            CASE
                WHEN p_all_reject_file = 1 THEN
                    p_kh_cancel_msg
                ELSE p_error_message
            END;
        IF v_error IS NULL THEN
            ROLLBACK TO sp_business;
            o_result_code := 'INVALID_INPUT';
            o_result_message :=
                CASE
                    WHEN p_all_reject_file = 1 THEN
                        'KH_CANCEL_MSG is null'
                    ELSE 'Fail callback error message is null'
                END;
            o_business_result := 'NO_ACTION';
            o_new_status := v_old_status;
            add_log('STEP 8 - INVALID_INPUT - ' || o_result_message);
            RETURN;
        END IF;

        UPDATE sign_attachment
        SET
            status = 'SIGN_FAILED',
            msg_fail = v_error,
            updated_date = sysdate
        WHERE
                transaction_code = p_transaction_code
            AND trace_number = p_trace_number
            AND doc_id = p_doc_id_origin
            AND doc_type = 'NO_SIGN';

        add_log('STEP 8 - FAIL CALLBACK APPLIED');
        add_log('STEP 8 - allRejectFile: '
                || CASE
            WHEN p_all_reject_file = 1 THEN
                'true'
            ELSE 'false'
        END);
        add_log('STEP 8 - error: ' || v_error);
    END IF;

    /* =========================================================
       STEP 9 - AGGREGATE
       Ch? aggregate file g?c c?n KH ký
       ========================================================= */
    add_log('STEP 9 - AGGREGATE');
    SELECT
        COUNT(*),
        COUNT(
            CASE
                WHEN status = 'SIGNED' THEN
                    1
            END
        ),
        COUNT(
            CASE
                WHEN status = 'SIGN_FAILED' THEN
                    1
            END
        ),
        COUNT(
            CASE
                WHEN status IN('SIGNED', 'SIGN_FAILED') THEN
                    1
            END
        ),
        COUNT(
            CASE
                WHEN status = 'SIGN_FAILED'
                     AND msg_fail = p_kh_cancel_msg THEN
                    1
            END
        ),
        COUNT(
            CASE
                WHEN status = 'SIGN_FAILED'
                     AND(msg_fail <> p_kh_cancel_msg
                         OR msg_fail IS NULL) THEN
                    1
            END
        ),
        COUNT(
            CASE
                WHEN status = 'SIGNED'
                     AND nvl(require_tpb_sign, 0) = 1 THEN
                    1
            END
        )
    INTO
        v_total,
        v_signed,
        v_failed,
        v_processed,
        v_reject,
        v_fail_other,
        v_signed_require_tpb
    FROM
        sign_attachment
    WHERE
            transaction_code = p_transaction_code
        AND doc_type = 'NO_SIGN'
        AND nvl(require_kh_sign, 0) = 1;

    v_skip_tpb :=
        CASE
            WHEN v_signed_require_tpb > 0 THEN
                0
            ELSE 1
        END;
    add_log('STEP 9 - total: '
            || v_total
            || ', signed: '
            || v_signed
            || ', failed: '
            || v_failed
            || ', processed: '
            || v_processed
            || ', reject: '
            || v_reject
            || ', failOther: '
            || v_fail_other);

    add_log('STEP 9 - isSkipTPB: '
            || CASE
        WHEN v_skip_tpb = 1 THEN
            'true'
        ELSE 'false'
    END);

    /* =========================================================
       STEP 10 - CHECK CALLBACK COMPLETE
       ========================================================= */
    add_log('STEP 10 - CHECK CALLBACK COMPLETE');
    IF v_total = 0 THEN
        ROLLBACK TO sp_business;
        o_result_code := 'INVALID_AGGREGATE';
        o_result_message := 'No KH sign attachment found';
        o_business_result := 'NO_ACTION';
        o_new_status := v_old_status;
        add_log('STEP 10 - ERROR - total=0');
        RETURN;
    END IF;

    /*
     * Không rollback:
     * ph?i gi? SIGNED/SIGN_FAILED c?a callback hi?n t?i
     * ?? callback sau ??m ti?p.
     */
    IF (v_total - v_reject) <> v_processed THEN
        o_result_code := '0';
        o_result_message := 'SUCCESS';
        o_business_result := 'INCOMPLETE';
        o_new_status := v_old_status;
        o_callback_complete := 0;
        o_noti_type := NULL;
        add_log('STEP 10 - INCOMPLETE - '
                || v_processed
                || '/'
                || v_total);
        RETURN;
    END IF;

    add_log('STEP 10 - COMPLETE - '
            || v_processed
            || '/'
            || v_total);

    /* =========================================================
       STEP 11 - BUSINESS TRANSITION
       ========================================================= */
    add_log('STEP 11 - BUSINESS TRANSITION');
    v_new_status := NULL;

    /* ===================== CALLBACK FAIL ===================== */
    IF upper(p_callback_result) = 'FAIL' THEN
        add_log('STEP 11A - FAIL BRANCH');

        /*
         * Có l?i ký th?c s?:
         * quay v? CREATE
         */
        IF v_fail_other > 0 THEN
            v_new_status := 'CREATE';
            v_msg_history := 'FAIL';
            v_result := 'BACK_CREATE';

        /*
         * T?t c? file ??u b? KH t? ch?i
         */
        ELSIF
            v_failed > 0
            AND v_failed = v_reject
            AND v_signed = 0
        THEN
            v_new_status := 'CANCEL';
            v_msg_history := 'CANCEL-Khách hàng t? ch?i ký s? h? s? tín d?ng';
            v_result := 'BACK_CREATE';
            v_all_reject := 1;

        /*
         * Có file signed + có file KH t? ch?i
         */
        ELSIF
            v_failed > 0
            AND v_failed = v_reject
            AND v_signed > 0
        THEN
            v_new_status := 'TPB_SIGN_REPRESENT';
            v_result := 'SUCCESS_AND_FAIL';
            IF v_skip_tpb = 1 THEN
                v_new_status := 'SEND_DOC_KH';
                v_result := 'BACK_CREATE';
            END IF;

        /*
         * Các file còn l?i ??u ký thành công
         */
        ELSIF ( v_total - v_reject ) = v_signed THEN
            v_new_status := 'TPB_SIGN_REPRESENT';
            v_result := 'SUCCESS';
            IF v_skip_tpb = 1 THEN
                v_new_status := 'SEND_DOC_KH';
            END IF;
        END IF;

        v_set_sign_date :=
            CASE
                WHEN v_result = 'SUCCESS' THEN
                    1
                ELSE 0
            END;
        v_history_status :=
            CASE
                WHEN v_new_status IN ( 'CREATE', 'CANCEL' ) THEN
                    'KH_SIGN'
                ELSE v_new_status
            END;

    /* ==================== CALLBACK SUCCESS =================== */
    ELSE
        add_log('STEP 11B - SUCCESS BRANCH');
        IF v_fail_other > 0 THEN
            v_new_status := 'CREATE';
            v_msg_history := 'CREATE';
            v_result := 'BACK_CREATE';
        ELSIF
            v_failed > 0
            AND v_failed = v_reject
        THEN
            v_new_status := 'TPB_SIGN_REPRESENT';
            v_result := 'SUCCESS_AND_FAIL';
            IF v_skip_tpb = 1 THEN
                v_new_status := 'SEND_DOC_KH';
                v_result := 'BACK_CREATE';
            END IF;
        ELSIF ( v_total - v_reject ) = v_signed THEN
            v_new_status := 'TPB_SIGN_REPRESENT';
            v_result := 'SUCCESS';
            IF v_skip_tpb = 1 THEN
                v_new_status := 'SEND_DOC_KH';
            END IF;
        END IF;

        v_set_sign_date :=
            CASE
                WHEN v_result IN ( 'SUCCESS', 'SUCCESS_AND_FAIL' ) THEN
                    1
                ELSE 0
            END;
        v_history_status :=
            CASE
                WHEN v_new_status = 'CREATE' THEN
                    'KH_SIGN'
                ELSE v_new_status
            END;
    END IF;

    /* Không có business case phù h?p */
    IF v_new_status IS NULL OR v_result = 'INCOMPLETE' THEN
        ROLLBACK TO sp_business;
        o_result_code := 'UNHANDLED_BUSINESS_CASE';
        o_result_message := 'No business transition matched';
        o_business_result := 'NO_ACTION';
        o_new_status := v_old_status;
        add_log('STEP 11 - ERROR - UNHANDLED_BUSINESS_CASE');
        add_log('STEP 11 - total='
                || v_total
                || ', signed='
                || v_signed
                || ', failed='
                || v_failed
                || ', reject='
                || v_reject
                || ', failOther='
                || v_fail_other
                || ', skipTPB='
                || v_skip_tpb);

        RETURN;
    END IF;

    /* Update transaction */
    UPDATE sign_transaction
    SET
        status = v_new_status,
        sign_date_kh =
            CASE
                WHEN v_set_sign_date = 1 THEN
                    sysdate
                ELSE
                    sign_date_kh
            END,
        updated_date = sysdate
    WHERE
        transaction_code = p_transaction_code;

    /* History */
    INSERT INTO sign_history (
        action,
        fre_status,
        status,
        description,
        msg_fail,
        transaction_code
    ) VALUES (
        'SEND_TO_VNEID',
        'KH_SIGN',
        v_history_status,
        CASE v_result
        WHEN 'BACK_CREATE' THEN
            'L?i - Quay v? tr?ng thái Kh?i t?o'
        WHEN 'SUCCESS_AND_FAIL' THEN
            'Có c? file ???c ký L?i và Thành công - ?i ti?p flow'
        WHEN 'SUCCESS' THEN
            '?ã ký thành công - ?i ti?p flow'
        ELSE
            v_result
        END,
        v_msg_history,
        p_transaction_code
    );

    add_log('STEP 11 - businessResult: ' || v_result);
    add_log('STEP 11 - newStatus: ' || v_new_status);
    add_log('STEP 11 - historyStatus: ' || v_history_status);
    add_log('STEP 11 - historyMessage: ' || nvl(v_msg_history, 'NULL'));

    /* =========================================================
       STEP 12 - CALCULATE EMAIL
       ========================================================= */
    add_log('STEP 12 - CALCULATE EMAIL');
    IF v_all_reject = 1 THEN
        o_mail_codes := 'M_SIGN_6';
        o_mail_error_detail := 'Khách hàng t? ch?i ký s? h? s? tín d?ng';
    ELSIF
        v_result = 'SUCCESS'
        AND v_skip_tpb = 0
    THEN
        o_mail_codes := 'M_SIGN_3';
    ELSIF v_result = 'SUCCESS_AND_FAIL' THEN
        o_mail_codes :=
            CASE
                WHEN v_skip_tpb = 0 THEN
                    'M_SIGN_5,M_SIGN_3'
                ELSE 'M_SIGN_5'
            END;
    ELSIF v_result = 'BACK_CREATE' THEN
        o_mail_codes := 'M_SIGN_5';
    END IF;

    add_log('STEP 12 - mailCodes: ' || nvl(o_mail_codes, 'NULL'));

    /* =========================================================
       STEP 13 - BUILD ERROR DETAIL
       ========================================================= */
    add_log('STEP 13 - BUILD ERROR DETAIL');
    IF instr(nvl(o_mail_codes, ' '), 'M_SIGN_5') > 0 THEN
        SELECT
            LISTAGG(sa.doc_name
                    || ' - Chi ti?t l?i: '
                    || sa.msg_fail, '<br>') WITHIN GROUP(
            ORDER BY
                sa.doc_name
            )
        INTO o_mail_error_detail
        FROM
            sign_attachment sa
        WHERE
                sa.transaction_code = p_transaction_code
            AND sa.doc_type = 'NO_SIGN'
            AND nvl(sa.require_kh_sign, 0) = 1
            AND sa.status = 'SIGN_FAILED'
            AND sa.msg_fail IS NOT NULL;

    END IF;

    add_log('STEP 13 - SUCCESS');

    /* =========================================================
       STEP 14 - OUTPUT + EBANK NOTIFICATION
       Ch? t?i ?ây m?i ???c coi là hoàn t?t callback
       ========================================================= */
    o_result_code := '0';
    o_result_message := 'SUCCESS';
    o_business_result := v_result;
    o_new_status := v_new_status;
    o_callback_complete := 1;

    /*
     * TH?T B?I:
     * - Có l?i ký th?c s?
     * - Ho?c toàn b? file b? KH t? ch?i
     *
     * THÀNH CÔNG:
     * - T?t c? signed
     * - Ho?c signed + m?t ph?n KH t? ch?i
     */
    o_noti_type :=
        CASE
            WHEN v_fail_other > 0 OR v_all_reject = 1 THEN
                'DA_KY_VNEID_THAT_BAI'
            ELSE 'DA_KY_VNEID_THANH_CONG'
        END;
    add_log('STEP 14 - callbackComplete: true');
    add_log('STEP 14 - notiType: ' || o_noti_type);
    add_log('STEP 14 - businessResult: ' || v_result);
    add_log('STEP 14 - signed: '
            || v_signed
            || ', failed: '
            || v_failed
            || ', reject: '
            || v_reject
            || ', failOther: '
            || v_fail_other);

    add_log('STEP 14 - SUCCESS');
EXCEPTION
    WHEN no_data_found THEN
        ROLLBACK TO sp_business;
        o_result_code := 'DATA_NOT_FOUND';
        o_result_message := 'Current transaction/attachment not found';
        o_business_result := 'NO_ACTION';
        o_new_status := nvl(v_old_status, p_transaction_status_pre);
        o_callback_complete := 0;
        o_noti_type := NULL;
        o_mail_codes := NULL;
        o_mail_error_detail := NULL;
        add_log('ERROR - DATA_NOT_FOUND');
    WHEN too_many_rows THEN
        ROLLBACK TO sp_business;
        o_result_code := 'DATA_NOT_UNIQUE';
        o_result_message := 'Transaction/attachment not unique';
        o_business_result := 'NO_ACTION';
        o_new_status := nvl(v_old_status, p_transaction_status_pre);
        o_callback_complete := 0;
        o_noti_type := NULL;
        o_mail_codes := NULL;
        o_mail_error_detail := NULL;
        add_log('ERROR - DATA_NOT_UNIQUE');
    WHEN OTHERS THEN
        ROLLBACK TO sp_business;
        o_result_code := 'DB_ERROR';
        o_result_message := substr(sqlerrm, 1, 2000);
        o_business_result := 'NO_ACTION';
        o_new_status := nvl(v_old_status, p_transaction_status_pre);
        o_callback_complete := 0;
        o_noti_type := NULL;
        o_mail_codes := NULL;
        o_mail_error_detail := NULL;
        add_log('ERROR - '
                || substr(sqlerrm, 1, 2000));
END sp_sign_vneid_callback;

/
--------------------------------------------------------
--  DDL for Procedure SP_SIGN_VNEID_KH
--------------------------------------------------------
set define off;

  CREATE OR REPLACE NONEDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_SIGN_VNEID_KH" (
  p_json_object IN CLOB,
  P_RES_MESSAGE OUT VARCHAR2
) AS
  json_obj JSON_OBJECT_T;
  -- BK c?a SF API Callback by Sign VNeID BK
  P_TRANSACTION_CODE VARCHAR2(100) DEFAULT '';
  P_ECM_ID_ORIGIN VARCHAR2(100) DEFAULT '';
  P_ECM_ID VARCHAR2(100) DEFAULT '';
  P_FILE_NAME VARCHAR2(500) DEFAULT '';
  P_SIGNATURE_INFO VARCHAR2(4000) DEFAULT '[]';
  P_META_DATA VARCHAR2(4000) DEFAULT '{}';
  P_REQUIRED_KH NUMBER DEFAULT 0;
  P_REQUIRED_TPB NUMBER DEFAULT 0;
  P_MODIFIED_BY VARCHAR2(500) DEFAULT '';
  P_FILES JSON_ARRAY_T DEFAULT NULL;
  v_object JSON_OBJECT_T;
  v_element JSON_ELEMENT_T;
  v_size PLS_INTEGER;
  P_RESPONSE_CODE VARCHAR2(500) DEFAULT '';
  
  v_total_docs NUMBER;
  v_signed_docs NUMBER;
  v_signed_docs_fail NUMBER;
  v_exist_fail NUMBER;
BEGIN
  json_obj := JSON_OBJECT_T.parse(p_json_object);
  P_MODIFIED_BY := json_obj.get_String('modifiedBy');
  P_TRANSACTION_CODE := json_obj.get_String('transactionCode');
  P_FILES := json_obj.get_Array('files');
  P_RESPONSE_CODE := json_obj.get_String('responseCode');
  v_size := P_FILES.get_size;

  IF (v_size > 0) THEN
    FOR i IN 0.. v_size -1 LOOP
      v_element := P_FILES.get(i);
      IF (v_element IS NOT NULL) THEN
        v_object := TREAT (v_element AS JSON_OBJECT_T);
        P_ECM_ID:= v_object.get_String('docId');
        P_FILE_NAME:= v_object.get_String('docName');
        
        -- L?y thông tin t? SIGN_ATTACHMENT (d?a theo file g?c)
        BEGIN
          SELECT SIGNATURE_INFO, META_DATA, REQUIRE_KH_SIGN, REQUIRE_TPB_SIGN, DOC_ID
          INTO P_SIGNATURE_INFO, P_META_DATA, P_REQUIRED_KH, P_REQUIRED_TPB, P_ECM_ID_ORIGIN
          FROM SIGN_ATTACHMENT
          WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
            AND DOC_TYPE = 'NO_SIGN'
            AND DOC_NAME = P_FILE_NAME
            AND ROWNUM = 1;
        EXCEPTION
          WHEN NO_DATA_FOUND THEN
            P_SIGNATURE_INFO := '[]';
            P_META_DATA := '{}';
            P_REQUIRED_KH := 0;
            P_REQUIRED_TPB := 0;
        END;
        
        INSERT INTO SIGN_ATTACHMENT (TRANSACTION_CODE, DOC_ID, DOC_NAME, DOC_TYPE, STATUS, SIGNATURE_INFO, META_DATA, CREATED_BY, CREATED_DATE, REQUIRE_KH_SIGN, REQUIRE_TPB_SIGN)
        VALUES (
          P_TRANSACTION_CODE,
          P_ECM_ID,
          'B?n KH ?ã ký_' || P_FILE_NAME,
          'CUSTOMER_SIGNED',
          'NO_SIGN',
          P_SIGNATURE_INFO,
          P_META_DATA,
          P_MODIFIED_BY,
          SYSDATE,
          P_REQUIRED_KH, 
          P_REQUIRED_TPB
        );
        
        UPDATE SIGN_ATTACHMENT SET STATUS = 'SIGNED', MSG_FAIL = NULL, UPDATED_DATE = sysdate WHERE DOC_ID = P_ECM_ID_ORIGIN;-- file g?c b??c tr??c
        
      END IF;
    END LOOP;
    
    COMMIT;
  END IF;
  
-- ??m t?ng s? DOC_ID c?n KH ký
SELECT COUNT(*) INTO v_total_docs
FROM SIGN_ATTACHMENT
WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
AND DOC_TYPE = 'NO_SIGN'
--AND MSG_FAIL != ''--H?t h?n chia s? thông tin
AND REQUIRE_KH_SIGN = 1;

-- ??m s? DOC_ID ???c KH ký thành công
SELECT COUNT(*) INTO v_signed_docs
FROM SIGN_ATTACHMENT
WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
    AND (DOC_TYPE = 'CUSTOMER_SIGNED' or DOC_TYPE = 'TPB_SIGNED')
    AND REQUIRE_KH_SIGN = 1;
    
-- ??m s? DOC_ID ?ã ký thành công/ fail
SELECT COUNT(*) INTO v_signed_docs_fail
FROM SIGN_ATTACHMENT
WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
  AND DOC_TYPE = 'NO_SIGN'
  AND REQUIRE_KH_SIGN = 1
  AND (STATUS = 'SIGNED' or STATUS = 'SIGN_FAILED');

-- ??m s? DOC_ID ?ã ký fail
SELECT COUNT(*) INTO v_exist_fail
FROM SIGN_ATTACHMENT
WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
  AND DOC_TYPE = 'NO_SIGN'
  AND REQUIRE_KH_SIGN = 1
  AND STATUS = 'SIGN_FAILED';

    
-- Ki?m tra t?t c? ?ã ký ch?a
IF v_total_docs > 0 AND v_total_docs = v_signed_docs THEN
    P_RES_MESSAGE := 'SUCCESS';
    -- C?p nh?t tr?ng thái giao d?ch
    UPDATE SIGN_TRANSACTION SET STATUS = 'TPB_SIGN_REPRESENT', SIGN_DATE_KH = SYSDATE WHERE TRANSACTION_CODE = P_TRANSACTION_CODE;

    -- Ghi l?ch s? ký s?
    INSERT INTO SIGN_HISTORY (TRANSACTION_CODE, ACTION, FRE_STATUS, STATUS, DESCRIPTION, MSG_FAIL)
    VALUES (P_TRANSACTION_CODE, 'SEND_TO_VNEID', 'KH_SIGN', 'TPB_SIGN_REPRESENT', P_RES_MESSAGE, null);
    COMMIT;
ELSIF v_total_docs > 0 AND v_total_docs = v_signed_docs_fail AND v_exist_fail > 0 THEN
    P_RES_MESSAGE := 'SUCCESS_AND_FAIL';
    -- C?p nh?t tr?ng thái giao d?ch
    UPDATE SIGN_TRANSACTION SET STATUS = 'CREATE', SIGN_DATE_KH = SYSDATE WHERE TRANSACTION_CODE = P_TRANSACTION_CODE;
    -- Ghi l?ch s? ký s?
    INSERT INTO SIGN_HISTORY (TRANSACTION_CODE, ACTION, FRE_STATUS, STATUS, DESCRIPTION, MSG_FAIL)
    VALUES (P_TRANSACTION_CODE, 'SEND_TO_VNEID', 'KH_SIGN', 'KH_SIGN', P_RES_MESSAGE, 'FAILED');
    COMMIT;
ELSE P_RES_MESSAGE := 'INCOMPLETE';
END IF;

-- Thêm b??c c?p nh?t DOC_TYPE sau khi KH ký
UPDATE SIGN_ATTACHMENT
    SET DOC_TYPE = 'TPB_SIGNED', STATUS = 'SIGNED', DOC_NAME = 'B?n hoàn ch?nh_' || P_FILE_NAME
    WHERE TRANSACTION_CODE = P_TRANSACTION_CODE
    AND DOC_TYPE = 'CUSTOMER_SIGNED'
    AND REQUIRE_KH_SIGN = 1
    AND REQUIRE_TPB_SIGN = 0;
    
COMMIT;

EXCEPTION
  WHEN OTHERS THEN
    P_RES_MESSAGE := 'ERROR: ' || SQLERRM;

END SP_SIGN_VNEID_KH;

/
--------------------------------------------------------
--  DDL for Procedure SP_TPB_APP_GET_NOTIFICATIONS
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_TPB_APP_GET_NOTIFICATIONS" (
  P_USERNAME IN VARCHAR2,
  OUT_DATA OUT SYS_REFCURSOR
) AS BEGIN OPEN OUT_DATA FOR
  SELECT
    d.ID,
    d.GNCN_CODE AS transactionCode,
    d.USER_NAME AS userId,
    d.DISPLAY_NAME AS fullName,
    d.CONTENT,
    n.MARK_AS_READ,
    n.FLAG,
    n.DESCRIPTION,
    to_char(d.CREATED_DATE, 'HH24:MI, DD/MM/YYYY') AS pushTime,
    'GN_KHCN' AS processApp,
    'GNCN.Detail' AS serviceName
  FROM
    GNCN_TRANSACTION_DISSCUSTION_NOITIFICATION n
    INNER JOIN GNCN_TRANSACTION_DISSCUSTION d ON d.ID = n.TRANS_DISSCUSTION_ID
  WHERE
    1 = 1
    AND UPPER(n.USER_NAME) = UPPER(P_USERNAME)
  ORDER BY
    d.CREATED_DATE DESC;

END SP_TPB_APP_GET_NOTIFICATIONS;

/
--------------------------------------------------------
--  DDL for Procedure SP_UPDATE_ASSIGNMENT_APPROVAL
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_UPDATE_ASSIGNMENT_APPROVAL" (
    p_json_object IN CLOB
) AS 
    json_obj JSON_OBJECT_T;
    P_CODE VARCHAR2(50) DEFAULT '';
    P_STATUS VARCHAR2(200) DEFAULT '';
    P_TRANSACTION_FLOW VARCHAR2(50) DEFAULT '';
    P_PROCESSING_OWNER VARCHAR2(50) DEFAULT '';
    P_APPROVAL_BY VARCHAR2(50) DEFAULT '';
    P_APPROVER_SUGGEST VARCHAR2(50) DEFAULT '';
    P_PROCESS_GROUP VARCHAR2(50) DEFAULT '';
    P_APPROVAL_SUBMIT_TIME VARCHAR2(20) DEFAULT '';
    P_MODIFIED_BY VARCHAR2(50) DEFAULT '';
    P_MODIFIED_DATE VARCHAR2(20) DEFAULT '';
    V_APPROVAL_SUBMIT_TIME DATE DEFAULT NULL;
    V_MODIFIED_DATE DATE DEFAULT NULL;
    P_RECENT_EDITOR VARCHAR2(50) DEFAULT '';
    P_REASSIGN_FLOW_EDITOR VARCHAR2(50) DEFAULT '';
BEGIN 
    json_obj := JSON_OBJECT_T.parse(p_json_object);
    P_CODE := json_obj.get_String('gntdCode');
    P_STATUS := json_obj.get_String('status');
    P_TRANSACTION_FLOW := json_obj.get_String('transactionFlow');
    P_PROCESSING_OWNER := json_obj.get_String('processingOwner');
    P_APPROVAL_BY := json_obj.get_String('approvalBy');
    P_APPROVER_SUGGEST := json_obj.get_String('approverSuggest');
    P_PROCESS_GROUP := json_obj.get_String('processGroup');
    P_APPROVAL_SUBMIT_TIME := json_obj.get_String('approvalSubmitTime');
    P_MODIFIED_BY := json_obj.get_String('modifiedBy');
    P_MODIFIED_DATE := json_obj.get_String('modifiedDate');
    P_RECENT_EDITOR := json_obj.get_String('recentEditor');
    P_REASSIGN_FLOW_EDITOR := json_obj.get_String('reassignFlow');
     
--    DBMS_OUTPUT.PUT_LINE('P_MODIFIED_DATE = ' || P_MODIFIED_DATE);
    IF (P_MODIFIED_DATE IS NOT NULL) 
        THEN 
--            DBMS_OUTPUT.PUT_LINE('V_MODIFIED_DATE = ' || P_MODIFIED_DATE);
            V_MODIFIED_DATE := TO_DATE(P_MODIFIED_DATE, 'YYYY-MM-DD HH24:MI:SS');
       ELSE 
            V_MODIFIED_DATE := SYSDATE;
    END IF;
    
--    DBMS_OUTPUT.PUT_LINE('P_APPROVAL_SUBMIT_TIME = ' || P_APPROVAL_SUBMIT_TIME);
    IF (P_APPROVAL_SUBMIT_TIME IS NOT NULL)
        THEN
--            DBMS_OUTPUT.PUT_LINE('V_APPROVAL_SUBMIT_TIME = ' || P_MODIFIED_DATE);
            V_APPROVAL_SUBMIT_TIME := TO_DATE(P_APPROVAL_SUBMIT_TIME, 'YYYY-MM-DD HH24:MI:SS');
        ELSE 
            V_APPROVAL_SUBMIT_TIME := NULL;
    END IF;

    UPDATE GNCN_TRANSACTION 
        SET 
            STATUS=P_STATUS,
            TRANSACTION_FLOW=P_TRANSACTION_FLOW,
            PROCESSING_OWNER=P_PROCESSING_OWNER,
            PROCESS_GROUP=P_PROCESS_GROUP,
            APPROVER_SUGGEST=P_APPROVER_SUGGEST,
            APPROVAL_SUBMIT_TIME=V_APPROVAL_SUBMIT_TIME,
            MODIFIED_BY=P_MODIFIED_BY,
            MODIFIED_DATE=V_MODIFIED_DATE,
            LAST_PROCESSING_UNIT = P_REASSIGN_FLOW_EDITOR,
            RECENT_EDITOR = P_RECENT_EDITOR,
            USER_LOCKED = NULL
        WHERE GNTD_CODE=P_CODE;

END SP_UPDATE_ASSIGNMENT_APPROVAL;

