--------------------------------------------------------
--  DDL for Procedure SP_UPDATE_ENTRY_NUM_FCC
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_UPDATE_ENTRY_NUM_FCC" (
  p_json_object IN CLOB
) AS 
  json_obj JSON_OBJECT_T;
  loanData JSON_OBJECT_T;
  P_CODE VARCHAR2(50) DEFAULT '';
  P_STATUS VARCHAR2(200) DEFAULT '';
  P_FCC_REF_NUM VARCHAR2(100) DEFAULT NULL;
  P_INTERFACE_STATUS VARCHAR2(100) DEFAULT NULL;
  P_LOAN_DATA CLOB DEFAULT NULL;
  P_INTERFACE_MSG CLOB DEFAULT NULL;
  P_PRE_STATUS VARCHAR2(200) DEFAULT '';
  P_MODIFIED_BY VARCHAR2(50) DEFAULT '';
BEGIN 
  json_obj := JSON_OBJECT_T.parse(p_json_object);
  P_CODE := json_obj.get_String('gntdCode');
  P_STATUS := json_obj.get_String('status');
  P_LOAN_DATA := TO_CLOB(json_obj.get_String('loanData'));
  loanData := JSON_OBJECT_T.parse(P_LOAN_DATA);
  P_FCC_REF_NUM := loanData.get_String('entryNumFcc');
  P_INTERFACE_STATUS := loanData.get_String('interfaceStatus');
  P_INTERFACE_MSG := TO_CLOB(loanData.get_String('interfaceError'));
  P_PRE_STATUS := json_obj.get_String('preStatus');
  P_MODIFIED_BY := json_obj.get_String('modifiedBy');

  UPDATE 
    GNCN_TRANSACTION_PURPOSE
  SET 
    LOAN_DATA = P_LOAN_DATA,
    INTERFACE_MSG = P_INTERFACE_MSG,
    INTERFACE_STATUS = P_INTERFACE_STATUS,
    FCC_REF_NUM = P_FCC_REF_NUM
  WHERE GNTD_CODE = P_CODE;

  UPDATE 
    GNCN_TRANSACTION 
  SET 
    STATUS = P_STATUS,
    MODIFIED_BY = P_MODIFIED_BY
  WHERE GNTD_CODE = P_CODE;

  INSERT INTO GNCN_TRANSACTION_HISTORY(
    GNTD_CODE,
    STATUS,
    CREATED_BY,
    ACTION,
    PRE_STATUS
  )
  VALUES (
    P_CODE,
    P_STATUS,
    P_MODIFIED_BY,
    'System Update',
    P_PRE_STATUS --'GNCN_LOI_HACH_TOAN_KHOAN_VAY'
  );

END SP_UPDATE_ENTRY_NUM_FCC;

