--  DDL for Procedure SP_UPDATE_GNCN_CA_DISBURSEMENT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_UPDATE_GNCN_CA_DISBURSEMENT" 
  (
     I_TASK_ID Varchar ,
     I_INSTANCE_ID Varchar ,
     I_STATUS   Varchar ,
     I_GNTD_CODE Varchar,
     I_PDTD_CODE Varchar,
     I_BRANCH_CODE Varchar, 
     I_BRANCH_NAME Varchar,
     I_TRANSACTION_CODE varchar,
     I_DOCUMENT_TYPE varchar,
     I_APPROVAL_BY  varchar,
     I_APPROVAL_DATE TIMESTAMP,
     I_TRANSACTION_FLOW varchar ,
     I_TRANSACTION_TYPE1 varchar,
     I_TRANSACTION_TYPE2 varchar,
     I_TRANSACTION_TYPE3 varchar,
     I_CUSTOMER_CODE varchar,
     I_CUSTOMER_NAME varchar,
     I_CREDIT_USER  varchar,
     I_PROCESSING_USERNAME varchar,
     I_DOCUMENT_SRC varchar,
     I_CREATED_BY varchar,
     ID_CARD varchar,
     I_CUSTOMER_TYPE varchar
  )
AS 
    sql_Temp    VARCHAR2(2000) DEFAULT '';
    tempId      NUMBER;
    currentDate DATE := SYSDATE;
BEGIN
    tempId := -1;
    sql_Temp := 'SELECT COUNT(*) FROM GNCN_CA_DISBURSEMENT WHERE PDTD_CODE = :I_PDTD_CODE AND GNTD_CODE = :I_GNTD_CODE';
    EXECUTE IMMEDIATE sql_Temp INTO tempId USING  I_PDTD_CODE , I_GNTD_CODE ;
  IF ( tempId < 1) THEN   
    INSERT INTO GNCN_CA_DISBURSEMENT (
        TASK_ID,
        INSTANCE_ID,
        STATUS,
        GNTD_CODE,
        PDTD_CODE,
        BRANCH_CODE,
        BRANCH_NAME,
        TRANSACTION_CODE,
        DOCUMENT_TYPE,
        APPROVAL_BY,
        APPROVAL_DATE,
        TRANSACTION_FLOW,
        TRANSACTION_TYPE1,
        TRANSACTION_TYPE2,
        TRANSACTION_TYPE3,
        CUSTOMER_CODE,
        CUSTOMER_NAME ,
        CREDIT_USER,
        PROCESSING_USERNAME,
        DOCUMENT_SRC,
        CREATED_BY,
        ID_CARD,
        CUSTOMER_TYPE
    ) VALUES (
        I_TASK_ID,
        I_INSTANCE_ID,
        I_STATUS,
        I_GNTD_CODE,
        I_PDTD_CODE,
        I_BRANCH_CODE ,
        I_BRANCH_NAME ,
        I_TRANSACTION_CODE ,
        I_DOCUMENT_TYPE ,
        I_APPROVAL_BY,
        I_APPROVAL_DATE ,
        I_TRANSACTION_FLOW  ,
        I_TRANSACTION_TYPE1 ,
        I_TRANSACTION_TYPE2 ,
        I_TRANSACTION_TYPE3 ,
        I_CUSTOMER_CODE ,
        I_CUSTOMER_NAME ,
        I_CREDIT_USER  ,
        I_PROCESSING_USERNAME ,
        I_DOCUMENT_SRC,
        I_CREATED_BY,
        ID_CARD,
        I_CUSTOMER_TYPE
    )
     RETURNING ID INTO tempId;
   ELSE 
    UPDATE GNCN_CA_DISBURSEMENT
    SET TASK_ID = I_TASK_ID,
        INSTANCE_ID = I_INSTANCE_ID,
        STATUS = I_STATUS,
        BRANCH_CODE = I_BRANCH_CODE,
        BRANCH_NAME = I_BRANCH_NAME,
        TRANSACTION_CODE = I_TRANSACTION_CODE,
        DOCUMENT_TYPE =I_DOCUMENT_TYPE,
        APPROVAL_BY = I_APPROVAL_BY,
        APPROVAL_DATE = I_APPROVAL_DATE,
        TRANSACTION_FLOW = I_TRANSACTION_FLOW,
        TRANSACTION_TYPE1 = I_TRANSACTION_TYPE1,
        TRANSACTION_TYPE2= I_TRANSACTION_TYPE2,
        TRANSACTION_TYPE3 =I_TRANSACTION_TYPE3,
        CUSTOMER_CODE = I_CUSTOMER_CODE,
        CUSTOMER_NAME = I_CUSTOMER_NAME,
        CREDIT_USER =I_CREDIT_USER,
        PROCESSING_USERNAME = I_PROCESSING_USERNAME,
        DOCUMENT_SRC = I_DOCUMENT_SRC,
        CREATED_BY = I_CREATED_BY,
        ID_CARD = ID_CARD,
        CUSTOMER_TYPE = I_CUSTOMER_TYPE
   WHERE gntd_code = I_GNTD_CODE and PDTD_CODE = I_PDTD_CODE ;
   END IF;
 COMMIT;
END SP_UPDATE_GNCN_CA_DISBURSEMENT;

