--------------------------------------------------------
--  DDL for Procedure SP_UPDATE_GNCN_EMPLOYEE_PROCESS_CONFIG
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_UPDATE_GNCN_EMPLOYEE_PROCESS_CONFIG" (
    p_json_object IN CLOB,
    P_MODIFIED_BY IN VARCHAR
) AS
    json_obj JSON_OBJECT_T;
    v_userName VARCHAR2(50) DEFAULT '';
    v_fullName VARCHAR2(200) DEFAULT '';
    v_branchCode VARCHAR2(50) DEFAULT '';
    v_branchs VARCHAR2(2000) DEFAULT '';
    v_role VARCHAR2(200) DEFAULT '';
    v_positionCode VARCHAR2(200) DEFAULT '';
    v_userManager VARCHAR2(50) DEFAULT '';
BEGIN
    json_obj := JSON_OBJECT_T.parse(p_json_object);
    v_userName:= json_obj.get_String('userName');
    v_fullName:= json_obj.get_String('fullName');
    v_branchCode:= json_obj.get_String('branchCode');
    v_branchs:= json_obj.get_String('branchs');
    v_role:= json_obj.get_String('role');
    v_positionCode:= json_obj.get_String('positionCode');
    v_userManager:= json_obj.get_String('userManager');
    IF (v_userName IS NULL) THEN v_userName := ''; END IF;
    IF (v_positionCode IS NULL) THEN v_positionCode := ''; END IF;
    IF (v_userManager IS NULL) THEN v_userManager := NULL; END IF;
    IF (v_fullName IS NULL) THEN v_fullName := NULL; END IF;
    IF (v_branchCode IS NULL) THEN v_branchCode := NULL; END IF;
    IF (v_branchs IS NULL) THEN v_branchs := NULL; END IF;
    IF (v_role IS NULL) THEN v_role := NULL; END IF;

    UPDATE GNCN_EMPLOYEE_PROCESS_CONFIG SET USE_STATUS = 2 WHERE USE_STATUS = 1 AND USER_NAME = v_userName;

    INSERT INTO GNCN_EMPLOYEE_PROCESS_CONFIG (
        USER_NAME,
        FULL_NAME,
        BRANCH_MAIN,
        BRANCHS,
        ROLE,
        POSITION_CODE,
        USER_MANAGER,
        CREATED_BY,
        CREATED_DATE
    ) VALUES (
        v_userName, 
        v_fullName,
        v_branchCode,
        v_branchs,
        v_role,
        v_positionCode,
        v_userManager,
        P_MODIFIED_BY,
        SYSDATE
    );

    UPDATE GNCN_EMPLOYEE_PROCESS_CONFIG SET USE_STATUS = 0 WHERE USE_STATUS = 2 AND USER_NAME = v_userName;

END SP_UPDATE_GNCN_EMPLOYEE_PROCESS_CONFIG;

