--  DDL for Procedure SP_UPDATE_GNCN_LIMIT_ACCOUNTING
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_UPDATE_GNCN_LIMIT_ACCOUNTING" (
    P_GNTD_CODE IN VARCHAR2,
    p_json_object IN CLOB,
    P_MODIFIED_BY IN VARCHAR2
) AS 
    json_obj JSON_OBJECT_T;
    P_STATUS VARCHAR2(50) DEFAULT '';
    P_LINE_CODE VARCHAR2(20) DEFAULT ''; --Mã h?n m?c
    P_LIMIT_CODE VARCHAR2(20) DEFAULT ''; --Mã h?n m?c sau h?ch toán
    P_LIMIT_JSON_DATA CLOB;--VARCHAR2(4000) DEFAULT NULL;
    P_MESSAGE VARCHAR2(2000) DEFAULT '';
BEGIN 
    json_obj := JSON_OBJECT_T.parse(p_json_object);
    P_STATUS := json_obj.get_String('status');
    P_LINE_CODE := json_obj.get_String('lineCode');
    P_LIMIT_CODE := json_obj.get_String('limitCode');
    P_LIMIT_JSON_DATA := json_obj.get_Clob('limitData');
    P_MESSAGE := json_obj.get_String('message');

    -- DBMS_OUTPUT.PUT_LINE('UPDATE GNCN_TRANSACTION LIMIT INFO');
    UPDATE GNCN_TRANSACTION 
        SET 
            USER_LOCKED = NULL,
            STATUS = P_STATUS,
            LINE_CODE = P_LINE_CODE, -- Mã h?n m?c
            LIMIT_CODE = P_LIMIT_CODE, -- Mã h?n m?c
            LIMIT_JSON_DATA = P_LIMIT_JSON_DATA, -- Thông tin h?ch toán h?n m?c
            MESSAGE = P_MESSAGE,
            MODIFIED_BY = P_MODIFIED_BY,
            MODIFIED_DATE = SYSDATE
        WHERE GNTD_CODE=P_GNTD_CODE;

END SP_UPDATE_GNCN_LIMIT_ACCOUNTING;

