--------------------------------------------------------
--  DDL for Procedure SP_UPDATE_GNCN_OVERDRAFT_ACCOUNTING
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_UPDATE_GNCN_OVERDRAFT_ACCOUNTING" (
    P_GNTD_CODE IN VARCHAR2,
    p_json_object IN CLOB,
    P_MODIFIED_BY IN VARCHAR2
) AS
    json_obj JSON_OBJECT_T;
    P_STATUS VARCHAR2(50) DEFAULT '';
    P_MESSAGE VARCHAR2(2000) DEFAULT '';
    P_OVERDRAFT_DATA CLOB DEFAULT NULL;
    overdraftData JSON_OBJECT_T;
    P_FCC_REF_NUM VARCHAR2(50) DEFAULT '';
    P_INTERFACE_STATUS VARCHAR2(100) DEFAULT '001';
BEGIN
    json_obj := JSON_OBJECT_T.parse(p_json_object);
    P_STATUS := json_obj.get_String('status');
    P_MESSAGE := json_obj.get_String('message');
    P_OVERDRAFT_DATA := TO_CLOB(json_obj.get_String('overdraftData'));
    IF (P_MESSAGE IS NULL) THEN
       overdraftData := JSON_OBJECT_T.parse(P_OVERDRAFT_DATA);
       P_FCC_REF_NUM := overdraftData.get_String('overdraftAccount');
       P_INTERFACE_STATUS := '00';
    END IF;

    UPDATE GNCN_TRANSACTION 
        SET 
            USER_LOCKED = NULL,
            STATUS = P_STATUS,
            MESSAGE = P_MESSAGE,
            MODIFIED_BY = P_MODIFIED_BY,
            MODIFIED_DATE = SYSDATE
        WHERE GNTD_CODE = P_GNTD_CODE;
        
    UPDATE GNCN_TRANSACTION_PURPOSE 
        SET 
            OVERDRAFT_DATA = P_OVERDRAFT_DATA,
            FCC_REF_NUM = P_FCC_REF_NUM,
            INTERFACE_MSG = P_MESSAGE,
            INTERFACE_STATUS = P_INTERFACE_STATUS,
            INTERFACE_DATE = SYSDATE,
            MODIFIED_BY = P_MODIFIED_BY,
            MODIFIED_DATE = SYSDATE
        WHERE GNTD_CODE = P_GNTD_CODE;
END SP_UPDATE_GNCN_OVERDRAFT_ACCOUNTING;

/
--------------------------------------------------------
--  DDL for Procedure SP_UPDATE_GNCN_PAYMENT_ACCOUNTING
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_UPDATE_GNCN_PAYMENT_ACCOUNTING" (
    P_GNTD_CODE IN VARCHAR2,
    P_STATUS IN VARCHAR2,
    P_MESSAGE IN VARCHAR2,
    P_MODIFIED_BY IN VARCHAR2
) AS BEGIN
    UPDATE
      GNCN_TRANSACTION
    SET
      STATUS = P_STATUS,
      -- MESSAGE = P_MESSAGE,
      MODIFIED_BY = P_MODIFIED_BY,
      MODIFIED_DATE = SYSDATE
    WHERE
      GNTD_CODE = P_GNTD_CODE;

    -- UPDATE PAYMENT
    UPDATE
      GNCN_TRANSACTION_PAYMENT
    SET
      USER_ACCOUNTING = P_MODIFIED_BY,
      MODIFIED_BY = P_MODIFIED_BY,
      MODIFIED_DATE = SYSDATE
    WHERE
      GNTD_CODE = P_GNTD_CODE;
      
END SP_UPDATE_GNCN_PAYMENT_ACCOUNTING;

/
--------------------------------------------------------
--  DDL for Procedure SP_UPDATE_GNCN_PRODUCT_CATEGORY_CONFIG
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_UPDATE_GNCN_PRODUCT_CATEGORY_CONFIG" (
    p_json_object IN CLOB,
    P_MODIFIED_BY IN VARCHAR
) AS 
    json_obj JSON_OBJECT_T;
    v_productType VARCHAR2(200) DEFAULT '';
    v_productName VARCHAR2(200) DEFAULT '';
    v_loanMethod VARCHAR2(200) DEFAULT '';
    v_loanPurpose VARCHAR2(500) DEFAULT '';

BEGIN
    json_obj := JSON_OBJECT_T.parse(p_json_object);
    v_productType:= json_obj.get_String('productType');
    v_productName:= json_obj.get_String('productName');
    v_loanMethod:= json_obj.get_String('loanMethod');
    v_loanPurpose:= json_obj.get_String('loanPurpose');
    IF (v_productType IS NULL) THEN v_productType := ''; END IF;
    IF (v_productName IS NULL) THEN v_productName := ''; END IF;
    IF (v_loanMethod IS NULL) THEN v_loanMethod := ''; END IF;
    IF (v_loanPurpose IS NULL) THEN v_loanPurpose := ''; END IF;

    UPDATE GNCN_PRODUCT_CATEGORY_CONFIG SET USE_STATUS = 2 WHERE USE_STATUS = 1 
    AND PRODUCT_TYPE = v_productType AND PRODUCT_NAME = v_productName AND LOAN_METHOD = v_loanMethod;

    INSERT INTO GNCN_PRODUCT_CATEGORY_CONFIG (
        PRODUCT_TYPE,
        PRODUCT_NAME,
        LOAN_METHOD,
        LOAN_PURPOSE,
        CREATED_BY,
        CREATED_DATE,
        MODIFIED_BY,
        MODIFIED_DATE                        
    ) VALUES (
        v_productType,
        v_productName,
        v_loanMethod,
        v_loanPurpose,
        P_MODIFIED_BY,
        SYSDATE,
        P_MODIFIED_BY,
        SYSDATE
    );

    UPDATE GNCN_PRODUCT_CATEGORY_CONFIG SET USE_STATUS = 0 WHERE USE_STATUS = 2
    AND PRODUCT_TYPE = v_productType AND PRODUCT_NAME = v_productName AND LOAN_METHOD = v_loanMethod;
    Commit;

END SP_UPDATE_GNCN_PRODUCT_CATEGORY_CONFIG;

/
--------------------------------------------------------
--  DDL for Procedure SP_UPDATE_GNCN_TRANSACTION_APPROVAL
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_UPDATE_GNCN_TRANSACTION_APPROVAL" (
    p_json_arr IN CLOB,
    p_gntd_code IN VARCHAR2,
    P_MESS OUT VARCHAR2
) AS 
    json_arr                        JSON_ARRAY_T;
    json_obj                        JSON_OBJECT_T;
    p_id                            NUMBER;
    p_title                         VARCHAR2(500) DEFAULT '';
    p_isApproved                    NUMBER DEFAULT 0;
    p_groupId                       VARCHAR2(200) DEFAULT '';
    p_comments                      VARCHAR2(2000) DEFAULT '';
    trans_approval_id               NUMBER;

    -- Ly do tu choi
    json_arr_reason                 JSON_ARRAY_T;
    json_obj_reason                 JSON_OBJECT_T;
    p_errorType                     VARCHAR2(200) DEFAULT '';
    p_errorDetail                   VARCHAR2(4000) DEFAULT '';
    p_group                         VARCHAR2(200) DEFAULT '';

BEGIN 
    SAVEPOINT SP_UPDATE_DATA;
--    DELETE FROM GNCN_TRANSACTION_APPROVAL WHERE gntd_code = p_gntd_code;
--    DELETE FROM GNCN_REASON_REFUSE WHERE gntd_code = p_gntd_code;
    json_arr := json_array_t(p_json_arr);
    FOR i IN 0..json_arr.get_size - 1
    LOOP
        json_obj := TREAT( json_arr.get ( i ) AS JSON_OBJECT_T );
        p_id := json_obj.get_Number('id');
        p_title := json_obj.get_String('title');
        p_groupId := json_obj.get_String('groupId');
        p_comments := json_obj.get_String('comments');
        IF(json_obj.get_Boolean('isApproved')) THEN p_isApproved := 1;
        ELSE p_isApproved := 0;
        END IF;
        
        INSERT INTO GNCN_TRANSACTION_APPROVAL(GNTD_CODE, title, group_id, comments, is_approved, created_date)
        VALUES (p_gntd_code, p_title, p_groupId, p_comments, p_isApproved, SYSDATE) RETURNING ID INTO trans_approval_id;
        IF(json_obj.get_Array('reasonRefuse') IS NOT NULL) THEN
            json_arr_reason := json_obj.get_Array('reasonRefuse');
            FOR i IN 0..json_arr_reason.get_size - 1
            LOOP
                json_obj_reason := TREAT( json_arr_reason.get ( i ) AS JSON_OBJECT_T );
                p_group := json_obj_reason.get_String('group');
                p_errorType := json_obj_reason.get_String('errorType');
                p_errorDetail := json_obj_reason.get_String('errorDetail');
                INSERT INTO GNCN_REASON_REFUSE (group_code, error_code, error_detail, trans_approval_id,
                created_date, gntd_code)
                VALUES (p_group, p_errorType, p_errorDetail, trans_approval_id, SYSDATE, p_gntd_code);
            END LOOP;
        END IF;
    END LOOP;
    P_MESS := '1';
EXCEPTION
   WHEN OTHERS 
   THEN ROLLBACK  TO SP_UPDATE_DATA;
    P_MESS := SUBSTR(SQLERRM, 1, 500);
END SP_UPDATE_GNCN_TRANSACTION_APPROVAL;

/
