--  DDL for Procedure SP_UPDATE_GNCN_TRANSACTION_ATTACHMENT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_UPDATE_GNCN_TRANSACTION_ATTACHMENT" 
(
    P_ID              IN    NUMBER,   --
    P_GNCN_CODE       IN    VARCHAR2,                --Mã giao d?ch gi?i ngân
    P_GROUP_NAME      IN    VARCHAR2,               --Hi?n th? tên nhóm h? s? c?p 1
    P_DOC_NAME        IN    VARCHAR2,               --Danh sách Checklist
    P_FILE_NAME       IN    VARCHAR2,               --DisplayName
    P_DOC_ID          IN    VARCHAR2,               --ECM ID file
    P_ECM_PATH        IN    VARCHAR2,               --ECM Path 
    P_FILE_SIZE       IN    VARCHAR2,               --
    P_DOC_SOURCE      IN    VARCHAR2,               --Ngu?n file: BPM, ECM, xxx
    P_CREATED_BY      IN    VARCHAR2,   --
    P_CREATED_DATE    IN    DATE,   --
    P_MODIFIED_BY     IN    VARCHAR2,   --
    P_MODIFIED_DATE   IN    DATE,
    P_PDTD_CODE       IN    VARCHAR2                --Mã LOS/PDTD
) AS 
    sql_Temp VARCHAR2(2000) DEFAULT '';
    tempId NUMBER;
    currentDate DATE := SYSDATE; 
BEGIN
    tempId := -1;
    sql_Temp := 'SELECT COUNT(*) FROM GNCN_TRANSACTION_ATTACHMENT WHERE ID=:id';

    EXECUTE IMMEDIATE  sql_Temp INTO tempId USING P_ID;
    IF (P_ID IS NULL OR P_ID <=0 OR tempId < 1) THEN
        INSERT INTO GNCN_TRANSACTION_ATTACHMENT (
            GNCN_CODE, --
            GROUP_NAME,
            DOC_NAME,
            FILE_NAME,
            DOC_ID,
            ECM_PATH,
            FILE_SIZE,
            DOC_SOURCE,
            CREATED_BY, --
            CREATED_DATE,
            PDTD_CODE
        ) 
        VALUES(
            P_GNCN_CODE, --
            P_GROUP_NAME,
            P_DOC_NAME,
            P_FILE_NAME,
            P_DOC_ID,
            P_ECM_PATH,
            P_FILE_SIZE,
            P_DOC_SOURCE,
            P_CREATED_BY, --
            currentDate,
            P_PDTD_CODE
        )
        RETURNING ID INTO tempId;
    ELSE
        UPDATE GNCN_TRANSACTION_ATTACHMENT
        SET
            GNCN_CODE = P_GNCN_CODE, --
            GROUP_NAME = P_GROUP_NAME, --
            DOC_NAME = P_DOC_NAME, --
            FILE_NAME = P_FILE_NAME, --
            DOC_ID = P_DOC_ID, --
            ECM_PATH = P_ECM_PATH, --
            FILE_SIZE = P_FILE_SIZE,
            DOC_SOURCE = P_DOC_SOURCE,
            MODIFIED_BY = P_CREATED_BY, --
            MODIFIED_DATE = currentDate,
            PDTD_CODE = P_PDTD_CODE
        WHERE ID = P_ID;
    END IF;
END SP_UPDATE_GNCN_TRANSACTION_ATTACHMENT;

/
--------------------------------------------------------
--  DDL for Procedure SP_UPDATE_GNCN_TRANSACTION_CA_DISBURSEMENT_DOCUMENTS
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_UPDATE_GNCN_TRANSACTION_CA_DISBURSEMENT_DOCUMENTS" 
(
    p_json_arr IN CLOB,
    P_MESS OUT VARCHAR2
) AS 
    sql_Temp                VARCHAR2(2000) DEFAULT '';
    tempId                  NUMBER;
    currentDate             DATE := SYSDATE;
    json_obj                JSON_OBJECT_T;
    json_arr                JSON_ARRAY_T;

    P_ID                    NUMBER;
    P_STATUS                VARCHAR2(100);
    P_STATUS_APPROVAL       VARCHAR2(50);
    P_MODIFIED_BY           VARCHAR2(50);
    P_MODIFIED_DATE         DATE;
    P_DEADLINE_EXT          DATE;
    P_DEADLINE              DATE;
    P_PRE_STATUS_DOC        VARCHAR2(50);
    P_STATUS_DOC            VARCHAR2(50);
    P_STATUS_VERIFY         NUMBER;
    P_USER_PHE_DUYET        VARCHAR2(50);
    P_APPROVAL_BY           VARCHAR2(50);
    P_APPROVAL_DATE         DATE;
    P_APPROVAL_SUBMIT_BY    VARCHAR2(50);
    P_APPROVAL_SUBMIT_DATE  DATE;
    
    -- caDisbursement
    obj_caDisbursement      JSON_OBJECT_T;
    P_ID_CA                 NUMBER;

BEGIN
    SAVEPOINT SP_UPDATE_DATA;
    json_arr := JSON_ARRAY_T(p_json_arr);

    FOR i IN 0..json_arr.get_size - 1 LOOP
        -- Mapping input
        json_obj := JSON_OBJECT_T(json_arr.get(i));
        P_ID := json_obj.get_Number('id');
        P_STATUS := json_obj.get_String('status');
        P_STATUS_APPROVAL := json_obj.get_String('statusApproval');
        P_STATUS_DOC := json_obj.get_String('statusDoc');
        P_PRE_STATUS_DOC := P_STATUS_DOC;
        P_MODIFIED_BY := json_obj.get_String('modifiedBy');
        P_MODIFIED_DATE := json_obj.get_Date('modifiedDate');
        P_DEADLINE_EXT := json_obj.get_Date('deadlineExt');
        P_DEADLINE := json_obj.get_Date('deadline');
        P_APPROVAL_BY := json_obj.get_String('approvalBy');
        P_APPROVAL_DATE := json_obj.get_Date('approvalDate');
        P_APPROVAL_SUBMIT_BY := json_obj.get_String('approvalSubmitBy');
        P_APPROVAL_SUBMIT_DATE := json_obj.get_Date('approvalSubmitDate');
--        P_USER_PHE_DUYET := json_obj.get_String('userPheDuyet');
--        
--        IF P_USER_PHE_DUYET IS NULL THEN
--           P_USER_PHE_DUYET := json_obj.get_String('assigneeUserBy');
--        END IF;

        P_STATUS_VERIFY := 0;
        
        IF json_obj.get_Object('caDisbursement') IS NOT NULL THEN    
            obj_caDisbursement := json_obj.get_Object('caDisbursement');
            P_ID_CA := obj_caDisbursement.get_Number('id');
        END IF;

        -- Processing status logic
        IF P_STATUS = 'HSSGN_CHO_PHE_DUYET' THEN
            IF P_STATUS_DOC = 'DA_BO_SUNG' THEN
                IF P_STATUS_APPROVAL = 'DONG_Y' THEN
                    P_STATUS := 'HSSGN_HOAN_THANH';
                ELSIF P_STATUS_APPROVAL = 'TU_CHOI' THEN
                    P_STATUS := 'HSSGN_CHO_BO_SUNG';
                    P_STATUS_DOC := 'CHUA_BO_SUNG';
                END IF;
            ELSIF P_STATUS_DOC = 'GIA_HAN_BO_SUNG' THEN
                IF P_STATUS_APPROVAL = 'DONG_Y' THEN
                    P_STATUS := 'HSSGN_CHO_BO_SUNG';
                    P_STATUS_DOC := 'CHUA_BO_SUNG';
                    P_DEADLINE := P_DEADLINE_EXT;
                ELSIF P_STATUS_APPROVAL = 'TU_CHOI' THEN
                    P_STATUS := 'HSSGN_CHO_BO_SUNG';
                    P_STATUS_DOC := 'CHUA_BO_SUNG';
                END IF;
            ELSIF P_STATUS_DOC = 'HUY_TAN_SUAT' THEN
                IF P_STATUS_APPROVAL = 'DONG_Y' THEN
                    P_STATUS := 'HSSGN_CHO_BO_SUNG';
                    P_STATUS_DOC := 'CHUA_BO_SUNG';
                ELSIF P_STATUS_APPROVAL = 'TU_CHOI' THEN
                    P_STATUS := 'HSSGN_CHO_BO_SUNG';   
                    P_STATUS_DOC := 'CHUA_BO_SUNG';
                END IF;
            ELSIF P_STATUS_DOC = 'HUY_DIEU_KIEN_BO_SUNG' THEN
                IF P_STATUS_APPROVAL = 'DONG_Y' THEN
                    P_STATUS := 'HSSGN_HUY_DK_BO_SUNG';
                ELSIF P_STATUS_APPROVAL = 'TU_CHOI' THEN
                    P_STATUS := 'HSSGN_CHO_BO_SUNG'; 
                    P_STATUS_DOC := 'CHUA_BO_SUNG';
                END IF;
            END IF;
        ELSIF P_STATUS = 'HSSGN_CHO_BO_SUNG' THEN 
            P_STATUS := 'HSSGN_CHO_PHE_DUYET';
            P_STATUS_APPROVAL := 'CHO_PHE_DUYET';
        END IF;       

        -- Update statement
        UPDATE gncn_ca_disbursement_documents
        SET
            STATUS = P_STATUS,
            STATUS_APPROVAL = P_STATUS_APPROVAL,
            STATUS_VERIFY = P_STATUS_VERIFY,
            STATUS_DOC = P_STATUS_DOC,
            PRE_STATUS_DOC = P_PRE_STATUS_DOC,
            DEADLINE = P_DEADLINE,
            MODIFIED_BY = P_MODIFIED_BY,
            MODIFIED_DATE = currentDate,
            APPROVAL_BY = P_APPROVAL_BY,
            APPROVAL_DATE = P_APPROVAL_DATE,
            APPROVAL_SUBMIT_BY = P_APPROVAL_SUBMIT_BY,
            APPROVAL_SUBMIT_DATE = P_APPROVAL_SUBMIT_DATE
--            ASSIGNEE_USER_BY = P_USER_PHE_DUYET
        WHERE ID = P_ID;
    END LOOP; -- Correct closing of the loop

    P_MESS := '1';
EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK TO SP_UPDATE_DATA;
        P_MESS := SUBSTR(SQLERRM, 1, 500);
END SP_UPDATE_GNCN_TRANSACTION_CA_DISBURSEMENT_DOCUMENTS;

/
--------------------------------------------------------
--  DDL for Procedure SP_UPDATE_GNCN_TRANSACTION_DISCUSSION
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_UPDATE_GNCN_TRANSACTION_DISCUSSION" (
        P_JSON IN CLOB,
        P_MESS OUT VARCHAR2
) AS
    json_obj        JSON_OBJECT_T;
    user_noti_arr   JSON_ARRAY_T;
    P_ID            NUMBER;
    P_GNCN_CODE     VARCHAR2(50) DEFAULT '';
    P_USER_NAME     VARCHAR2(50) DEFAULT '';
    P_DISPLAY_NAME  VARCHAR2(50) DEFAULT '';
    P_CONTENT       CLOB;
    P_CREATED_BY    VARCHAR2(50) DEFAULT '';
    P_MODIFIED_BY   VARCHAR2(50) DEFAULT '';
    P_NOTI_USER     VARCHAR2(50) DEFAULT '';
    sumDiscussion   NUMBER := 0;
    currentDate     DATE := SYSDATE;
BEGIN
    SAVEPOINT SP_UPDATE_DATA;
    json_obj := JSON_OBJECT_T.parse(P_JSON);
    P_ID := json_obj.get_Number('id');
    P_GNCN_CODE := json_obj.get_String('gncnCode');
    P_USER_NAME := json_obj.get_String('userName');
    P_DISPLAY_NAME := json_obj.get_String('displayName');
    P_CONTENT := json_obj.get_Clob('content');
    P_CREATED_BY := json_obj.get_String('createdBy');
    P_MODIFIED_BY := json_obj.get_String('modifiedBy');
    SELECT COUNT(*) into sumDiscussion FROM GNCN_TRANSACTION_DISSCUSTION WHERE ID = P_ID;
    IF(P_ID IS NULL OR P_ID <=0 OR sumDiscussion < 1) THEN
        INSERT INTO GNCN_TRANSACTION_DISSCUSTION(
            GNCN_CODE,
            USER_NAME,
            DISPLAY_NAME,
            CONTENT,
            CREATED_BY,
            CREATED_DATE,
            MODIFIED_BY,
            MODIFIED_DATE
        )
        VALUES(
            P_GNCN_CODE,
            P_USER_NAME,
            P_DISPLAY_NAME,
            P_CONTENT,
            P_CREATED_BY,
            currentDate,
            P_MODIFIED_BY,
            currentDate
        )
        RETURNING ID INTO P_ID;
        IF (json_obj.get_Array('userNoti') IS NOT NULL) THEN
            user_noti_arr := json_obj.get_Array('userNoti');
                FOR i IN 0 .. user_noti_arr.get_size - 1 LOOP
                    P_NOTI_USER := REPLACE(user_noti_arr.get(i).to_string(), '"', '');
                    INSERT INTO GNCN_TRANSACTION_DISSCUSTION_NOITIFICATION(
                        TRANS_DISSCUSTION_ID,
                        USER_NAME,
                        CREATED_BY,
                        CREATED_DATE,
                        MODIFIED_BY,
                        MODIFIED_DATE
                    )
                    VALUES(
                        P_ID,
                        P_NOTI_USER,
                        P_CREATED_BY,
                        currentDate,
                        P_MODIFIED_BY,
                        currentDate
                    );
                END LOOP;
        END IF;
    ELSE
        UPDATE GNCN_TRANSACTION_DISSCUSTION
        SET
            DISPLAY_NAME = P_DISPLAY_NAME,
            CONTENT = P_CONTENT,
            MODIFIED_BY = P_MODIFIED_BY,
            MODIFIED_DATE = currentDate
        WHERE ID= P_ID
        RETURNING ID INTO P_ID;
    END IF;
    P_MESS :='1';
EXCEPTION
   WHEN OTHERS 
   THEN ROLLBACK  TO SP_UPDATE_DATA;
    P_MESS := SUBSTR(SQLERRM, 1, 500);
END SP_UPDATE_GNCN_TRANSACTION_DISCUSSION;

/
--------------------------------------------------------
--  DDL for Procedure SP_UPDATE_GNCN_TRANSACTION_DISCUSSION_NOTIFICATION
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_UPDATE_GNCN_TRANSACTION_DISCUSSION_NOTIFICATION" (
    P_TRANS_DISSCUSTION_ID IN NUMBER,
    P_USER_NAME IN VARCHAR2,
    P_MARK_AS_READ IN NUMBER,
