        WHERE TRANS_DISSCUSTION_ID= P_TRANS_DISSCUSTION_ID AND USER_NAME = P_USER_NAME;
    END IF;
END SP_UPDATE_GNCN_TRANSACTION_DISCUSSION_NOTIFICATION;

/
--------------------------------------------------------
--  DDL for Procedure SP_UPDATE_GNCN_TRANSACTION_DOC
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_UPDATE_GNCN_TRANSACTION_DOC" 
(
        p_json_arr          IN CLOB,
        P_USER              IN VARCHAR2,
        P_TRANSACTION_DOC   OUT SYS_REFCURSOR,
        P_MESS              OUT VARCHAR2
) AS 
    sql_Temp                VARCHAR2(2000) DEFAULT '';
    tempId                  NUMBER;
    currentDate             DATE := SYSDATE;
    json_arr                JSON_ARRAY_T;

    -- transaction doc
    json_obj                JSON_OBJECT_T;
    P_ID                    NUMBER;
    P_GNCN_CODE	            VARCHAR2(50);
    P_PDTD_CODE	            VARCHAR2(50);
    P_DOCUMENT_GROUP	    VARCHAR2(500);
    P_DOCUMENT_CATEGORY	    VARCHAR2(1000);
    P_COMPLETED_TIME	    VARCHAR2(500);
    P_COMPLETED_USER	    VARCHAR2(500);
    P_STATUS	            NUMBER;
    P_REASON	            VARCHAR2(150);
    P_OTHER_REASON	        VARCHAR2(2000);
    P_CREATED_DATE	        DATE;
    P_MODIFIED_DATE	        DATE;

    -- trans_attachment
	arr_transaction_attachment      json_array_t;
	obj_transaction_attachment      JSON_OBJECT_T;
	transDocId              NUMBER;
	p_gncnCode              VARCHAR2(50);
	p_groupName             VARCHAR2(50);
	p_docName               VARCHAR2(150);
	p_fileName              VARCHAR2(150);
	p_docId                 VARCHAR2(150);
	p_ecmPath               VARCHAR2(200);
	p_fileSize              VARCHAR2(50);
	p_docSource             VARCHAR2(200);

BEGIN
    SAVEPOINT SP_UPDATE_DATA;
    json_arr := json_array_t(p_json_arr);
    FOR i IN 0..json_arr.get_size - 1
    LOOP
        -- Mapping input transactionDoc
        json_obj := TREAT( json_arr.get ( i ) AS JSON_OBJECT_T );
        P_ID := json_obj.get_Number('id');
        P_GNCN_CODE := json_obj.get_String('gncnCode');
        P_PDTD_CODE := json_obj.get_String('pdtdCode');
        P_DOCUMENT_GROUP := json_obj.get_String('documentGroup');
        P_DOCUMENT_CATEGORY := json_obj.get_String('documentCategory');
        P_COMPLETED_TIME := json_obj.get_String('completedTime');
        P_COMPLETED_USER := json_obj.get_String('completedUser');
        P_REASON	:= json_obj.get_String('reason');
        P_OTHER_REASON := json_obj.get_String('otherReason');
        P_CREATED_DATE	:= json_obj.get_Date('createdDate');
        P_MODIFIED_DATE	:= json_obj.get_Date('modifiedDate');
        IF json_obj.get_Boolean('status') THEN 
                P_STATUS := 1;
        ELSE P_STATUS := 0;
        END IF;
        -- Checking transactionDoc
        tempId := -1;
        sql_Temp := 'SELECT COUNT(*) FROM GNCN_TRANSACTION_DOC WHERE ID=:id';
        EXECUTE IMMEDIATE  sql_Temp INTO tempId USING P_ID;

        IF (P_ID IS NULL OR P_ID <=0 OR tempId < 1) THEN
            INSERT INTO gncn_transaction_doc ( GNCN_CODE, PDTD_CODE, DOCUMENT_GROUP, DOCUMENT_CATEGORY, COMPLETED_TIME, COMPLETED_USER,
                REASON, CREATED_BY, CREATED_DATE, STATUS, OTHER_REASON) 
			VALUES( P_GNCN_CODE ,P_PDTD_CODE ,P_DOCUMENT_GROUP, P_DOCUMENT_CATEGORY, P_COMPLETED_TIME, P_COMPLETED_USER, P_REASON, P_USER, currentDate, P_STATUS, P_OTHER_REASON)
			RETURNING ID INTO tempId;

            -- Update transactionAttachment
            IF(json_obj.get_Array('transactionAttachment') IS NOT NULL) THEN
                    arr_transaction_attachment := json_obj.get_Array('transactionAttachment');
                    FOR i IN 0..arr_transaction_attachment.get_size - 1
                    LOOP
                        obj_transaction_attachment := TREAT( arr_transaction_attachment.get ( i ) AS JSON_OBJECT_T );
                        p_gncnCode := obj_transaction_attachment.get_String('gncnCode');
                        p_groupName := obj_transaction_attachment.get_String('groupName');
                        p_docName := obj_transaction_attachment.get_String('docName');
                        p_fileName := obj_transaction_attachment.get_String('fileName');
                        p_docId := obj_transaction_attachment.get_String('docId');
                        p_ecmPath := obj_transaction_attachment.get_String('ecmPath');
                        p_fileSize := obj_transaction_attachment.get_String('fileSize');
                        p_docSource := obj_transaction_attachment.get_String('docSource');

                        INSERT INTO gncn_transaction_attachment (transaction_doc_id, gncn_code, doc_name, file_name, file_size,
                        doc_source, doc_id, ecm_path, created_by, created_date)
                        VALUES (tempId, p_gncnCode, p_docName, p_fileName, p_fileSize, 
                                p_docSource, p_docId, p_ecmPath,
                                P_USER, SYSDATE);
                    END LOOP;
                END IF;
        ELSE
            UPDATE gncn_transaction_doc
            SET
                GNCN_CODE = P_GNCN_CODE,
                PDTD_CODE = P_PDTD_CODE,
                DOCUMENT_GROUP =P_DOCUMENT_GROUP,
                DOCUMENT_CATEGORY =P_DOCUMENT_CATEGORY,
                COMPLETED_TIME = P_COMPLETED_TIME,
                COMPLETED_USER = P_COMPLETED_USER,
                STATUS = P_STATUS,
                REASON = P_REASON,
                OTHER_REASON = P_OTHER_REASON,
                MODIFIED_BY = P_USER,
                MODIFIED_DATE = currentDate
            WHERE ID = P_ID;

            -- Update transactionAttachment
            IF(json_obj.get_Array('transactionAttachment') IS NOT NULL) THEN
                    arr_transaction_attachment := json_obj.get_Array('transactionAttachment');
					DELETE FROM gncn_transaction_attachment WHERE transaction_doc_id = P_ID;
                    FOR i IN 0..arr_transaction_attachment.get_size - 1
                    LOOP
                        obj_transaction_attachment := TREAT( arr_transaction_attachment.get ( i ) AS JSON_OBJECT_T );
                        p_gncnCode := obj_transaction_attachment.get_String('gncnCode');
                        p_groupName := obj_transaction_attachment.get_String('groupName');
                        p_docName := obj_transaction_attachment.get_String('docName');
                        p_fileName := obj_transaction_attachment.get_String('fileName');
                        p_docId := obj_transaction_attachment.get_String('docId');
                        p_ecmPath := obj_transaction_attachment.get_String('ecmPath');
                        p_fileSize := obj_transaction_attachment.get_String('fileSize');
                        p_docSource := obj_transaction_attachment.get_String('docSource');

                        INSERT INTO gncn_transaction_attachment (transaction_doc_id, gncn_code, doc_name, file_name, file_size,
                        doc_source, doc_id, ecm_path, created_by, created_date)
                        VALUES (P_ID, p_gncnCode, p_docName, p_fileName, p_fileSize, 
                                p_docSource, p_docId, p_ecmPath,
                                P_USER, SYSDATE);
                    END LOOP;
            END IF;
        END IF;
    END LOOP;
    OPEN P_TRANSACTION_DOC FOR 
    SELECT
    TD.ID,
    TD.PDTD_CODE,
    TD.GNCN_CODE,
    TD.DOCUMENT_GROUP,
    TD.DOCUMENT_CATEGORY,
    TD.COMPLETED_TIME,
    TD.COMPLETED_USER,
    TD.STATUS,
    TD.REASON,
    TD.OTHER_REASON,
    NVL(
        (SELECT JSON_ARRAYAGG(
            JSON_OBJECT('gncnCode' VALUE lq.GNCN_CODE, 'docId' VALUE lq.DOC_ID, 'fileName' VALUE lq.file_name,
            'id' VALUE lq.ID, 'docName' VALUE lq.DOC_NAME, 'fileSize' VALUE lq.FILE_SIZE, 'transactionDocId' VALUE lq.TRANSACTION_DOC_ID)
        )
        FROM GNCN_TRANSACTION_ATTACHMENT lq
        WHERE lq.TRANSACTION_DOC_ID = TD.id),
        null
    ) AS infoAttachment
    FROM 
        GNCN_TRANSACTION_DOC TD
    WHERE 
        TD.GNCN_CODE = P_GNCN_CODE;
    P_MESS := '1';
EXCEPTION
   WHEN OTHERS 
   THEN ROLLBACK  TO SP_UPDATE_DATA;
    P_MESS := SUBSTR(SQLERRM, 1, 500);
END SP_UPDATE_GNCN_TRANSACTION_DOC;

/
--------------------------------------------------------
--  DDL for Procedure SP_UPDATE_GNCN_TRANSACTION_FCC
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_UPDATE_GNCN_TRANSACTION_FCC" (
    p_json_arr IN CLOB,
    p_gntd_code IN VARCHAR2,
    p_lst_id IN VARCHAR2,
    P_MESS OUT VARCHAR2
) AS 
    json_arr                        JSON_ARRAY_T;
    json_obj                        JSON_OBJECT_T;
    p_id                            NUMBER;
    p_key                           NUMBER;
    p_typeEntry                     VARCHAR2(50) DEFAULT '';
    p_accompanyingInfo              VARCHAR2(1000) DEFAULT '';
    p_processResult                 VARCHAR2(50) DEFAULT '';
    p_commentsReasons               VARCHAR2(1000) DEFAULT '';
    p_parentPath                    VARCHAR2(200) DEFAULT '';
    p_path                          VARCHAR2(500) DEFAULT '';
    p_pdtdCode                      VARCHAR2(50) DEFAULT '';
    p_isDocument                    NUMBER;
    sumFcc                          NUMBER := 0;

BEGIN 
    SAVEPOINT SP_UPDATE_DATA;
    DELETE FROM GNCN_TRANSACTION_FCC WHERE gntd_code = p_gntd_code; --and instr(p_lst_id, id) = 0;
    json_arr := json_array_t(p_json_arr);
    FOR i IN 0..json_arr.get_size - 1
    LOOP
        json_obj := TREAT( json_arr.get ( i ) AS JSON_OBJECT_T );
        p_id := json_obj.get_Number('id');
        p_key := json_obj.get_Number('key');
        p_typeEntry := json_obj.get_String('typeEntry');
        p_accompanyingInfo := json_obj.get_String('accompanyingInfo');
        p_processResult := json_obj.get_String('processResult');
        p_commentsReasons := json_obj.get_String('commentsReasons');
        p_path := json_obj.get_String('path');
        p_parentPath := json_obj.get_String('parentPath');
        p_pdtdCode := json_obj.get_String('pdtdCode');
        IF(json_obj.get_Boolean('isDocument')) THEN p_isDocument := 1;
        ELSE p_isDocument := 0;
        END IF;
        SELECT count(*) into sumFcc from GNCN_TRANSACTION_FCC WHERE ID = p_id;
        IF(P_ID IS NULL OR P_ID <=0 OR sumFcc < 1) THEN
            INSERT INTO GNCN_TRANSACTION_FCC(key, type_entry, accompanying_info, process_result, 
            comments_reasons, parent_path, path, pdtd_code, gntd_code, created_date, is_document)
            VALUES (p_key, p_typeEntry, p_accompanyingInfo, p_processResult, p_commentsReasons,
            p_parentpath, p_path, p_pdtdCode, p_gntd_code, SYSDATE, p_isDocument);
        ELSE
            UPDATE GNCN_TRANSACTION_FCC
                SET gntd_code = p_gntd_code,
                    key = p_key,
                    type_entry = p_typeentry,
                    accompanying_info = p_accompanyingInfo,
                    process_result = p_processResult,
                    comments_reasons = p_commentsReasons,
                    parent_path = p_parentpath,
                    is_document = p_isDocument,
                    path = p_path,
                    pdtd_code = p_pdtdCode,
                    updated_date = sysdate
            WHERE ID = p_id;
        END IF;
    END LOOP;
    P_MESS := '1';
EXCEPTION
   WHEN OTHERS 
   THEN ROLLBACK  TO SP_UPDATE_DATA;
    P_MESS := SUBSTR(SQLERRM, 1, 500);
END SP_UPDATE_GNCN_TRANSACTION_FCC;

/
