--  DDL for Procedure SP_UPDATE_GNCN_TRANSACTION_LIMIT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_UPDATE_GNCN_TRANSACTION_LIMIT" (
    P_GNTD_CODE IN VARCHAR2,
    p_json_object IN CLOB,
    P_MODIFIED_BY IN VARCHAR2
) AS 
    json_obj JSON_OBJECT_T;
    P_LINE_CODE VARCHAR2(20) DEFAULT ''; --Mã h?n m?c
    P_LIMIT_JSON_DATA CLOB; --(4000) DEFAULT NULL;

BEGIN 
    json_obj := JSON_OBJECT_T.parse(p_json_object);
    P_LINE_CODE := json_obj.get_String('lineCode');
    P_LIMIT_JSON_DATA := json_obj.get_Clob('limitData');

    UPDATE GNCN_TRANSACTION 
        SET 
            LINE_CODE = P_LINE_CODE, -- Mã h?n m?c
            LIMIT_JSON_DATA = P_LIMIT_JSON_DATA, -- Thông tin h?ch toán h?n m?c
            MODIFIED_BY = P_MODIFIED_BY,
