--------------------------------------------------------
--  DDL for Procedure SP_UPDATE_GNCN_TRANSACTION_PAYMENT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_UPDATE_GNCN_TRANSACTION_PAYMENT" (
  p_json_object IN CLOB,
  P_GNTD_CODE IN VARCHAR2,
  P_MODIFIED_BY IN VARCHAR2
) AS 
  -- trans_payment
  obj_transaction_payment JSON_OBJECT_T;
  obj_payment_detail      JSON_OBJECT_T;
  p_currency              VARCHAR2(3);
  p_transferAccountNum    VARCHAR2(11);
  p_transferAccountName   VARCHAR2(50);
  p_rate                  NUMBER;
  p_receiveAccountNum     VARCHAR2(100);
  p_receiveAccountName    VARCHAR2(200);
  p_refNumMBNT            VARCHAR2(50);
  p_fee                   NUMBER DEFAULT 0;
  p_feeExcept             NUMBER;
  p_feeApprovalDocId      VARCHAR2(50);
  p_feeApprovalDocPath    VARCHAR2(255);
  p_feeApprovalDocName    VARCHAR2(150);
  p_feeAmount             NUMBER;
  p_feeVat                NUMBER;
  p_feeAccountNum         VARCHAR2(20);
  p_feeBalanceAmount      NUMBER;
  p_transferTotalAmount   NUMBER;
  p_amountAccountBalance  NUMBER;
  p_feeAccountBranch      VARCHAR2(10);
  p_transactionPaymentStatus      VARCHAR2(25);
  p_visibleSoButToanMBNT  VARCHAR2(50);
  p_receiveAccountBranch  VARCHAR2(50);
  p_description           VARCHAR2(200);
  -- trans_payment_detail
  arr_transaction_payment_detail json_array_t;
  transPaymentId          NUMBER;
  p_gncnCode              VARCHAR2(50);
  p_bankName              VARCHAR2(150);
  p_bankCode              VARCHAR2(50);
  p_branchCode            VARCHAR2(10);
  p_branchName            VARCHAR2(300);
  p_accountNum            VARCHAR2(20);
  p_accountName           VARCHAR2(200);
  p_amount                NUMBER;
  p_content               VARCHAR2(20000);
  p_transferType          NUMBER;
  p_ratioLock             NUMBER;
  p_receiveLock           NUMBER DEFAULT 0;
  p_refTransferType       NUMBER;
  p_refNoFccLock          VARCHAR2(50);
  p_refNoFeeFcc           VARCHAR2(50);
  p_udfCode               VARCHAR2(50);
  p_handleStatus          VARCHAR2(50);
  p_refNumFeeFcc          VARCHAR2(50);
  p_refNumTransferFcc     VARCHAR2(50);
  p_refNumTransferAch     VARCHAR2(50);
  p_lsBranch              CLOB;
  p_bicCode               VARCHAR2(50) DEFAULT '';
  p_benId                 VARCHAR2(50) DEFAULT '';
  p_uuid                  VARCHAR2(50) DEFAULT '';

BEGIN 
      obj_transaction_payment := JSON_OBJECT_T.parse(p_json_object);
      -- Mapping input transactionPayment
      IF obj_transaction_payment IS NOT NULL THEN
          DELETE GNCN_TRANSACTION_PAYMENT WHERE GNTD_CODE = P_GNTD_CODE;
          DELETE GNCN_TRANSACTION_PAYMENT_DEAIL WHERE GNCN_CODE = P_GNTD_CODE;
          p_currency := obj_transaction_payment.get_String('currency');
          p_transferAccountNum := obj_transaction_payment.get_String('transferAccountNum');
          p_transferAccountName := obj_transaction_payment.get_String('transferAccountName'); 
          p_rate := obj_transaction_payment.get_Number('rate');
          p_receiveAccountNum := obj_transaction_payment.get_String('receiveAccountNum');
          p_receiveAccountName := obj_transaction_payment.get_String('receiveAccountName');
          p_refNumMBNT := obj_transaction_payment.get_String('refNumMBNT');
          p_feeApprovalDocId := obj_transaction_payment.get_String('feeApprovalDocId');
          p_feeApprovalDocPath := obj_transaction_payment.get_String('feeApprovalDocPath');
          p_feeApprovalDocName := obj_transaction_payment.get_String('feeApprovalDocName');
          p_feeAmount := obj_transaction_payment.get_Number('feeAmount');
          p_feeVat := obj_transaction_payment.get_Number('feeVat');
          p_feeAccountNum := obj_transaction_payment.get_String('feeAccountNum');
          p_feeBalanceAmount := obj_transaction_payment.get_Number('feeBalanceAmount');
          p_description := obj_transaction_payment.get_String('description');
          p_transferTotalAmount := obj_transaction_payment.get_String('transferTotalAmount');
          p_amountAccountBalance := obj_transaction_payment.get_Number('amountAccountBalance');
          p_feeAccountBranch := obj_transaction_payment.get_String('feeAccountBranch');
          p_transactionPaymentStatus := obj_transaction_payment.get_String('transactionPaymentStatus');
          p_visibleSoButToanMBNT := obj_transaction_payment.get_String('visibleSoButToanMBNT');
          p_receiveAccountBranch := obj_transaction_payment.get_String('receiveAccountBranch');
          IF obj_transaction_payment.get_Boolean('feeExcept') THEN 
              p_feeExcept := 1;
          ELSE p_feeExcept := 0;
          END IF;

          INSERT INTO gncn_transaction_payment (gntd_code, currency, transfer_account_num, transfer_account_name, 
            rate, receive_account_num, receive_account_name, ref_num_mbnt
            , fee_except, fee_approval_doc_id, fee_approval_doc_path, fee_approval_doc_name, fee_amount,
            fee_vat, fee_account_num, fee_balance_amount, description,transfer_total_amount, amount_account_balance, fee_account_branch,
            transaction_payment_status,visible_so_but_toan_mbnt, receive_account_branch, created_by, created_date)
            VALUES (P_GNTD_CODE, p_currency, p_transferAccountNum, p_transferAccountName, p_rate, p_receiveAccountNum, 
            p_receiveAccountName,  p_refNumMBNT
            , p_feeExcept, p_feeApprovalDocId, p_feeApprovalDocPath, p_feeApprovalDocName, p_feeAmount,
            p_feeVat, p_feeAccountNum, p_feeBalanceAmount, p_description , p_transferTotalAmount, p_amountAccountBalance, p_feeAccountBranch,
            p_transactionPaymentStatus, p_visibleSoButToanMBNT, p_receiveAccountBranch, P_MODIFIED_BY, SYSDATE) RETURNING ID INTO transPaymentId;

          IF (obj_transaction_payment.get_Array('transactionPaymentDetail') IS NOT NULL) THEN
                arr_transaction_payment_detail := obj_transaction_payment.get_Array('transactionPaymentDetail');
                FOR i IN 0..arr_transaction_payment_detail.get_size - 1
                LOOP
                    obj_payment_detail := TREAT( arr_transaction_payment_detail.get ( i ) AS JSON_OBJECT_T );
                    p_gncnCode := obj_payment_detail.get_String('gncnCode');
                    p_bankName := obj_payment_detail.get_String('bankName');
                    p_bankCode := obj_payment_detail.get_String('bankCode');
                    p_branchCode := obj_payment_detail.get_String('branchCode');
                    p_accountNum := obj_payment_detail.get_String('accountNum');
                    p_accountName := obj_payment_detail.get_String('accountName');
                    p_amount := obj_payment_detail.get_Number('amount');
                    p_content := obj_payment_detail.get_String('content');
                    p_fee := NVL(obj_payment_detail.get_Number('fee'), 0);
                    p_transferType := obj_payment_detail.get_Number('transferType');
                    p_ratioLock := obj_payment_detail.get_String('ratioLock');
                    IF obj_payment_detail.get_Boolean('receiveLock') THEN 
                          p_receiveLock := 1;
                    ELSE p_receiveLock := 0;
                    END IF;
                    p_refTransferType := obj_payment_detail.get_String('refTransferType');
                    p_refNoFccLock := obj_payment_detail.get_String('refNoFccLock');
                    p_refNoFeeFcc := obj_payment_detail.get_String('refNoFeeFcc');
                    p_description := obj_payment_detail.get_String('description');
                    p_branchName := obj_payment_detail.get_String('branchName');
                    p_udfCode := obj_payment_detail.get_String('udfCode');
                    p_handleStatus := obj_payment_detail.get_String('handleStatus');
                    p_refNumFeeFcc := obj_payment_detail.get_String('refNumFeeFcc');
                    p_refNumTransferFcc := obj_payment_detail.get_String('refNumTransferFcc');
                    p_refNumTransferAch := obj_payment_detail.get_String('refNumTransferAch');
                    p_lsBranch := obj_payment_detail.get_Array('lsBranch').TO_CLOB;
                    p_bicCode := obj_payment_detail.get_String('bicCode');
                    p_benId := obj_payment_detail.get_String('benId');
                    p_uuid := obj_payment_detail.get_String('uuid');
                    INSERT INTO gncn_transaction_payment_deail (gncn_code, bank_name, bank_code, branch_code,
                    account_num, account_name, amount, content, fee, transfer_type, ratio_lock, receive_lock,
                    ref_transfer_type, ref_no_fcc_lock, description,
                    branch_name, handle_status,ref_num_fee_fcc,
                    ref_num_transfer_fcc, ref_num_transfer_ach,
                    created_by, created_date, udf_code, ls_branch, bic_code, ben_id, uuid)
                    VALUES (P_GNTD_CODE, p_bankName, p_bankCode, p_branchCode, 
                            p_accountNum, p_accountName, p_amount, p_content,
                            p_fee, p_transferType, p_ratioLock, p_receiveLock,
                             p_refTransferType,
                            p_refNoFccLock, p_description,
                            p_branchName,p_handleStatus, p_refNumFeeFcc,
                            p_refNumTransferFcc, p_refNumTransferAch,
                            P_MODIFIED_BY, SYSDATE, p_udfcode, p_lsBranch, p_bicCode, p_benId, p_uuid);
                END LOOP;
          END IF;
      END IF;
      
END SP_UPDATE_GNCN_TRANSACTION_PAYMENT;

/
--------------------------------------------------------
--  DDL for Procedure SP_UPDATE_GNCN_TRANSACTION_PURPOSE
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_UPDATE_GNCN_TRANSACTION_PURPOSE" (
  p_json_arr IN CLOB,
  P_GNTD_CODE IN VARCHAR2,
  P_MODIFIED_BY IN VARCHAR2
) AS 

  json_arr JSON_ARRAY_T;
  -- transaction purpose
  json_obj JSON_OBJECT_T;
  V_COUNT NUMBER DEFAULT 0;
  P_CONTRACT_CODE VARCHAR2(50);
  P_TOTAL_AMOUNT NUMBER;
  V_CURRENCY VARCHAR2(5);
  P_DEADLINE NUMBER;
  P_DURATION_UNIT VARCHAR2(20);
  P_DEADLINE_DISPLAY VARCHAR2(200);
  P_FROM_DATE VARCHAR2(50) DEFAULT '';
  V_FROM_DATE DATE DEFAULT NULL;
  P_TO_DATE VARCHAR2(50) DEFAULT '';
  V_TO_DATE DATE DEFAULT NULL;
  P_REASON VARCHAR2(2000);
  P_ALLOW_INTERFACE NUMBER DEFAULT 0;
  P_OVERDRAFT_DATA CLOB DEFAULT NULL;
  P_LOAN_DATA CLOB DEFAULT NULL;

BEGIN
  IF p_json_arr IS NOT NULL THEN 
    json_arr := json_array_t(p_json_arr);
    IF json_arr.get_size > 0 THEN
        SELECT COUNT(*) INTO V_COUNT FROM GNCN_TRANSACTION_PURPOSE WHERE GNTD_CODE = P_GNTD_CODE;
        json_obj := TREAT(json_arr.get (0) AS JSON_OBJECT_T);
        P_CONTRACT_CODE := json_obj.get_String('contractCode');
        P_TOTAL_AMOUNT := json_obj.get_Number('totalAmount');
        V_CURRENCY := json_obj.get_String('currency');
        P_DEADLINE := json_obj.get_Number('deadline');
        P_DEADLINE_DISPLAY := json_obj.get_String('deadlineDisplay');
        P_DURATION_UNIT := json_obj.get_String('durationUnit');
        P_FROM_DATE := json_obj.get_String('fromDateStr');
        P_TO_DATE := json_obj.get_String('toDateStr');
        IF (P_FROM_DATE IS NOT NULL) THEN V_FROM_DATE := TO_DATE(P_FROM_DATE, 'YYYY-MM-DD HH24:MI:SS');
        ELSE V_FROM_DATE := NULL;
        END IF;
        IF (P_TO_DATE IS NOT NULL) THEN V_TO_DATE := TO_DATE(P_TO_DATE, 'YYYY-MM-DD HH24:MI:SS');
        ELSE V_TO_DATE := NULL;
        END IF;
        P_REASON := json_obj.get_String('reason');
        P_OVERDRAFT_DATA := TO_CLOB(json_obj.get_String('overdraftData'));
        P_LOAN_DATA := TO_CLOB(json_obj.get_String('loanData'));
        IF json_obj.get_Boolean('allowInterface') THEN P_ALLOW_INTERFACE := 1; ELSE P_ALLOW_INTERFACE := 0; END IF;
        
        IF V_COUNT > 0 THEN
            UPDATE 
              GNCN_TRANSACTION_PURPOSE
            SET 
              GNTD_CODE = P_GNTD_CODE,
              ALLOW_INTERFACE = P_ALLOW_INTERFACE,
              CONTRACT_CODE = P_CONTRACT_CODE,
              TOTAL_AMOUNT = P_TOTAL_AMOUNT,
              CURRENCY = V_CURRENCY,
              DEADLINE = P_DEADLINE,
              DEADLINE_DISPLAY = P_DEADLINE_DISPLAY,
              DURATION_UNIT = P_DURATION_UNIT,
              FROM_DATE = V_FROM_DATE,
              TO_DATE = V_TO_DATE,
              REASON = P_REASON,
              OVERDRAFT_DATA = P_OVERDRAFT_DATA,
              LOAN_DATA = P_LOAN_DATA,
              MODIFIED_BY = P_MODIFIED_BY,
              MODIFIED_DATE = SYSDATE
            WHERE GNTD_CODE = P_GNTD_CODE;
        ELSE
            INSERT INTO
              GNCN_TRANSACTION_PURPOSE (
                GNTD_CODE,
                ALLOW_INTERFACE,
                CONTRACT_CODE,
                TOTAL_AMOUNT,
                CURRENCY,
                DEADLINE,
                DEADLINE_DISPLAY,
                DURATION_UNIT,
                FROM_DATE,
                TO_DATE,
                REASON,
                OVERDRAFT_DATA,
                LOAN_DATA,
                CREATED_BY,
                CREATED_DATE
              )
            VALUES
              (
                P_GNTD_CODE,
                P_ALLOW_INTERFACE,
                P_CONTRACT_CODE,
                P_TOTAL_AMOUNT,
                V_CURRENCY,
                P_DEADLINE,
                P_DEADLINE_DISPLAY,
                P_DURATION_UNIT,
                V_FROM_DATE,
                V_TO_DATE,
                P_REASON,
                P_OVERDRAFT_DATA,
                P_LOAN_DATA,
                P_MODIFIED_BY,
                SYSDATE
              );
        END IF;
    END IF;
  END IF;
END SP_UPDATE_GNCN_TRANSACTION_PURPOSE;

/
