--  DDL for Procedure SP_UPDATE_GNCN_TRANSACTION_V2
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_UPDATE_GNCN_TRANSACTION_V2" (
