    V_PROCESSING_DATE DATE DEFAULT NULL;
    P_APPROVAL_TOTAL_AMOUNT NUMBER DEFAULT NULL;
    P_APPROVAL_LOAN_METHOD VARCHAR2(50) DEFAULT '';
    P_APPROVAL_PDTD_DATE VARCHAR2(20) DEFAULT '';
    V_APPROVAL_PDTD_DATE DATE DEFAULT NULL;
    P_VIEWER VARCHAR2(500) DEFAULT '';
    P_PROCESS_GROUP VARCHAR2(200) DEFAULT '';
    P_APPROVAL_BY VARCHAR2(50) DEFAULT '';
    P_APPROVAL_DATE VARCHAR2(20) DEFAULT '';
    V_APPROVAL_DATE DATE DEFAULT NULL;
    P_IS_VIEW_RELATION_INFO NUMBER DEFAULT 0;
    P_CVKH_DATE VARCHAR2(50) DEFAULT '';
    V_CVKH_DATE DATE DEFAULT NULL;
    P_REQUEST_CONTENT CLOB;
    P_CMP_JSON_DATA CLOB;
    P_DISBURSEMENT_CODE VARCHAR2(50) DEFAULT '';
    P_SME_ID VARCHAR2(50) DEFAULT '';
    P_PARENT_SME_ID VARCHAR2(200) DEFAULT '';
    P_IS_VIEW_TAB_HTHS NUMBER DEFAULT 0;
BEGIN 
    json_obj := JSON_OBJECT_T.parse(p_json_object);
    P_ID := json_obj.get_Number('id');
    P_GNTD_CODE := json_obj.get_String('gntdCode');
    P_INSTANCE_ID := json_obj.get_String('instanceId');
    P_TASK_ID := json_obj.get_String('taskId');
    P_STATUS := json_obj.get_String('status');
    P_BRANCH_CODE := json_obj.get_String('branchCode');
    P_BRANCH_NAME := json_obj.get_String('branchName');
    P_PRODUCT_CODE := json_obj.get_String('productCode');
    P_PRODUCT_NAME := json_obj.get_String('productName');
    P_CUSTOMER_CODE := json_obj.get_String('customerCode');
    P_CUSTOMER_NAME := json_obj.get_String('customerName');
    P_CUSTOMER_TYPE := json_obj.get_String('customerType');
    P_ID_CARD := json_obj.get_String('idCard');
    P_TRANSACTION_TYPE1 := json_obj.get_String('transactionType1');
    P_TRANSACTION_TYPE2 := json_obj.get_String('transactionType2');
    P_TRANSACTION_TYPE3 := json_obj.get_String('transactionType3');
    P_TRANSACTION_FLOW := json_obj.get_String('transactionFlow');
    P_USE_PDTD := json_obj.get_Number('usePdtd');
    P_PDTD_CODE := json_obj.get_String('pdtdCode');
    P_APPROVAL_DATE_FROM_LOS := json_obj.get_String('approvalDateFromLos');
    P_SOURCE_SYNC := json_obj.get_String('sourceSync');
    P_LOAN_TERM := json_obj.get_Number('loanTerm');
    P_CURRENCY := json_obj.get_String('currency');
    P_DESCRIPTION := json_obj.get_String('description');
    P_PROCESSING_USER := json_obj.get_String('processingUser');
    P_PROCESSING_DATE := json_obj.get_String('processingDate');
    P_CREATED_BY := json_obj.get_String('createdBy');
    P_MODIFIED_BY := json_obj.get_String('modifiedBy');
    -- P_MODIFIED_DATE := json_obj.get_String('modifiedDate');
    P_APPROVAL_TOTAL_AMOUNT := json_obj.get_Number('approvalTotalAmount');
    P_APPROVAL_LOAN_METHOD := json_obj.get_String('pdtdLoanMethod');
    P_APPROVAL_PDTD_DATE := json_obj.get_String('pdtdApprovalDate');
    P_VIEWER := json_obj.get_String('viewer');
    P_PROCESS_GROUP := json_obj.get_String('processGroup');
    P_APPROVAL_BY := json_obj.get_String('approvalBy');
    P_APPROVAL_DATE := json_obj.get_String('approvalDate');
    P_CVKH_DATE := json_obj.get_String('cvkhDate');
    P_REQUEST_CONTENT := json_obj.get_Clob('requestContent');
    P_CMP_JSON_DATA := json_obj.get_Clob('cmpJsonData');
    P_DISBURSEMENT_CODE := json_obj.get_String('disbursementCode');
    P_SME_ID := json_obj.get_String('smeID');
    P_PARENT_SME_ID := json_obj.get_String('parentSmeID');
    P_IS_VIEW_TAB_HTHS := json_obj.get_Number('isViewTabHTHS');

    IF (P_APPROVAL_PDTD_DATE IS NOT NULL) 
        THEN V_APPROVAL_PDTD_DATE := TO_DATE(P_APPROVAL_PDTD_DATE, 'YYYY-MM-DD HH24:MI:SS');
    END IF;
     
    --    DBMS_OUTPUT.PUT_LINE('P_MODIFIED_DATE = ' || P_MODIFIED_DATE);
    IF (P_MODIFIED_DATE IS NOT NULL) 
      THEN 
        V_MODIFIED_DATE := TO_DATE(P_MODIFIED_DATE, 'YYYY-MM-DD HH24:MI:SS');
      ELSE 
        V_MODIFIED_DATE := SYSDATE;
    END IF;
    
    --    DBMS_OUTPUT.PUT_LINE('P_PROCESSING_DATE = ' || P_PROCESSING_DATE);
    IF (P_PROCESSING_DATE IS NOT NULL) 
      THEN 
        V_PROCESSING_DATE := TO_DATE(P_PROCESSING_DATE, 'YYYY-MM-DD HH24:MI:SS');
      ELSE 
        V_PROCESSING_DATE := NULL;
    END IF;
    
    IF (P_APPROVAL_DATE IS NOT NULL) 
      THEN 
        V_APPROVAL_DATE := TO_DATE(P_APPROVAL_DATE, 'YYYY-MM-DD HH24:MI:SS');
      ELSE 
        V_APPROVAL_DATE := NULL;
    END IF;
    
    IF (P_CVKH_DATE IS NOT NULL) 
      THEN 
        V_CVKH_DATE := TO_DATE(P_CVKH_DATE, 'YYYY-MM-DD HH24:MI:SS');
      ELSE 
        V_CVKH_DATE := NULL;
    END IF;
    
    P_IS_VIEW_RELATION_INFO := json_obj.get_Number('isViewRelationInfo');
    IF (P_IS_VIEW_RELATION_INFO IS NULL) THEN P_IS_VIEW_RELATION_INFO := 0; END IF;

    IF (P_ID IS NULL OR P_ID < 1) THEN
        INSERT INTO GNCN_TRANSACTION (
            GNTD_CODE, --Mã gi?i ngân tín d?ng
            TASK_ID, --Mã Task trên BPM
            INSTANCE_ID, --Mã Instance ID
            STATUS, --Tr?ng thái
            BRANCH_CODE, --Mã ?VKD - Mã chi nhánh
            BRANCH_NAME, --Tên ?VKD - Tên chi nhánh
            PRODUCT_CODE, --Mã S?n Ph?m
            PRODUCT_NAME, --Tên S?n Ph?m
            CUSTOMER_CODE, --Mã Khách Hàng
            CUSTOMER_NAME, --Tên Khách Hàng
            CUSTOMER_TYPE, --Lo?i Khách Hàng
            ID_CARD, --C?n c??c công dân
            TRANSACTION_TYPE1, --Lo?i GD C?p 1
            TRANSACTION_TYPE2, --Lo?i GD C?p 2
            TRANSACTION_TYPE3, --Lo?i GD C?p 3
            TRANSACTION_FLOW, --Lu?ng Giao d?ch Gi?i ngân
            USE_PDTD, --Dùng mã PDTD (True/False)
            PDTD_CODE, --Mã PDTD (LOS, BPM, ECM)
            APPROVAL_DATE_FROM_LOS, --Ngày PDTD
            SOURCE_SYNC, -- Ngu?n ??ng b?
            LOAN_TERM, --Th?i h?n vay
            APPROVAL_TOTAL_AMOUNT, -- S? ti?n PDTD
            APPROVAL_LOAN_METHOD, -- Ph??ng th?c vay PDTD
            APPROVAL_PDTD_DATE, -- Ngày PDTD
            CURRENCY, --Lo?i ti?n PDTD
            DESCRIPTION, --
            PROCESSING_USER, --
            PROCESSING_DATE, --L?u ngày t?i tr?ng thái ch? x? lý. Tr??ng h?p ch?a chuy?n b??c ch? x? lý thì giá tr? này = null
            CREATED_BY, --
            CREATED_DATE,
            VIEWER,
            PROCESS_GROUP,
            IS_VIEW_RELATION_INFO,
            EMP_RECEIPT_DATE,
            REQUEST_CONTENT,
            SME_ID,
            PARENT_SME_ID,
            IS_VIEW_TAB_HTHS,
            CMP_JSON_DATA,
            DISBURSEMENT_CODE
        ) VALUES (
            P_GNTD_CODE, --Mã gi?i ngân tín d?ng
            P_TASK_ID, --Mã Task trên BPM
            P_INSTANCE_ID, --Mã Instance ID
            P_STATUS, --Tr?ng thái
            P_BRANCH_CODE, --Mã ?VKD - Mã chi nhánh
            P_BRANCH_NAME, --Tên ?VKD - Tên chi nhánh
            P_PRODUCT_CODE, --Mã S?n Ph?m
            P_PRODUCT_NAME, --Tên S?n Ph?m
            REGEXP_REPLACE(P_CUSTOMER_CODE, '[]~!@#$%^&*()_+=\ {}[:”;’<,>./?]+', ''),--Mã Khách Hàng
            REGEXP_REPLACE(P_CUSTOMER_NAME, '[]~!@#$%^&*()_+=\{}[:”;’<,>./?]+', ''),--Tên Khách Hàng
            P_CUSTOMER_TYPE, --Lo?i Khách Hàng
            P_ID_CARD, --C?n c??c công dân
            P_TRANSACTION_TYPE1, --Lo?i GD C?p 1
            P_TRANSACTION_TYPE2, --Lo?i GD C?p 2
            P_TRANSACTION_TYPE3, --Lo?i GD C?p 3
            P_TRANSACTION_FLOW, --Lu?ng Giao d?ch Gi?i ngân
            P_USE_PDTD, --Dùng mã PDTD (True/False)
            P_PDTD_CODE, --Mã PDTD (LOS, BPM, ECM)
            P_APPROVAL_DATE_FROM_LOS, --Ngày PDTD
            P_SOURCE_SYNC, -- Ngu?n ??ng b?
            P_LOAN_TERM, --LOAN_TERM
            P_APPROVAL_TOTAL_AMOUNT,
            P_APPROVAL_LOAN_METHOD,
            V_APPROVAL_PDTD_DATE,
            P_CURRENCY, --CURRENCY
            P_DESCRIPTION, --DESCRIPTION
            P_PROCESSING_USER, --PROCESSING_USER
            V_PROCESSING_DATE, --PROCESSING_DATE
            P_CREATED_BY, -- CREATED_BY
            SYSDATE, --CREATED_DATE
            P_VIEWER,
            P_PROCESS_GROUP,
            P_IS_VIEW_RELATION_INFO,
            V_CVKH_DATE,
            P_REQUEST_CONTENT,
            P_SME_ID,
            P_PARENT_SME_ID,
            P_IS_VIEW_TAB_HTHS,
            P_CMP_JSON_DATA,
            P_DISBURSEMENT_CODE
        )
        RETURNING ID INTO P_RECORD_ID;    
        COMMIT;    
        P_RES_MESSAGE:='INSERT SUCCESSFULLY';
    ELSE
        UPDATE GNCN_TRANSACTION 
        SET 
            TASK_ID = P_TASK_ID, --Mã Task trên BPM
            INSTANCE_ID = P_INSTANCE_ID, --Mã Instance ID
            STATUS = P_STATUS, --Tr?ng thái
            BRANCH_CODE = P_BRANCH_CODE, --Mã ?VKD - Mã chi nhánh
            BRANCH_NAME = P_BRANCH_NAME, --Tên ?VKD - Tên chi nhánh
            PRODUCT_CODE = P_PRODUCT_CODE, --Mã S?n Ph?m
            PRODUCT_NAME = P_PRODUCT_NAME, --Tên S?n Ph?m
            CUSTOMER_CODE = REGEXP_REPLACE(P_CUSTOMER_CODE, '[]~!@#$%^&*()_+=\ {}[:”;’<,>./?]+', ''), --Mã Khách Hàng
            CUSTOMER_NAME = REGEXP_REPLACE(P_CUSTOMER_NAME, '[]~!@#$%^&*()_+=\{}[:”;’<,>./?]+', ''), --Tên Khách Hàng
            CUSTOMER_TYPE = P_CUSTOMER_TYPE, --Lo?i Khách Hàng
            ID_CARD = P_ID_CARD, --C?n c??c công dân
            TRANSACTION_TYPE1 = P_TRANSACTION_TYPE1, --Lo?i GD C?p 1
            TRANSACTION_TYPE2 = P_TRANSACTION_TYPE2, --Lo?i GD C?p 2
            TRANSACTION_TYPE3 = P_TRANSACTION_TYPE3, --Lo?i GD C?p 3
            TRANSACTION_FLOW = P_TRANSACTION_FLOW, --Lu?ng Giao d?ch Gi?i ngân
            USE_PDTD = P_USE_PDTD, --Dùng mã PDTD (True/False)
            PDTD_CODE = P_PDTD_CODE, --Mã PDTD (LOS, BPM, ECM)
            APPROVAL_DATE_FROM_LOS = P_APPROVAL_DATE_FROM_LOS,
            SOURCE_SYNC = P_SOURCE_SYNC,
            LOAN_TERM = P_LOAN_TERM,
            APPROVAL_TOTAL_AMOUNT = P_APPROVAL_TOTAL_AMOUNT,
            APPROVAL_LOAN_METHOD = P_APPROVAL_LOAN_METHOD,
            APPROVAL_PDTD_DATE = V_APPROVAL_PDTD_DATE,
            CURRENCY = P_CURRENCY, --Lo?i ti?n PDTD
            DESCRIPTION = P_DESCRIPTION,
            PROCESSING_USER = P_PROCESSING_USER, --
            PROCESSING_DATE = V_PROCESSING_DATE, --L?u ngày t?i tr?ng thái ch? x? lý. Tr??ng h?p ch?a chuy?n b??c ch? x? lý thì giá tr? này = null
            MODIFIED_BY = P_MODIFIED_BY,
            MODIFIED_DATE = SYSDATE,
            VIEWER = P_VIEWER,
            PROCESS_GROUP = P_PROCESS_GROUP,
            APPROVAL_BY = P_APPROVAL_BY,
            APPROVAL_DATE = V_APPROVAL_DATE,
            IS_VIEW_RELATION_INFO = P_IS_VIEW_RELATION_INFO,
            EMP_RECEIPT_DATE = V_CVKH_DATE,
            REQUEST_CONTENT = P_REQUEST_CONTENT,
            CMP_JSON_DATA = P_CMP_JSON_DATA,
            DISBURSEMENT_CODE = P_DISBURSEMENT_CODE,
            SME_ID = P_SME_ID,
            PARENT_SME_ID = P_PARENT_SME_ID,
            IS_VIEW_TAB_HTHS = P_IS_VIEW_TAB_HTHS
        WHERE GNTD_CODE=P_GNTD_CODE;
        COMMIT;
        P_RECORD_ID:= P_ID;
        P_RES_MESSAGE:='UPDATE SUCCESSFULLY';
    END IF;

END SP_UPDATE_GNCN_TRANSACTION_V2;

