--  DDL for Procedure SP_UPDATE_GNCN_USER_CLERICAL_CONFIG
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_UPDATE_GNCN_USER_CLERICAL_CONFIG" (
  p_json_object IN CLOB,
  P_MODIFIED_BY IN VARCHAR
) AS
  json_obj JSON_OBJECT_T;
  v_userId VARCHAR2(50) DEFAULT '';
  v_branchCode VARCHAR2(50) DEFAULT '';
  v_allowBranch VARCHAR2(2000) DEFAULT '';
BEGIN
  json_obj := JSON_OBJECT_T.parse(p_json_object);
  v_userId:= json_obj.get_String('userId');
  v_branchCode:= json_obj.get_String('branchCode');
  v_allowBranch:= json_obj.get_String('allowBranch');

  UPDATE GNCN_USER_CLERICAL_CONFIG SET 
    STATUS = 0, 
    MODIFIED_BY = P_MODIFIED_BY,
    MODIFIED_DATE = SYSDATE 
  WHERE 
    STATUS = 1 AND USER_ID = v_userId AND BRANCH_CODE = v_branchCode;

  INSERT INTO GNCN_USER_CLERICAL_CONFIG (
    USER_ID,
    BRANCH_CODE,
    ALLOW_BRANCH,
    CREATED_BY
  ) VALUES (
    v_userId, 
    v_branchCode,
    v_allowBranch,
    P_MODIFIED_BY
  );
  COMMIT;

END SP_UPDATE_GNCN_USER_CLERICAL_CONFIG;

