--  DDL for Procedure SP_UPDATE_HSTT_DETAIL_GNCN_CA_DISBURSEMENT_DOCUMENTS
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_UPDATE_HSTT_DETAIL_GNCN_CA_DISBURSEMENT_DOCUMENTS" (
     P_ID                   number ,
     P_GNTD_CODE            varchar,
     P_PDTD_LOS             varchar,
     P_PDTD_CODE            varchar,
     P_STATUS_DOC           varchar,
     P_DEADLINE_EXT         DATE,
     P_USER_IDEA            varchar,
     P_STATUS_APPROVAL      varchar,
     P_APPROVAL_IDEA        varchar,
     P_modified_By          VARCHAR,
     P_APPROVAL_BY          VARCHAR,
     p_APPROVAL_DATE        DATE,
     P_APPROVAL_SUBMIT_BY   VARCHAR,
     P_APPROVAL_SUBMIT_DATE DATE
) AS 
BEGIN

    UPDATE GNCN_CA_DISBURSEMENT_DOCUMENTS
    SET 
        modified_date = sysdate,
        MODIFIED_BY = P_modified_By,
        DEADLINE_EXT = P_DEADLINE_EXT,
        USER_IDEA = P_USER_IDEA,
        STATUS_DOC = P_STATUS_DOC,
        STATUS_VERIFY = 1,
        STATUS_APPROVAL = P_STATUS_APPROVAL,
        APPROVAL_IDEA = P_APPROVAL_IDEA,
        APPROVAL_BY = P_APPROVAL_BY,
        APPROVAL_DATE = p_APPROVAL_DATE,
        APPROVAL_SUBMIT_BY = P_APPROVAL_SUBMIT_BY,
        APPROVAL_SUBMIT_DATE = P_APPROVAL_SUBMIT_DATE
    WHERE ID = P_ID;
    
--    IF P_STATUS_DOC = 'DA_BO_SUNG' AND P_STATUS_APPROVAL = 'DONG_Y' THEN
--        UPDATE GNCN_CA_DISBURSEMENT_DOCUMENTS
--        SET PDTD_CODE = P_PDTD_LOS
--        WHERE PDTD_CODE = P_PDTD_CODE;
--        
--        UPDATE GNCN_TRANSACTION 
--        SET PDTD_CODE = P_PDTD_LOS
--        WHERE PDTD_CODE = P_PDTD_CODE;
    IF P_STATUS_DOC = 'HUY_TAN_SUAT' AND P_STATUS_APPROVAL = 'DONG_Y' THEN
        UPDATE GNCN_CA_DISBURSEMENT_DOCUMENTS
        SET frequency = NULL, frequency_unit = null
        WHERE ID = P_ID;
    END IF;
    
END SP_UPDATE_HSTT_DETAIL_GNCN_CA_DISBURSEMENT_DOCUMENTS;

