--------------------------------------------------------
--  DDL for Procedure SP_UPDATE_REF_LOAN_FCC
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_UPDATE_REF_LOAN_FCC" (
  P_GNTD_CODE IN VARCHAR2,
  p_json_object IN CLOB,
  P_MODIFIED_BY IN VARCHAR2
) AS 
  json_obj JSON_OBJECT_T;
  loanData JSON_OBJECT_T;
  P_STATUS VARCHAR2(50) DEFAULT '';
  P_FCC_REF_NUM VARCHAR2(100) DEFAULT NULL;
  P_INTERFACE_STATUS VARCHAR2(100) DEFAULT NULL;
  P_LOAN_DATA CLOB DEFAULT NULL;
  P_INTERFACE_MSG CLOB DEFAULT NULL;
BEGIN
  json_obj := JSON_OBJECT_T.parse(p_json_object);
  P_STATUS := json_obj.get_String('status');
  P_LOAN_DATA := TO_CLOB(json_obj.get_String('loanData'));
  loanData := JSON_OBJECT_T.parse(P_LOAN_DATA);
  P_FCC_REF_NUM := loanData.get_String('entryNumFcc');
  P_INTERFACE_STATUS := loanData.get_String('interfaceStatus');
  P_INTERFACE_MSG := TO_CLOB(loanData.get_String('interfaceError'));

  UPDATE 
    GNCN_TRANSACTION 
  SET 
    STATUS = P_STATUS,
    -- MESSAGE = P_MESSAGE,
    MODIFIED_BY = P_MODIFIED_BY,
    MODIFIED_DATE = SYSDATE
  WHERE GNTD_CODE = P_GNTD_CODE;

  UPDATE
    GNCN_TRANSACTION_PURPOSE 
  SET 
    LOAN_DATA = P_LOAN_DATA,
    INTERFACE_MSG = P_INTERFACE_MSG,
    INTERFACE_STATUS = P_INTERFACE_STATUS,
    FCC_REF_NUM = P_FCC_REF_NUM,
    INTERFACE_DATE = SYSDATE
    -- MODIFIED_BY = P_MODIFIED_BY,
    -- MODIFIED_DATE = SYSDATE
  WHERE GNTD_CODE = P_GNTD_CODE;

END SP_UPDATE_REF_LOAN_FCC;

/
--------------------------------------------------------
--  DDL for Procedure SP_UPDATE_REF_NUM_TRANSFER_MONEY
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_UPDATE_REF_NUM_TRANSFER_MONEY" (
    p_json_object IN CLOB,
    P_IS_UPDATE_PAYMENT OUT VARCHAR2,
    P_IS_UPDATE_TRANSACTION OUT VARCHAR2
) AS 
    json_obj JSON_OBJECT_T;
    P_GNTD_CODE VARCHAR2(50) DEFAULT '';
    P_ENTRY_TYPE VARCHAR2(10) DEFAULT '';
    P_REF_NUM VARCHAR2(50) DEFAULT '';
    P_PAYMENT_DETAIL_ID VARCHAR2(100) DEFAULT '';
    P_PAYMENT_ID VARCHAR2(100) DEFAULT '';
    P_PRE_STATUS VARCHAR2(50) DEFAULT '';
    P_MODIFIED_BY VARCHAR2(50) DEFAULT '';
    P_STATUS_DB VARCHAR2(50) DEFAULT '';
    sumPayment NUMBER := 0;
    sumDetail NUMBER := 0;
BEGIN 
    SAVEPOINT SP_UPDATE_DATA;
    P_IS_UPDATE_PAYMENT := '0'; -- default = 0 không update k?t qu? chuy?n ti?n
    P_IS_UPDATE_TRANSACTION := '0'; -- default = 0 khong update trang thai giao dich
    json_obj := JSON_OBJECT_T.parse(p_json_object);
    P_GNTD_CODE := json_obj.get_String('gntdCode');
    P_ENTRY_TYPE := json_obj.get_String('typeButToan');
    P_PAYMENT_DETAIL_ID := json_obj.get_String('idTransPaymentDetail');
    P_PAYMENT_ID := json_obj.get_String('idTransPayment');
    P_REF_NUM := json_obj.get_String('refNo');
    P_PRE_STATUS := json_obj.get_String('preStatus');
    P_MODIFIED_BY := json_obj.get_String('modifiedBy');
    IF P_ENTRY_TYPE = '1' THEN -- Update bút toán MBNT
        UPDATE GNCN_TRANSACTION_PAYMENT 
        SET REF_NUM_MBNT = P_REF_NUM, TRANSFER_TYPE_MBNT = 1
        WHERE ID = P_PAYMENT_ID;

    ELSIF P_ENTRY_TYPE = '2' THEN -- Update bút toán thu phí
        UPDATE GNCN_TRANSACTION_PAYMENT_DEAIL 
        SET REF_NUM_FEE_FCC = P_REF_NUM, 
            REF_TRANSFER_TYPE = 1 
        WHERE ID = P_PAYMENT_DETAIL_ID;

        SELECT COUNT(*) into sumDetail FROM GNCN_TRANSACTION_PAYMENT_DEAIL PD
        WHERE PD.ID = P_PAYMENT_DETAIL_ID
        AND PD.REF_NUM_TRANSFER_FCC IS NOT NULL
        AND ((PD.TRANSFER_TYPE = 1 AND (PD.RECEIVE_LOCK = 0 OR PD.REF_NO_FCC_LOCK IS NOT NULL)) OR PD.TRANSFER_TYPE = 3 OR PD.TRANSFER_TYPE = 2);

    ELSIF P_ENTRY_TYPE = '3' OR P_ENTRY_TYPE = '4' THEN -- Update bút toán chuy?n ti?n
        UPDATE GNCN_TRANSACTION_PAYMENT_DEAIL PD
        SET PD.REF_NUM_TRANSFER_FCC = P_REF_NUM, 
            PD.REF_TRANSFER_TYPE = 1 
        WHERE PD.ID = P_PAYMENT_DETAIL_ID;

        SELECT COUNT(*) into sumDetail FROM GNCN_TRANSACTION_PAYMENT_DEAIL PD
        WHERE PD.ID = P_PAYMENT_DETAIL_ID
        AND (PD.REF_NUM_FEE_FCC IS NOT NULL OR PD.FEE = 0)
        AND ((PD.TRANSFER_TYPE = 1 AND (PD.RECEIVE_LOCK = 0 OR PD.REF_NO_FCC_LOCK IS NOT NULL)) OR PD.TRANSFER_TYPE = 2 OR PD.TRANSFER_TYPE = 3);

    ELSIF P_ENTRY_TYPE = '5' THEN -- Update bút toán phong t?a TK
        UPDATE GNCN_TRANSACTION_PAYMENT_DEAIL 
        SET REF_NO_FCC_LOCK = P_REF_NUM,
            REF_TRANSFER_TYPE = 1
        WHERE ID = P_PAYMENT_DETAIL_ID;

        SELECT COUNT(*) into sumDetail FROM GNCN_TRANSACTION_PAYMENT_DEAIL PD
        WHERE PD.ID = P_PAYMENT_DETAIL_ID
        AND (PD.REF_NUM_FEE_FCC IS NOT NULL OR PD.FEE = 0)
        AND PD.REF_NUM_TRANSFER_FCC IS NOT NULL;
    END IF;

    -- Ki?m tra c?p nh?t tr?ng thái chuy?n ti?n và tr?ng thái giao d?ch
    IF sumDetail > 0 THEN
        UPDATE GNCN_TRANSACTION_PAYMENT_DEAIL PD
        SET PD.RESULT_INTERFACE = 'Chuy?n ti?n thành công'
        WHERE PD.ID = P_PAYMENT_DETAIL_ID;
        P_IS_UPDATE_PAYMENT := '1';
    END IF;

    SELECT COUNT(*) into sumPayment FROM GNCN_TRANSACTION_PAYMENT_DEAIL PD
    WHERE PD.GNCN_CODE = P_GNTD_CODE
    AND NOT
        ((PD.REF_NUM_FEE_FCC IS NOT NULL OR PD.FEE = 0)
        AND PD.REF_NUM_TRANSFER_FCC IS NOT NULL
        AND ((PD.TRANSFER_TYPE = 1 AND (PD.RECEIVE_LOCK = 0 OR PD.REF_NO_FCC_LOCK IS NOT NULL)) OR PD.TRANSFER_TYPE = 2 OR PD.TRANSFER_TYPE = 3));
    SELECT STATUS INTO P_STATUS_DB FROM GNCN_TRANSACTION WHERE GNTD_CODE = P_GNTD_CODE;
    IF P_STATUS_DB <> 'GNCN_HOAN_THANH' AND (sumPayment = 0 OR P_ENTRY_TYPE = '1') THEN
        UPDATE GNCN_TRANSACTION 
        SET 
            STATUS='GNCN_HOAN_THANH',
            MODIFIED_BY = P_MODIFIED_BY,
            MODIFIED_DATE = SYSDATE
        WHERE GNTD_CODE = P_GNTD_CODE;
        INSERT INTO GNCN_TRANSACTION_HISTORY(
            GNTD_CODE, STATUS, CREATED_BY, ACTION, PRE_STATUS
        )
        VALUES ( P_GNTD_CODE, 'GNCN_HOAN_THANH', P_MODIFIED_BY, 'System Update', P_PRE_STATUS);
        P_IS_UPDATE_TRANSACTION := '1'; -- ?ã cap nhat trang thai giao dich
    END IF;
EXCEPTION
   WHEN OTHERS 
   THEN ROLLBACK TO SP_UPDATE_DATA;
    P_IS_UPDATE_TRANSACTION := SUBSTR(SQLERRM, 1, 500);
END SP_UPDATE_REF_NUM_TRANSFER_MONEY;

