/
--------------------------------------------------------
--  DDL for Procedure SP_UPDATE_USER_APPROVAL_ASSIGNMENT_CA_DISBURSEMENT
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "KHCN_MASTERDATA"."SP_UPDATE_USER_APPROVAL_ASSIGNMENT_CA_DISBURSEMENT" (
    p_json_arr IN CLOB,
    P_MESS     OUT VARCHAR2
) AS 
    -- Bi?n t?m
    currentDate DATE := SYSDATE;
    json_obj    JSON_OBJECT_T;
    json_arr    JSON_ARRAY_T;

    -- caDisbursementDocBO
    P_ID                   NUMBER;
    P_ASSIGNEE_ROLE_BY     VARCHAR2(100);
    P_ASSIGNEE_USER_BY     VARCHAR2(50);
    P_DOC_CATEGORY         NUMBER;
    P_APPROVAL_BY          VARCHAR2(50);
    P_CREATED_BY           VARCHAR2(50);
    P_MODIFIED_BY          VARCHAR2(50);

    -- caDisbursement
    obj_caDisbursement     JSON_OBJECT_T;
    P_TRANSACTION_FLOW     VARCHAR2(50);
    P_TRANSACTION_TYPE_1   VARCHAR2(50);
    P_TRANSACTION_TYPE_2   VARCHAR2(50);
    P_TRANSACTION_TYPE_3   VARCHAR2(50);
    P_PROCESSING_USER_NAME VARCHAR2(20);
    P_BRANCH_CODE          VARCHAR2(20);

    -- Các bi?n x? lý
    P_BRANCHS              VARCHAR2(4000);
    P_ASSIGNEE_USER_BY_OLD VARCHAR2(50);
    P_COUNT_IS_EXIST       NUMBER := 0;
    P_COUNT_USER_PROCESS   NUMBER := 0;
    P_COUNT_USER_BACKUP    NUMBER := 0;
    P_SUPPORT_USER         VARCHAR2(50);
    P_USER_LEAST           VARCHAR2(50);

BEGIN
    SAVEPOINT SP_UPDATE_DATA;
    json_arr := JSON_ARRAY_T(p_json_arr);

    FOR i IN 0..json_arr.get_size - 1 LOOP
        -- mapping input
        json_obj := JSON_OBJECT_T(json_arr.get(i));
        P_ID := json_obj.get_Number('id');
        P_ASSIGNEE_ROLE_BY := json_obj.get_String('assigneeRoleBy');
        P_ASSIGNEE_USER_BY := json_obj.get_String('assigneeUserBy');
        P_DOC_CATEGORY := json_obj.get_Number('docCategory');
        P_CREATED_BY := json_obj.get_String('createdBy');
        P_MODIFIED_BY := json_obj.get_String('modifiedBy');

        IF json_obj.get_Object('caDisbursement') IS NOT NULL THEN
            obj_caDisbursement := json_obj.get_Object('caDisbursement');
            P_TRANSACTION_FLOW := obj_caDisbursement.get_String('transactionFlow');
            P_TRANSACTION_TYPE_1 := obj_caDisbursement.get_String('transactionType1');
            P_TRANSACTION_TYPE_2 := obj_caDisbursement.get_String('transactionType2');
            P_TRANSACTION_TYPE_3 := obj_caDisbursement.get_String('transactionType3');
            P_PROCESSING_USER_NAME := obj_caDisbursement.get_String('processingUsername');
            P_BRANCH_CODE := obj_caDisbursement.get_String('branchCode');
            P_APPROVAL_BY := obj_caDisbursement.get_String('approvalBy');
        ELSE
            -- ??m b?o không null khi caDisbursement không có
            P_TRANSACTION_FLOW := NULL;
            P_TRANSACTION_TYPE_1 := NULL;
            P_TRANSACTION_TYPE_2 := NULL;
            P_TRANSACTION_TYPE_3 := NULL;
            P_PROCESSING_USER_NAME := NULL;
            P_BRANCH_CODE := NULL;
            P_APPROVAL_BY := NULL;
        END IF;

        -- L?y danh sách chi nhánh h?p l? (n?u không có dòng thì P_BRANCHS := NULL)
        BEGIN
            SELECT LISTAGG(BRANCHS, ',') WITHIN GROUP (ORDER BY BRANCHS)
            INTO P_BRANCHS
            FROM gncn_employee_process_config
            WHERE use_status = 1
              AND INSTR(',' || UPPER(ROLE) || ',', ',GNCN_QL_HTTD_DVKD,') > 0;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                P_BRANCHS := NULL;
        END;

        -- Ki?m tra user phân công c? (n?u không có thì NULL)
        BEGIN
            SELECT APPROVAL_BY
            INTO P_ASSIGNEE_USER_BY_OLD
            FROM (
                SELECT APPROVAL_BY
                FROM gncn_ca_disbursement_documents
                WHERE ID = P_ID
                ORDER BY NULL
            )
            WHERE ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                P_ASSIGNEE_USER_BY_OLD := NULL;
        END;

        ----------------------------------------------------------------------
        -- ? PHÂN LU?NG THEO LO?I H? S?
        ----------------------------------------------------------------------
        IF P_DOC_CATEGORY IN (1, 2) THEN
            -- Lu?ng phân công ??n gi?n
            P_ASSIGNEE_ROLE_BY := 'GNCN_QL_HTTD_DVKD,GNCN_CV_HTTD_DVKD_HTHS,GNCN_GD_DVKD';
            P_COUNT_IS_EXIST := 0;

            -- N?u user c? h?p l? -> ki?m tra xem có t?n t?i trong tài li?u không
            IF P_ASSIGNEE_USER_BY_OLD IS NOT NULL THEN
                SELECT COUNT(*) INTO P_COUNT_IS_EXIST
                FROM gncn_ca_disbursement_documents d
                WHERE d.ID = P_ID
                  AND d.APPROVAL_BY IN (
                      SELECT user_name
                      FROM gncn_employee_process_config c
                      WHERE c.use_status = 1
                        AND INSTR(',' || UPPER(c.ROLE) || ',', ',GNCN_QL_HTTD_DVKD,') > 0
                        AND (
                            INSTR(',' || UPPER(c.BRANCHS) || ',', ',' || UPPER(P_BRANCH_CODE) || ',') > 0
                            OR INSTR(',' || UPPER(c.BRANCH_MAIN) || ',', ',' || UPPER(P_BRANCH_CODE) || ',') > 0
                        )
                  );
            END IF;

            IF P_COUNT_IS_EXIST > 0 THEN
                P_ASSIGNEE_USER_BY := P_ASSIGNEE_USER_BY_OLD;
            ELSE
                -- Th? theo th? t? role ?u tiên, dùng function FN_GET_RANDOM_USER
                P_ASSIGNEE_USER_BY := NULL;
                FOR role_name IN (
                    SELECT COLUMN_VALUE AS ROLE_NAME
                    FROM TABLE(sys.odcivarchar2list(
                        'GNCN_QL_HTTD_DVKD',
                        'GNCN_CV_HTTD_DVKD_HTHS',
                        'GNCN_GD_DVKD'
                    ))
                ) LOOP
                    P_ASSIGNEE_USER_BY := FN_GET_RANDOM_USER(role_name.ROLE_NAME, P_BRANCH_CODE);
                    EXIT WHEN P_ASSIGNEE_USER_BY IS NOT NULL;
                END LOOP;
            END IF;

        ELSIF P_DOC_CATEGORY = 3 THEN
            ------------------------------------------------------------------
            -- ? Phân công h? s? gi?i ngân tín d?ng (CA_DISBURSEMENT)
            ------------------------------------------------------------------
            IF P_TRANSACTION_FLOW = 'TT' THEN
                SELECT COUNT(*) INTO P_COUNT_USER_PROCESS
                FROM GNCN_USER_GROUP_CONFIG ug
                WHERE ug.USE_STATUS = 1
                  AND ug.BRANCH_CODE = P_BRANCH_CODE
                  AND UPPER(ug.USER_PROCESS) = UPPER(P_APPROVAL_BY)
                  AND ug.GROUP_PROCESS IN (
                      SELECT DISTINCT GROUP_PROCESS_CODE
                      FROM GNCN_MAPPING_CONFIG
                      WHERE USE_STATUS = 1
                        AND TRANS_LEVEL_CODE_1 = P_TRANSACTION_TYPE_1
                        AND TRANS_LEVEL_CODE_2 = P_TRANSACTION_TYPE_2
                        AND TRANS_LEVEL_CODE_3 = P_TRANSACTION_TYPE_3
                  );

                SELECT COUNT(*) INTO P_COUNT_USER_BACKUP
                FROM GNCN_DISABLE_USER_CONFIG
                WHERE USE_STATUS = 1
                  AND UPPER(LOGIN_USER) = UPPER(P_APPROVAL_BY)
                  AND CURRENT_TIMESTAMP BETWEEN BEGIN_DATE AND FINISH_DATE;

                P_COUNT_IS_EXIST := 0;
                IF P_ASSIGNEE_USER_BY_OLD IS NOT NULL THEN
                    SELECT COUNT(*) INTO P_COUNT_IS_EXIST
                    FROM gncn_ca_disbursement_documents d
                    WHERE d.ID = P_ID
                      AND d.APPROVAL_BY IN (
                          SELECT USER_PROCESS
                          FROM GNCN_USER_GROUP_CONFIG ug
                          WHERE ug.USE_STATUS = 1
                            AND ug.BRANCH_CODE = P_BRANCH_CODE
                            AND ug.GROUP_PROCESS IN (
                                SELECT DISTINCT GROUP_PROCESS_CODE
                                FROM GNCN_MAPPING_CONFIG
                                WHERE USE_STATUS = 1
                                  AND TRANS_LEVEL_CODE_1 = P_TRANSACTION_TYPE_1
                                  AND TRANS_LEVEL_CODE_2 = P_TRANSACTION_TYPE_2
                                  AND TRANS_LEVEL_CODE_3 = P_TRANSACTION_TYPE_3
                            )
                      );
                END IF;

                IF P_COUNT_IS_EXIST > 0 THEN
                    P_ASSIGNEE_USER_BY := P_ASSIGNEE_USER_BY_OLD;

                ELSIF P_COUNT_USER_BACKUP > 0 THEN
                    -- Th? l?y user backup
                    BEGIN
                        SELECT SUPPORT_USER
                        INTO P_SUPPORT_USER
                        FROM (
                            SELECT SUPPORT_USER
                            FROM GNCN_DISABLE_USER_CONFIG
                            WHERE USE_STATUS = 1
                              AND UPPER(LOGIN_USER) = UPPER(P_APPROVAL_BY)
                            ORDER BY NULL
                        )
                        WHERE ROWNUM = 1;
                    EXCEPTION
                        WHEN NO_DATA_FOUND THEN
                            P_SUPPORT_USER := NULL;
                    END;

                    -- N?u không có support user, l?y 1 user_process random
                    IF P_SUPPORT_USER IS NULL THEN
                        BEGIN
                            SELECT USER_PROCESS
                            INTO P_USER_LEAST
                            FROM (
                                SELECT USER_PROCESS
                                FROM GNCN_USER_GROUP_CONFIG ug
                                WHERE ug.USE_STATUS = 1
                                  AND ug.BRANCH_CODE = P_BRANCH_CODE
                                  AND ug.GROUP_PROCESS IN (
                                      SELECT DISTINCT GROUP_PROCESS_CODE
                                      FROM GNCN_MAPPING_CONFIG
                                      WHERE USE_STATUS = 1
                                        AND TRANS_LEVEL_CODE_1 = P_TRANSACTION_TYPE_1
                                        AND TRANS_LEVEL_CODE_2 = P_TRANSACTION_TYPE_2
                                        AND TRANS_LEVEL_CODE_3 = P_TRANSACTION_TYPE_3
                                  )
                                ORDER BY DBMS_RANDOM.VALUE
                            )
                            WHERE ROWNUM = 1;
                        EXCEPTION
                            WHEN NO_DATA_FOUND THEN
                                P_USER_LEAST := NULL;
                        END;
                        P_ASSIGNEE_USER_BY := NVL(P_SUPPORT_USER, P_USER_LEAST);
                    ELSE
                        P_ASSIGNEE_USER_BY := P_SUPPORT_USER;
                    END IF;

                ELSIF P_COUNT_USER_PROCESS > 0 THEN
                    P_ASSIGNEE_USER_BY := P_APPROVAL_BY;

                ELSE
                    -- L?y 1 user-process random (fallback)
                    BEGIN
                        SELECT USER_PROCESS
                        INTO P_USER_LEAST
                        FROM (
                            SELECT USER_PROCESS
                            FROM GNCN_USER_GROUP_CONFIG ug
                            WHERE ug.USE_STATUS = 1
                              AND ug.BRANCH_CODE = P_BRANCH_CODE
                              AND ug.GROUP_PROCESS IN (
                                  SELECT DISTINCT GROUP_PROCESS_CODE
                                  FROM GNCN_MAPPING_CONFIG
                                  WHERE USE_STATUS = 1
                                    AND TRANS_LEVEL_CODE_1 = P_TRANSACTION_TYPE_1
                                    AND TRANS_LEVEL_CODE_2 = P_TRANSACTION_TYPE_2
                                    AND TRANS_LEVEL_CODE_3 = P_TRANSACTION_TYPE_3
                              )
                            ORDER BY DBMS_RANDOM.VALUE
                        )
                        WHERE ROWNUM = 1;
                    EXCEPTION
                        WHEN NO_DATA_FOUND THEN
                            P_USER_LEAST := NULL;
                    END;
                    P_ASSIGNEE_USER_BY := P_USER_LEAST;
                END IF;

            ELSE  -- n?u P_TRANSACTION_FLOW <> 'TT'
                -- Th? các role GNCN_QL_HTTD_DVKD -> GNCN_GD_DVKD
                P_ASSIGNEE_USER_BY := NULL;
                FOR role_name IN (
                    SELECT COLUMN_VALUE AS ROLE_NAME
                    FROM TABLE(sys.odcivarchar2list('GNCN_QL_HTTD_DVKD','GNCN_GD_DVKD'))
                ) LOOP
                    P_ASSIGNEE_USER_BY := FN_GET_RANDOM_USER(role_name.ROLE_NAME, P_BRANCH_CODE);
                    EXIT WHEN P_ASSIGNEE_USER_BY IS NOT NULL;
                END LOOP;
            END IF;
        END IF;

        -- C?p nh?t k?t qu? cu?i cùng
        UPDATE GNCN_CA_DISBURSEMENT_DOCUMENTS
        SET ASSIGNEE_USER_BY = P_ASSIGNEE_USER_BY,
            ASSIGNEE_ROLE_BY = P_ASSIGNEE_ROLE_BY,
            ASSIGNEE_DATE = currentDate
        WHERE ID = P_ID;
    END LOOP; -- end for each json

    P_MESS := CASE WHEN P_ASSIGNEE_USER_BY IS NOT NULL THEN '0' ELSE '1' END;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK TO SP_UPDATE_DATA;
        P_MESS := SUBSTR(SQLERRM, 1, 500);
END SP_UPDATE_USER_APPROVAL_ASSIGNMENT_CA_DISBURSEMENT;

/
