--  DDL for Package PAGINGPACKAGE
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE PACKAGE "KHCN_MASTERDATA"."PAGINGPACKAGE" AS
    TYPE PAGING_CURSOR IS REF CURSOR;
END PAGINGPACKAGE;

/
--------------------------------------------------------
--  DDL for Function FN_GET_RANDOM_USER
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "KHCN_MASTERDATA"."FN_GET_RANDOM_USER" (
    P_ROLE_NAME   IN VARCHAR2,
    P_BRANCH_CODE IN VARCHAR2
) RETURN VARCHAR2 IS
    V_USER VARCHAR2(200);
BEGIN
    SELECT user_name
    INTO V_USER
    FROM (
        SELECT DISTINCT user_name
        FROM gncn_employee_process_config c
        WHERE c.use_status = 1
          -- check role list membership (role có th? ch?a nhi?u role phân tách b?ng ,)
          AND INSTR(',' || UPPER(c.ROLE) || ',', ',' || UPPER(P_ROLE_NAME) || ',') > 0
          -- check branchs ho?c branch_main ch?a branch_code
          AND (
              INSTR(',' || UPPER(c.BRANCHS) || ',', ',' || UPPER(P_BRANCH_CODE) || ',') > 0
              OR INSTR(',' || UPPER(c.BRANCH_MAIN) || ',', ',' || UPPER(P_BRANCH_CODE) || ',') > 0
          )
        ORDER BY DBMS_RANDOM.VALUE
    )
    WHERE ROWNUM = 1;

    RETURN V_USER;

EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN NULL;
END FN_GET_RANDOM_USER;

/
--------------------------------------------------------
--  DDL for Function VN_TO_CAMELCASE
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "KHCN_MASTERDATA"."VN_TO_CAMELCASE" (input_text IN VARCHAR2) RETURN VARCHAR2 AS
    normalized_text VARCHAR2(4000);
BEGIN
    normalized_text :=
            TRANSLATE(LOWER(input_text), 'àá??ãâ???????????èé???ê?????ìí???òó??õô???????????ùú??????????ý????',
                      'aaaaaaaaaaaaaaaaaeeeeeeeeeeeiiiiiooooooooooooooooouuuuuuuuuuuyyyyyd');
    RETURN LOWER(SUBSTR(INITCAP(REGEXP_REPLACE(normalized_text, '(^|\s)(\S)', '\1\2')), 1, 1)) ||
           SUBSTR(REGEXP_REPLACE(INITCAP(REGEXP_REPLACE(normalized_text, '(^|\s)(\S)', '\1\2')), '\s+', ''), 2);
END;

/
